static u32 mmio64_page_count_for_span(u32 span_bytes)
{
    if (span_bytes == 0u)
    {
        return 0u;
    }

    return (span_bytes + (MMIO64_PAGE_BYTES - 1u)) / MMIO64_PAGE_BYTES;
}

