static int mmio64_range_fits(u32 offset, u32 byte_count, u32 limit)
{
    return (byte_count != 0u)
        && (offset <= limit)
        && (byte_count <= (limit - offset));
}

static u32 mmio64_ahci_port_offset(u32 port, u32 register_offset)
{
    return MMIO64_AHCI_PORT_BASE
        + (port * MMIO64_AHCI_PORT_STRIDE)
        + register_offset;
}

static int mmio64_register_fits_span(u32 byte_offset)
{
    return (byte_offset <= (MMIO64_MAX_SAFE_WINDOW_BYTES - sizeof(u32)))
        && ((byte_offset + sizeof(u32)) <= g_ahci_span);
}

static void mmio64_reset_mapping_request(void)
{
    g_ahci_map_virtual_base = 0ull;
    g_ahci_map_page_count = 0u;
    g_ahci_map_flags = MMIO64_MAP_FLAG_NOT_INSTALLED | MMIO64_MAP_FLAG_NO_DEREF;
    g_ahci_map_state = MMIO64_MAP_STATE_UNREQUESTED;
    g_ahci_map_installed = 0u;
    g_ahci_map_install_token = 0u;
    g_ahci_map_pml4_index = 0u;
    g_ahci_map_pdpt_index = 0u;
    g_ahci_map_pd_index = 0u;
    g_ahci_map_pt_index = 0u;
    g_ahci_map_entry_flags = 0ull;
    g_ahci_map_nx_enabled = 0u;
    mmio64_reset_snapshot();
    g_ahci_map_token = mmio64_make_map_token(
        g_ahci_map_virtual_base,
        g_ahci_map_page_count,
        g_ahci_map_flags,
        g_ahci_map_state,
        g_ahci_token);
}

static int mmio64_authorize(u32 hardware_capability_handle, u32 owner_id, int count_query)
{
    u32 endpoint;

    if (principal64_is_active(owner_id) == 0u)
    {
        ++g_denial_count;
        return 0;
    }

    endpoint = capability64_route(
        hardware_capability_handle,
        CAPABILITY64_RIGHT_QUERY,
        owner_id);
    if (endpoint != services64_resolve_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE))
    {
        ++g_denial_count;
        return 0;
    }

    if (count_query)
    {
        ++g_query_count;
    }
    return 1;
}

static u32 mmio64_authorized_value(
    u32 hardware_capability_handle,
    u32 owner_id,
    u32 value)
{
    if (!mmio64_authorize(hardware_capability_handle, owner_id, 1))
    {
        return MMIO64_INVALID_RESULT;
    }

    return value;
}

static u64 mmio64_authorized_value64(
    u32 hardware_capability_handle,
    u32 owner_id,
    u64 value)
{
    if (!mmio64_authorize(hardware_capability_handle, owner_id, 1))
    {
        return (u64)MMIO64_INVALID_RESULT;
    }

    return value;
}

