void mmio64_register_ahci_candidate(
    u32 physical_base,
    u32 span_bytes,
    u32 source_flags,
    u32 source_token)
{
    u32 flags = MMIO64_PLAN_FLAG_SAFE_NO_TOUCH | MMIO64_PLAN_FLAG_UNMAPPED;
    u32 state = MMIO64_PLAN_STATE_SAFE_NO_TOUCH;

    if ((source_flags & PCI64_AHCI_MMIO_FLAG_PRESENT) != 0u)
    {
        flags |= MMIO64_PLAN_FLAG_PRESENT;
    }

    if ((source_flags & PCI64_AHCI_MMIO_FLAG_MEMORY_BAR) != 0u)
    {
        flags |= MMIO64_PLAN_FLAG_MEMORY_WINDOW;
    }

    if (physical_base != 0u)
    {
        flags |= MMIO64_PLAN_FLAG_BASE_NONZERO;
    }

    if ((physical_base != 0u)
        && ((physical_base & (MMIO64_PAGE_BYTES - 1u)) == 0u))
    {
        flags |= MMIO64_PLAN_FLAG_PAGE_ALIGNED;
    }

    if ((span_bytes != 0u) && (span_bytes <= MMIO64_MAX_SAFE_WINDOW_BYTES))
    {
        flags |= MMIO64_PLAN_FLAG_SPAN_BOUNDED;
    }

    if ((source_flags & PCI64_AHCI_MMIO_FLAG_MAPPING_REQUIRED) != 0u)
    {
        flags |= MMIO64_PLAN_FLAG_REQUIRES_EXPLICIT_MAP;
    }

    if ((flags & (MMIO64_PLAN_FLAG_PRESENT
            | MMIO64_PLAN_FLAG_MEMORY_WINDOW
            | MMIO64_PLAN_FLAG_BASE_NONZERO
            | MMIO64_PLAN_FLAG_PAGE_ALIGNED
            | MMIO64_PLAN_FLAG_SPAN_BOUNDED
            | MMIO64_PLAN_FLAG_REQUIRES_EXPLICIT_MAP))
        == (MMIO64_PLAN_FLAG_PRESENT
            | MMIO64_PLAN_FLAG_MEMORY_WINDOW
            | MMIO64_PLAN_FLAG_BASE_NONZERO
            | MMIO64_PLAN_FLAG_PAGE_ALIGNED
            | MMIO64_PLAN_FLAG_SPAN_BOUNDED
            | MMIO64_PLAN_FLAG_REQUIRES_EXPLICIT_MAP))
    {
        state = MMIO64_PLAN_STATE_CANDIDATE;
        g_plan_count = 1u;
        g_ahci_base = physical_base;
        g_ahci_span = span_bytes;
    }
    else
    {
        g_plan_count = 0u;
        g_ahci_base = 0u;
        g_ahci_span = 0u;
    }

    g_ahci_flags = flags;
    g_ahci_state = state;
    g_ahci_token = mmio64_make_token(
        g_ahci_base,
        g_ahci_span,
        g_ahci_flags,
        g_ahci_state,
        source_token);
    mmio64_reset_mapping_request();
}

void mmio64_register_nvme_candidate(
    u32 physical_base_low,
    u32 physical_base_high,
    u32 span_bytes,
    u32 source_flags,
    u32 source_token)
{
    u32 ready_flags = PCI64_NVME_MMIO_FLAG_PRESENT
        | PCI64_NVME_MMIO_FLAG_MEMORY_BAR
        | PCI64_NVME_MMIO_FLAG_BASE_NONZERO
        | PCI64_NVME_MMIO_FLAG_PAGE_ALIGNED
        | PCI64_NVME_MMIO_FLAG_MAPPING_REQUIRED
        | PCI64_NVME_MMIO_FLAG_ADMIN_ONLY
        | PCI64_NVME_MMIO_FLAG_SAFE_NO_IO_QUEUE;

    g_nvme_flags = source_flags;
    g_nvme_base_low = physical_base_low;
    g_nvme_base_high = physical_base_high;
    g_nvme_span = span_bytes;
    g_nvme_plan_count = 0u;

    if (((source_flags & ready_flags) == ready_flags)
        && ((physical_base_low != 0u) || (physical_base_high != 0u))
        && (span_bytes >= MMIO64_NVME_MMIO_SPAN_HINT)
        && (span_bytes <= MMIO64_MAX_SAFE_WINDOW_BYTES))
    {
        g_nvme_plan_count = 1u;
    }

    g_nvme_token = mmio64_make_token(
        g_nvme_base_low,
        g_nvme_span,
        source_flags,
        g_nvme_plan_count,
        source_token);
    mmio64_reset_nvme_probe();
}

static int mmio64_authorize_nvme_probe(u32 hardware_capability_handle, u32 owner_id)
{
    u32 endpoint;

    if (principal64_is_active(owner_id) == 0u)
    {
        return 0;
    }

    endpoint = capability64_route(
        hardware_capability_handle,
        CAPABILITY64_RIGHT_QUERY,
        owner_id);
    return endpoint == services64_resolve_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE);
}

static void mmio64_nvme_fence(void)
{
    __asm__ __volatile__("mfence" ::: "memory");
}

static u32 mmio64_nvme_reg32(volatile u32 *registers, u32 offset)
{
    return registers[offset / sizeof(u32)];
}

static void mmio64_nvme_write_reg32(volatile u32 *registers, u32 offset, u32 value)
{
    registers[offset / sizeof(u32)] = value;
    mmio64_nvme_fence();
}

static void mmio64_nvme_copy_identify_string(
    char *destination,
    u32 destination_bytes,
    u32 source_offset,
    u32 source_bytes)
{
    u32 source_index;
    u32 out_index = 0u;
    u32 last_non_space = 0u;
    u8 value;

    if (destination_bytes == 0u)
    {
        return;
    }

    for (source_index = 0u; source_index < source_bytes; ++source_index)
    {
        value = g_nvme_identify_buffer[source_offset + source_index];
        if (value == 0u)
        {
            break;
        }

        if ((value == (u8)' ') && (out_index == 0u))
        {
            continue;
        }

        if (out_index >= destination_bytes - 1u)
        {
            break;
        }

        if (value == (u8)' ')
        {
            value = (u8)'_';
        }
        else if (!(((value >= (u8)'0') && (value <= (u8)'9'))
                || ((value >= (u8)'A') && (value <= (u8)'Z'))
                || ((value >= (u8)'a') && (value <= (u8)'z'))
                || (value == (u8)'.')
                || (value == (u8)'-')
                || (value == (u8)'_')))
        {
            value = (u8)'_';
        }

        destination[out_index++] = (char)value;
        if (value != (u8)'_')
        {
            last_non_space = out_index;
        }
    }

    out_index = last_non_space;
    if (out_index == 0u)
    {
        destination[0] = 'n';
        destination[1] = 'o';
        destination[2] = 'n';
        destination[3] = 'e';
        destination[4] = '\0';
        return;
    }

    destination[out_index] = '\0';
}

static u32 mmio64_nvme_wait_csts_ready(
    volatile u32 *registers,
    u32 want_ready,
    const char *timeout_label)
{
    u32 start_ticks = pit_get_ticks();
    u32 poll;

    for (poll = 0u; poll < MMIO64_NVME_READY_SPIN_BUDGET; ++poll)
    {
        u32 ready = ((mmio64_nvme_reg32(registers, MMIO64_NVME_REG_CSTS)
            & MMIO64_NVME_CSTS_READY) != 0u) ? 1u : 0u;
        if (ready == want_ready)
        {
            return 1u;
        }
        if ((pit_get_ticks() - start_ticks) >= MMIO64_NVME_READY_TIMEOUT_TICKS)
        {
            break;
        }
        __asm__ __volatile__("pause");
    }

    serial_write_string("[x64] NVMe CSTS.RDY timeout ");
    serial_write_string(timeout_label);
    serial_write_string("\n");
    return 0u;
}

static u32 mmio64_nvme_wait_completion(
    volatile u32 *completion_queue,
    u32 entry,
    u32 expected_phase,
    u32 expected_cid,
    u32 *status_out)
{
    u32 poll;
    u32 completion_dw3;
    u32 completion_cid;
    u32 completion_status;
    volatile u32 *entry_base = completion_queue + (entry * 4u);

    for (poll = 0u; poll < MMIO64_NVME_POLL_BUDGET; ++poll)
    {
        completion_dw3 = entry_base[3];
        if (((completion_dw3 >> 16) & 1u) == expected_phase)
        {
            completion_cid = completion_dw3 & 0xFFFFu;
            completion_status = completion_dw3 >> 17;
            *status_out = completion_status;
            return (completion_cid == expected_cid) ? 1u : 0u;
        }
    }

    *status_out = 0xFFFFFFFFu;
    return 0u;
}

static u32 mmio64_nvme_submit_block_read(
    volatile u32 *registers,
    u32 io_sq_tail_offset,
    u32 io_cq_head_offset,
    u32 queue_slot,
    u32 next_tail,
    u32 expected_phase,
    u32 command_id,
    u32 lba,
    u32 block_count,
    u64 data_physical,
    u32 *status_out)
{
    volatile u32 *completion;
    u32 command_offset = queue_slot * 64u;

    if ((block_count == 0u)
        || (block_count > (MMIO64_NVME_IO_BUFFER_BYTES / 512u)))
    {
        *status_out = 0xFFFFFFFFu;
        return 0u;
    }

    mmio64_zero_bytes(g_nvme_io_data_buffer, MMIO64_NVME_IO_BUFFER_BYTES);
    mmio64_zero_bytes(g_nvme_io_submission_queue + command_offset, 64u);
    mmio64_write_u32(
        g_nvme_io_submission_queue,
        command_offset,
        MMIO64_NVME_READ_OPCODE | (command_id << 16));
    mmio64_write_u32(
        g_nvme_io_submission_queue,
        command_offset + 4u,
        MMIO64_NVME_NAMESPACE_ID);
    mmio64_write_u32(
        g_nvme_io_submission_queue,
        command_offset + 24u,
        (u32)data_physical);
    mmio64_write_u32(
        g_nvme_io_submission_queue,
        command_offset + 28u,
            (u32)(data_physical >> 32));
    mmio64_write_u32(g_nvme_io_submission_queue, command_offset + 40u, lba);
    mmio64_write_u32(
        g_nvme_io_submission_queue,
        command_offset + 48u,
        block_count - 1u);
    mmio64_nvme_fence();
    mmio64_nvme_write_reg32(registers, io_sq_tail_offset, next_tail);

    completion = (volatile u32 *)(void *)g_nvme_io_completion_queue;
    if (mmio64_nvme_wait_completion(
            completion,
            queue_slot,
            expected_phase,
            command_id,
            status_out) == 0u)
    {
        return 0u;
    }

    mmio64_nvme_write_reg32(registers, io_cq_head_offset, next_tail);
    return (*status_out == 0u) ? 1u : 0u;
}

static u32 mmio64_nvme_submit_single_block_read(
    volatile u32 *registers,
    u32 io_sq_tail_offset,
    u32 io_cq_head_offset,
    u32 queue_slot,
    u32 next_tail,
    u32 expected_phase,
    u32 command_id,
    u32 lba,
    u64 data_physical,
    u32 *status_out)
{
    return mmio64_nvme_submit_block_read(
        registers,
        io_sq_tail_offset,
        io_cq_head_offset,
        queue_slot,
        next_tail,
        expected_phase,
        command_id,
        lba,
        1u,
        data_physical,
        status_out);
}

static u32 mmio64_nvme_submit_single_block_write(
    volatile u32 *registers,
    u32 io_sq_tail_offset,
    u32 io_cq_head_offset,
    u32 queue_slot,
    u32 next_tail,
    u32 expected_phase,
    u32 command_id,
    u32 lba,
    u64 data_physical,
    u32 *status_out)
{
    volatile u32 *completion;
    u32 command_offset = queue_slot * 64u;

    mmio64_zero_bytes(g_nvme_io_submission_queue + command_offset, 64u);
    mmio64_write_u32(
        g_nvme_io_submission_queue,
        command_offset,
        MMIO64_NVME_WRITE_OPCODE | (command_id << 16));
    mmio64_write_u32(
        g_nvme_io_submission_queue,
        command_offset + 4u,
        MMIO64_NVME_NAMESPACE_ID);
    mmio64_write_u32(
        g_nvme_io_submission_queue,
        command_offset + 24u,
        (u32)data_physical);
    mmio64_write_u32(
        g_nvme_io_submission_queue,
        command_offset + 28u,
        (u32)(data_physical >> 32));
    mmio64_write_u32(g_nvme_io_submission_queue, command_offset + 40u, lba);
    mmio64_nvme_fence();
    mmio64_nvme_write_reg32(registers, io_sq_tail_offset, next_tail);

    completion = (volatile u32 *)(void *)g_nvme_io_completion_queue;
    if (mmio64_nvme_wait_completion(
            completion,
            queue_slot,
            expected_phase,
            command_id,
            status_out) == 0u)
    {
        return 0u;
    }

    mmio64_nvme_write_reg32(registers, io_cq_head_offset, next_tail);
    return (*status_out == 0u) ? 1u : 0u;
}

u32 mmio64_probe_nvme_controller(u32 hardware_capability_handle, u32 owner_id)
{
    volatile u32 *registers;
    volatile u32 *completion;
    u64 sq_physical;
    u64 cq_physical;
    u64 identify_physical;
    u32 page_count;
    u32 cap_high;
    u32 doorbell_stride;
    u32 sq_tail_offset;
    u32 cq_head_offset;
    u32 doorbell_page;
    u32 page0_open = 0u;
    u32 doorbell_open = 0u;
    u32 poll;
    u32 command;
    u32 completion_dw3;
    u32 completion_cid;
    u32 completion_status;
    u32 success = 0u;
    u32 error = 0u;

    if (!mmio64_authorize_nvme_probe(hardware_capability_handle, owner_id))
    {
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_nvme_probe();
    g_nvme_probe_found = (g_nvme_plan_count != 0u) ? 1u : 0u;
    if ((g_nvme_probe_found == 0u)
        || ((g_nvme_base_low == 0u) && (g_nvme_base_high == 0u))
        || (g_nvme_span < MMIO64_NVME_MMIO_SPAN_HINT))
    {
        g_nvme_probe_error = 1u;
        return MMIO64_INVALID_RESULT;
    }

    page_count = (g_nvme_span + (MMIO64_PAGE_BYTES - 1u)) / MMIO64_PAGE_BYTES;
    if (paging64_install_kernel_mmio_mapping(
            MMIO64_NVME_MAP_VIRTUAL_BASE,
            ((u64)g_nvme_base_high << 32) | (u64)g_nvme_base_low,
            page_count) == 0u)
    {
        g_nvme_probe_error = 2u;
        return MMIO64_INVALID_RESULT;
    }

    registers = (volatile u32 *)(u64)MMIO64_NVME_MAP_VIRTUAL_BASE;
    (void)mmio64_nvme_reg32(registers, MMIO64_NVME_REG_CAP_LOW);
    cap_high = mmio64_nvme_reg32(registers, MMIO64_NVME_REG_CAP_HIGH);
    doorbell_stride = 4u << (cap_high & 0x0Fu);
    sq_tail_offset = MMIO64_NVME_DOORBELL_BASE;
    cq_head_offset = MMIO64_NVME_DOORBELL_BASE + doorbell_stride;
    doorbell_page = cq_head_offset / MMIO64_PAGE_BYTES;
    if ((sq_tail_offset >= g_nvme_span)
        || (cq_head_offset >= g_nvme_span)
        || (doorbell_page >= page_count))
    {
        g_nvme_probe_error = 4u;
        return MMIO64_INVALID_RESULT;
    }

    sq_physical = mmio64_lower_half_alias((const void *)g_nvme_admin_submission_queue);
    cq_physical = mmio64_lower_half_alias((const void *)g_nvme_admin_completion_queue);
    identify_physical = mmio64_lower_half_alias((const void *)g_nvme_identify_buffer);
    if (((sq_physical & 0xFFFull) != 0ull)
        || ((cq_physical & 0xFFFull) != 0ull)
        || ((identify_physical & 0xFFFull) != 0ull))
    {
        g_nvme_probe_error = 5u;
        return MMIO64_INVALID_RESULT;
    }

    page0_open = paging64_kernel_mmio_write_window_open(0u);
    if (doorbell_page == 0u)
    {
        doorbell_open = page0_open;
    }
    else
    {
        doorbell_open = paging64_kernel_mmio_write_window_open(doorbell_page);
    }

    if ((page0_open != 0u) && (doorbell_open != 0u))
    {
        command = mmio64_nvme_reg32(registers, MMIO64_NVME_REG_CC);
        if ((command & MMIO64_NVME_CC_ENABLE) != 0u)
        {
            mmio64_nvme_write_reg32(
                registers,
                MMIO64_NVME_REG_CC,
                command & ~MMIO64_NVME_CC_ENABLE);
        }

        if (mmio64_nvme_wait_csts_ready(registers, 0u, "disable") == 0u)
        {
            error = 6u;
        }
        else
        {
            mmio64_zero_bytes(
                g_nvme_admin_submission_queue,
                MMIO64_NVME_ADMIN_QUEUE_PAGE_BYTES);
            mmio64_zero_bytes(
                g_nvme_admin_completion_queue,
                MMIO64_NVME_ADMIN_QUEUE_PAGE_BYTES);
            mmio64_zero_bytes(g_nvme_identify_buffer, MMIO64_NVME_IDENTIFY_BYTES);

            mmio64_nvme_write_reg32(
                registers,
                MMIO64_NVME_REG_AQA,
                ((MMIO64_NVME_ADMIN_QUEUE_ENTRIES - 1u) << 16)
                    | (MMIO64_NVME_ADMIN_QUEUE_ENTRIES - 1u));
            mmio64_nvme_write_reg32(
                registers,
                MMIO64_NVME_REG_ASQ_LOW,
                (u32)sq_physical);
            mmio64_nvme_write_reg32(
                registers,
                MMIO64_NVME_REG_ASQ_HIGH,
                (u32)(sq_physical >> 32));
            mmio64_nvme_write_reg32(
                registers,
                MMIO64_NVME_REG_ACQ_LOW,
                (u32)cq_physical);
            mmio64_nvme_write_reg32(
                registers,
                MMIO64_NVME_REG_ACQ_HIGH,
                (u32)(cq_physical >> 32));
            mmio64_nvme_write_reg32(
                registers,
                MMIO64_NVME_REG_CC,
                MMIO64_NVME_CC_ENABLE
                    | MMIO64_NVME_CC_IOSQES_64
                    | MMIO64_NVME_CC_IOCQES_16);

            if (mmio64_nvme_wait_csts_ready(registers, 1u, "enable") == 0u)
            {
                error = 7u;
            }
            else
            {
                g_nvme_probe_ready = 1u;
                mmio64_write_u32(
                    g_nvme_admin_submission_queue,
                    0u,
                    MMIO64_NVME_IDENTIFY_OPCODE
                        | (MMIO64_NVME_IDENTIFY_CID << 16));
                mmio64_write_u32(
                    g_nvme_admin_submission_queue,
                    24u,
                    (u32)identify_physical);
                mmio64_write_u32(
                    g_nvme_admin_submission_queue,
                    28u,
                    (u32)(identify_physical >> 32));
                mmio64_write_u32(
                    g_nvme_admin_submission_queue,
                    40u,
                    MMIO64_NVME_IDENTIFY_CONTROLLER_CNS);
                mmio64_nvme_fence();
                mmio64_nvme_write_reg32(registers, sq_tail_offset, 1u);

                completion = (volatile u32 *)(void *)g_nvme_admin_completion_queue;
                for (poll = 0u; poll < MMIO64_NVME_POLL_BUDGET; ++poll)
                {
                    completion_dw3 = completion[3];
                    if (((completion_dw3 >> 16) & 1u) != 0u)
                    {
                        completion_cid = completion_dw3 & 0xFFFFu;
                        completion_status = completion_dw3 >> 17;
                        if ((completion_cid == MMIO64_NVME_IDENTIFY_CID)
                            && (completion_status == 0u))
                        {
                            success = 1u;
                        }
                        else
                        {
                            error = 8u;
                        }
                        break;
                    }
                }

                if (poll == MMIO64_NVME_POLL_BUDGET)
                {
                    error = 9u;
                }
                mmio64_nvme_write_reg32(registers, cq_head_offset, 1u);
            }
        }
    }
    else
    {
        error = 10u;
    }

    if ((doorbell_page != 0u) && (doorbell_open != 0u))
    {
        (void)paging64_kernel_mmio_write_window_close(doorbell_page);
    }
    if (page0_open != 0u)
    {
        (void)paging64_kernel_mmio_write_window_close(0u);
    }

    if (success == 0u)
    {
        g_nvme_probe_error = (error != 0u) ? error : 11u;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_nvme_copy_identify_string(
        g_nvme_probe_model,
        MMIO64_NVME_MODEL_BYTES + 1u,
        MMIO64_NVME_MODEL_OFFSET,
        MMIO64_NVME_MODEL_BYTES);
    mmio64_nvme_copy_identify_string(
        g_nvme_probe_firmware,
        MMIO64_NVME_FIRMWARE_BYTES + 1u,
        MMIO64_NVME_FIRMWARE_OFFSET,
        MMIO64_NVME_FIRMWARE_BYTES);
    g_nvme_probe_identify = 1u;
    g_nvme_probe_unavailable = 0u;
    g_nvme_probe_error = 0u;
    g_nvme_probe_result_token = mmio64_make_token(
        g_nvme_base_low,
        g_nvme_span,
        g_nvme_flags,
        mmio64_checksum_bytes(g_nvme_identify_buffer, MMIO64_NVME_IDENTIFY_BYTES),
        g_nvme_token);
    return g_nvme_probe_result_token;
}

u32 mmio64_read_nvme_lba0(
    u32 probe_token,
    u32 hardware_capability_handle,
    u32 owner_id)
{
    volatile u32 *registers;
    volatile u32 *completion;
    u64 io_sq_physical;
    u64 io_cq_physical;
    u64 data_physical;
    u32 page_count;
    u32 cap_high;
    u32 doorbell_stride;
    u32 admin_sq_tail_offset;
    u32 admin_cq_head_offset;
    u32 io_sq_tail_offset;
    u32 io_cq_head_offset;
    u32 doorbell_page;
    u32 page0_open = 0u;
    u32 doorbell_open = 0u;
    u32 completion_status = 0u;
    u32 error = 0u;
    u32 success = 0u;

    if (!mmio64_authorize_nvme_probe(hardware_capability_handle, owner_id))
    {
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_nvme_read();
    if ((probe_token == MMIO64_INVALID_RESULT)
        || (probe_token != g_nvme_probe_result_token)
        || (g_nvme_probe_identify == 0u)
        || (g_nvme_plan_count == 0u))
    {
        g_nvme_read_error = 1u;
        return MMIO64_INVALID_RESULT;
    }

    page_count = (g_nvme_span + (MMIO64_PAGE_BYTES - 1u)) / MMIO64_PAGE_BYTES;
    if (paging64_install_kernel_mmio_mapping(
            MMIO64_NVME_MAP_VIRTUAL_BASE,
            ((u64)g_nvme_base_high << 32) | (u64)g_nvme_base_low,
            page_count) == 0u)
    {
        g_nvme_read_error = 2u;
        return MMIO64_INVALID_RESULT;
    }

    registers = (volatile u32 *)(u64)MMIO64_NVME_MAP_VIRTUAL_BASE;
    cap_high = mmio64_nvme_reg32(registers, MMIO64_NVME_REG_CAP_HIGH);
    doorbell_stride = 4u << (cap_high & 0x0Fu);
    admin_sq_tail_offset = MMIO64_NVME_DOORBELL_BASE;
    admin_cq_head_offset = MMIO64_NVME_DOORBELL_BASE + doorbell_stride;
    io_sq_tail_offset = MMIO64_NVME_DOORBELL_BASE + (doorbell_stride * 2u);
    io_cq_head_offset = MMIO64_NVME_DOORBELL_BASE + (doorbell_stride * 3u);
    doorbell_page = io_cq_head_offset / MMIO64_PAGE_BYTES;
    if ((admin_sq_tail_offset >= g_nvme_span)
        || (admin_cq_head_offset >= g_nvme_span)
        || (io_sq_tail_offset >= g_nvme_span)
        || (io_cq_head_offset >= g_nvme_span)
        || (doorbell_page >= page_count))
    {
        g_nvme_read_error = 3u;
        return MMIO64_INVALID_RESULT;
    }

    io_sq_physical = mmio64_lower_half_alias((const void *)g_nvme_io_submission_queue);
    io_cq_physical = mmio64_lower_half_alias((const void *)g_nvme_io_completion_queue);
    data_physical = mmio64_lower_half_alias((const void *)g_nvme_io_data_buffer);
    if (((io_sq_physical & 0xFFFull) != 0ull)
        || ((io_cq_physical & 0xFFFull) != 0ull)
        || ((data_physical & 0xFFFull) != 0ull))
    {
        g_nvme_read_error = 4u;
        return MMIO64_INVALID_RESULT;
    }

    page0_open = paging64_kernel_mmio_write_window_open(0u);
    if (doorbell_page == 0u)
    {
        doorbell_open = page0_open;
    }
    else
    {
        doorbell_open = paging64_kernel_mmio_write_window_open(doorbell_page);
    }

    if ((page0_open != 0u) && (doorbell_open != 0u))
    {
        mmio64_zero_bytes(
            g_nvme_admin_submission_queue + 64u,
            64u);
        mmio64_write_u32(
            g_nvme_admin_submission_queue,
            64u,
            MMIO64_NVME_CREATE_IO_CQ_OPCODE
                | (MMIO64_NVME_CREATE_IO_CQ_CID << 16));
        mmio64_write_u32(
            g_nvme_admin_submission_queue,
            64u + 24u,
            (u32)io_cq_physical);
        mmio64_write_u32(
            g_nvme_admin_submission_queue,
            64u + 28u,
            (u32)(io_cq_physical >> 32));
        mmio64_write_u32(
            g_nvme_admin_submission_queue,
            64u + 40u,
            ((MMIO64_NVME_IO_QUEUE_ENTRIES - 1u) << 16)
                | MMIO64_NVME_IO_QUEUE_ID);
        mmio64_write_u32(
            g_nvme_admin_submission_queue,
            64u + 44u,
            1u);
        mmio64_nvme_fence();
        mmio64_nvme_write_reg32(registers, admin_sq_tail_offset, 0u);

        completion = (volatile u32 *)(void *)g_nvme_admin_completion_queue;
        if ((mmio64_nvme_wait_completion(
                completion,
                1u,
                1u,
                MMIO64_NVME_CREATE_IO_CQ_CID,
                &completion_status) == 0u)
            || (completion_status != 0u))
        {
            error = 5u;
        }
        else
        {
            mmio64_nvme_write_reg32(registers, admin_cq_head_offset, 0u);
            mmio64_zero_bytes(g_nvme_admin_submission_queue, 64u);
            mmio64_write_u32(
                g_nvme_admin_submission_queue,
                0u,
                MMIO64_NVME_CREATE_IO_SQ_OPCODE
                    | (MMIO64_NVME_CREATE_IO_SQ_CID << 16));
            mmio64_write_u32(
                g_nvme_admin_submission_queue,
                24u,
                (u32)io_sq_physical);
            mmio64_write_u32(
                g_nvme_admin_submission_queue,
                28u,
                (u32)(io_sq_physical >> 32));
            mmio64_write_u32(
                g_nvme_admin_submission_queue,
                40u,
                ((MMIO64_NVME_IO_QUEUE_ENTRIES - 1u) << 16)
                    | MMIO64_NVME_IO_QUEUE_ID);
            mmio64_write_u32(
                g_nvme_admin_submission_queue,
                44u,
                (MMIO64_NVME_IO_QUEUE_ID << 16) | 1u);
            mmio64_nvme_fence();
            mmio64_nvme_write_reg32(registers, admin_sq_tail_offset, 1u);

            if ((mmio64_nvme_wait_completion(
                    completion,
                    0u,
                    0u,
                    MMIO64_NVME_CREATE_IO_SQ_CID,
                    &completion_status) == 0u)
                || (completion_status != 0u))
            {
                error = 6u;
            }
            else
            {
                mmio64_nvme_write_reg32(registers, admin_cq_head_offset, 1u);
                g_nvme_read_ioq_created = 1u;
                mmio64_write_u32(
                    g_nvme_io_submission_queue,
                    0u,
                    MMIO64_NVME_READ_OPCODE | (MMIO64_NVME_READ_CID << 16));
                mmio64_write_u32(
                    g_nvme_io_submission_queue,
                    4u,
                    MMIO64_NVME_NAMESPACE_ID);
                mmio64_write_u32(
                    g_nvme_io_submission_queue,
                    24u,
                    (u32)data_physical);
                mmio64_write_u32(
                    g_nvme_io_submission_queue,
                    28u,
                    (u32)(data_physical >> 32));
                mmio64_nvme_fence();
                g_nvme_read_issued = 1u;
                mmio64_nvme_write_reg32(registers, io_sq_tail_offset, 1u);

                completion = (volatile u32 *)(void *)g_nvme_io_completion_queue;
                if (mmio64_nvme_wait_completion(
                        completion,
                        0u,
                        1u,
                        MMIO64_NVME_READ_CID,
                        &completion_status) == 0u)
                {
                    error = 7u;
                }
                else
                {
                    g_nvme_read_completed = 1u;
                    g_nvme_read_status = completion_status;
                    mmio64_nvme_write_reg32(registers, io_cq_head_offset, 1u);
                    success = (completion_status == 0u) ? 1u : 0u;
                    error = (completion_status == 0u) ? 0u : 8u;
                }
            }
        }
    }
    else
    {
        error = 9u;
    }

    if ((doorbell_page != 0u) && (doorbell_open != 0u))
    {
        (void)paging64_kernel_mmio_write_window_close(doorbell_page);
    }
    if (page0_open != 0u)
    {
        (void)paging64_kernel_mmio_write_window_close(0u);
    }

    if (success == 0u)
    {
        g_nvme_read_error = (error != 0u) ? error : 10u;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_nvme_fence();
    g_nvme_read_bytes = MMIO64_NVME_IO_BUFFER_BYTES;
    g_nvme_read_checksum = mmio64_checksum_bytes(
        g_nvme_io_data_buffer,
        MMIO64_NVME_IO_BUFFER_BYTES);
    g_nvme_read_unavailable = 0u;
    g_nvme_read_error = 0u;
    g_nvme_read_token = mmio64_make_token(
        g_nvme_base_low,
        g_nvme_read_checksum,
        g_nvme_read_status,
        g_nvme_read_bytes,
        probe_token);
    return g_nvme_read_token;
}

u32 mmio64_scan_nvme_gpt(
    u32 read_token,
    u32 hardware_capability_handle,
    u32 owner_id)
{
    volatile u32 *registers;
    u64 data_physical;
    u64 entries_lba;
    u64 first_lba;
    u64 last_lba;
    u32 page_count;
    u32 cap_high;
    u32 doorbell_stride;
    u32 io_sq_tail_offset;
    u32 io_cq_head_offset;
    u32 doorbell_page;
    u32 doorbell_open = 0u;
    u32 completion_status = 0u;
    u32 header_size;
    u32 header_crc;
    u32 computed_crc;
    u32 entry_count;
    u32 entry_size;
    u32 entry_offset;
    u32 entry_index;
    u32 guid_nonzero;
    u32 guid_index;
    u32 error = 0u;
    u32 success = 0u;

    if (!mmio64_authorize_nvme_probe(hardware_capability_handle, owner_id))
    {
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_nvme_gpt();
    if ((read_token == MMIO64_INVALID_RESULT)
        || (read_token != g_nvme_read_token)
        || (g_nvme_read_ioq_created == 0u)
        || (g_nvme_read_completed == 0u)
        || (g_nvme_read_status != 0u))
    {
        g_nvme_gpt_error = 1u;
        return MMIO64_INVALID_RESULT;
    }

    page_count = (g_nvme_span + (MMIO64_PAGE_BYTES - 1u)) / MMIO64_PAGE_BYTES;
    if (paging64_install_kernel_mmio_mapping(
            MMIO64_NVME_MAP_VIRTUAL_BASE,
            ((u64)g_nvme_base_high << 32) | (u64)g_nvme_base_low,
            page_count) == 0u)
    {
        g_nvme_gpt_error = 2u;
        return MMIO64_INVALID_RESULT;
    }

    registers = (volatile u32 *)(u64)MMIO64_NVME_MAP_VIRTUAL_BASE;
    cap_high = mmio64_nvme_reg32(registers, MMIO64_NVME_REG_CAP_HIGH);
    doorbell_stride = 4u << (cap_high & 0x0Fu);
    io_sq_tail_offset = MMIO64_NVME_DOORBELL_BASE + (doorbell_stride * 2u);
    io_cq_head_offset = MMIO64_NVME_DOORBELL_BASE + (doorbell_stride * 3u);
    doorbell_page = io_cq_head_offset / MMIO64_PAGE_BYTES;
    if ((io_sq_tail_offset >= g_nvme_span)
        || (io_cq_head_offset >= g_nvme_span)
        || (doorbell_page >= page_count))
    {
        g_nvme_gpt_error = 3u;
        return MMIO64_INVALID_RESULT;
    }

    data_physical = mmio64_lower_half_alias((const void *)g_nvme_io_data_buffer);
    if ((data_physical & 0xFFFull) != 0ull)
    {
        g_nvme_gpt_error = 4u;
        return MMIO64_INVALID_RESULT;
    }

    doorbell_open = paging64_kernel_mmio_write_window_open(doorbell_page);
    if (doorbell_open == 0u)
    {
        g_nvme_gpt_error = 5u;
        return MMIO64_INVALID_RESULT;
    }

    if (mmio64_nvme_submit_single_block_read(
            registers,
            io_sq_tail_offset,
            io_cq_head_offset,
            1u,
            0u,
            1u,
            MMIO64_NVME_GPT_READ_HEADER_CID,
            MMIO64_NVME_GPT_HEADER_LBA,
            data_physical,
            &completion_status) == 0u)
    {
        error = (completion_status == 0u) ? 6u : 7u;
    }
    else
    {
        header_size = mmio64_read_u32(g_nvme_io_data_buffer, 12u);
        header_crc = mmio64_read_u32(g_nvme_io_data_buffer, 16u);
        computed_crc = (header_size <= MMIO64_NVME_IO_BUFFER_BYTES)
            ? mmio64_crc32_bytes_with_zeroed_dword(
                g_nvme_io_data_buffer,
                header_size,
                16u)
            : 0u;
        entries_lba = mmio64_read_u64(g_nvme_io_data_buffer, 72u);
        entry_count = mmio64_read_u32(g_nvme_io_data_buffer, 80u);
        entry_size = mmio64_read_u32(g_nvme_io_data_buffer, 84u);

        if ((g_nvme_io_data_buffer[0] != (u8)'E')
            || (g_nvme_io_data_buffer[1] != (u8)'F')
            || (g_nvme_io_data_buffer[2] != (u8)'I')
            || (g_nvme_io_data_buffer[3] != (u8)' ')
            || (g_nvme_io_data_buffer[4] != (u8)'P')
            || (g_nvme_io_data_buffer[5] != (u8)'A')
            || (g_nvme_io_data_buffer[6] != (u8)'R')
            || (g_nvme_io_data_buffer[7] != (u8)'T')
            || (mmio64_read_u32(g_nvme_io_data_buffer, 8u) != 0x00010000u)
            || (header_size < 92u)
            || (header_size > 512u)
            || (header_crc == 0u)
            || (computed_crc != header_crc)
            || (entries_lba != (u64)MMIO64_NVME_GPT_ENTRY_LBA)
            || (entry_count == 0u)
            || (entry_size < 128u))
        {
            error = 8u;
        }
        else
        {
            g_nvme_gpt_signature = 1u;
        }
    }

    if ((error == 0u)
        && (mmio64_nvme_submit_block_read(
                registers,
                io_sq_tail_offset,
                io_cq_head_offset,
                0u,
                1u,
                0u,
                MMIO64_NVME_GPT_READ_ENTRY_CID,
                MMIO64_NVME_GPT_ENTRY_LBA,
                MMIO64_NVME_IO_BUFFER_BYTES / 512u,
                data_physical,
                &completion_status) == 0u))
    {
        error = (completion_status == 0u) ? 9u : 10u;
    }

    if (error == 0u)
    {
        for (entry_index = 0u, entry_offset = 0u;
            (entry_index < entry_count)
                && ((entry_offset + 128u) <= MMIO64_NVME_IO_BUFFER_BYTES);
            ++entry_index, entry_offset += entry_size)
        {
            guid_nonzero = 0u;
            for (guid_index = 0u; guid_index < 16u; ++guid_index)
            {
                if (g_nvme_io_data_buffer[entry_offset + guid_index] != 0u)
                {
                    guid_nonzero = 1u;
                }
            }

            if (guid_nonzero != 0u)
            {
                ++g_nvme_gpt_partitions;
                first_lba = mmio64_read_u64(g_nvme_io_data_buffer, entry_offset + 32u);
                last_lba = mmio64_read_u64(g_nvme_io_data_buffer, entry_offset + 40u);
                if ((first_lba <= 0xFFFFFFFFull)
                    && (last_lba <= 0xFFFFFFFFull)
                    && (last_lba >= first_lba))
                {
                    if (mmio64_guid_is_gpt_limitless_boot(
                            g_nvme_io_data_buffer,
                            entry_offset) != 0u)
                    {
                        ++g_nvme_gpt_m5_safe_targets;
                        if (g_nvme_gpt_m5_boot_start == 0u)
                        {
                            g_nvme_gpt_m5_boot_partition = entry_index + 1u;
                            g_nvme_gpt_m5_boot_start = (u32)first_lba;
                        }
                    }
                    else if (mmio64_guid_is_gpt_limitless_root(
                            g_nvme_io_data_buffer,
                            entry_offset) != 0u)
                    {
                        ++g_nvme_gpt_m5_safe_targets;
                        if (g_nvme_gpt_m5_root_start == 0u)
                        {
                            g_nvme_gpt_m5_root_partition = entry_index + 1u;
                            g_nvme_gpt_m5_root_start = (u32)first_lba;
                        }
                    }
                    else if ((mmio64_guid_is_gpt_basic_data(
                                g_nvme_io_data_buffer,
                                entry_offset) != 0u)
                        || (mmio64_guid_is_gpt_efi_system(
                                g_nvme_io_data_buffer,
                                entry_offset) != 0u)
                        || (mmio64_guid_is_gpt_microsoft_reserved(
                                g_nvme_io_data_buffer,
                                entry_offset) != 0u))
                    {
                        ++g_nvme_gpt_m5_forbidden_targets;
                    }
                    else
                    {
                        ++g_nvme_gpt_m5_unknown_targets;
                    }
                }
                else
                {
                    ++g_nvme_gpt_m5_unknown_targets;
                }
            }

            if ((g_nvme_gpt_fat32_start == 0u)
                && (mmio64_guid_is_gpt_basic_data(
                        g_nvme_io_data_buffer,
                        entry_offset) != 0u))
            {
                first_lba = mmio64_read_u64(g_nvme_io_data_buffer, entry_offset + 32u);
                last_lba = mmio64_read_u64(g_nvme_io_data_buffer, entry_offset + 40u);
                if ((first_lba <= 0xFFFFFFFFull)
                    && (last_lba <= 0xFFFFFFFFull)
                    && (last_lba >= first_lba))
                {
                    g_nvme_gpt_fat32_start = (u32)first_lba;
                    g_nvme_gpt_fat32_sectors = (u32)(last_lba - first_lba + 1ull);
                }
            }
        }

        g_nvme_gpt_m5_forbidden_denied =
            ((g_nvme_gpt_m5_forbidden_targets != 0u)
                && (g_nvme_gpt_write_authority == 0u))
                ? 1u
                : 0u;
        g_nvme_gpt_m5_no_write_authority =
            (g_nvme_gpt_write_authority == 0u) ? 1u : 0u;

        if ((g_nvme_gpt_partitions == 0u)
            || (g_nvme_gpt_fat32_start != MMIO64_NVME_GPT_FAT32_EXPECTED_START)
            || (g_nvme_gpt_fat32_sectors == 0u))
        {
            error = 11u;
        }
    }

    if ((error == 0u)
        && (mmio64_nvme_submit_single_block_read(
                registers,
                io_sq_tail_offset,
                io_cq_head_offset,
                1u,
                0u,
                0u,
                MMIO64_NVME_GPT_READ_VBR_CID,
                g_nvme_gpt_fat32_start,
                data_physical,
                &completion_status) == 0u))
    {
        error = (completion_status == 0u) ? 12u : 13u;
    }

    if (error == 0u)
    {
        g_nvme_gpt_vbr = ((g_nvme_io_data_buffer[510] == 0x55u)
            && (g_nvme_io_data_buffer[511] == 0xAAu)) ? 1u : 0u;
        success = g_nvme_gpt_vbr;
        error = (success != 0u) ? 0u : 14u;
    }

    if (doorbell_open != 0u)
    {
        (void)paging64_kernel_mmio_write_window_close(doorbell_page);
    }

    if (success == 0u)
    {
        g_nvme_gpt_error = (error != 0u) ? error : 15u;
        return MMIO64_INVALID_RESULT;
    }

    g_nvme_gpt_unavailable = 0u;
    g_nvme_gpt_error = 0u;
    g_nvme_gpt_token = mmio64_make_token(
        g_nvme_gpt_fat32_start,
        g_nvme_gpt_fat32_sectors,
        g_nvme_gpt_partitions,
        g_nvme_gpt_vbr,
        read_token);
    return g_nvme_gpt_token;
}

typedef struct Mmio64NvmeFatReader
{
    volatile u32 *registers;
    u64 data_physical;
    u32 io_sq_tail_offset;
    u32 io_cq_head_offset;
    u32 queue_slot;
    u32 next_tail;
    u32 expected_phase;
} Mmio64NvmeFatReader;

typedef struct Mmio64Fat32Volume
{
    u32 bytes_per_sector;
    u32 sectors_per_cluster;
    u32 reserved_sectors;
    u32 fat_count;
    u32 sectors_per_fat;
    u32 root_cluster;
    u32 total_sectors;
    u32 partition_start_lba;
    u32 partition_sectors;
    u32 fat_sector_base;
    u32 data_sector_base;
    u32 lbas_per_fat_sector;
    u32 lbas_per_cluster;
} Mmio64Fat32Volume;

typedef struct Mmio64Fat32EntryLocation
{
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    u32 directory_cluster;
#endif
    u32 cluster;
    u32 size;
    u32 attr;
    u32 entry_lba;
    u32 entry_offset;
    u32 lfn_lba;
    u32 lfn_offset;
    u32 lfn_entries;
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    u32 lfn_start_slot;
    u32 entry_slot;
#endif
} Mmio64Fat32EntryLocation;

static u32 mmio64_fat32_next_cluster(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    u32 cluster,
    u32 *next_cluster);

static void mmio64_nvme_fat_save_runtime(
    const Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume)
{
    g_nvme_fat_runtime_bytes_per_sector = volume->bytes_per_sector;
    g_nvme_fat_runtime_sectors_per_cluster = volume->sectors_per_cluster;
    g_nvme_fat_runtime_reserved_sectors = volume->reserved_sectors;
    g_nvme_fat_runtime_fat_count = volume->fat_count;
    g_nvme_fat_runtime_sectors_per_fat = volume->sectors_per_fat;
    g_nvme_fat_runtime_root_cluster = volume->root_cluster;
    g_nvme_fat_runtime_total_sectors = volume->total_sectors;
    g_nvme_fat_runtime_partition_start_lba = volume->partition_start_lba;
    g_nvme_fat_runtime_partition_sectors = volume->partition_sectors;
    g_nvme_fat_runtime_fat_sector_base = volume->fat_sector_base;
    g_nvme_fat_runtime_data_sector_base = volume->data_sector_base;
    g_nvme_fat_runtime_lbas_per_fat_sector = volume->lbas_per_fat_sector;
    g_nvme_fat_runtime_lbas_per_cluster = volume->lbas_per_cluster;
    g_nvme_fat_runtime_queue_slot = reader->queue_slot;
    g_nvme_fat_runtime_next_tail = reader->next_tail;
    g_nvme_fat_runtime_expected_phase = reader->expected_phase;
    g_nvme_fat_runtime_ready = 1u;
}

static u32 mmio64_nvme_fat_restore_volume(Mmio64Fat32Volume *volume)
{
    if (g_nvme_fat_runtime_ready == 0u)
    {
        return 0u;
    }

    volume->bytes_per_sector = g_nvme_fat_runtime_bytes_per_sector;
    volume->sectors_per_cluster = g_nvme_fat_runtime_sectors_per_cluster;
    volume->reserved_sectors = g_nvme_fat_runtime_reserved_sectors;
    volume->fat_count = g_nvme_fat_runtime_fat_count;
    volume->sectors_per_fat = g_nvme_fat_runtime_sectors_per_fat;
    volume->root_cluster = g_nvme_fat_runtime_root_cluster;
    volume->total_sectors = g_nvme_fat_runtime_total_sectors;
    volume->partition_start_lba = g_nvme_fat_runtime_partition_start_lba;
    volume->partition_sectors = g_nvme_fat_runtime_partition_sectors;
    volume->fat_sector_base = g_nvme_fat_runtime_fat_sector_base;
    volume->data_sector_base = g_nvme_fat_runtime_data_sector_base;
    volume->lbas_per_fat_sector = g_nvme_fat_runtime_lbas_per_fat_sector;
    volume->lbas_per_cluster = g_nvme_fat_runtime_lbas_per_cluster;
    return 1u;
}

static u32 mmio64_nvme_fat_open_runtime(
    Mmio64NvmeFatReader *reader,
    Mmio64Fat32Volume *volume,
    u32 *doorbell_page)
{
    volatile u32 *registers;
    u64 data_physical;
    u32 page_count;
    u32 cap_high;
    u32 doorbell_stride;
    u32 io_sq_tail_offset;
    u32 io_cq_head_offset;

    if ((reader == (Mmio64NvmeFatReader *)0)
        || (volume == (Mmio64Fat32Volume *)0)
        || (doorbell_page == (u32 *)0)
        || (mmio64_nvme_fat_restore_volume(volume) == 0u)
        || (g_nvme_span < MMIO64_NVME_MMIO_SPAN_HINT))
    {
        return 0u;
    }

    page_count = (g_nvme_span + (MMIO64_PAGE_BYTES - 1u)) / MMIO64_PAGE_BYTES;
    if (paging64_install_kernel_mmio_mapping(
            MMIO64_NVME_MAP_VIRTUAL_BASE,
            ((u64)g_nvme_base_high << 32) | (u64)g_nvme_base_low,
            page_count) == 0u)
    {
        return 0u;
    }

    registers = (volatile u32 *)(u64)MMIO64_NVME_MAP_VIRTUAL_BASE;
    cap_high = mmio64_nvme_reg32(registers, MMIO64_NVME_REG_CAP_HIGH);
    doorbell_stride = 4u << (cap_high & 0x0Fu);
    io_sq_tail_offset = MMIO64_NVME_DOORBELL_BASE + (doorbell_stride * 2u);
    io_cq_head_offset = MMIO64_NVME_DOORBELL_BASE + (doorbell_stride * 3u);
    *doorbell_page = io_cq_head_offset / MMIO64_PAGE_BYTES;
    if ((io_sq_tail_offset >= g_nvme_span)
        || (io_cq_head_offset >= g_nvme_span)
        || (*doorbell_page >= page_count))
    {
        return 0u;
    }

    data_physical = mmio64_lower_half_alias((const void *)g_nvme_io_data_buffer);
    if ((data_physical & 0xFFFull) != 0ull)
    {
        return 0u;
    }
    if (paging64_kernel_mmio_write_window_open(*doorbell_page) == 0u)
    {
        return 0u;
    }

    reader->registers = registers;
    reader->data_physical = data_physical;
    reader->io_sq_tail_offset = io_sq_tail_offset;
    reader->io_cq_head_offset = io_cq_head_offset;
    reader->queue_slot = g_nvme_fat_runtime_queue_slot;
    reader->next_tail = g_nvme_fat_runtime_next_tail;
    reader->expected_phase = g_nvme_fat_runtime_expected_phase;
    return 1u;
}

static void mmio64_nvme_fat_close_runtime(
    const Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    u32 doorbell_page)
{
    mmio64_nvme_fat_save_runtime(reader, volume);
    (void)paging64_kernel_mmio_write_window_close(doorbell_page);
}

static void mmio64_nvme_fat_advance_queue(Mmio64NvmeFatReader *reader)
{
    if (reader->queue_slot == 0u)
    {
        reader->queue_slot = 1u;
        reader->next_tail = 0u;
    }
    else
    {
        reader->queue_slot = 0u;
        reader->next_tail = 1u;
        reader->expected_phase ^= 1u;
    }
}

static u32 mmio64_nvme_fat_read_lba(
    Mmio64NvmeFatReader *reader,
    u32 lba,
    u32 command_id)
{
    u32 status = 0u;

    if (mmio64_nvme_submit_single_block_read(
            reader->registers,
            reader->io_sq_tail_offset,
            reader->io_cq_head_offset,
            reader->queue_slot,
            reader->next_tail,
            reader->expected_phase,
            command_id,
            lba,
            reader->data_physical,
            &status) == 0u)
    {
        return 0u;
    }

    mmio64_nvme_fat_advance_queue(reader);
    return 1u;
}

static u32 mmio64_nvme_fat_write_lba(
    Mmio64NvmeFatReader *reader,
    u32 lba,
    u32 command_id)
{
    u32 status = 0u;

    if (mmio64_nvme_submit_single_block_write(
            reader->registers,
            reader->io_sq_tail_offset,
            reader->io_cq_head_offset,
            reader->queue_slot,
            reader->next_tail,
            reader->expected_phase,
            command_id,
            lba,
            reader->data_physical,
            &status) == 0u)
    {
        return 0u;
    }

    mmio64_nvme_fat_advance_queue(reader);
    ++g_nvme_fat_flushes;
    return 1u;
}

static u32 mmio64_fat32_volume_sector_lba(
    const Mmio64Fat32Volume *volume,
    u32 volume_sector,
    u32 *lba_out)
{
    u64 byte_offset = (u64)volume_sector * (u64)volume->bytes_per_sector;
    u64 lba = (u64)volume->partition_start_lba + (byte_offset / 512ull);

    if (((byte_offset % 512ull) != 0ull) || (lba > 0xFFFFFFFFull))
    {
        return 0u;
    }

    *lba_out = (u32)lba;
    return 1u;
}

static u32 mmio64_fat32_cluster_lba(
    const Mmio64Fat32Volume *volume,
    u32 cluster,
    u32 *lba_out)
{
    u32 sector;

    if (cluster < 2u)
    {
        return 0u;
    }

    sector = volume->data_sector_base
        + ((cluster - 2u) * volume->sectors_per_cluster);
    return mmio64_fat32_volume_sector_lba(volume, sector, lba_out);
}

static u32 mmio64_fat32_names_equal(
    const u8 *left,
    u32 left_length,
    const u8 *right,
    u32 right_length)
{
    u32 index;

    if (left_length != right_length)
    {
        return 0u;
    }

    for (index = 0u; index < left_length; ++index)
    {
        if (mmio64_ascii_upper(left[index]) != mmio64_ascii_upper(right[index]))
        {
            return 0u;
        }
    }

    return 1u;
}

static u32 mmio64_fat32_short_name_matches(
    const u8 *entry,
    const u8 *component,
    u32 component_length)
{
    u8 short_name[13];
    u32 index;
    u32 length = 0u;
    u32 base_end = 8u;
    u32 ext_end = 11u;

    while ((base_end > 0u) && (entry[base_end - 1u] == (u8)' '))
    {
        --base_end;
    }
    while ((ext_end > 8u) && (entry[ext_end - 1u] == (u8)' '))
    {
        --ext_end;
    }

    for (index = 0u; index < base_end; ++index)
    {
        short_name[length++] = entry[index];
    }
    if (ext_end > 8u)
    {
        short_name[length++] = (u8)'.';
        for (index = 8u; index < ext_end; ++index)
        {
            short_name[length++] = entry[index];
        }
    }

    return mmio64_fat32_names_equal(short_name, length, component, component_length);
}

static void mmio64_fat32_lfn_clear(u16 *lfn_name, u32 unit_count)
{
    u32 index;

    for (index = 0u; index < unit_count; ++index)
    {
        lfn_name[index] = 0u;
    }
}

static void mmio64_fat32_lfn_collect(const u8 *entry, u16 *lfn_name, u32 unit_count)
{
    static const u8 char_offsets[13] = {
        1u, 3u, 5u, 7u, 9u, 14u, 16u, 18u, 20u, 22u, 24u, 28u, 30u
    };
    u32 ordinal = (u32)(entry[0] & 0x1Fu);
    u32 slot;
    u32 target;
    u32 value;

    if ((entry[0] & 0x40u) != 0u)
    {
        mmio64_fat32_lfn_clear(lfn_name, unit_count);
    }

    if ((ordinal == 0u) || (((ordinal - 1u) * 13u) >= unit_count))
    {
        return;
    }

    for (slot = 0u; slot < 13u; ++slot)
    {
        target = ((ordinal - 1u) * 13u) + slot;
        if (target >= (unit_count - 1u))
        {
            return;
        }

        value = mmio64_read_u16(entry, char_offsets[slot]);
        if (value == 0x0000u)
        {
            lfn_name[target] = 0u;
            return;
        }
        if (value == 0xFFFFu)
        {
            continue;
        }

        lfn_name[target] = (u16)value;
    }
}

static u32 mmio64_utf8_decode(
    const u8 *bytes,
    u32 byte_count,
    u32 *offset,
    u32 *codepoint)
{
    u32 b0;
    u32 b1;
    u32 b2;
    u32 b3;

    if (*offset >= byte_count)
    {
        return 0u;
    }

    b0 = bytes[*offset];
    if (b0 < 0x80u)
    {
        *codepoint = b0;
        *offset += 1u;
        return 1u;
    }
    if (((b0 & 0xE0u) == 0xC0u) && ((*offset + 1u) < byte_count))
    {
        b1 = bytes[*offset + 1u];
        if ((b1 & 0xC0u) != 0x80u)
        {
            return 0u;
        }
        *codepoint = ((b0 & 0x1Fu) << 6) | (b1 & 0x3Fu);
        if (*codepoint < 0x80u)
        {
            return 0u;
        }
        *offset += 2u;
        return 1u;
    }
    if (((b0 & 0xF0u) == 0xE0u) && ((*offset + 2u) < byte_count))
    {
        b1 = bytes[*offset + 1u];
        b2 = bytes[*offset + 2u];
        if (((b1 & 0xC0u) != 0x80u) || ((b2 & 0xC0u) != 0x80u))
        {
            return 0u;
        }
        *codepoint = ((b0 & 0x0Fu) << 12) | ((b1 & 0x3Fu) << 6) | (b2 & 0x3Fu);
        if ((*codepoint < 0x800u) || ((*codepoint >= 0xD800u) && (*codepoint <= 0xDFFFu)))
        {
            return 0u;
        }
        *offset += 3u;
        return 1u;
    }
    if (((b0 & 0xF8u) == 0xF0u) && ((*offset + 3u) < byte_count))
    {
        b1 = bytes[*offset + 1u];
        b2 = bytes[*offset + 2u];
        b3 = bytes[*offset + 3u];
        if (((b1 & 0xC0u) != 0x80u)
            || ((b2 & 0xC0u) != 0x80u)
            || ((b3 & 0xC0u) != 0x80u))
        {
            return 0u;
        }
        *codepoint = ((b0 & 0x07u) << 18)
            | ((b1 & 0x3Fu) << 12)
            | ((b2 & 0x3Fu) << 6)
            | (b3 & 0x3Fu);
        if ((*codepoint < 0x10000u) || (*codepoint > 0x10FFFFu))
        {
            return 0u;
        }
        *offset += 4u;
        return 1u;
    }

    return 0u;
}

static u32 mmio64_fat32_lfn_unit_matches(u16 stored, u32 codepoint)
{
    if ((stored >= (u16)'a') && (stored <= (u16)'z'))
    {
        stored = (u16)(stored - 32u);
    }
    if ((codepoint >= (u32)'a') && (codepoint <= (u32)'z'))
    {
        codepoint -= 32u;
    }

    return ((u32)stored == codepoint) ? 1u : 0u;
}

static u32 mmio64_fat32_lfn_matches(
    const u16 *lfn_name,
    const u8 *component,
    u32 component_length)
{
    u32 unit_index = 0u;
    u32 offset = 0u;
    u32 codepoint;
    u32 high;
    u32 low;

    while (offset < component_length)
    {
        if (mmio64_utf8_decode(component, component_length, &offset, &codepoint) == 0u)
        {
            return 0u;
        }
        if (codepoint <= 0xFFFFu)
        {
            if ((unit_index >= 95u)
                || (mmio64_fat32_lfn_unit_matches(lfn_name[unit_index], codepoint) == 0u))
            {
                return 0u;
            }
            ++unit_index;
            continue;
        }

        codepoint -= 0x10000u;
        high = 0xD800u + (codepoint >> 10);
        low = 0xDC00u + (codepoint & 0x3FFu);
        if ((unit_index + 1u) >= 95u)
        {
            return 0u;
        }
        if (((u32)lfn_name[unit_index] != high)
            || ((u32)lfn_name[unit_index + 1u] != low))
        {
            return 0u;
        }
        unit_index += 2u;
    }

    return ((unit_index < 96u) && (lfn_name[unit_index] == 0u)) ? 1u : 0u;
}

static void mmio64_nvme_fat_zero_stat(mmio64_nvme_fat_stat_t *stat_out)
{
    if (stat_out == (mmio64_nvme_fat_stat_t *)0)
    {
        return;
    }

    stat_out->entry_type = MMIO64_NVME_FAT_DIRENT_TYPE_UNKNOWN;
    stat_out->attr = 0u;
    stat_out->cluster = 0u;
    stat_out->byte_count = 0u;
}

static void mmio64_nvme_fat_zero_dirent(mmio64_nvme_fat_dirent_t *entry_out)
{
    u32 index;

    if (entry_out == (mmio64_nvme_fat_dirent_t *)0)
    {
        return;
    }

    entry_out->entry_type = MMIO64_NVME_FAT_DIRENT_TYPE_UNKNOWN;
    entry_out->attr = 0u;
    entry_out->cluster = 0u;
    entry_out->byte_count = 0u;
    entry_out->next_cursor = 0u;
    entry_out->name_byte_count = 0u;
    for (index = 0u; index < MMIO64_NVME_FAT_DIRENT_NAME_MAX; ++index)
    {
        entry_out->name[index] = 0u;
    }
}

static u32 mmio64_fat32_entry_type_from_attr(u32 attr)
{
    return ((attr & 0x10u) != 0u)
        ? MMIO64_NVME_FAT_DIRENT_TYPE_DIRECTORY
        : MMIO64_NVME_FAT_DIRENT_TYPE_FILE;
}

static u32 mmio64_fat32_lfn_to_utf8(
    const u16 *lfn_name,
    u8 *name_out,
    u32 name_capacity,
    u32 *name_bytes_out)
{
    u32 unit_index = 0u;
    u32 output = 0u;
    u32 codepoint;
    u32 high;
    u32 low;

    if (name_bytes_out != (u32 *)0)
    {
        *name_bytes_out = 0u;
    }
    if ((lfn_name == (const u16 *)0)
        || (name_out == (u8 *)0)
        || (name_bytes_out == (u32 *)0)
        || (name_capacity == 0u))
    {
        return 0u;
    }

    while ((unit_index < 96u) && (lfn_name[unit_index] != 0u))
    {
        codepoint = (u32)lfn_name[unit_index++];
        if ((codepoint >= 0xD800u) && (codepoint <= 0xDBFFu))
        {
            if ((unit_index >= 96u) || (lfn_name[unit_index] == 0u))
            {
                return 0u;
            }
            high = codepoint - 0xD800u;
            low = (u32)lfn_name[unit_index++];
            if ((low < 0xDC00u) || (low > 0xDFFFu))
            {
                return 0u;
            }
            codepoint = 0x10000u + ((high << 10) | (low - 0xDC00u));
        }
        else if ((codepoint >= 0xDC00u) && (codepoint <= 0xDFFFu))
        {
            return 0u;
        }

        if (codepoint <= 0x7Fu)
        {
            if (output >= name_capacity)
            {
                return 0u;
            }
            name_out[output++] = (u8)codepoint;
        }
        else if (codepoint <= 0x7FFu)
        {
            if ((output + 2u) > name_capacity)
            {
                return 0u;
            }
            name_out[output++] = (u8)(0xC0u | (codepoint >> 6));
            name_out[output++] = (u8)(0x80u | (codepoint & 0x3Fu));
        }
        else if (codepoint <= 0xFFFFu)
        {
            if ((output + 3u) > name_capacity)
            {
                return 0u;
            }
            name_out[output++] = (u8)(0xE0u | (codepoint >> 12));
            name_out[output++] = (u8)(0x80u | ((codepoint >> 6) & 0x3Fu));
            name_out[output++] = (u8)(0x80u | (codepoint & 0x3Fu));
        }
        else if (codepoint <= 0x10FFFFu)
        {
            if ((output + 4u) > name_capacity)
            {
                return 0u;
            }
            name_out[output++] = (u8)(0xF0u | (codepoint >> 18));
            name_out[output++] = (u8)(0x80u | ((codepoint >> 12) & 0x3Fu));
            name_out[output++] = (u8)(0x80u | ((codepoint >> 6) & 0x3Fu));
            name_out[output++] = (u8)(0x80u | (codepoint & 0x3Fu));
        }
        else
        {
            return 0u;
        }
    }

    *name_bytes_out = output;
    return (output != 0u) ? 1u : 0u;
}

static u32 mmio64_fat32_short_name_to_display(
    const u8 *entry,
    u8 *name_out,
    u32 name_capacity,
    u32 *name_bytes_out)
{
    u32 index;
    u32 length = 0u;
    u32 base_end = 8u;
    u32 ext_end = 11u;

    if (name_bytes_out != (u32 *)0)
    {
        *name_bytes_out = 0u;
    }
    if ((entry == (const u8 *)0)
        || (name_out == (u8 *)0)
        || (name_bytes_out == (u32 *)0)
        || (name_capacity == 0u))
    {
        return 0u;
    }

    while ((base_end > 0u) && (entry[base_end - 1u] == (u8)' '))
    {
        --base_end;
    }
    while ((ext_end > 8u) && (entry[ext_end - 1u] == (u8)' '))
    {
        --ext_end;
    }

    for (index = 0u; index < base_end; ++index)
    {
        if (length >= name_capacity)
        {
            return 0u;
        }
        name_out[length++] = mmio64_ascii_lower(entry[index]);
    }
    if (ext_end > 8u)
    {
        if (length >= name_capacity)
        {
            return 0u;
        }
        name_out[length++] = (u8)'.';
        for (index = 8u; index < ext_end; ++index)
        {
            if (length >= name_capacity)
            {
                return 0u;
            }
            name_out[length++] = mmio64_ascii_lower(entry[index]);
        }
    }

    *name_bytes_out = length;
    return (length != 0u) ? 1u : 0u;
}

static u32 mmio64_fat32_fill_dirent(
    const u8 *entry,
    const u16 *lfn_name,
    u32 cursor,
    mmio64_nvme_fat_dirent_t *entry_out)
{
    u32 index;
    u32 attr;
    u32 name_bytes = 0u;

    if ((entry == (const u8 *)0) || (entry_out == (mmio64_nvme_fat_dirent_t *)0))
    {
        return 0u;
    }

    mmio64_nvme_fat_zero_dirent(entry_out);
    attr = (u32)entry[11u];
    if ((lfn_name != (const u16 *)0)
        && (lfn_name[0] != 0u)
        && (mmio64_fat32_lfn_to_utf8(
                lfn_name,
                entry_out->name,
                MMIO64_NVME_FAT_DIRENT_NAME_MAX - 1u,
                &name_bytes) != 0u))
    {
        entry_out->name_byte_count = name_bytes;
    }
    else if (mmio64_fat32_short_name_to_display(
            entry,
            entry_out->name,
            MMIO64_NVME_FAT_DIRENT_NAME_MAX - 1u,
            &name_bytes) != 0u)
    {
        entry_out->name_byte_count = name_bytes;
    }
    else
    {
        return 0u;
    }

    for (index = entry_out->name_byte_count; index < MMIO64_NVME_FAT_DIRENT_NAME_MAX; ++index)
    {
        entry_out->name[index] = 0u;
    }
    entry_out->entry_type = mmio64_fat32_entry_type_from_attr(attr);
    entry_out->attr = attr;
    entry_out->cluster =
        (mmio64_read_u16(entry, 20u) << 16)
        | mmio64_read_u16(entry, 26u);
    entry_out->byte_count = mmio64_read_u32(entry, 28u);
    entry_out->next_cursor = cursor + 1u;
    return 1u;
}

static u32 mmio64_fat32_read_directory_entry(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    u32 directory_cluster,
    u32 cursor,
    mmio64_nvme_fat_dirent_t *entry_out)
{
    u16 lfn_name[96];
    u32 cluster = directory_cluster;
    u32 next_cluster;
    u32 visited;
    u32 lba;
    u32 lba_index;
    u32 entry_offset;
    u32 attr;
    u32 visible_cursor = 0u;

    if ((reader == (Mmio64NvmeFatReader *)0)
        || (volume == (const Mmio64Fat32Volume *)0)
        || (entry_out == (mmio64_nvme_fat_dirent_t *)0)
        || (directory_cluster < 2u))
    {
        return 0u;
    }

    mmio64_nvme_fat_zero_dirent(entry_out);
    mmio64_fat32_lfn_clear(lfn_name, 96u);
    for (visited = 0u; visited < MMIO64_FAT32_CLUSTER_VISIT_LIMIT; ++visited)
    {
        if (mmio64_fat32_cluster_lba(volume, cluster, &lba) == 0u)
        {
            return 0u;
        }

        for (lba_index = 0u; lba_index < volume->lbas_per_cluster; ++lba_index)
        {
            if (mmio64_nvme_fat_read_lba(
                    reader,
                    lba + lba_index,
                    MMIO64_NVME_FAT_READ_ROOT_CID) == 0u)
            {
                return 0u;
            }

            for (entry_offset = 0u; entry_offset < 512u; entry_offset += 32u)
            {
                if (g_nvme_io_data_buffer[entry_offset] == 0u)
                {
                    return MMIO64_NVME_FAT_READDIR_EOF;
                }

                attr = (u32)g_nvme_io_data_buffer[entry_offset + 11u];
                if (g_nvme_io_data_buffer[entry_offset] == 0xE5u)
                {
                    mmio64_fat32_lfn_clear(lfn_name, 96u);
                    continue;
                }
                if ((attr & 0x0Fu) == 0x0Fu)
                {
                    mmio64_fat32_lfn_collect(
                        g_nvme_io_data_buffer + entry_offset,
                        lfn_name,
                        96u);
                    continue;
                }
                if ((attr & 0x08u) != 0u)
                {
                    mmio64_fat32_lfn_clear(lfn_name, 96u);
                    continue;
                }

                if (visible_cursor == cursor)
                {
                    return (mmio64_fat32_fill_dirent(
                            g_nvme_io_data_buffer + entry_offset,
                            lfn_name,
                            cursor,
                            entry_out) != 0u)
                        ? MMIO64_NVME_FAT_READDIR_OK
                        : 0u;
                }

                ++visible_cursor;
                mmio64_fat32_lfn_clear(lfn_name, 96u);
            }
        }

        if (mmio64_fat32_next_cluster(reader, volume, cluster, &next_cluster) == 0u)
        {
            return 0u;
        }
        if (next_cluster >= 0x0FFFFFF8u)
        {
            return MMIO64_NVME_FAT_READDIR_EOF;
        }
        cluster = next_cluster;
    }

    return 0u;
}

static u32 mmio64_fat32_next_cluster(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    u32 cluster,
    u32 *next_cluster)
{
    u64 fat_byte_offset = ((u64)volume->reserved_sectors * (u64)volume->bytes_per_sector)
        + ((u64)cluster * 4ull);
    u64 lba = (u64)volume->partition_start_lba + (fat_byte_offset / 512ull);
    u32 sector_offset = (u32)(fat_byte_offset % 512ull);

    if ((lba > 0xFFFFFFFFull) || ((sector_offset + 4u) > 512u))
    {
        return 0u;
    }
    if (mmio64_nvme_fat_read_lba(
            reader,
            (u32)lba,
            MMIO64_NVME_FAT_READ_TABLE_CID) == 0u)
    {
        return 0u;
    }

    *next_cluster = mmio64_read_u32(g_nvme_io_data_buffer, sector_offset)
        & 0x0FFFFFFFu;
    return 1u;
}

static u32 mmio64_fat32_find_in_directory(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    u32 directory_cluster,
    const u8 *component,
    u32 component_length,
    u32 *entry_cluster,
    u32 *entry_size,
    u32 *entry_attr,
    Mmio64Fat32EntryLocation *location)
{
    u16 lfn_name[96];
    u32 cluster = directory_cluster;
    u32 next_cluster;
    u32 visited;
    u32 lba;
    u32 lba_index;
    u32 entry_offset;
    u32 attr;
    u32 matched;
    u32 lfn_lba = 0u;
    u32 lfn_offset = 0u;
    u32 lfn_entries = 0u;
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    u32 slot_index = 0u;
    u32 lfn_start_slot = 0u;
#endif

    mmio64_fat32_lfn_clear(lfn_name, 96u);
    for (visited = 0u; visited < MMIO64_FAT32_CLUSTER_VISIT_LIMIT; ++visited)
    {
        if (mmio64_fat32_cluster_lba(volume, cluster, &lba) == 0u)
        {
            return 0u;
        }

        for (lba_index = 0u; lba_index < volume->lbas_per_cluster; ++lba_index)
        {
            if (mmio64_nvme_fat_read_lba(
                    reader,
                    lba + lba_index,
                    MMIO64_NVME_FAT_READ_ROOT_CID) == 0u)
            {
                return 0u;
            }

            for (entry_offset = 0u; entry_offset < 512u; entry_offset += 32u)
            {
                if (g_nvme_io_data_buffer[entry_offset] == 0u)
                {
                    return 0u;
                }

                attr = (u32)g_nvme_io_data_buffer[entry_offset + 11u];
                if (g_nvme_io_data_buffer[entry_offset] == 0xE5u)
                {
                    mmio64_fat32_lfn_clear(lfn_name, 96u);
                    lfn_lba = 0u;
                    lfn_offset = 0u;
                    lfn_entries = 0u;
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
                    lfn_start_slot = 0u;
                    ++slot_index;
#endif
                    continue;
                }
                if ((attr & 0x0Fu) == 0x0Fu)
                {
                    if (lfn_entries == 0u)
                    {
                        lfn_lba = lba + lba_index;
                        lfn_offset = entry_offset;
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
                        lfn_start_slot = slot_index;
#endif
                    }
                    ++lfn_entries;
                    mmio64_fat32_lfn_collect(
                        g_nvme_io_data_buffer + entry_offset,
                        lfn_name,
                        96u);
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
                    ++slot_index;
#endif
                    continue;
                }

                matched = mmio64_fat32_lfn_matches(
                        lfn_name,
                        component,
                        component_length)
                    || mmio64_fat32_short_name_matches(
                        g_nvme_io_data_buffer + entry_offset,
                        component,
                        component_length);
                if (matched != 0u)
                {
                    *entry_cluster =
                        (mmio64_read_u16(g_nvme_io_data_buffer, entry_offset + 20u) << 16)
                        | mmio64_read_u16(g_nvme_io_data_buffer, entry_offset + 26u);
                    *entry_size = mmio64_read_u32(g_nvme_io_data_buffer, entry_offset + 28u);
                    *entry_attr = attr;
                    if (location != (Mmio64Fat32EntryLocation *)0)
                    {
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
                        location->directory_cluster = directory_cluster;
#endif
                        location->cluster = *entry_cluster;
                        location->size = *entry_size;
                        location->attr = attr;
                        location->entry_lba = lba + lba_index;
                        location->entry_offset = entry_offset;
                        location->lfn_lba = lfn_lba;
                        location->lfn_offset = lfn_offset;
                        location->lfn_entries = lfn_entries;
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
                        location->lfn_start_slot = (lfn_entries != 0u) ? lfn_start_slot : slot_index;
                        location->entry_slot = slot_index;
#endif
                    }
                    return 1u;
                }

                mmio64_fat32_lfn_clear(lfn_name, 96u);
                lfn_lba = 0u;
                lfn_offset = 0u;
                lfn_entries = 0u;
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
                lfn_start_slot = 0u;
                ++slot_index;
#endif
            }
        }

        if (mmio64_fat32_next_cluster(reader, volume, cluster, &next_cluster) == 0u)
        {
            return 0u;
        }
        if (next_cluster >= 0x0FFFFFF8u)
        {
            break;
        }
        cluster = next_cluster;
    }

    return 0u;
}

static u32 mmio64_fat32_find_path(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    const u8 *path,
    u32 *entry_cluster,
    u32 *entry_size,
    u32 *entry_attr)
{
    u32 cursor = 0u;
    u32 component_start;
    u32 component_length;
    u32 current_cluster = volume->root_cluster;
    u32 found_cluster = 0u;
    u32 found_size = 0u;
    u32 found_attr = 0u;
    u32 more_components;

    while (mmio64_iso9660_next_component(
            path,
            &cursor,
            &component_start,
            &component_length) != 0u)
    {
        if (mmio64_fat32_find_in_directory(
                reader,
                volume,
                current_cluster,
                path + component_start,
                component_length,
                &found_cluster,
                &found_size,
                &found_attr,
                (Mmio64Fat32EntryLocation *)0) == 0u)
        {
            return 0u;
        }

        more_components = (path[cursor] != 0u) ? 1u : 0u;
        if (more_components != 0u)
        {
            if (((found_attr & 0x10u) == 0u) || (found_cluster < 2u))
            {
                return 0u;
            }
            current_cluster = found_cluster;
        }
        else
        {
            *entry_cluster = found_cluster;
            *entry_size = found_size;
            *entry_attr = found_attr;
            return 1u;
        }
    }

    return 0u;
}

static u32 mmio64_fat32_find_path_location(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    const u8 *path,
    Mmio64Fat32EntryLocation *location)
{
    u32 cursor = 0u;
    u32 component_start;
    u32 component_length;
    u32 current_cluster = volume->root_cluster;
    u32 found_cluster = 0u;
    u32 found_size = 0u;
    u32 found_attr = 0u;
    u32 more_components;

    while (mmio64_iso9660_next_component(
            path,
            &cursor,
            &component_start,
            &component_length) != 0u)
    {
        if (mmio64_fat32_find_in_directory(
                reader,
                volume,
                current_cluster,
                path + component_start,
                component_length,
                &found_cluster,
                &found_size,
                &found_attr,
                location) == 0u)
        {
            return 0u;
        }

        more_components = (path[cursor] != 0u) ? 1u : 0u;
        if (more_components != 0u)
        {
            if (((found_attr & 0x10u) == 0u) || (found_cluster < 2u))
            {
                return 0u;
            }
            current_cluster = found_cluster;
        }
        else
        {
            return 1u;
        }
    }

    return 0u;
}

static u32 mmio64_fat32_read_file_crc(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    u32 start_cluster,
    u32 file_size,
    u32 *bytes_read,
    u32 *checksum)
{
    u32 cluster = start_cluster;
    u32 next_cluster;
    u32 remaining = file_size;
    u32 lba;
    u32 lba_index;
    u32 take;
    u32 visited;
    u32 crc = 0xFFFFFFFFu;

    *bytes_read = 0u;
    *checksum = 0u;
    if ((start_cluster < 2u) || (file_size == 0u))
    {
        return 0u;
    }

    for (visited = 0u;
        (remaining != 0u) && (visited < MMIO64_FAT32_CLUSTER_VISIT_LIMIT);
        ++visited)
    {
        if (mmio64_fat32_cluster_lba(volume, cluster, &lba) == 0u)
        {
            return 0u;
        }

        for (lba_index = 0u;
            (lba_index < volume->lbas_per_cluster) && (remaining != 0u);
            ++lba_index)
        {
            if (mmio64_nvme_fat_read_lba(
                    reader,
                    lba + lba_index,
                    MMIO64_NVME_FAT_READ_DATA_CID) == 0u)
            {
                return 0u;
            }

            take = (remaining < 512u) ? remaining : 512u;
            crc = mmio64_crc32_update(crc, g_nvme_io_data_buffer, take);
            *bytes_read += take;
            remaining -= take;
        }

        if (remaining != 0u)
        {
            if (mmio64_fat32_next_cluster(reader, volume, cluster, &next_cluster) == 0u)
            {
                return 0u;
            }
            if (next_cluster >= 0x0FFFFFF8u)
            {
                return 0u;
            }
            cluster = next_cluster;
        }
    }

    if (remaining != 0u)
    {
        return 0u;
    }

    *checksum = crc ^ 0xFFFFFFFFu;
    return 1u;
}

static u32 mmio64_nvme_fat_verify_file(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    const u8 *path,
    u32 expected_bytes,
    u32 expected_crc,
    u32 *bytes_read,
    u32 *checksum)
{
    u32 cluster = 0u;
    u32 size = 0u;
    u32 attr = 0u;

    if (mmio64_fat32_find_path(reader, volume, path, &cluster, &size, &attr) == 0u)
    {
        return 0u;
    }
    if (((attr & 0x10u) != 0u) || (size != expected_bytes))
    {
        return 0u;
    }
    if (mmio64_fat32_read_file_crc(
            reader,
            volume,
            cluster,
            size,
            bytes_read,
            checksum) == 0u)
    {
        return 0u;
    }

    return (*checksum == expected_crc) ? 1u : 0u;
}

static u32 mmio64_fat32_read_file_bytes(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    u32 start_cluster,
    u32 file_size,
    u8 *destination,
    u32 byte_capacity,
    u32 *bytes_read,
    u32 *checksum)
{
    u32 cluster = start_cluster;
    u32 next_cluster;
    u32 remaining = file_size;
    u32 lba;
    u32 lba_index;
    u32 take;
    u32 copied = 0u;
    u32 visited;
    u32 crc = 0xFFFFFFFFu;
    u32 index;

    *bytes_read = 0u;
    *checksum = 0u;
    if ((file_size > byte_capacity)
        || ((file_size != 0u) && (start_cluster < 2u)))
    {
        return 0u;
    }

    for (visited = 0u;
        (remaining != 0u) && (visited < MMIO64_FAT32_READ_CLUSTER_VISIT_LIMIT);
        ++visited)
    {
        if (mmio64_fat32_cluster_lba(volume, cluster, &lba) == 0u)
        {
            return 0u;
        }

        for (lba_index = 0u;
            (lba_index < volume->lbas_per_cluster) && (remaining != 0u);
            ++lba_index)
        {
            if (mmio64_nvme_fat_read_lba(
                    reader,
                    lba + lba_index,
                    MMIO64_NVME_FAT_READ_DATA_CID) == 0u)
            {
                return 0u;
            }

            take = (remaining < 512u) ? remaining : 512u;
            crc = mmio64_crc32_update(crc, g_nvme_io_data_buffer, take);
            if (destination != (u8 *)0)
            {
                for (index = 0u; index < take; ++index)
                {
                    destination[copied + index] = g_nvme_io_data_buffer[index];
                }
            }
            copied += take;
            remaining -= take;
        }

        if (remaining != 0u)
        {
            if (mmio64_fat32_next_cluster(reader, volume, cluster, &next_cluster) == 0u)
            {
                return 0u;
            }
            if (next_cluster >= 0x0FFFFFF8u)
            {
                return 0u;
            }
            cluster = next_cluster;
        }
    }

    if (remaining != 0u)
    {
        return 0u;
    }

    *bytes_read = copied;
    *checksum = crc ^ 0xFFFFFFFFu;
    return 1u;
}

#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
static u32 mmio64_fat32_read_file_range_bytes(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    u32 start_cluster,
    u32 file_size,
    u32 file_offset,
    u8 *destination,
    u32 byte_capacity,
    u32 *bytes_read,
    u32 *checksum)
{
    u32 cluster = start_cluster;
    u32 next_cluster;
    u32 remaining = file_size;
    u32 lba;
    u32 lba_index;
    u32 sector_start = 0u;
    u32 sector_end;
    u32 wanted_end;
    u32 copy_start;
    u32 copy_end;
    u32 source_offset;
    u32 take;
    u32 sector_take;
    u32 copied = 0u;
    u32 copy_goal;
    u32 visited;
    u32 crc = 0xFFFFFFFFu;
    u32 index;

    *bytes_read = 0u;
    *checksum = 0u;
    if ((destination == (u8 *)0)
        || (byte_capacity == 0u)
        || ((file_size != 0u) && (start_cluster < 2u))
        || (file_offset > file_size))
    {
        return 0u;
    }

    copy_goal = file_size - file_offset;
    if (copy_goal > byte_capacity)
    {
        copy_goal = byte_capacity;
    }
    if (copy_goal == 0u)
    {
        *checksum = crc ^ 0xFFFFFFFFu;
        return 1u;
    }

    wanted_end = file_offset + copy_goal;
    if (wanted_end < file_offset)
    {
        return 0u;
    }

    for (visited = 0u;
        (remaining != 0u) && (visited < MMIO64_FAT32_READ_CLUSTER_VISIT_LIMIT);
        ++visited)
    {
        if (mmio64_fat32_cluster_lba(volume, cluster, &lba) == 0u)
        {
            return 0u;
        }

        for (lba_index = 0u;
            (lba_index < volume->lbas_per_cluster) && (remaining != 0u);
            ++lba_index)
        {
            if (mmio64_nvme_fat_read_lba(
                    reader,
                    lba + lba_index,
                    MMIO64_NVME_FAT_READ_DATA_CID) == 0u)
            {
                return 0u;
            }

            sector_take = (remaining < 512u) ? remaining : 512u;
            sector_end = sector_start + sector_take;
            if ((sector_end > file_offset) && (sector_start < wanted_end))
            {
                copy_start = (file_offset > sector_start) ? file_offset : sector_start;
                copy_end = (wanted_end < sector_end) ? wanted_end : sector_end;
                source_offset = copy_start - sector_start;
                take = copy_end - copy_start;
                crc = mmio64_crc32_update(crc, &g_nvme_io_data_buffer[source_offset], take);
                for (index = 0u; index < take; ++index)
                {
                    destination[copied + index] = g_nvme_io_data_buffer[source_offset + index];
                }
                copied += take;
                if (copied == copy_goal)
                {
                    *bytes_read = copied;
                    *checksum = crc ^ 0xFFFFFFFFu;
                    return 1u;
                }
            }

            sector_start = sector_end;
            remaining -= sector_take;
        }

        if (remaining != 0u)
        {
            if (mmio64_fat32_next_cluster(reader, volume, cluster, &next_cluster) == 0u)
            {
                return 0u;
            }
            if (next_cluster >= 0x0FFFFFF8u)
            {
                return 0u;
            }
            cluster = next_cluster;
        }
    }

    *bytes_read = copied;
    *checksum = crc ^ 0xFFFFFFFFu;
    return (copied == copy_goal) ? 1u : 0u;
}
#endif

static u32 mmio64_nvme_fat_read_path_bytes_detailed(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    const u8 *path,
    u8 *destination,
    u32 byte_capacity,
    u32 *bytes_read,
    u32 *checksum,
    u32 *size_out,
    u32 *attr_out,
    u32 *error_out)
{
    u32 cluster = 0u;
    u32 size = 0u;
    u32 attr = 0u;

    if (size_out != (u32 *)0)
    {
        *size_out = 0u;
    }
    if (attr_out != (u32 *)0)
    {
        *attr_out = 0u;
    }
    if (error_out != (u32 *)0)
    {
        *error_out = MMIO64_NVME_FAT_SHELL_READ_ERROR_NONE;
    }

    if (mmio64_fat32_find_path(reader, volume, path, &cluster, &size, &attr) == 0u)
    {
        if (error_out != (u32 *)0)
        {
            *error_out = MMIO64_NVME_FAT_SHELL_READ_ERROR_NOT_FOUND;
        }
        return 0u;
    }
    if (size_out != (u32 *)0)
    {
        *size_out = size;
    }
    if (attr_out != (u32 *)0)
    {
        *attr_out = attr;
    }
    if ((attr & 0x10u) != 0u)
    {
        if (error_out != (u32 *)0)
        {
            *error_out = MMIO64_NVME_FAT_SHELL_READ_ERROR_DIRECTORY;
        }
        return 0u;
    }
    if (size > byte_capacity)
    {
        if (error_out != (u32 *)0)
        {
            *error_out = MMIO64_NVME_FAT_SHELL_READ_ERROR_TOO_LARGE;
        }
        return 0u;
    }

    if (mmio64_fat32_read_file_bytes(
            reader,
            volume,
            cluster,
            size,
            destination,
            byte_capacity,
            bytes_read,
            checksum) == 0u)
    {
        if (error_out != (u32 *)0)
        {
            *error_out = MMIO64_NVME_FAT_SHELL_READ_ERROR_READ_CHAIN;
        }
        return 0u;
    }

    return 1u;
}

static u32 mmio64_nvme_fat_read_path_bytes(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    const u8 *path,
    u8 *destination,
    u32 byte_capacity,
    u32 *bytes_read,
    u32 *checksum)
{
    return mmio64_nvme_fat_read_path_bytes_detailed(
        reader,
        volume,
        path,
        destination,
        byte_capacity,
        bytes_read,
        checksum,
        (u32 *)0,
        (u32 *)0,
        (u32 *)0);
}

