static u32 mmio64_fat32_cluster_limit(const Mmio64Fat32Volume *volume)
{
    u32 data_sectors;

    if (volume->total_sectors <= volume->data_sector_base)
    {
        return 0u;
    }

    data_sectors = volume->total_sectors - volume->data_sector_base;
    return (data_sectors / volume->sectors_per_cluster) + 2u;
}

static u32 mmio64_fat32_write_fat_entry(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    u32 cluster,
    u32 value)
{
    u32 fat_index;
    u64 fat_byte_offset;
    u64 lba;
    u32 sector_offset;

    for (fat_index = 0u; fat_index < volume->fat_count; ++fat_index)
    {
        fat_byte_offset =
            ((u64)volume->reserved_sectors
                + ((u64)fat_index * (u64)volume->sectors_per_fat))
                * (u64)volume->bytes_per_sector;
        fat_byte_offset += (u64)cluster * 4ull;
        lba = (u64)volume->partition_start_lba + (fat_byte_offset / 512ull);
        sector_offset = (u32)(fat_byte_offset % 512ull);
        if ((lba > 0xFFFFFFFFull) || ((sector_offset + 4u) > 512u))
        {
            return 0u;
        }
        if (mmio64_nvme_fat_read_lba(
                reader,
                (u32)lba,
                MMIO64_NVME_FAT_READ_TABLE_CID) == 0u)
        {
            return 0u;
        }

        mmio64_write_u32(g_nvme_io_data_buffer, sector_offset, value);
        if (mmio64_nvme_fat_write_lba(
                reader,
                (u32)lba,
                MMIO64_NVME_FAT_WRITE_TABLE_CID) == 0u)
        {
            return 0u;
        }
    }

    return 1u;
}

static u32 mmio64_fat32_find_free_cluster(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    u32 first_candidate,
    u32 *cluster_out)
{
    u32 cluster_limit = mmio64_fat32_cluster_limit(volume);
    u32 cluster;
    u32 next_cluster;

    if ((cluster_limit <= 2u) || (first_candidate < 2u))
    {
        return 0u;
    }

    for (cluster = first_candidate; cluster < cluster_limit; ++cluster)
    {
        if (mmio64_fat32_next_cluster(reader, volume, cluster, &next_cluster) == 0u)
        {
            return 0u;
        }
        if (next_cluster == 0u)
        {
            *cluster_out = cluster;
            return 1u;
        }
    }

    return 0u;
}

static u32 mmio64_fat32_find_free_dir_entries(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    u32 directory_cluster,
    u32 needed_entries,
    u32 *entry_lba,
    u32 *entry_offset)
{
    u32 cluster = directory_cluster;
    u32 next_cluster;
    u32 visited;
    u32 lba;
    u32 lba_index;
    u32 offset;
    u32 run_count = 0u;
    u32 run_lba = 0u;
    u32 run_offset = 0u;
    u8 first;
    u32 free_entry;

    for (visited = 0u; visited < MMIO64_FAT32_CLUSTER_VISIT_LIMIT; ++visited)
    {
        if (mmio64_fat32_cluster_lba(volume, cluster, &lba) == 0u)
        {
            return 0u;
        }
        for (lba_index = 0u; lba_index < volume->lbas_per_cluster; ++lba_index)
        {
            if (mmio64_nvme_fat_read_lba(
                    reader,
                    lba + lba_index,
                    MMIO64_NVME_FAT_READ_ROOT_CID) == 0u)
            {
                return 0u;
            }

            run_count = 0u;
            for (offset = 0u; offset < 512u; offset += 32u)
            {
                first = g_nvme_io_data_buffer[offset];
                free_entry = ((first == 0u) || (first == 0xE5u)) ? 1u : 0u;
                if (free_entry != 0u)
                {
                    if (run_count == 0u)
                    {
                        run_lba = lba + lba_index;
                        run_offset = offset;
                    }
                    ++run_count;
                    if (run_count >= needed_entries)
                    {
                        *entry_lba = run_lba;
                        *entry_offset = run_offset;
                        return 1u;
                    }
                }
                else
                {
                    run_count = 0u;
                }
            }
        }

        if (mmio64_fat32_next_cluster(reader, volume, cluster, &next_cluster) == 0u)
        {
            return 0u;
        }
        if (next_cluster >= 0x0FFFFFF8u)
        {
            break;
        }
        cluster = next_cluster;
    }

    return 0u;
}

static u8 mmio64_fat32_lfn_checksum(const u8 *short_name)
{
    u32 index;
    u32 sum = 0u;

    for (index = 0u; index < 11u; ++index)
    {
        sum = (((sum & 1u) << 7) + (sum >> 1) + (u32)short_name[index]) & 0xFFu;
    }

    return (u8)sum;
}

static void mmio64_fat32_write_dir_entry(
    u8 *sector,
    u32 offset,
    const u8 *short_name,
    u32 attr,
    u32 start_cluster,
    u32 size)
{
    u32 index;

    for (index = 0u; index < 32u; ++index)
    {
        sector[offset + index] = 0u;
    }
    for (index = 0u; index < 11u; ++index)
    {
        sector[offset + index] = short_name[index];
    }
    sector[offset + 11u] = (u8)attr;
    mmio64_write_u16(sector, offset + 20u, (start_cluster >> 16) & 0xFFFFu);
    mmio64_write_u16(sector, offset + 26u, start_cluster & 0xFFFFu);
    mmio64_write_u32(sector, offset + 28u, size);
}

static void mmio64_fat32_write_lfn_entry_ascii(
    u8 *sector,
    u32 offset,
    u32 ordinal,
    u32 is_last,
    const u8 *name,
    u32 name_length,
    u8 checksum)
{
    static const u8 char_offsets[13] = {
        1u, 3u, 5u, 7u, 9u, 14u, 16u, 18u, 20u, 22u, 24u, 28u, 30u
    };
    u32 slot;
    u32 name_index;
    u32 value;

    for (slot = 0u; slot < 32u; ++slot)
    {
        sector[offset + slot] = 0u;
    }
    sector[offset] = (u8)(ordinal | ((is_last != 0u) ? 0x40u : 0u));
    sector[offset + 11u] = 0x0Fu;
    sector[offset + 13u] = checksum;

    for (slot = 0u; slot < 13u; ++slot)
    {
        name_index = ((ordinal - 1u) * 13u) + slot;
        if (name_index < name_length)
        {
            value = (u32)name[name_index];
        }
        else if (name_index == name_length)
        {
            value = 0u;
        }
        else
        {
            value = 0xFFFFu;
        }
        mmio64_write_u16(sector, offset + (u32)char_offsets[slot], value);
    }
}

static void mmio64_fat32_fill_create_sector(u8 *sector)
{
    static const u8 content[] = "LimitlessOS FAT32 broker-private create proof\r\n";
    u32 index;

    mmio64_zero_bytes(sector, 512u);
    for (index = 0u; index < (sizeof(content) - 1u); ++index)
    {
        sector[index] = content[index];
    }
}

static void mmio64_fat32_fill_update_sector(
    u8 *sector,
    u32 file_offset,
    u32 file_size)
{
    u32 index;
    u32 absolute;

    for (index = 0u; index < 512u; ++index)
    {
        absolute = file_offset + index;
        sector[index] = (absolute < file_size)
            ? (u8)(((absolute * 29u) + 7u) & 0xFFu)
            : 0u;
    }
}

static u32 mmio64_fat32_write_create_data(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    u32 cluster)
{
    u32 lba;

    if (mmio64_fat32_cluster_lba(volume, cluster, &lba) == 0u)
    {
        return 0u;
    }

    mmio64_fat32_fill_create_sector(g_nvme_io_data_buffer);
    return mmio64_nvme_fat_write_lba(
        reader,
        lba,
        MMIO64_NVME_FAT_WRITE_DATA_CID);
}

static u32 mmio64_fat32_write_update_data(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    u32 start_cluster,
    u32 file_size)
{
    u32 cluster = start_cluster;
    u32 next_cluster;
    u32 remaining = file_size;
    u32 file_offset = 0u;
    u32 lba;
    u32 lba_index;
    u32 visited;

    for (visited = 0u;
        (remaining != 0u) && (visited < MMIO64_FAT32_CLUSTER_VISIT_LIMIT);
        ++visited)
    {
        if (mmio64_fat32_cluster_lba(volume, cluster, &lba) == 0u)
        {
            return 0u;
        }
        for (lba_index = 0u;
            (lba_index < volume->lbas_per_cluster) && (remaining != 0u);
            ++lba_index)
        {
            mmio64_fat32_fill_update_sector(
                g_nvme_io_data_buffer,
                file_offset,
                file_size);
            if (mmio64_nvme_fat_write_lba(
                    reader,
                    lba + lba_index,
                    MMIO64_NVME_FAT_WRITE_DATA_CID) == 0u)
            {
                return 0u;
            }
            file_offset += 512u;
            remaining = (remaining > 512u) ? (remaining - 512u) : 0u;
        }
        if (remaining != 0u)
        {
            if (mmio64_fat32_next_cluster(reader, volume, cluster, &next_cluster) == 0u)
            {
                return 0u;
            }
            if (next_cluster >= 0x0FFFFFF8u)
            {
                return 0u;
            }
            cluster = next_cluster;
        }
    }

    return (remaining == 0u) ? 1u : 0u;
}

static u32 mmio64_fat32_create_lfn_file(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume)
{
    static const u8 path[] = "/Written Long Name.txt";
    static const u8 name[] = "Written Long Name.txt";
    static const u8 short_name[11] = {
        (u8)'W', (u8)'R', (u8)'I', (u8)'T', (u8)'T', (u8)'E', (u8)'~', (u8)'1',
        (u8)'T', (u8)'X', (u8)'T'
    };
    u32 cluster;
    u32 entry_lba;
    u32 entry_offset;
    u32 bytes = 0u;
    u32 checksum = 0u;
    u8 lfn_checksum;

    if (mmio64_nvme_fat_verify_file(
            reader,
            volume,
            path,
            MMIO64_NVME_FAT_EXPECTED_CREATE_BYTES,
            MMIO64_NVME_FAT_EXPECTED_CREATE_CRC32,
            &bytes,
            &checksum) != 0u)
    {
        g_nvme_fat_create_cluster = MMIO64_NVME_FAT_EXPECTED_CREATE_CLUSTER;
        g_nvme_fat_create_readback = 1u;
        g_nvme_fat_create_bytes = bytes;
        g_nvme_fat_create_checksum = checksum;
        return 1u;
    }

    if (mmio64_fat32_find_free_cluster(
            reader,
            volume,
            MMIO64_NVME_FAT_EXPECTED_CREATE_CLUSTER,
            &cluster) == 0u)
    {
        return 0u;
    }
    if (cluster != MMIO64_NVME_FAT_EXPECTED_CREATE_CLUSTER)
    {
        return 0u;
    }
    if (mmio64_fat32_write_fat_entry(reader, volume, cluster, 0x0FFFFFFFu) == 0u)
    {
        return 0u;
    }
    if (mmio64_fat32_write_create_data(reader, volume, cluster) == 0u)
    {
        return 0u;
    }
    if (mmio64_fat32_find_free_dir_entries(
            reader,
            volume,
            volume->root_cluster,
            3u,
            &entry_lba,
            &entry_offset) == 0u)
    {
        return 0u;
    }
    if (mmio64_nvme_fat_read_lba(
            reader,
            entry_lba,
            MMIO64_NVME_FAT_READ_ROOT_CID) == 0u)
    {
        return 0u;
    }

    lfn_checksum = mmio64_fat32_lfn_checksum(short_name);
    mmio64_fat32_write_lfn_entry_ascii(
        g_nvme_io_data_buffer,
        entry_offset,
        2u,
        1u,
        name,
        sizeof(name) - 1u,
        lfn_checksum);
    mmio64_fat32_write_lfn_entry_ascii(
        g_nvme_io_data_buffer,
        entry_offset + 32u,
        1u,
        0u,
        name,
        sizeof(name) - 1u,
        lfn_checksum);
    mmio64_fat32_write_dir_entry(
        g_nvme_io_data_buffer,
        entry_offset + 64u,
        short_name,
        0x20u,
        cluster,
        MMIO64_NVME_FAT_EXPECTED_CREATE_BYTES);
    if (mmio64_nvme_fat_write_lba(
            reader,
            entry_lba,
            MMIO64_NVME_FAT_WRITE_DIR_CID) == 0u)
    {
        return 0u;
    }

    if (mmio64_nvme_fat_verify_file(
            reader,
            volume,
            path,
            MMIO64_NVME_FAT_EXPECTED_CREATE_BYTES,
            MMIO64_NVME_FAT_EXPECTED_CREATE_CRC32,
            &bytes,
            &checksum) == 0u)
    {
        return 0u;
    }

    g_nvme_fat_create_cluster = cluster;
    g_nvme_fat_create_readback = 1u;
    g_nvme_fat_create_bytes = bytes;
    g_nvme_fat_create_checksum = checksum;
    return 1u;
}

static u32 mmio64_fat32_update_existing_file(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume)
{
    static const u8 path[] = "/NVME.TXT";
    Mmio64Fat32EntryLocation location;
    u32 update_cluster;
    u32 bytes = 0u;
    u32 checksum = 0u;

    if (mmio64_nvme_fat_verify_file(
            reader,
            volume,
            path,
            MMIO64_NVME_FAT_EXPECTED_UPDATE_BYTES,
            MMIO64_NVME_FAT_EXPECTED_UPDATE_CRC32,
            &bytes,
            &checksum) != 0u)
    {
        if (mmio64_fat32_next_cluster(reader, volume, 3u, &update_cluster) == 0u)
        {
            return 0u;
        }
        if (update_cluster != MMIO64_NVME_FAT_EXPECTED_UPDATE_CLUSTER)
        {
            return 0u;
        }
        g_nvme_fat_update_cluster = update_cluster;
        g_nvme_fat_update_readback = 1u;
        g_nvme_fat_update_bytes = bytes;
        g_nvme_fat_update_checksum = checksum;
        return 1u;
    }

    if (mmio64_fat32_find_path_location(reader, volume, path, &location) == 0u)
    {
        return 0u;
    }
    if ((location.cluster != 3u) || ((location.attr & 0x10u) != 0u))
    {
        return 0u;
    }
    if (mmio64_fat32_find_free_cluster(
            reader,
            volume,
            MMIO64_NVME_FAT_EXPECTED_UPDATE_CLUSTER,
            &update_cluster) == 0u)
    {
        return 0u;
    }
    if (update_cluster != MMIO64_NVME_FAT_EXPECTED_UPDATE_CLUSTER)
    {
        return 0u;
    }
    if (mmio64_fat32_write_fat_entry(reader, volume, location.cluster, update_cluster) == 0u)
    {
        return 0u;
    }
    if (mmio64_fat32_write_fat_entry(reader, volume, update_cluster, 0x0FFFFFFFu) == 0u)
    {
        return 0u;
    }
    if (mmio64_fat32_write_update_data(
            reader,
            volume,
            location.cluster,
            MMIO64_NVME_FAT_EXPECTED_UPDATE_BYTES) == 0u)
    {
        return 0u;
    }
    if (mmio64_nvme_fat_read_lba(
            reader,
            location.entry_lba,
            MMIO64_NVME_FAT_READ_ROOT_CID) == 0u)
    {
        return 0u;
    }
    mmio64_write_u32(
        g_nvme_io_data_buffer,
        location.entry_offset + 28u,
        MMIO64_NVME_FAT_EXPECTED_UPDATE_BYTES);
    if (mmio64_nvme_fat_write_lba(
            reader,
            location.entry_lba,
            MMIO64_NVME_FAT_WRITE_DIR_CID) == 0u)
    {
        return 0u;
    }
    if (mmio64_nvme_fat_verify_file(
            reader,
            volume,
            path,
            MMIO64_NVME_FAT_EXPECTED_UPDATE_BYTES,
            MMIO64_NVME_FAT_EXPECTED_UPDATE_CRC32,
            &bytes,
            &checksum) == 0u)
    {
        return 0u;
    }

    g_nvme_fat_update_cluster = update_cluster;
    g_nvme_fat_update_readback = 1u;
    g_nvme_fat_update_bytes = bytes;
    g_nvme_fat_update_checksum = checksum;
    return 1u;
}

static u32 mmio64_fat32_delete_file(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume)
{
    static const u8 path[] = "/REMOVE.ME";
    Mmio64Fat32EntryLocation location;
    u32 freed_value = 0xFFFFFFFFu;
    u32 cluster = 0u;
    u32 size = 0u;
    u32 attr = 0u;
    u32 index;

    if (mmio64_fat32_find_path_location(reader, volume, path, &location) == 0u)
    {
        if ((mmio64_fat32_next_cluster(
                    reader,
                    volume,
                    MMIO64_NVME_FAT_EXPECTED_DELETE_CLUSTER,
                    &freed_value) != 0u)
            && (freed_value == 0u))
        {
            g_nvme_fat_delete_freed = 1u;
            g_nvme_fat_delete_tombstone = 1u;
            return 1u;
        }
        return 0u;
    }
    if (location.cluster != MMIO64_NVME_FAT_EXPECTED_DELETE_CLUSTER)
    {
        return 0u;
    }
    if (mmio64_fat32_write_fat_entry(reader, volume, location.cluster, 0u) == 0u)
    {
        return 0u;
    }
    if (mmio64_nvme_fat_read_lba(
            reader,
            location.entry_lba,
            MMIO64_NVME_FAT_READ_ROOT_CID) == 0u)
    {
        return 0u;
    }
    if ((location.lfn_entries != 0u) && (location.lfn_lba == location.entry_lba))
    {
        for (index = 0u; index < location.lfn_entries; ++index)
        {
            g_nvme_io_data_buffer[location.lfn_offset + (index * 32u)] = 0xE5u;
        }
    }
    g_nvme_io_data_buffer[location.entry_offset] = 0xE5u;
    if (mmio64_nvme_fat_write_lba(
            reader,
            location.entry_lba,
            MMIO64_NVME_FAT_WRITE_DIR_CID) == 0u)
    {
        return 0u;
    }
    if (mmio64_fat32_next_cluster(reader, volume, location.cluster, &freed_value) == 0u)
    {
        return 0u;
    }
    if (freed_value != 0u)
    {
        return 0u;
    }
    if (mmio64_fat32_find_path(reader, volume, path, &cluster, &size, &attr) != 0u)
    {
        return 0u;
    }

    g_nvme_fat_delete_freed = 1u;
    g_nvme_fat_delete_tombstone = 1u;
    return 1u;
}

