#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
static u32 mmio64_nvme_rw_split_parent_leaf(
    const u8 *path,
    u8 *parent,
    u32 parent_capacity,
    u8 *leaf,
    u32 leaf_capacity)
{
    u32 path_bytes;
    u32 slash = 0u;
    u32 index;
    u32 leaf_index = 0u;

    if ((path == (const u8 *)0)
        || (parent == (u8 *)0)
        || (leaf == (u8 *)0)
        || (parent_capacity < 2u)
        || (leaf_capacity < 2u)
        || (path[0] != (u8)'/'))
    {
        return 0u;
    }

    path_bytes = 0u;
    while ((path_bytes <= MMIO64_NVME_RW_MAX_PATH_BYTES) && (path[path_bytes] != 0u))
    {
        ++path_bytes;
    }
    if (path_bytes > MMIO64_NVME_RW_MAX_PATH_BYTES)
    {
        return 0u;
    }
    if (path_bytes <= 1u)
    {
        return 0u;
    }
    for (index = 1u; index < path_bytes; ++index)
    {
        if (path[index] == (u8)'/')
        {
            slash = index;
        }
    }
    if ((slash + 1u) >= path_bytes)
    {
        return 0u;
    }

    mmio64_zero_bytes(parent, parent_capacity);
    mmio64_zero_bytes(leaf, leaf_capacity);
    if (slash == 0u)
    {
        parent[0] = (u8)'/';
        parent[1] = 0u;
    }
    else
    {
        if ((slash + 1u) > parent_capacity)
        {
            return 0u;
        }
        for (index = 0u; index < slash; ++index)
        {
            parent[index] = path[index];
        }
        parent[slash] = 0u;
    }

    for (index = slash + 1u; index < path_bytes; ++index)
    {
        if ((leaf_index + 1u) >= leaf_capacity)
        {
            return 0u;
        }
        leaf[leaf_index++] = path[index];
    }
    leaf[leaf_index] = 0u;
    return (leaf_index != 0u) ? 1u : 0u;
}

static u32 mmio64_nvme_rw_create_file_in_directory(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    u32 directory_cluster,
    const u8 *leaf,
    const u8 *data,
    u32 byte_count)
{
    u8 short_name[11];
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    u32 cluster = 0u;
    u32 entry_lba = 0u;
    u32 entry_offset = 0u;
    u32 crc = 0u;
    u32 leaf_length = 0u;
    u32 lfn_entries = 0u;
    u32 entry_count = 1u;
    u32 slot;
    u32 ordinal;
    u8 lfn_checksum;

    if ((directory_cluster < 2u)
        || (byte_count == 0u)
        || (byte_count > MMIO64_NVME_RW_SHELL_MAX_FILE_BYTES)
        || (mmio64_nvme_rw_write_data_chain(
                reader,
                volume,
                data,
                byte_count,
                &cluster,
                &crc) == 0u))
    {
        return 0u;
    }

    while ((leaf_length <= MMIO64_NVME_RW_MAX_PATH_BYTES) && (leaf[leaf_length] != 0u))
    {
        ++leaf_length;
    }
    if (leaf_length > MMIO64_NVME_RW_MAX_PATH_BYTES)
    {
        (void)mmio64_fat32_free_cluster_chain_for_mutation(reader, volume, cluster);
        return 0u;
    }
    if (mmio64_nvme_rw_make_short_name(leaf, short_name) == 0u)
    {
        if (mmio64_nvme_rw_make_lfn_alias(
                reader,
                volume,
                directory_cluster,
                leaf,
                leaf_length,
                short_name) == 0u)
        {
            (void)mmio64_fat32_free_cluster_chain_for_mutation(reader, volume, cluster);
            return 0u;
        }
        lfn_entries = (leaf_length + 12u) / 13u;
        if (lfn_entries == 0u)
        {
            (void)mmio64_fat32_free_cluster_chain_for_mutation(reader, volume, cluster);
            return 0u;
        }
        entry_count = lfn_entries + 1u;
    }

    if ((mmio64_fat32_find_free_dir_entries(
                reader,
                volume,
                directory_cluster,
                entry_count,
                &entry_lba,
                &entry_offset) == 0u)
        || (mmio64_nvme_fat_read_lba(
                reader,
                entry_lba,
                MMIO64_NVME_FAT_READ_ROOT_CID) == 0u))
    {
        (void)mmio64_fat32_free_cluster_chain_for_mutation(reader, volume, cluster);
        return 0u;
    }
    if (lfn_entries != 0u)
    {
        lfn_checksum = mmio64_fat32_lfn_checksum(short_name);
        for (slot = 0u; slot < lfn_entries; ++slot)
        {
            ordinal = lfn_entries - slot;
            mmio64_fat32_write_lfn_entry_ascii(
                g_nvme_io_data_buffer,
                entry_offset + (slot * 32u),
                ordinal,
                (ordinal == lfn_entries) ? 1u : 0u,
                leaf,
                leaf_length,
                lfn_checksum);
        }
    }
    mmio64_fat32_write_dir_entry(
        g_nvme_io_data_buffer,
        entry_offset + (lfn_entries * 32u),
        short_name,
        0x20u,
        cluster,
        byte_count);
    if (mmio64_nvme_fat_write_lba(
            reader,
            entry_lba,
            MMIO64_NVME_FAT_WRITE_DIR_CID) == 0u)
    {
        (void)mmio64_fat32_free_cluster_chain_for_mutation(reader, volume, cluster);
        return 0u;
    }

    (void)crc;
    return 1u;
#else
    u32 cluster = 0u;
    u32 entry_lba = 0u;
    u32 entry_offset = 0u;
    u32 cluster_lba = 0u;
    u32 index;

    if ((byte_count > 512u)
        || (directory_cluster < 2u)
        || (mmio64_nvme_rw_make_short_name(leaf, short_name) == 0u)
        || (mmio64_fat32_find_free_cluster(
                reader,
                volume,
                MMIO64_NVME_RW_FIRST_CLUSTER,
                &cluster) == 0u)
        || (mmio64_fat32_write_fat_entry(reader, volume, cluster, 0x0FFFFFFFu) == 0u)
        || (mmio64_fat32_cluster_lba(volume, cluster, &cluster_lba) == 0u))
    {
        return 0u;
    }

    mmio64_zero_bytes(g_nvme_io_data_buffer, 512u);
    for (index = 0u; index < byte_count; ++index)
    {
        g_nvme_io_data_buffer[index] = data[index];
    }
    if (mmio64_nvme_fat_write_lba(
            reader,
            cluster_lba,
            MMIO64_NVME_FAT_WRITE_DATA_CID) == 0u)
    {
        return 0u;
    }

    if ((mmio64_fat32_find_free_dir_entries(
                reader,
                volume,
                directory_cluster,
                1u,
                &entry_lba,
                &entry_offset) == 0u)
        || (mmio64_nvme_fat_read_lba(
                reader,
                entry_lba,
                MMIO64_NVME_FAT_READ_ROOT_CID) == 0u))
    {
        return 0u;
    }
    mmio64_fat32_write_dir_entry(
        g_nvme_io_data_buffer,
        entry_offset,
        short_name,
        0x20u,
        cluster,
        byte_count);
    return mmio64_nvme_fat_write_lba(
        reader,
        entry_lba,
        MMIO64_NVME_FAT_WRITE_DIR_CID);
#endif
}

static u32 mmio64_nvme_rw_create_path_file(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume,
    const u8 *path,
    const u8 *data,
    u32 byte_count)
{
    u8 parent[MMIO64_NVME_RW_MAX_PATH_BYTES + 2u];
    u8 leaf[MMIO64_NVME_RW_MAX_PATH_BYTES + 2u];
    u32 parent_cluster = 0u;
    u32 parent_size = 0u;
    u32 parent_attr = 0u;

    if (mmio64_nvme_rw_split_parent_leaf(
            path,
            parent,
            sizeof(parent),
            leaf,
            sizeof(leaf)) == 0u)
    {
        return 0u;
    }

    if ((parent[0] == (u8)'/') && (parent[1] == 0u))
    {
        parent_cluster = volume->root_cluster;
    }
    else if ((mmio64_fat32_find_path(
                reader,
                volume,
                parent,
                &parent_cluster,
                &parent_size,
                &parent_attr) == 0u)
        || ((parent_attr & 0x10u) == 0u)
        || (parent_cluster < 2u))
    {
        return 0u;
    }

    return mmio64_nvme_rw_create_file_in_directory(
        reader,
        volume,
        parent_cluster,
        leaf,
        data,
        byte_count);
}
#endif

static u32 mmio64_nvme_rw_probe_persisted(
    Mmio64NvmeFatReader *reader,
    const Mmio64Fat32Volume *volume)
{
    static const u8 path[] = "/SHELL.TXT";
    static const u8 expected[] = "shell write ok";
    u8 buffer[MMIO64_NVME_RW_SHELL_EXPECTED_BYTES];
    u32 bytes = 0u;
    u32 checksum = 0u;
    u32 index;

    if (mmio64_nvme_fat_read_path_bytes(
            reader,
            volume,
            path,
            buffer,
            sizeof(buffer),
            &bytes,
            &checksum) == 0u)
    {
        return 0u;
    }
    if (bytes != (sizeof(expected) - 1u))
    {
        return 0u;
    }
    for (index = 0u; index < bytes; ++index)
    {
        if (buffer[index] != expected[index])
        {
            return 0u;
        }
    }

    (void)checksum;
    return 1u;
}

static u32 mmio64_nvme_rw_delegate_shell(void)
{
    u32 stale_capability;

    g_nvme_rw_source_capability = capability64_grant_service(
        SERVICE_ENDPOINT_CLASS_BLOCK,
        CAPABILITY64_RIGHT_SEND | CAPABILITY64_RIGHT_QUERY | CAPABILITY64_RIGHT_DELEGATE,
        PRINCIPAL64_ID_BLOCK_WORKER);
    if (g_nvme_rw_source_capability == CAPABILITY64_INVALID_HANDLE)
    {
        g_nvme_rw_error = 20u;
        return 0u;
    }

    g_nvme_rw_wrong_owner = (capability64_route(
            g_nvme_rw_source_capability,
            CAPABILITY64_RIGHT_SEND | CAPABILITY64_RIGHT_QUERY,
            PRINCIPAL64_ID_CONSOLE_CLIENT) == 0xFFFFFFFFu) ? 1u : 0u;

    g_nvme_rw_shell_capability = capability64_delegate_persistent(
        g_nvme_rw_source_capability,
        CAPABILITY64_RIGHT_SEND | CAPABILITY64_RIGHT_QUERY,
        CAPABILITY64_CONTEXT(PRINCIPAL64_ID_BLOCK_WORKER, PRINCIPAL64_ID_CONSOLE_CLIENT));
    if (g_nvme_rw_shell_capability == CAPABILITY64_INVALID_HANDLE)
    {
        g_nvme_rw_error = 21u;
        return 0u;
    }

    stale_capability = capability64_delegate_persistent(
        g_nvme_rw_source_capability,
        CAPABILITY64_RIGHT_SEND | CAPABILITY64_RIGHT_QUERY,
        CAPABILITY64_CONTEXT(PRINCIPAL64_ID_BLOCK_WORKER, PRINCIPAL64_ID_POLICY_CLIENT));
    if (stale_capability != CAPABILITY64_INVALID_HANDLE)
    {
        g_nvme_rw_revoked = capability64_revoke(stale_capability, PRINCIPAL64_ID_POLICY_CLIENT);
        g_nvme_rw_stale_denied = (capability64_route(
                stale_capability,
                CAPABILITY64_RIGHT_SEND,
                PRINCIPAL64_ID_POLICY_CLIENT) == 0xFFFFFFFFu) ? 1u : 0u;
    }

    g_nvme_rw_delegated = ((g_nvme_rw_wrong_owner != 0u)
        && (g_nvme_rw_revoked != 0u)
        && (g_nvme_rw_stale_denied != 0u)) ? 1u : 0u;
    g_nvme_rw_write_authority = g_nvme_rw_delegated;
    g_nvme_rw_commit_authority = g_nvme_rw_delegated;
    g_nvme_rw_unavailable = (g_nvme_rw_delegated != 0u) ? 0u : 1u;
    if (g_nvme_rw_delegated == 0u)
    {
        g_nvme_rw_error = 22u;
        return 0u;
    }

    return 1u;
}

u32 mmio64_nvme_fat_shell_stat_path(
    const u8 *path,
    u32 path_byte_count,
    u32 owner_id,
    mmio64_nvme_fat_stat_t *stat_out)
{
    u8 normalized[MMIO64_NVME_RW_MAX_PATH_BYTES + 2u];
    Mmio64NvmeFatReader reader;
    Mmio64Fat32Volume volume;
    u32 doorbell_page = 0u;
    u32 cluster = 0u;
    u32 size = 0u;
    u32 attr = 0u;
    u32 ok = 0u;

    mmio64_nvme_fat_zero_stat(stat_out);
    if ((stat_out == (mmio64_nvme_fat_stat_t *)0)
        || (path == (const u8 *)0)
        || (path_byte_count == 0u)
        || (mmio64_nvme_rw_shell_authorized(owner_id) == 0u))
    {
        return 0u;
    }

    if ((path_byte_count == 1u) && (path[0] == (u8)'/'))
    {
        normalized[0] = (u8)'/';
        normalized[1] = 0u;
    }
    else if (mmio64_nvme_rw_normalize_path(
            path,
            path_byte_count,
            normalized,
            sizeof(normalized)) == 0u)
    {
        return 0u;
    }

    if (mmio64_nvme_fat_open_runtime(&reader, &volume, &doorbell_page) == 0u)
    {
        return 0u;
    }

    if ((normalized[0] == (u8)'/') && (normalized[1] == 0u))
    {
        stat_out->entry_type = MMIO64_NVME_FAT_DIRENT_TYPE_DIRECTORY;
        stat_out->attr = 0x10u;
        stat_out->cluster = volume.root_cluster;
        stat_out->byte_count = 0u;
        ok = 1u;
    }
    else if (mmio64_fat32_find_path(&reader, &volume, normalized, &cluster, &size, &attr) != 0u)
    {
        stat_out->entry_type = mmio64_fat32_entry_type_from_attr(attr);
        stat_out->attr = attr;
        stat_out->cluster = cluster;
        stat_out->byte_count = size;
        ok = 1u;
    }

    mmio64_nvme_fat_close_runtime(&reader, &volume, doorbell_page);
    return ok;
}

u32 mmio64_nvme_fat_shell_read_dirent(
    const u8 *path,
    u32 path_byte_count,
    u32 cursor,
    u32 owner_id,
    mmio64_nvme_fat_dirent_t *entry_out)
{
    u8 normalized[MMIO64_NVME_RW_MAX_PATH_BYTES + 2u];
    Mmio64NvmeFatReader reader;
    Mmio64Fat32Volume volume;
    u32 doorbell_page = 0u;
    u32 directory_cluster = 0u;
    u32 size = 0u;
    u32 attr = 0u;
    u32 result = 0u;

    mmio64_nvme_fat_zero_dirent(entry_out);
    if ((entry_out == (mmio64_nvme_fat_dirent_t *)0)
        || (path == (const u8 *)0)
        || (path_byte_count == 0u)
        || (mmio64_nvme_rw_shell_authorized(owner_id) == 0u))
    {
        return 0u;
    }

    if ((path_byte_count == 1u) && (path[0] == (u8)'/'))
    {
        normalized[0] = (u8)'/';
        normalized[1] = 0u;
    }
    else if (mmio64_nvme_rw_normalize_path(
            path,
            path_byte_count,
            normalized,
            sizeof(normalized)) == 0u)
    {
        return 0u;
    }

    if (mmio64_nvme_fat_open_runtime(&reader, &volume, &doorbell_page) == 0u)
    {
        return 0u;
    }

    if ((normalized[0] == (u8)'/') && (normalized[1] == 0u))
    {
        directory_cluster = volume.root_cluster;
    }
    else if ((mmio64_fat32_find_path(&reader, &volume, normalized, &directory_cluster, &size, &attr) == 0u)
        || ((attr & 0x10u) == 0u)
        || (directory_cluster < 2u))
    {
        mmio64_nvme_fat_close_runtime(&reader, &volume, doorbell_page);
        return 0u;
    }

    result = mmio64_fat32_read_directory_entry(
        &reader,
        &volume,
        directory_cluster,
        cursor,
        entry_out);
    mmio64_nvme_fat_close_runtime(&reader, &volume, doorbell_page);
    return result;
}

