u32 mmio64_request_ahci_mapping(u32 hardware_capability_handle, u32 owner_id)
{
    u32 page_count;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_map_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if (!mmio64_candidate_ready())
    {
        ++g_map_unavailable_count;
        return MMIO64_INVALID_RESULT;
    }

    page_count = mmio64_page_count_for_span(g_ahci_span);
    if (page_count == 0u)
    {
        ++g_map_unavailable_count;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_map_virtual_base = MMIO64_AHCI_MAP_VIRTUAL_BASE;
    g_ahci_map_page_count = page_count;
    g_ahci_map_flags = MMIO64_MAP_FLAG_REQUESTED
        | MMIO64_MAP_FLAG_CANDIDATE_PRESENT
        | MMIO64_MAP_FLAG_PAGE_ALIGNED
        | MMIO64_MAP_FLAG_SPAN_BOUNDED
        | MMIO64_MAP_FLAG_KERNEL_ONLY
        | MMIO64_MAP_FLAG_READ_ONLY
        | MMIO64_MAP_FLAG_NO_EXEC
        | MMIO64_MAP_FLAG_NOT_INSTALLED
        | MMIO64_MAP_FLAG_NO_DEREF;
    g_ahci_map_state = MMIO64_MAP_STATE_STAGED_NO_TOUCH;
    g_ahci_map_installed = 0u;
    g_ahci_map_install_token = 0u;
    g_ahci_map_pml4_index = 0u;
    g_ahci_map_pdpt_index = 0u;
    g_ahci_map_pd_index = 0u;
    g_ahci_map_pt_index = 0u;
    g_ahci_map_entry_flags = 0ull;
    g_ahci_map_nx_enabled = 0u;
    mmio64_reset_snapshot();

    if (paging64_install_kernel_mmio_mapping(
            g_ahci_map_virtual_base,
            g_ahci_base,
            g_ahci_map_page_count) != 0u)
    {
        g_ahci_map_flags &= ~MMIO64_MAP_FLAG_NOT_INSTALLED;
        g_ahci_map_flags |= MMIO64_MAP_FLAG_PAGE_TABLE_INSTALLED
            | MMIO64_MAP_FLAG_CACHE_DISABLED
            | MMIO64_MAP_FLAG_NX_ENFORCED;
        g_ahci_map_state = MMIO64_MAP_STATE_INSTALLED_NO_DEREF;
        g_ahci_map_installed = paging64_kernel_mmio_mapping_installed();
        g_ahci_map_install_token = paging64_kernel_mmio_mapping_install_token();
        g_ahci_map_pml4_index = paging64_kernel_mmio_mapping_pml4_index();
        g_ahci_map_pdpt_index = paging64_kernel_mmio_mapping_pdpt_index();
        g_ahci_map_pd_index = paging64_kernel_mmio_mapping_pd_index();
        g_ahci_map_pt_index = paging64_kernel_mmio_mapping_pt_index();
        g_ahci_map_entry_flags = paging64_kernel_mmio_mapping_entry_flags();
        g_ahci_map_nx_enabled = paging64_kernel_mmio_mapping_nx_enabled();
    }

    g_ahci_map_token = mmio64_make_map_token(
        g_ahci_map_virtual_base,
        g_ahci_map_page_count,
        g_ahci_map_flags,
        g_ahci_map_state,
        g_ahci_token);
    ++g_map_request_count;
    return g_ahci_map_token;
}

