u32 mmio64_snapshot_ahci_registers(u32 hardware_capability_handle, u32 owner_id)
{
    volatile const u32 *registers;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_snapshot_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if ((g_ahci_map_installed == 0u)
        || (g_ahci_map_state != MMIO64_MAP_STATE_INSTALLED_NO_DEREF)
        || ((g_ahci_map_flags & (MMIO64_MAP_FLAG_PAGE_TABLE_INSTALLED
                | MMIO64_MAP_FLAG_KERNEL_ONLY
                | MMIO64_MAP_FLAG_READ_ONLY
                | MMIO64_MAP_FLAG_NO_EXEC
                | MMIO64_MAP_FLAG_CACHE_DISABLED
                | MMIO64_MAP_FLAG_NX_ENFORCED)) !=
            (MMIO64_MAP_FLAG_PAGE_TABLE_INSTALLED
                | MMIO64_MAP_FLAG_KERNEL_ONLY
                | MMIO64_MAP_FLAG_READ_ONLY
                | MMIO64_MAP_FLAG_NO_EXEC
                | MMIO64_MAP_FLAG_CACHE_DISABLED
                | MMIO64_MAP_FLAG_NX_ENFORCED))
        || (g_ahci_map_virtual_base == 0ull)
        || (g_ahci_span < MMIO64_AHCI_REGISTER_WINDOW_BYTES))
    {
        ++g_ahci_snapshot_unavailable_count;
        g_ahci_snapshot_state = MMIO64_SNAPSHOT_STATE_UNAVAILABLE;
        g_ahci_snapshot_flags = MMIO64_SNAPSHOT_FLAG_REQUESTED
            | MMIO64_SNAPSHOT_FLAG_CAPABILITY_GATED
            | MMIO64_SNAPSHOT_FLAG_NO_WRITES
            | MMIO64_SNAPSHOT_FLAG_NO_COMMANDS
            | MMIO64_SNAPSHOT_FLAG_UNAVAILABLE;
        g_ahci_snapshot_token = 0u;
        g_ahci_snapshot_cap = 0u;
        g_ahci_snapshot_ghc = 0u;
        g_ahci_snapshot_pi = 0u;
        g_ahci_snapshot_version = 0u;
        return MMIO64_INVALID_RESULT;
    }

    registers = (volatile const u32 *)(u64)g_ahci_map_virtual_base;
    g_ahci_snapshot_cap = registers[MMIO64_AHCI_CAP_REGISTER];
    g_ahci_snapshot_ghc = registers[MMIO64_AHCI_GHC_REGISTER];
    g_ahci_snapshot_pi = registers[MMIO64_AHCI_PI_REGISTER];
    g_ahci_snapshot_version = registers[MMIO64_AHCI_VERSION_REGISTER];
    g_ahci_snapshot_state = MMIO64_SNAPSHOT_STATE_READ_ONLY;
    g_ahci_snapshot_flags = MMIO64_SNAPSHOT_FLAG_REQUESTED
        | MMIO64_SNAPSHOT_FLAG_MAP_INSTALLED
        | MMIO64_SNAPSHOT_FLAG_CAP_READ
        | MMIO64_SNAPSHOT_FLAG_GHC_READ
        | MMIO64_SNAPSHOT_FLAG_PI_READ
        | MMIO64_SNAPSHOT_FLAG_VERSION_READ
        | MMIO64_SNAPSHOT_FLAG_READ_ONLY
        | MMIO64_SNAPSHOT_FLAG_NO_WRITES
        | MMIO64_SNAPSHOT_FLAG_NO_COMMANDS
        | MMIO64_SNAPSHOT_FLAG_CAPABILITY_GATED;
    g_ahci_snapshot_token = mmio64_make_snapshot_token();
    ++g_ahci_snapshot_read_count;
    return g_ahci_snapshot_token;
}

