u32 mmio64_snapshot_ahci_ports(u32 hardware_capability_handle, u32 owner_id)
{
    volatile const u32 *registers;
    u32 port;
    u32 selected;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_port_snapshot_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if (!mmio64_snapshot_ready() || (g_ahci_snapshot_pi == 0u))
    {
        ++g_ahci_port_snapshot_unavailable_count;
        mmio64_reset_port_snapshot();
        g_ahci_port_snapshot_state = MMIO64_PORT_SNAPSHOT_STATE_UNAVAILABLE;
        g_ahci_port_snapshot_flags = MMIO64_PORT_SNAPSHOT_FLAG_REQUESTED
            | MMIO64_PORT_SNAPSHOT_FLAG_CAPABILITY_GATED
            | MMIO64_PORT_SNAPSHOT_FLAG_NO_WRITES
            | MMIO64_PORT_SNAPSHOT_FLAG_NO_COMMANDS
            | MMIO64_PORT_SNAPSHOT_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_port_snapshot();
    registers = (volatile const u32 *)(u64)g_ahci_map_virtual_base;

    for (port = 0u; port < MMIO64_AHCI_MAX_PORTS; ++port)
    {
        u32 ssts_offset;
        u32 ssts;

        if ((g_ahci_snapshot_pi & (1u << port)) == 0u)
        {
            continue;
        }

        if (!mmio64_register_fits_span(
                mmio64_ahci_port_offset(port, MMIO64_AHCI_PORT_LAST_READ_OFFSET)))
        {
            continue;
        }

        if (g_ahci_port_implemented_count == 0u)
        {
            g_ahci_port_first_implemented = port;
        }
        ++g_ahci_port_implemented_count;

        ssts_offset = mmio64_ahci_port_offset(port, MMIO64_AHCI_PORT_SSTS_OFFSET);
        ssts = registers[ssts_offset / sizeof(u32)];
        if ((ssts & 0xFu) == MMIO64_AHCI_PORT_DET_PRESENT)
        {
            if (g_ahci_port_active_count == 0u)
            {
                g_ahci_port_first_active = port;
            }
            ++g_ahci_port_active_count;
        }
    }

    selected = (g_ahci_port_first_active != MMIO64_INVALID_RESULT)
        ? g_ahci_port_first_active
        : g_ahci_port_first_implemented;
    if (selected == MMIO64_INVALID_RESULT)
    {
        ++g_ahci_port_snapshot_unavailable_count;
        g_ahci_port_snapshot_state = MMIO64_PORT_SNAPSHOT_STATE_UNAVAILABLE;
        g_ahci_port_snapshot_flags = MMIO64_PORT_SNAPSHOT_FLAG_REQUESTED
            | MMIO64_PORT_SNAPSHOT_FLAG_CONTROLLER_READY
            | MMIO64_PORT_SNAPSHOT_FLAG_PI_OBSERVED
            | MMIO64_PORT_SNAPSHOT_FLAG_IMPLEMENTED_SCANNED
            | MMIO64_PORT_SNAPSHOT_FLAG_CAPABILITY_GATED
            | MMIO64_PORT_SNAPSHOT_FLAG_NO_WRITES
            | MMIO64_PORT_SNAPSHOT_FLAG_NO_COMMANDS
            | MMIO64_PORT_SNAPSHOT_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_port_selected = selected;
    g_ahci_port_selected_ssts =
        registers[mmio64_ahci_port_offset(selected, MMIO64_AHCI_PORT_SSTS_OFFSET) / sizeof(u32)];
    g_ahci_port_selected_signature =
        registers[mmio64_ahci_port_offset(selected, MMIO64_AHCI_PORT_SIG_OFFSET) / sizeof(u32)];
    g_ahci_port_selected_command =
        registers[mmio64_ahci_port_offset(selected, MMIO64_AHCI_PORT_CMD_OFFSET) / sizeof(u32)];
    g_ahci_port_selected_task_file =
        registers[mmio64_ahci_port_offset(selected, MMIO64_AHCI_PORT_TFD_OFFSET) / sizeof(u32)];
    g_ahci_port_selected_ci =
        registers[mmio64_ahci_port_offset(selected, MMIO64_AHCI_PORT_CI_OFFSET) / sizeof(u32)];
    g_ahci_port_selected_serr =
        registers[mmio64_ahci_port_offset(selected, MMIO64_AHCI_PORT_SERR_OFFSET) / sizeof(u32)];
    g_ahci_port_snapshot_state = MMIO64_PORT_SNAPSHOT_STATE_READ_ONLY;
    g_ahci_port_snapshot_flags = MMIO64_PORT_SNAPSHOT_FLAG_REQUESTED
        | MMIO64_PORT_SNAPSHOT_FLAG_MAP_INSTALLED
        | MMIO64_PORT_SNAPSHOT_FLAG_CONTROLLER_READY
        | MMIO64_PORT_SNAPSHOT_FLAG_PI_OBSERVED
        | MMIO64_PORT_SNAPSHOT_FLAG_IMPLEMENTED_SCANNED
        | MMIO64_PORT_SNAPSHOT_FLAG_SELECTED_READ
        | MMIO64_PORT_SNAPSHOT_FLAG_ACTIVE_SCANNED
        | MMIO64_PORT_SNAPSHOT_FLAG_READ_ONLY
        | MMIO64_PORT_SNAPSHOT_FLAG_NO_WRITES
        | MMIO64_PORT_SNAPSHOT_FLAG_NO_COMMANDS
        | MMIO64_PORT_SNAPSHOT_FLAG_CAPABILITY_GATED;
    if (g_ahci_port_active_count != 0u)
    {
        g_ahci_port_snapshot_flags |= MMIO64_PORT_SNAPSHOT_FLAG_ACTIVE_FOUND;
    }
    g_ahci_port_snapshot_token = mmio64_make_port_snapshot_token();
    ++g_ahci_port_snapshot_read_count;
    return g_ahci_port_snapshot_token;
}

