u32 mmio64_classify_ahci_port(u32 hardware_capability_handle, u32 owner_id)
{
    u32 flags;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_port_policy_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if (!mmio64_port_snapshot_ready())
    {
        ++g_ahci_port_policy_unavailable_count;
        mmio64_reset_port_policy();
        g_ahci_port_policy_state = MMIO64_PORT_POLICY_STATE_UNAVAILABLE;
        g_ahci_port_policy_flags = MMIO64_PORT_POLICY_FLAG_REQUESTED
            | MMIO64_PORT_POLICY_FLAG_CAPABILITY_GATED
            | MMIO64_PORT_POLICY_FLAG_NO_WRITES
            | MMIO64_PORT_POLICY_FLAG_NO_COMMANDS
            | MMIO64_PORT_POLICY_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_port_policy();
    g_ahci_port_policy_det = g_ahci_port_selected_ssts & 0xFu;
    g_ahci_port_policy_spd = (g_ahci_port_selected_ssts >> 4) & 0xFu;
    g_ahci_port_policy_ipm = (g_ahci_port_selected_ssts >> 8) & 0xFu;
    g_ahci_port_policy_busy =
        ((g_ahci_port_selected_task_file & MMIO64_AHCI_TFD_STS_BSY) != 0u) ? 1u : 0u;
    g_ahci_port_policy_drq =
        ((g_ahci_port_selected_task_file & MMIO64_AHCI_TFD_STS_DRQ) != 0u) ? 1u : 0u;
    g_ahci_port_policy_ci_idle = (g_ahci_port_selected_ci == 0u) ? 1u : 0u;
    g_ahci_port_policy_serr_clear = (g_ahci_port_selected_serr == 0u) ? 1u : 0u;

    if (g_ahci_port_selected_signature == MMIO64_AHCI_PORT_SIG_SATA)
    {
        g_ahci_port_policy_device_kind = MMIO64_PORT_DEVICE_SATA;
    }
    else if (g_ahci_port_selected_signature == MMIO64_AHCI_PORT_SIG_ATAPI)
    {
        g_ahci_port_policy_device_kind = MMIO64_PORT_DEVICE_ATAPI;
    }
    else if (g_ahci_port_selected_signature == MMIO64_AHCI_PORT_SIG_SEMB)
    {
        g_ahci_port_policy_device_kind = MMIO64_PORT_DEVICE_SEMB;
    }
    else if (g_ahci_port_selected_signature == MMIO64_AHCI_PORT_SIG_PM)
    {
        g_ahci_port_policy_device_kind = MMIO64_PORT_DEVICE_PORT_MULTIPLIER;
    }
    else
    {
        g_ahci_port_policy_device_kind = MMIO64_PORT_DEVICE_UNKNOWN;
    }

    flags = MMIO64_PORT_POLICY_FLAG_REQUESTED
        | MMIO64_PORT_POLICY_FLAG_PORT_SNAPSHOT_READY
        | MMIO64_PORT_POLICY_FLAG_ACTIVE_PORT
        | MMIO64_PORT_POLICY_FLAG_READ_ONLY
        | MMIO64_PORT_POLICY_FLAG_NO_WRITES
        | MMIO64_PORT_POLICY_FLAG_NO_COMMANDS
        | MMIO64_PORT_POLICY_FLAG_CAPABILITY_GATED;

    if (g_ahci_port_policy_det == MMIO64_AHCI_PORT_DET_PRESENT)
    {
        flags |= MMIO64_PORT_POLICY_FLAG_DET_PRESENT;
    }

    if (g_ahci_port_policy_ipm == MMIO64_AHCI_PORT_IPM_ACTIVE)
    {
        flags |= MMIO64_PORT_POLICY_FLAG_IPM_ACTIVE;
    }

    if (g_ahci_port_policy_spd != 0u)
    {
        flags |= MMIO64_PORT_POLICY_FLAG_SPEED_NONZERO;
    }

    if ((g_ahci_port_policy_busy == 0u) && (g_ahci_port_policy_drq == 0u))
    {
        flags |= MMIO64_PORT_POLICY_FLAG_TFD_READY;
    }

    if (g_ahci_port_policy_ci_idle != 0u)
    {
        flags |= MMIO64_PORT_POLICY_FLAG_CI_IDLE;
    }

    if (g_ahci_port_policy_serr_clear != 0u)
    {
        flags |= MMIO64_PORT_POLICY_FLAG_SERR_CLEAR;
    }

    if (g_ahci_port_policy_device_kind == MMIO64_PORT_DEVICE_SATA)
    {
        flags |= MMIO64_PORT_POLICY_FLAG_SATA_SIGNATURE;
    }
    else if (g_ahci_port_policy_device_kind == MMIO64_PORT_DEVICE_ATAPI)
    {
        flags |= MMIO64_PORT_POLICY_FLAG_ATAPI_SIGNATURE;
    }

    g_ahci_port_policy_ready =
        ((flags & (MMIO64_PORT_POLICY_FLAG_DET_PRESENT
                | MMIO64_PORT_POLICY_FLAG_IPM_ACTIVE
                | MMIO64_PORT_POLICY_FLAG_TFD_READY
                | MMIO64_PORT_POLICY_FLAG_CI_IDLE)) ==
            (MMIO64_PORT_POLICY_FLAG_DET_PRESENT
                | MMIO64_PORT_POLICY_FLAG_IPM_ACTIVE
                | MMIO64_PORT_POLICY_FLAG_TFD_READY
                | MMIO64_PORT_POLICY_FLAG_CI_IDLE))
        && ((g_ahci_port_policy_device_kind == MMIO64_PORT_DEVICE_SATA)
            || (g_ahci_port_policy_device_kind == MMIO64_PORT_DEVICE_ATAPI))
            ? 1u : 0u;

    if (g_ahci_port_policy_ready != 0u)
    {
        flags |= MMIO64_PORT_POLICY_FLAG_READ_ELIGIBLE;
    }

    g_ahci_port_policy_state = MMIO64_PORT_POLICY_STATE_READY_READ_ONLY;
    g_ahci_port_policy_flags = flags;
    g_ahci_port_policy_token = mmio64_make_port_policy_token();
    ++g_ahci_port_policy_read_count;
    return g_ahci_port_policy_token;
}

