u32 mmio64_stage_ahci_read_plan(
    u32 hardware_capability_handle,
    u32 lba_low,
    u32 block_count,
    u32 owner_id)
{
    u32 flags;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_read_plan_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if (!mmio64_port_policy_ready()
        || (block_count == 0u)
        || (block_count > MMIO64_AHCI_READ_PLAN_MAX_BLOCKS))
    {
        ++g_ahci_read_plan_unavailable_count;
        mmio64_reset_read_plan();
        g_ahci_read_plan_state = MMIO64_AHCI_READ_PLAN_STATE_UNAVAILABLE;
        g_ahci_read_plan_flags = MMIO64_AHCI_READ_PLAN_FLAG_REQUESTED
            | MMIO64_AHCI_READ_PLAN_FLAG_NO_WRITES
            | MMIO64_AHCI_READ_PLAN_FLAG_NO_DMA
            | MMIO64_AHCI_READ_PLAN_FLAG_NO_COMMANDS
            | MMIO64_AHCI_READ_PLAN_FLAG_NOT_ARMED
            | MMIO64_AHCI_READ_PLAN_FLAG_CAPABILITY_GATED
            | MMIO64_AHCI_READ_PLAN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_read_plan();
    g_ahci_read_plan_state = MMIO64_AHCI_READ_PLAN_STATE_STAGED_NO_COMMAND;
    g_ahci_read_plan_port = g_ahci_port_selected;
    g_ahci_read_plan_policy_token = g_ahci_port_policy_token;
    g_ahci_read_plan_lba_low = lba_low;
    g_ahci_read_plan_block_count = block_count;
    g_ahci_read_plan_command_slot = 0u;
    g_ahci_read_plan_armed = 0u;
    g_ahci_read_plan_issued = 0u;
    g_ahci_read_plan_dma_mapped = 0u;

    flags = MMIO64_AHCI_READ_PLAN_FLAG_REQUESTED
        | MMIO64_AHCI_READ_PLAN_FLAG_POLICY_READY
        | MMIO64_AHCI_READ_PLAN_FLAG_ACTIVE_PORT
        | MMIO64_AHCI_READ_PLAN_FLAG_SELECTED_PORT_BOUND
        | MMIO64_AHCI_READ_PLAN_FLAG_LBA_BOUND
        | MMIO64_AHCI_READ_PLAN_FLAG_BLOCK_COUNT_BOUNDED
        | MMIO64_AHCI_READ_PLAN_FLAG_OPERATION_SELECTED
        | MMIO64_AHCI_READ_PLAN_FLAG_READ_ONLY
        | MMIO64_AHCI_READ_PLAN_FLAG_NO_WRITES
        | MMIO64_AHCI_READ_PLAN_FLAG_NO_DMA
        | MMIO64_AHCI_READ_PLAN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_READ_PLAN_FLAG_NOT_ARMED
        | MMIO64_AHCI_READ_PLAN_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_READ_PLAN_FLAG_USES_POLICY_TOKEN;

    if (g_ahci_port_policy_device_kind == MMIO64_PORT_DEVICE_SATA)
    {
        g_ahci_read_plan_operation = MMIO64_AHCI_READ_OPERATION_ATA_READ_DMA_EXT;
        g_ahci_read_plan_byte_count_hint =
            block_count * MMIO64_AHCI_SATA_LOGICAL_BLOCK_BYTES;
        flags |= MMIO64_AHCI_READ_PLAN_FLAG_SATA_OPERATION;
    }
    else
    {
        g_ahci_read_plan_operation = MMIO64_AHCI_READ_OPERATION_ATAPI_READ_10;
        g_ahci_read_plan_byte_count_hint = 0u;
        flags |= MMIO64_AHCI_READ_PLAN_FLAG_ATAPI_OPERATION;
    }

    g_ahci_read_plan_flags = flags;
    g_ahci_read_plan_token = mmio64_make_read_plan_token();
    ++g_ahci_read_plan_stage_count;
    return g_ahci_read_plan_token;
}

