u32 mmio64_stage_ahci_command_plan(u32 hardware_capability_handle, u32 owner_id)
{
    u32 flags;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_command_plan_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if (!mmio64_read_plan_ready())
    {
        ++g_ahci_command_plan_unavailable_count;
        mmio64_reset_command_plan();
        g_ahci_command_plan_state = MMIO64_AHCI_CMD_PLAN_STATE_UNAVAILABLE;
        g_ahci_command_plan_flags = MMIO64_AHCI_CMD_PLAN_FLAG_REQUESTED
            | MMIO64_AHCI_CMD_PLAN_FLAG_NO_WRITES
            | MMIO64_AHCI_CMD_PLAN_FLAG_NO_DMA
            | MMIO64_AHCI_CMD_PLAN_FLAG_NO_COMMANDS
            | MMIO64_AHCI_CMD_PLAN_FLAG_NOT_ARMED
            | MMIO64_AHCI_CMD_PLAN_FLAG_CAPABILITY_GATED
            | MMIO64_AHCI_CMD_PLAN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_command_plan();
    g_ahci_command_plan_state = MMIO64_AHCI_CMD_PLAN_STATE_STAGED_NO_ISSUE;
    g_ahci_command_plan_read_token = g_ahci_read_plan_token;
    g_ahci_command_plan_operation = g_ahci_read_plan_operation;
    g_ahci_command_plan_slot = g_ahci_read_plan_command_slot;
    g_ahci_command_plan_header_bytes = MMIO64_AHCI_COMMAND_HEADER_BYTES;
    g_ahci_command_plan_cfis_bytes = MMIO64_AHCI_COMMAND_CFIS_BYTES;
    g_ahci_command_plan_cfis_dwords = MMIO64_AHCI_COMMAND_CFIS_DWORDS;
    g_ahci_command_plan_prdt_entries = 1u;
    g_ahci_command_plan_prdt_bytes =
        g_ahci_command_plan_prdt_entries * MMIO64_AHCI_COMMAND_PRDT_ENTRY_BYTES;
    g_ahci_command_plan_table_bytes =
        MMIO64_AHCI_COMMAND_TABLE_BASE_BYTES + g_ahci_command_plan_prdt_bytes;
    g_ahci_command_plan_armed = 0u;
    g_ahci_command_plan_issued = 0u;
    g_ahci_command_plan_dma_mapped = 0u;

    flags = MMIO64_AHCI_CMD_PLAN_FLAG_REQUESTED
        | MMIO64_AHCI_CMD_PLAN_FLAG_READ_PLAN_READY
        | MMIO64_AHCI_CMD_PLAN_FLAG_SLOT_BOUND
        | MMIO64_AHCI_CMD_PLAN_FLAG_HEADER_DESCRIBED
        | MMIO64_AHCI_CMD_PLAN_FLAG_TABLE_DESCRIBED
        | MMIO64_AHCI_CMD_PLAN_FLAG_CFIS_DESCRIBED
        | MMIO64_AHCI_CMD_PLAN_FLAG_PRDT_DESCRIBED
        | MMIO64_AHCI_CMD_PLAN_FLAG_TRANSFER_BOUNDED
        | MMIO64_AHCI_CMD_PLAN_FLAG_OPCODE_SELECTED
        | MMIO64_AHCI_CMD_PLAN_FLAG_READ_ONLY
        | MMIO64_AHCI_CMD_PLAN_FLAG_NO_WRITES
        | MMIO64_AHCI_CMD_PLAN_FLAG_NO_DMA
        | MMIO64_AHCI_CMD_PLAN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_CMD_PLAN_FLAG_NOT_ARMED
        | MMIO64_AHCI_CMD_PLAN_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_CMD_PLAN_FLAG_USES_READ_PLAN_TOKEN;

    if (g_ahci_command_plan_operation == MMIO64_AHCI_READ_OPERATION_ATA_READ_DMA_EXT)
    {
        g_ahci_command_plan_command_opcode = MMIO64_ATA_COMMAND_READ_DMA_EXT;
        g_ahci_command_plan_packet_opcode = 0u;
        g_ahci_command_plan_transfer_bytes = g_ahci_read_plan_byte_count_hint;
    }
    else
    {
        g_ahci_command_plan_command_opcode = MMIO64_ATA_COMMAND_PACKET;
        g_ahci_command_plan_packet_opcode = MMIO64_ATAPI_COMMAND_READ_10;
        g_ahci_command_plan_atapi_packet_bytes = MMIO64_AHCI_ATAPI_PACKET_BYTES;
        g_ahci_command_plan_transfer_bytes =
            g_ahci_read_plan_block_count * MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES;
        flags |= MMIO64_AHCI_CMD_PLAN_FLAG_ATAPI_PACKET_DESCRIBED;
    }

    g_ahci_command_plan_flags = flags;
    g_ahci_command_plan_token = mmio64_make_command_plan_token();
    ++g_ahci_command_plan_stage_count;
    return g_ahci_command_plan_token;
}

