u32 mmio64_stage_ahci_memory_plan(u32 hardware_capability_handle, u32 owner_id)
{
    u32 flags;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_memory_plan_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if (!mmio64_command_plan_ready())
    {
        ++g_ahci_memory_plan_unavailable_count;
        mmio64_reset_memory_plan();
        g_ahci_memory_plan_state = MMIO64_AHCI_MEM_PLAN_STATE_UNAVAILABLE;
        g_ahci_memory_plan_flags = MMIO64_AHCI_MEM_PLAN_FLAG_REQUESTED
            | MMIO64_AHCI_MEM_PLAN_FLAG_NO_MEMORY_WRITES
            | MMIO64_AHCI_MEM_PLAN_FLAG_NO_DMA_MAPPING
            | MMIO64_AHCI_MEM_PLAN_FLAG_NO_PORT_WRITES
            | MMIO64_AHCI_MEM_PLAN_FLAG_NO_COMMANDS
            | MMIO64_AHCI_MEM_PLAN_FLAG_NOT_ARMED
            | MMIO64_AHCI_MEM_PLAN_FLAG_CAPABILITY_GATED
            | MMIO64_AHCI_MEM_PLAN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_memory_plan();
    g_ahci_memory_plan_state = MMIO64_AHCI_MEM_PLAN_STATE_STAGED_NO_DMA;
    g_ahci_memory_plan_command_token = g_ahci_command_plan_token;
    g_ahci_memory_plan_slot = g_ahci_command_plan_slot;
    g_ahci_memory_plan_page_count = 1u;
    g_ahci_memory_plan_page_bytes = MMIO64_PAGE_BYTES;
    g_ahci_memory_plan_page_virtual = (u64)(void *)g_ahci_command_page;
    g_ahci_memory_plan_page_physical = mmio64_lower_half_alias((const void *)g_ahci_command_page);
    g_ahci_memory_plan_page_checksum =
        mmio64_checksum_bytes((const u8 *)g_ahci_command_page, MMIO64_PAGE_BYTES);
    g_ahci_memory_plan_page_zeroed =
        mmio64_memory_is_zeroed((const u8 *)g_ahci_command_page, MMIO64_PAGE_BYTES);
    g_ahci_memory_plan_page_materialized =
        (((g_ahci_memory_plan_page_virtual & (MMIO64_PAGE_BYTES - 1u)) == 0ull)
            && ((g_ahci_memory_plan_page_physical & (MMIO64_PAGE_BYTES - 1u)) == 0ull)
            && (g_ahci_memory_plan_page_zeroed != 0u))
            ? 1u
            : 0u;
    g_ahci_memory_plan_command_list_offset = 0u;
    g_ahci_memory_plan_command_list_bytes = MMIO64_AHCI_COMMAND_LIST_BYTES;
    g_ahci_memory_plan_command_header_offset =
        g_ahci_memory_plan_slot * MMIO64_AHCI_COMMAND_HEADER_BYTES;
    g_ahci_memory_plan_command_header_bytes = g_ahci_command_plan_header_bytes;
    g_ahci_memory_plan_command_table_offset = MMIO64_AHCI_COMMAND_TABLE_OFFSET;
    g_ahci_memory_plan_command_table_bytes = g_ahci_command_plan_table_bytes;
    g_ahci_memory_plan_prdt_offset =
        g_ahci_memory_plan_command_table_offset + MMIO64_AHCI_COMMAND_TABLE_BASE_BYTES;
    g_ahci_memory_plan_prdt_bytes = g_ahci_command_plan_prdt_bytes;
    g_ahci_memory_plan_bounce_offset = MMIO64_AHCI_BOUNCE_BUFFER_OFFSET;
    g_ahci_memory_plan_bounce_bytes = g_ahci_command_plan_transfer_bytes;
    g_ahci_memory_plan_prdt_data_byte_count = g_ahci_memory_plan_bounce_bytes - 1u;
    g_ahci_memory_plan_dma_address_low = 0u;
    g_ahci_memory_plan_dma_address_high = 0u;
    g_ahci_memory_plan_dma_mapped = 0u;
    g_ahci_memory_plan_table_written = 0u;
    g_ahci_memory_plan_port_programmed = 0u;
    g_ahci_memory_plan_armed = 0u;

    if (!mmio64_range_fits(
            g_ahci_memory_plan_command_header_offset,
            g_ahci_memory_plan_command_header_bytes,
            g_ahci_memory_plan_command_list_bytes)
        || (g_ahci_memory_plan_page_materialized == 0u)
        || !mmio64_range_fits(
            g_ahci_memory_plan_command_table_offset,
            g_ahci_memory_plan_command_table_bytes,
            g_ahci_memory_plan_bounce_offset)
        || !mmio64_range_fits(
            g_ahci_memory_plan_prdt_offset,
            g_ahci_memory_plan_prdt_bytes,
            g_ahci_memory_plan_bounce_offset)
        || !mmio64_range_fits(
            g_ahci_memory_plan_bounce_offset,
            g_ahci_memory_plan_bounce_bytes,
            g_ahci_memory_plan_page_bytes))
    {
        ++g_ahci_memory_plan_unavailable_count;
        mmio64_reset_memory_plan();
        g_ahci_memory_plan_state = MMIO64_AHCI_MEM_PLAN_STATE_UNAVAILABLE;
        g_ahci_memory_plan_flags = MMIO64_AHCI_MEM_PLAN_FLAG_REQUESTED
            | MMIO64_AHCI_MEM_PLAN_FLAG_NO_MEMORY_WRITES
            | MMIO64_AHCI_MEM_PLAN_FLAG_NO_DMA_MAPPING
            | MMIO64_AHCI_MEM_PLAN_FLAG_NO_PORT_WRITES
            | MMIO64_AHCI_MEM_PLAN_FLAG_NO_COMMANDS
            | MMIO64_AHCI_MEM_PLAN_FLAG_NOT_ARMED
            | MMIO64_AHCI_MEM_PLAN_FLAG_CAPABILITY_GATED
            | MMIO64_AHCI_MEM_PLAN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    flags = MMIO64_AHCI_MEM_PLAN_FLAG_REQUESTED
        | MMIO64_AHCI_MEM_PLAN_FLAG_COMMAND_PLAN_READY
        | MMIO64_AHCI_MEM_PLAN_FLAG_BROKER_OWNED
        | MMIO64_AHCI_MEM_PLAN_FLAG_ONE_PAGE
        | MMIO64_AHCI_MEM_PLAN_FLAG_PAGE_ALIGNED
        | MMIO64_AHCI_MEM_PLAN_FLAG_COMMAND_LIST_DESCRIBED
        | MMIO64_AHCI_MEM_PLAN_FLAG_HEADER_BOUND
        | MMIO64_AHCI_MEM_PLAN_FLAG_TABLE_BOUND
        | MMIO64_AHCI_MEM_PLAN_FLAG_PRDT_BOUND
        | MMIO64_AHCI_MEM_PLAN_FLAG_BOUNCE_BOUND
        | MMIO64_AHCI_MEM_PLAN_FLAG_TRANSFER_BOUNDED
        | MMIO64_AHCI_MEM_PLAN_FLAG_NO_MEMORY_WRITES
        | MMIO64_AHCI_MEM_PLAN_FLAG_NO_DMA_MAPPING
        | MMIO64_AHCI_MEM_PLAN_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_MEM_PLAN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_MEM_PLAN_FLAG_NOT_ARMED
        | MMIO64_AHCI_MEM_PLAN_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_MEM_PLAN_FLAG_USES_COMMAND_PLAN_TOKEN
        | MMIO64_AHCI_MEM_PLAN_FLAG_PAGE_MATERIALIZED
        | MMIO64_AHCI_MEM_PLAN_FLAG_PAGE_ZEROED
        | MMIO64_AHCI_MEM_PLAN_FLAG_CHECKSUM_RECORDED
        | MMIO64_AHCI_MEM_PLAN_FLAG_KERNEL_PRIVATE;

    g_ahci_memory_plan_flags = flags;
    g_ahci_memory_plan_token = mmio64_make_memory_plan_token();
    ++g_ahci_memory_plan_stage_count;
    return g_ahci_memory_plan_token;
}

