u32 mmio64_prepare_ahci_command_table(u32 hardware_capability_handle, u32 owner_id)
{
    u32 flags;
    u32 header_offset;
    u32 table_offset;
    u32 packet_offset;
    u32 prdt_offset;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_table_plan_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if (!mmio64_memory_plan_ready())
    {
        ++g_ahci_table_plan_unavailable_count;
        mmio64_reset_table_plan();
        g_ahci_table_plan_state = MMIO64_AHCI_TABLE_PLAN_STATE_UNAVAILABLE;
        g_ahci_table_plan_flags = MMIO64_AHCI_TABLE_PLAN_FLAG_REQUESTED
            | MMIO64_AHCI_TABLE_PLAN_FLAG_NO_DMA_MAPPING
            | MMIO64_AHCI_TABLE_PLAN_FLAG_NO_MMIO_WRITES
            | MMIO64_AHCI_TABLE_PLAN_FLAG_NO_PORT_WRITES
            | MMIO64_AHCI_TABLE_PLAN_FLAG_NO_COMMANDS
            | MMIO64_AHCI_TABLE_PLAN_FLAG_NOT_ARMED
            | MMIO64_AHCI_TABLE_PLAN_FLAG_CAPABILITY_GATED
            | MMIO64_AHCI_TABLE_PLAN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    header_offset = g_ahci_memory_plan_command_header_offset;
    table_offset = g_ahci_memory_plan_command_table_offset;
    packet_offset = table_offset + MMIO64_AHCI_ATAPI_PACKET_OFFSET;
    prdt_offset = g_ahci_memory_plan_prdt_offset;
    if (!mmio64_range_fits(
            header_offset,
            g_ahci_memory_plan_command_header_bytes,
            g_ahci_memory_plan_command_list_bytes)
        || !mmio64_range_fits(
            table_offset,
            g_ahci_memory_plan_command_table_bytes,
            g_ahci_memory_plan_bounce_offset)
        || !mmio64_range_fits(
            prdt_offset,
            g_ahci_memory_plan_prdt_bytes,
            g_ahci_memory_plan_bounce_offset)
        || ((g_ahci_command_plan_operation == MMIO64_AHCI_READ_OPERATION_ATAPI_READ_10)
            && !mmio64_range_fits(
                packet_offset,
                MMIO64_AHCI_ATAPI_PACKET_BYTES,
                g_ahci_memory_plan_prdt_offset)))
    {
        ++g_ahci_table_plan_unavailable_count;
        mmio64_reset_table_plan();
        g_ahci_table_plan_state = MMIO64_AHCI_TABLE_PLAN_STATE_UNAVAILABLE;
        g_ahci_table_plan_flags = MMIO64_AHCI_TABLE_PLAN_FLAG_REQUESTED
            | MMIO64_AHCI_TABLE_PLAN_FLAG_NO_DMA_MAPPING
            | MMIO64_AHCI_TABLE_PLAN_FLAG_NO_MMIO_WRITES
            | MMIO64_AHCI_TABLE_PLAN_FLAG_NO_PORT_WRITES
            | MMIO64_AHCI_TABLE_PLAN_FLAG_NO_COMMANDS
            | MMIO64_AHCI_TABLE_PLAN_FLAG_NOT_ARMED
            | MMIO64_AHCI_TABLE_PLAN_FLAG_CAPABILITY_GATED
            | MMIO64_AHCI_TABLE_PLAN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_table_plan();
    mmio64_zero_bytes(g_ahci_command_page, MMIO64_PAGE_BYTES);

    g_ahci_table_plan_state = MMIO64_AHCI_TABLE_PLAN_STATE_PREPARED_NO_ISSUE;
    g_ahci_table_plan_memory_token = g_ahci_memory_plan_token;
    g_ahci_table_plan_checksum_before =
        mmio64_checksum_bytes((const u8 *)g_ahci_command_page, MMIO64_PAGE_BYTES);
    g_ahci_table_plan_header_prdt_length = g_ahci_command_plan_prdt_entries;
    g_ahci_table_plan_header_prdbc = 0u;
    g_ahci_table_plan_header_ctba_low = 0u;
    g_ahci_table_plan_header_ctba_high = 0u;
    g_ahci_table_plan_header_flags = MMIO64_AHCI_COMMAND_HEADER_CFL
        | (g_ahci_table_plan_header_prdt_length << 16);

    if (g_ahci_command_plan_operation == MMIO64_AHCI_READ_OPERATION_ATAPI_READ_10)
    {
        g_ahci_table_plan_header_flags |= MMIO64_AHCI_COMMAND_HEADER_ATAPI;
    }

    mmio64_write_u32(g_ahci_command_page, header_offset, g_ahci_table_plan_header_flags);
    mmio64_write_u32(g_ahci_command_page, header_offset + 4u, g_ahci_table_plan_header_prdbc);
    mmio64_write_u32(g_ahci_command_page, header_offset + 8u, g_ahci_table_plan_header_ctba_low);
    mmio64_write_u32(g_ahci_command_page, header_offset + 12u, g_ahci_table_plan_header_ctba_high);

    g_ahci_table_plan_cfis_type = MMIO64_AHCI_REGISTER_FIS_TYPE_H2D;
    g_ahci_table_plan_cfis_flags = MMIO64_AHCI_REGISTER_FIS_COMMAND;
    g_ahci_table_plan_cfis_command = g_ahci_command_plan_command_opcode;
    g_ahci_table_plan_cfis_device = MMIO64_ATA_DEVICE_LBA;
    if (g_ahci_command_plan_operation == MMIO64_AHCI_READ_OPERATION_ATA_READ_DMA_EXT)
    {
        g_ahci_table_plan_cfis_count = g_ahci_read_plan_block_count;
    }
    else
    {
        g_ahci_table_plan_cfis_count = 0u;
    }

    g_ahci_command_page[table_offset] = (u8)g_ahci_table_plan_cfis_type;
    g_ahci_command_page[table_offset + 1u] = (u8)g_ahci_table_plan_cfis_flags;
    g_ahci_command_page[table_offset + 2u] = (u8)g_ahci_table_plan_cfis_command;
    g_ahci_command_page[table_offset + 4u] = (u8)(g_ahci_read_plan_lba_low & 0xFFu);
    g_ahci_command_page[table_offset + 5u] = (u8)((g_ahci_read_plan_lba_low >> 8) & 0xFFu);
    g_ahci_command_page[table_offset + 6u] = (u8)((g_ahci_read_plan_lba_low >> 16) & 0xFFu);
    g_ahci_command_page[table_offset + 7u] = (u8)g_ahci_table_plan_cfis_device;
    g_ahci_command_page[table_offset + 8u] = (u8)((g_ahci_read_plan_lba_low >> 24) & 0xFFu);
    mmio64_write_u16(g_ahci_command_page, table_offset + 12u, g_ahci_table_plan_cfis_count);

    if (g_ahci_command_plan_operation == MMIO64_AHCI_READ_OPERATION_ATAPI_READ_10)
    {
        g_ahci_table_plan_packet_opcode = g_ahci_command_plan_packet_opcode;
        g_ahci_table_plan_packet_blocks = g_ahci_read_plan_block_count;
        g_ahci_command_page[packet_offset] = (u8)g_ahci_table_plan_packet_opcode;
        g_ahci_command_page[packet_offset + 2u] = (u8)((g_ahci_read_plan_lba_low >> 24) & 0xFFu);
        g_ahci_command_page[packet_offset + 3u] = (u8)((g_ahci_read_plan_lba_low >> 16) & 0xFFu);
        g_ahci_command_page[packet_offset + 4u] = (u8)((g_ahci_read_plan_lba_low >> 8) & 0xFFu);
        g_ahci_command_page[packet_offset + 5u] = (u8)(g_ahci_read_plan_lba_low & 0xFFu);
        g_ahci_command_page[packet_offset + 7u] =
            (u8)((g_ahci_table_plan_packet_blocks >> 8) & 0xFFu);
        g_ahci_command_page[packet_offset + 8u] =
            (u8)(g_ahci_table_plan_packet_blocks & 0xFFu);
    }

    g_ahci_table_plan_prdt_dba_low = 0u;
    g_ahci_table_plan_prdt_dba_high = 0u;
    g_ahci_table_plan_prdt_byte_count = g_ahci_memory_plan_prdt_data_byte_count;
    mmio64_write_u32(g_ahci_command_page, prdt_offset, g_ahci_table_plan_prdt_dba_low);
    mmio64_write_u32(g_ahci_command_page, prdt_offset + 4u, g_ahci_table_plan_prdt_dba_high);
    mmio64_write_u32(g_ahci_command_page, prdt_offset + 8u, 0u);
    mmio64_write_u32(g_ahci_command_page, prdt_offset + 12u, g_ahci_table_plan_prdt_byte_count);

    g_ahci_table_plan_table_written = 1u;
    g_ahci_table_plan_dma_mapped = 0u;
    g_ahci_table_plan_port_programmed = 0u;
    g_ahci_table_plan_armed = 0u;
    g_ahci_table_plan_issued = 0u;
    g_ahci_table_plan_checksum_after =
        mmio64_checksum_bytes((const u8 *)g_ahci_command_page, MMIO64_PAGE_BYTES);
    g_ahci_table_plan_checksum_changed =
        (g_ahci_table_plan_checksum_before != g_ahci_table_plan_checksum_after) ? 1u : 0u;

    flags = MMIO64_AHCI_TABLE_PLAN_FLAG_REQUESTED
        | MMIO64_AHCI_TABLE_PLAN_FLAG_MEMORY_PLAN_READY
        | MMIO64_AHCI_TABLE_PLAN_FLAG_PAGE_MATERIALIZED
        | MMIO64_AHCI_TABLE_PLAN_FLAG_PAGE_ZEROED_BEFORE
        | MMIO64_AHCI_TABLE_PLAN_FLAG_CHECKSUM_BEFORE_RECORDED
        | MMIO64_AHCI_TABLE_PLAN_FLAG_HEADER_WRITTEN
        | MMIO64_AHCI_TABLE_PLAN_FLAG_CFIS_WRITTEN
        | MMIO64_AHCI_TABLE_PLAN_FLAG_PRDT_WRITTEN
        | MMIO64_AHCI_TABLE_PLAN_FLAG_TRANSFER_BOUNDED
        | MMIO64_AHCI_TABLE_PLAN_FLAG_ADDRESSES_HELD_ZERO
        | MMIO64_AHCI_TABLE_PLAN_FLAG_BROKER_MEMORY_ONLY
        | MMIO64_AHCI_TABLE_PLAN_FLAG_NO_DMA_MAPPING
        | MMIO64_AHCI_TABLE_PLAN_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_TABLE_PLAN_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_TABLE_PLAN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_TABLE_PLAN_FLAG_NOT_ARMED
        | MMIO64_AHCI_TABLE_PLAN_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_TABLE_PLAN_FLAG_USES_MEMORY_PLAN_TOKEN
        | MMIO64_AHCI_TABLE_PLAN_FLAG_KERNEL_PRIVATE
        | MMIO64_AHCI_TABLE_PLAN_FLAG_CHECKSUM_AFTER_RECORDED;

    if (g_ahci_command_plan_operation == MMIO64_AHCI_READ_OPERATION_ATAPI_READ_10)
    {
        flags |= MMIO64_AHCI_TABLE_PLAN_FLAG_ATAPI_PACKET_WRITTEN;
    }

    if (g_ahci_table_plan_checksum_changed != 0u)
    {
        flags |= MMIO64_AHCI_TABLE_PLAN_FLAG_CHECKSUM_CHANGED;
    }

    g_ahci_table_plan_flags = flags;
    g_ahci_table_plan_token = mmio64_make_table_plan_token();
    ++g_ahci_table_plan_stage_count;
    return g_ahci_table_plan_token;
}

