u32 mmio64_preflight_ahci_command_issue(u32 hardware_capability_handle, u32 owner_id)
{
    u32 flags;
    u32 required_flags;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_issue_plan_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if (!mmio64_table_plan_ready() || !mmio64_port_policy_ready())
    {
        ++g_ahci_issue_plan_unavailable_count;
        mmio64_reset_issue_plan();
        g_ahci_issue_plan_state = MMIO64_AHCI_ISSUE_PLAN_STATE_UNAVAILABLE;
        g_ahci_issue_plan_flags = MMIO64_AHCI_ISSUE_PLAN_FLAG_REQUESTED
            | MMIO64_AHCI_ISSUE_PLAN_FLAG_NO_DMA_MAPPING
            | MMIO64_AHCI_ISSUE_PLAN_FLAG_NO_MMIO_WRITES
            | MMIO64_AHCI_ISSUE_PLAN_FLAG_NO_PORT_WRITES
            | MMIO64_AHCI_ISSUE_PLAN_FLAG_NO_COMMANDS
            | MMIO64_AHCI_ISSUE_PLAN_FLAG_NOT_ARMED
            | MMIO64_AHCI_ISSUE_PLAN_FLAG_CAPABILITY_GATED
            | MMIO64_AHCI_ISSUE_PLAN_FLAG_UNAVAILABLE
            | MMIO64_AHCI_ISSUE_PLAN_FLAG_ISSUE_BLOCKED
            | MMIO64_AHCI_ISSUE_PLAN_FLAG_REVOCATION_REQUIRED;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_issue_plan();
    g_ahci_issue_plan_table_token = g_ahci_table_plan_token;
    g_ahci_issue_plan_memory_token = g_ahci_memory_plan_token;
    g_ahci_issue_plan_command_token = g_ahci_command_plan_token;
    g_ahci_issue_plan_read_token = g_ahci_read_plan_token;
    g_ahci_issue_plan_port = g_ahci_port_selected;
    g_ahci_issue_plan_slot = g_ahci_command_plan_slot;
    g_ahci_issue_plan_ci_snapshot = g_ahci_port_selected_ci;
    if (g_ahci_issue_plan_slot < 32u)
    {
        g_ahci_issue_plan_slot_mask = 1u << g_ahci_issue_plan_slot;
    }
    g_ahci_issue_plan_slot_idle =
        ((g_ahci_issue_plan_slot_mask != 0u)
            && ((g_ahci_issue_plan_ci_snapshot & g_ahci_issue_plan_slot_mask) == 0u))
            ? 1u : 0u;
    g_ahci_issue_plan_tfd_ready =
        ((g_ahci_port_policy_busy == 0u) && (g_ahci_port_policy_drq == 0u)) ? 1u : 0u;
    g_ahci_issue_plan_serr_clear = g_ahci_port_policy_serr_clear;
    g_ahci_issue_plan_policy_ready = g_ahci_port_policy_ready;
    g_ahci_issue_plan_engine_st =
        ((g_ahci_port_selected_command & MMIO64_AHCI_PORT_CMD_ST) != 0u) ? 1u : 0u;
    g_ahci_issue_plan_engine_fre =
        ((g_ahci_port_selected_command & MMIO64_AHCI_PORT_CMD_FRE) != 0u) ? 1u : 0u;
    g_ahci_issue_plan_engine_fr =
        ((g_ahci_port_selected_command & MMIO64_AHCI_PORT_CMD_FR) != 0u) ? 1u : 0u;
    g_ahci_issue_plan_engine_cr =
        ((g_ahci_port_selected_command & MMIO64_AHCI_PORT_CMD_CR) != 0u) ? 1u : 0u;
    g_ahci_issue_plan_stop_required =
        ((g_ahci_issue_plan_engine_st != 0u)
            || (g_ahci_issue_plan_engine_fre != 0u)
            || (g_ahci_issue_plan_engine_fr != 0u)
            || (g_ahci_issue_plan_engine_cr != 0u)) ? 1u : 0u;
    g_ahci_issue_plan_start_required = 1u;
    g_ahci_issue_plan_timeout_ticks = MMIO64_AHCI_ISSUE_PLAN_TIMEOUT_TICKS;
    g_ahci_issue_plan_poll_budget = MMIO64_AHCI_ISSUE_PLAN_POLL_BUDGET;
    g_ahci_issue_plan_table_checksum =
        mmio64_checksum_bytes((const u8 *)g_ahci_command_page, MMIO64_PAGE_BYTES);
    g_ahci_issue_plan_expected_table_checksum = g_ahci_table_plan_checksum_after;
    g_ahci_issue_plan_checksum_match =
        (g_ahci_issue_plan_table_checksum == g_ahci_issue_plan_expected_table_checksum) ? 1u : 0u;
    g_ahci_issue_plan_dma_mapped = 0u;
    g_ahci_issue_plan_port_programmed = 0u;
    g_ahci_issue_plan_command_issued = 0u;
    g_ahci_issue_plan_armed = 0u;

    flags = MMIO64_AHCI_ISSUE_PLAN_FLAG_REQUESTED
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_TABLE_PLAN_READY
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_PORT_POLICY_READY
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_ENGINE_STATE_OBSERVED
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_STOP_START_POLICY_RECORDED
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_TIMEOUT_RECORDED
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_NO_DMA_MAPPING
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_NOT_ARMED
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_USES_TABLE_PLAN_TOKEN
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_KERNEL_PRIVATE
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_ISSUE_BLOCKED
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_REVOCATION_REQUIRED;

    if (g_ahci_issue_plan_policy_ready != 0u)
    {
        flags |= MMIO64_AHCI_ISSUE_PLAN_FLAG_POLICY_READY;
    }

    if ((g_ahci_issue_plan_port != MMIO64_INVALID_RESULT)
        && (g_ahci_issue_plan_port == g_ahci_read_plan_port))
    {
        flags |= MMIO64_AHCI_ISSUE_PLAN_FLAG_SELECTED_PORT_BOUND;
    }

    if ((g_ahci_issue_plan_slot_mask != 0u)
        && (g_ahci_issue_plan_slot == g_ahci_read_plan_command_slot)
        && (g_ahci_issue_plan_slot == g_ahci_memory_plan_slot))
    {
        flags |= MMIO64_AHCI_ISSUE_PLAN_FLAG_COMMAND_SLOT_BOUND;
    }

    if (g_ahci_port_policy_ci_idle != 0u)
    {
        flags |= MMIO64_AHCI_ISSUE_PLAN_FLAG_CI_IDLE;
    }

    if (g_ahci_issue_plan_slot_idle != 0u)
    {
        flags |= MMIO64_AHCI_ISSUE_PLAN_FLAG_SLOT_IDLE;
    }

    if (g_ahci_issue_plan_tfd_ready != 0u)
    {
        flags |= MMIO64_AHCI_ISSUE_PLAN_FLAG_TFD_READY;
    }

    if (g_ahci_issue_plan_serr_clear != 0u)
    {
        flags |= MMIO64_AHCI_ISSUE_PLAN_FLAG_SERR_CLEAR;
    }

    if (g_ahci_table_plan_table_written != 0u)
    {
        flags |= MMIO64_AHCI_ISSUE_PLAN_FLAG_TABLE_WRITTEN;
    }

    if (g_ahci_issue_plan_checksum_match != 0u)
    {
        flags |= MMIO64_AHCI_ISSUE_PLAN_FLAG_TABLE_CHECKSUM_MATCHED;
    }

    if ((g_ahci_table_plan_header_ctba_low == 0u)
        && (g_ahci_table_plan_header_ctba_high == 0u)
        && (g_ahci_table_plan_prdt_dba_low == 0u)
        && (g_ahci_table_plan_prdt_dba_high == 0u))
    {
        flags |= MMIO64_AHCI_ISSUE_PLAN_FLAG_ADDRESSES_HELD_ZERO;
    }

    required_flags = MMIO64_AHCI_ISSUE_PLAN_FLAG_TABLE_PLAN_READY
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_PORT_POLICY_READY
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_POLICY_READY
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_SELECTED_PORT_BOUND
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_COMMAND_SLOT_BOUND
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_CI_IDLE
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_SLOT_IDLE
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_TFD_READY
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_SERR_CLEAR
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_TABLE_WRITTEN
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_TABLE_CHECKSUM_MATCHED
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_ADDRESSES_HELD_ZERO
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_NO_DMA_MAPPING
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_NOT_ARMED
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_USES_TABLE_PLAN_TOKEN
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_KERNEL_PRIVATE
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_ISSUE_BLOCKED
        | MMIO64_AHCI_ISSUE_PLAN_FLAG_REVOCATION_REQUIRED;

    g_ahci_issue_plan_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_issue_plan_unavailable_count;
        g_ahci_issue_plan_state = MMIO64_AHCI_ISSUE_PLAN_STATE_UNAVAILABLE;
        g_ahci_issue_plan_flags |= MMIO64_AHCI_ISSUE_PLAN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_issue_plan_state = MMIO64_AHCI_ISSUE_PLAN_STATE_READY_NO_ISSUE;
    g_ahci_issue_plan_token = mmio64_make_issue_plan_token();
    ++g_ahci_issue_plan_stage_count;
    return g_ahci_issue_plan_token;
}

