u32 mmio64_stage_ahci_address_bind_plan(u32 hardware_capability_handle, u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u64 page_physical;
    u64 command_list_physical;
    u64 command_table_physical;
    u64 bounce_physical;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_bind_plan_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if (!mmio64_issue_plan_ready() || !mmio64_table_plan_ready() || !mmio64_memory_plan_ready())
    {
        ++g_ahci_bind_plan_unavailable_count;
        mmio64_reset_bind_plan();
        g_ahci_bind_plan_state = MMIO64_AHCI_BIND_PLAN_STATE_UNAVAILABLE;
        g_ahci_bind_plan_flags = MMIO64_AHCI_BIND_PLAN_FLAG_REQUESTED
            | MMIO64_AHCI_BIND_PLAN_FLAG_NO_MEMORY_WRITES
            | MMIO64_AHCI_BIND_PLAN_FLAG_NO_DMA_MAPPING
            | MMIO64_AHCI_BIND_PLAN_FLAG_NO_MMIO_WRITES
            | MMIO64_AHCI_BIND_PLAN_FLAG_NO_PORT_WRITES
            | MMIO64_AHCI_BIND_PLAN_FLAG_NO_COMMANDS
            | MMIO64_AHCI_BIND_PLAN_FLAG_NOT_PUBLISHED
            | MMIO64_AHCI_BIND_PLAN_FLAG_NOT_ARMED
            | MMIO64_AHCI_BIND_PLAN_FLAG_CAPABILITY_GATED
            | MMIO64_AHCI_BIND_PLAN_FLAG_REVOCATION_REQUIRED
            | MMIO64_AHCI_BIND_PLAN_FLAG_PREDICTED_ONLY
            | MMIO64_AHCI_BIND_PLAN_FLAG_KERNEL_PRIVATE
            | MMIO64_AHCI_BIND_PLAN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_bind_plan();
    page_physical = g_ahci_memory_plan_page_physical;
    command_list_physical = page_physical + (u64)g_ahci_memory_plan_command_list_offset;
    command_table_physical = page_physical + (u64)g_ahci_memory_plan_command_table_offset;
    bounce_physical = page_physical + (u64)g_ahci_memory_plan_bounce_offset;

    g_ahci_bind_plan_issue_token = g_ahci_issue_plan_token;
    g_ahci_bind_plan_table_token = g_ahci_table_plan_token;
    g_ahci_bind_plan_memory_token = g_ahci_memory_plan_token;
    g_ahci_bind_plan_command_token = g_ahci_command_plan_token;
    g_ahci_bind_plan_read_token = g_ahci_read_plan_token;
    g_ahci_bind_plan_page_physical_low = (u32)(page_physical & 0xFFFFFFFFull);
    g_ahci_bind_plan_page_physical_high = (u32)(page_physical >> 32);
    g_ahci_bind_plan_command_list_low = (u32)(command_list_physical & 0xFFFFFFFFull);
    g_ahci_bind_plan_command_list_high = (u32)(command_list_physical >> 32);
    g_ahci_bind_plan_command_table_low = (u32)(command_table_physical & 0xFFFFFFFFull);
    g_ahci_bind_plan_command_table_high = (u32)(command_table_physical >> 32);
    g_ahci_bind_plan_bounce_low = (u32)(bounce_physical & 0xFFFFFFFFull);
    g_ahci_bind_plan_bounce_high = (u32)(bounce_physical >> 32);
    g_ahci_bind_plan_header_ctba_low = g_ahci_bind_plan_command_table_low;
    g_ahci_bind_plan_header_ctba_high = g_ahci_bind_plan_command_table_high;
    g_ahci_bind_plan_prdt_dba_low = g_ahci_bind_plan_bounce_low;
    g_ahci_bind_plan_prdt_dba_high = g_ahci_bind_plan_bounce_high;
    g_ahci_bind_plan_prdt_byte_count = g_ahci_memory_plan_prdt_data_byte_count;
    g_ahci_bind_plan_header_patch_offset = g_ahci_memory_plan_command_header_offset + 8u;
    g_ahci_bind_plan_prdt_patch_offset = g_ahci_memory_plan_prdt_offset;
    g_ahci_bind_plan_checksum_before =
        mmio64_checksum_bytes((const u8 *)g_ahci_command_page, MMIO64_PAGE_BYTES);
    g_ahci_bind_plan_checksum_predicted =
        mmio64_checksum_command_page_with_address_bind(
            g_ahci_bind_plan_header_patch_offset,
            g_ahci_bind_plan_header_ctba_low,
            g_ahci_bind_plan_header_ctba_high,
            g_ahci_bind_plan_prdt_patch_offset,
            g_ahci_bind_plan_prdt_dba_low,
            g_ahci_bind_plan_prdt_dba_high);
    g_ahci_bind_plan_checksum_changed =
        (g_ahci_bind_plan_checksum_before != g_ahci_bind_plan_checksum_predicted) ? 1u : 0u;
    g_ahci_bind_plan_address_aligned =
        (((page_physical & (MMIO64_PAGE_BYTES - 1u)) == 0ull)
            && ((command_list_physical & 0x3FFull) == 0ull)
            && ((command_table_physical & 0x7Full) == 0ull)
            && ((bounce_physical & 0x1ull) == 0ull)) ? 1u : 0u;
    g_ahci_bind_plan_address_range_ready =
        (mmio64_range_fits(
                g_ahci_memory_plan_command_list_offset,
                g_ahci_memory_plan_command_list_bytes,
                MMIO64_PAGE_BYTES)
            && mmio64_range_fits(
                g_ahci_memory_plan_command_table_offset,
                g_ahci_memory_plan_command_table_bytes,
                MMIO64_PAGE_BYTES)
            && mmio64_range_fits(
                g_ahci_memory_plan_bounce_offset,
                g_ahci_memory_plan_bounce_bytes,
                MMIO64_PAGE_BYTES)
            && mmio64_range_fits(g_ahci_bind_plan_header_patch_offset, 8u, MMIO64_PAGE_BYTES)
            && mmio64_range_fits(g_ahci_bind_plan_prdt_patch_offset, 8u, MMIO64_PAGE_BYTES))
            ? 1u : 0u;
    g_ahci_bind_plan_address_below_4g =
        ((g_ahci_bind_plan_page_physical_high == 0u)
            && (g_ahci_bind_plan_command_list_high == 0u)
            && (g_ahci_bind_plan_command_table_high == 0u)
            && (g_ahci_bind_plan_bounce_high == 0u)) ? 1u : 0u;
    g_ahci_bind_plan_memory_written = 0u;
    g_ahci_bind_plan_dma_mapped = 0u;
    g_ahci_bind_plan_port_programmed = 0u;
    g_ahci_bind_plan_published = 0u;
    g_ahci_bind_plan_command_issued = 0u;
    g_ahci_bind_plan_armed = 0u;

    flags = MMIO64_AHCI_BIND_PLAN_FLAG_REQUESTED
        | MMIO64_AHCI_BIND_PLAN_FLAG_ISSUE_PLAN_READY
        | MMIO64_AHCI_BIND_PLAN_FLAG_TABLE_PLAN_READY
        | MMIO64_AHCI_BIND_PLAN_FLAG_MEMORY_PLAN_READY
        | MMIO64_AHCI_BIND_PLAN_FLAG_PAGE_MATERIALIZED
        | MMIO64_AHCI_BIND_PLAN_FLAG_PRIVATE_PAGE
        | MMIO64_AHCI_BIND_PLAN_FLAG_COMMAND_LIST_ADDR_BOUND
        | MMIO64_AHCI_BIND_PLAN_FLAG_COMMAND_TABLE_ADDR_BOUND
        | MMIO64_AHCI_BIND_PLAN_FLAG_BOUNCE_ADDR_BOUND
        | MMIO64_AHCI_BIND_PLAN_FLAG_HEADER_PATCH_DESCRIBED
        | MMIO64_AHCI_BIND_PLAN_FLAG_PRDT_PATCH_DESCRIBED
        | MMIO64_AHCI_BIND_PLAN_FLAG_CHECKSUM_BEFORE_RECORDED
        | MMIO64_AHCI_BIND_PLAN_FLAG_CHECKSUM_AFTER_PREDICTED
        | MMIO64_AHCI_BIND_PLAN_FLAG_NO_MEMORY_WRITES
        | MMIO64_AHCI_BIND_PLAN_FLAG_NO_DMA_MAPPING
        | MMIO64_AHCI_BIND_PLAN_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_BIND_PLAN_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_BIND_PLAN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_BIND_PLAN_FLAG_NOT_PUBLISHED
        | MMIO64_AHCI_BIND_PLAN_FLAG_NOT_ARMED
        | MMIO64_AHCI_BIND_PLAN_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_BIND_PLAN_FLAG_USES_ISSUE_PLAN_TOKEN
        | MMIO64_AHCI_BIND_PLAN_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_BIND_PLAN_FLAG_PREDICTED_ONLY
        | MMIO64_AHCI_BIND_PLAN_FLAG_KERNEL_PRIVATE;

    if (g_ahci_bind_plan_address_aligned != 0u)
    {
        flags |= MMIO64_AHCI_BIND_PLAN_FLAG_ADDRESS_ALIGN_READY;
    }

    if (g_ahci_bind_plan_address_range_ready != 0u)
    {
        flags |= MMIO64_AHCI_BIND_PLAN_FLAG_ADDRESS_RANGE_READY;
    }

    if (g_ahci_bind_plan_address_below_4g != 0u)
    {
        flags |= MMIO64_AHCI_BIND_PLAN_FLAG_BELOW_4G;
    }

    required_flags = MMIO64_AHCI_BIND_PLAN_FLAG_ISSUE_PLAN_READY
        | MMIO64_AHCI_BIND_PLAN_FLAG_TABLE_PLAN_READY
        | MMIO64_AHCI_BIND_PLAN_FLAG_MEMORY_PLAN_READY
        | MMIO64_AHCI_BIND_PLAN_FLAG_PAGE_MATERIALIZED
        | MMIO64_AHCI_BIND_PLAN_FLAG_PRIVATE_PAGE
        | MMIO64_AHCI_BIND_PLAN_FLAG_COMMAND_LIST_ADDR_BOUND
        | MMIO64_AHCI_BIND_PLAN_FLAG_COMMAND_TABLE_ADDR_BOUND
        | MMIO64_AHCI_BIND_PLAN_FLAG_BOUNCE_ADDR_BOUND
        | MMIO64_AHCI_BIND_PLAN_FLAG_HEADER_PATCH_DESCRIBED
        | MMIO64_AHCI_BIND_PLAN_FLAG_PRDT_PATCH_DESCRIBED
        | MMIO64_AHCI_BIND_PLAN_FLAG_ADDRESS_ALIGN_READY
        | MMIO64_AHCI_BIND_PLAN_FLAG_ADDRESS_RANGE_READY
        | MMIO64_AHCI_BIND_PLAN_FLAG_BELOW_4G
        | MMIO64_AHCI_BIND_PLAN_FLAG_CHECKSUM_BEFORE_RECORDED
        | MMIO64_AHCI_BIND_PLAN_FLAG_CHECKSUM_AFTER_PREDICTED
        | MMIO64_AHCI_BIND_PLAN_FLAG_NO_MEMORY_WRITES
        | MMIO64_AHCI_BIND_PLAN_FLAG_NO_DMA_MAPPING
        | MMIO64_AHCI_BIND_PLAN_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_BIND_PLAN_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_BIND_PLAN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_BIND_PLAN_FLAG_NOT_PUBLISHED
        | MMIO64_AHCI_BIND_PLAN_FLAG_NOT_ARMED
        | MMIO64_AHCI_BIND_PLAN_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_BIND_PLAN_FLAG_USES_ISSUE_PLAN_TOKEN
        | MMIO64_AHCI_BIND_PLAN_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_BIND_PLAN_FLAG_PREDICTED_ONLY
        | MMIO64_AHCI_BIND_PLAN_FLAG_KERNEL_PRIVATE;

    g_ahci_bind_plan_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_bind_plan_unavailable_count;
        g_ahci_bind_plan_state = MMIO64_AHCI_BIND_PLAN_STATE_UNAVAILABLE;
        g_ahci_bind_plan_flags |= MMIO64_AHCI_BIND_PLAN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_bind_plan_state = MMIO64_AHCI_BIND_PLAN_STATE_STAGED_NO_WRITE;
    g_ahci_bind_plan_token = mmio64_make_bind_plan_token();
    ++g_ahci_bind_plan_stage_count;
    return g_ahci_bind_plan_token;
}

