u32 mmio64_apply_ahci_private_address_patch(u32 hardware_capability_handle, u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 range_ready;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_patch_plan_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if (!mmio64_bind_plan_ready())
    {
        ++g_ahci_patch_plan_unavailable_count;
        mmio64_reset_patch_plan();
        g_ahci_patch_plan_state = MMIO64_AHCI_PATCH_PLAN_STATE_UNAVAILABLE;
        g_ahci_patch_plan_flags = MMIO64_AHCI_PATCH_PLAN_FLAG_REQUESTED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_DMA_MAPPING
            | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_MMIO_WRITES
            | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_PORT_WRITES
            | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_COMMANDS
            | MMIO64_AHCI_PATCH_PLAN_FLAG_NOT_PUBLISHED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_NOT_ARMED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_CAPABILITY_GATED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_REVOCATION_REQUIRED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_KERNEL_PRIVATE
            | MMIO64_AHCI_PATCH_PLAN_FLAG_PUBLISH_BLOCKED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_COMMAND_ISSUE_BLOCKED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_patch_plan();
    g_ahci_patch_plan_bind_token = g_ahci_bind_plan_token;
    g_ahci_patch_plan_issue_token = g_ahci_bind_plan_issue_token;
    g_ahci_patch_plan_table_token = g_ahci_bind_plan_table_token;
    g_ahci_patch_plan_memory_token = g_ahci_bind_plan_memory_token;
    g_ahci_patch_plan_command_token = g_ahci_bind_plan_command_token;
    g_ahci_patch_plan_read_token = g_ahci_bind_plan_read_token;
    g_ahci_patch_plan_header_patch_offset = g_ahci_bind_plan_header_patch_offset;
    g_ahci_patch_plan_prdt_patch_offset = g_ahci_bind_plan_prdt_patch_offset;
    g_ahci_patch_plan_header_ctba_low = g_ahci_bind_plan_header_ctba_low;
    g_ahci_patch_plan_header_ctba_high = g_ahci_bind_plan_header_ctba_high;
    g_ahci_patch_plan_prdt_dba_low = g_ahci_bind_plan_prdt_dba_low;
    g_ahci_patch_plan_prdt_dba_high = g_ahci_bind_plan_prdt_dba_high;
    g_ahci_patch_plan_checksum_before =
        mmio64_checksum_bytes((const u8 *)g_ahci_command_page, MMIO64_PAGE_BYTES);
    g_ahci_patch_plan_checksum_expected = g_ahci_bind_plan_checksum_predicted;
    range_ready =
        (mmio64_range_fits(g_ahci_patch_plan_header_patch_offset, 8u, MMIO64_PAGE_BYTES)
            && mmio64_range_fits(g_ahci_patch_plan_prdt_patch_offset, 8u, MMIO64_PAGE_BYTES))
            ? 1u : 0u;

    if ((g_ahci_patch_plan_checksum_before != g_ahci_bind_plan_checksum_before)
        || (range_ready == 0u))
    {
        ++g_ahci_patch_plan_unavailable_count;
        g_ahci_patch_plan_state = MMIO64_AHCI_PATCH_PLAN_STATE_UNAVAILABLE;
        g_ahci_patch_plan_flags = MMIO64_AHCI_PATCH_PLAN_FLAG_REQUESTED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_BIND_PLAN_READY
            | MMIO64_AHCI_PATCH_PLAN_FLAG_CHECKSUM_BEFORE_RECORDED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_DMA_MAPPING
            | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_MMIO_WRITES
            | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_PORT_WRITES
            | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_COMMANDS
            | MMIO64_AHCI_PATCH_PLAN_FLAG_NOT_PUBLISHED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_NOT_ARMED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_CAPABILITY_GATED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_USES_BIND_PLAN_TOKEN
            | MMIO64_AHCI_PATCH_PLAN_FLAG_REVOCATION_REQUIRED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_KERNEL_PRIVATE
            | MMIO64_AHCI_PATCH_PLAN_FLAG_PUBLISH_BLOCKED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_COMMAND_ISSUE_BLOCKED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_write_u32(
        g_ahci_command_page,
        g_ahci_patch_plan_header_patch_offset,
        g_ahci_patch_plan_header_ctba_low);
    mmio64_write_u32(
        g_ahci_command_page,
        g_ahci_patch_plan_header_patch_offset + 4u,
        g_ahci_patch_plan_header_ctba_high);
    mmio64_write_u32(
        g_ahci_command_page,
        g_ahci_patch_plan_prdt_patch_offset,
        g_ahci_patch_plan_prdt_dba_low);
    mmio64_write_u32(
        g_ahci_command_page,
        g_ahci_patch_plan_prdt_patch_offset + 4u,
        g_ahci_patch_plan_prdt_dba_high);

    g_ahci_patch_plan_checksum_after =
        mmio64_checksum_bytes((const u8 *)g_ahci_command_page, MMIO64_PAGE_BYTES);
    g_ahci_patch_plan_checksum_match =
        (g_ahci_patch_plan_checksum_after == g_ahci_patch_plan_checksum_expected) ? 1u : 0u;
    g_ahci_patch_plan_checksum_changed =
        (g_ahci_patch_plan_checksum_before != g_ahci_patch_plan_checksum_after) ? 1u : 0u;
    g_ahci_patch_plan_memory_written = 1u;
    g_ahci_patch_plan_dma_mapped = 0u;
    g_ahci_patch_plan_port_programmed = 0u;
    g_ahci_patch_plan_published = 0u;
    g_ahci_patch_plan_command_issued = 0u;
    g_ahci_patch_plan_armed = 0u;

    flags = MMIO64_AHCI_PATCH_PLAN_FLAG_REQUESTED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_BIND_PLAN_READY
        | MMIO64_AHCI_PATCH_PLAN_FLAG_ISSUE_PLAN_READY
        | MMIO64_AHCI_PATCH_PLAN_FLAG_TABLE_PLAN_READY
        | MMIO64_AHCI_PATCH_PLAN_FLAG_MEMORY_PLAN_READY
        | MMIO64_AHCI_PATCH_PLAN_FLAG_PRIVATE_PAGE
        | MMIO64_AHCI_PATCH_PLAN_FLAG_HEADER_CTBA_WRITTEN
        | MMIO64_AHCI_PATCH_PLAN_FLAG_PRDT_DBA_WRITTEN
        | MMIO64_AHCI_PATCH_PLAN_FLAG_CHECKSUM_BEFORE_RECORDED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_CHECKSUM_AFTER_RECORDED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_MEMORY_WRITTEN
        | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_DMA_MAPPING
        | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_PATCH_PLAN_FLAG_NOT_PUBLISHED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_NOT_ARMED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_USES_BIND_PLAN_TOKEN
        | MMIO64_AHCI_PATCH_PLAN_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_KERNEL_PRIVATE
        | MMIO64_AHCI_PATCH_PLAN_FLAG_PUBLISH_BLOCKED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_COMMAND_ISSUE_BLOCKED;

    if (g_ahci_patch_plan_checksum_match != 0u)
    {
        flags |= MMIO64_AHCI_PATCH_PLAN_FLAG_CHECKSUM_EXPECTED_MATCHED
            | MMIO64_AHCI_PATCH_PLAN_FLAG_CHECKSUM_BIND_PREDICTED;
    }

    if (g_ahci_patch_plan_checksum_changed != 0u)
    {
        flags |= MMIO64_AHCI_PATCH_PLAN_FLAG_CHECKSUM_CHANGED;
    }

    if (range_ready != 0u)
    {
        flags |= MMIO64_AHCI_PATCH_PLAN_FLAG_ADDRESS_RANGE_READY;
    }

    required_flags = MMIO64_AHCI_PATCH_PLAN_FLAG_BIND_PLAN_READY
        | MMIO64_AHCI_PATCH_PLAN_FLAG_ISSUE_PLAN_READY
        | MMIO64_AHCI_PATCH_PLAN_FLAG_TABLE_PLAN_READY
        | MMIO64_AHCI_PATCH_PLAN_FLAG_MEMORY_PLAN_READY
        | MMIO64_AHCI_PATCH_PLAN_FLAG_PRIVATE_PAGE
        | MMIO64_AHCI_PATCH_PLAN_FLAG_HEADER_CTBA_WRITTEN
        | MMIO64_AHCI_PATCH_PLAN_FLAG_PRDT_DBA_WRITTEN
        | MMIO64_AHCI_PATCH_PLAN_FLAG_CHECKSUM_BEFORE_RECORDED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_CHECKSUM_EXPECTED_MATCHED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_CHECKSUM_AFTER_RECORDED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_CHECKSUM_CHANGED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_MEMORY_WRITTEN
        | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_DMA_MAPPING
        | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PATCH_PLAN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_PATCH_PLAN_FLAG_NOT_PUBLISHED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_NOT_ARMED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_USES_BIND_PLAN_TOKEN
        | MMIO64_AHCI_PATCH_PLAN_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_KERNEL_PRIVATE
        | MMIO64_AHCI_PATCH_PLAN_FLAG_PUBLISH_BLOCKED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_COMMAND_ISSUE_BLOCKED
        | MMIO64_AHCI_PATCH_PLAN_FLAG_ADDRESS_RANGE_READY
        | MMIO64_AHCI_PATCH_PLAN_FLAG_CHECKSUM_BIND_PREDICTED;

    g_ahci_patch_plan_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_patch_plan_unavailable_count;
        g_ahci_patch_plan_state = MMIO64_AHCI_PATCH_PLAN_STATE_UNAVAILABLE;
        g_ahci_patch_plan_flags |= MMIO64_AHCI_PATCH_PLAN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_patch_plan_state = MMIO64_AHCI_PATCH_PLAN_STATE_PATCHED_PRIVATE_NO_PUBLISH;
    g_ahci_patch_plan_token = mmio64_make_patch_plan_token();
    ++g_ahci_patch_plan_stage_count;
    return g_ahci_patch_plan_token;
}

