u32 mmio64_stage_ahci_controller_publish_plan(u32 hardware_capability_handle, u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u64 command_list_physical;
    u64 receive_fis_physical;
    u64 page_physical;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_publish_plan_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if (!mmio64_patch_plan_ready())
    {
        ++g_ahci_publish_plan_unavailable_count;
        mmio64_reset_publish_plan();
        g_ahci_publish_plan_state = MMIO64_AHCI_PUBLISH_PLAN_STATE_UNAVAILABLE;
        g_ahci_publish_plan_flags = MMIO64_AHCI_PUBLISH_PLAN_FLAG_REQUESTED
            | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_MEMORY_WRITES
            | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_DMA_MAPPING
            | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_MMIO_WRITES
            | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_PORT_WRITES
            | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_COMMANDS
            | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NOT_PUBLISHED
            | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NOT_ARMED
            | MMIO64_AHCI_PUBLISH_PLAN_FLAG_CAPABILITY_GATED
            | MMIO64_AHCI_PUBLISH_PLAN_FLAG_REVOCATION_REQUIRED
            | MMIO64_AHCI_PUBLISH_PLAN_FLAG_KERNEL_PRIVATE
            | MMIO64_AHCI_PUBLISH_PLAN_FLAG_PUBLISH_BLOCKED
            | MMIO64_AHCI_PUBLISH_PLAN_FLAG_COMMAND_ISSUE_BLOCKED
            | MMIO64_AHCI_PUBLISH_PLAN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_publish_plan();
    page_physical = ((u64)g_ahci_bind_plan_page_physical_high << 32)
        | (u64)g_ahci_bind_plan_page_physical_low;
    command_list_physical = ((u64)g_ahci_bind_plan_command_list_high << 32)
        | (u64)g_ahci_bind_plan_command_list_low;
    receive_fis_physical = page_physical + (u64)MMIO64_AHCI_RECEIVE_FIS_OFFSET;

    g_ahci_publish_plan_patch_token = g_ahci_patch_plan_token;
    g_ahci_publish_plan_bind_token = g_ahci_patch_plan_bind_token;
    g_ahci_publish_plan_issue_token = g_ahci_patch_plan_issue_token;
    g_ahci_publish_plan_table_token = g_ahci_patch_plan_table_token;
    g_ahci_publish_plan_memory_token = g_ahci_patch_plan_memory_token;
    g_ahci_publish_plan_command_token = g_ahci_patch_plan_command_token;
    g_ahci_publish_plan_read_token = g_ahci_patch_plan_read_token;
    g_ahci_publish_plan_port = g_ahci_issue_plan_port;
    g_ahci_publish_plan_port_base_offset = mmio64_ahci_port_offset(g_ahci_publish_plan_port, 0u);
    g_ahci_publish_plan_command_list_low = (u32)(command_list_physical & 0xFFFFFFFFull);
    g_ahci_publish_plan_command_list_high = (u32)(command_list_physical >> 32);
    g_ahci_publish_plan_receive_fis_low = (u32)(receive_fis_physical & 0xFFFFFFFFull);
    g_ahci_publish_plan_receive_fis_high = (u32)(receive_fis_physical >> 32);
    g_ahci_publish_plan_clb_offset =
        mmio64_ahci_port_offset(g_ahci_publish_plan_port, MMIO64_AHCI_PORT_CLB_OFFSET);
    g_ahci_publish_plan_clbu_offset =
        mmio64_ahci_port_offset(g_ahci_publish_plan_port, MMIO64_AHCI_PORT_CLBU_OFFSET);
    g_ahci_publish_plan_fb_offset =
        mmio64_ahci_port_offset(g_ahci_publish_plan_port, MMIO64_AHCI_PORT_FB_OFFSET);
    g_ahci_publish_plan_fbu_offset =
        mmio64_ahci_port_offset(g_ahci_publish_plan_port, MMIO64_AHCI_PORT_FBU_OFFSET);
    g_ahci_publish_plan_cmd_offset =
        mmio64_ahci_port_offset(g_ahci_publish_plan_port, MMIO64_AHCI_PORT_CMD_OFFSET);
    g_ahci_publish_plan_ci_offset =
        mmio64_ahci_port_offset(g_ahci_publish_plan_port, MMIO64_AHCI_PORT_CI_OFFSET);
    g_ahci_publish_plan_clb_value_low = g_ahci_publish_plan_command_list_low;
    g_ahci_publish_plan_clb_value_high = g_ahci_publish_plan_command_list_high;
    g_ahci_publish_plan_fb_value_low = g_ahci_publish_plan_receive_fis_low;
    g_ahci_publish_plan_fb_value_high = g_ahci_publish_plan_receive_fis_high;
    g_ahci_publish_plan_receive_fis_offset = MMIO64_AHCI_RECEIVE_FIS_OFFSET;
    g_ahci_publish_plan_receive_fis_bytes = MMIO64_AHCI_RECEIVE_FIS_BYTES;
    g_ahci_publish_plan_page_checksum =
        mmio64_checksum_bytes((const u8 *)g_ahci_command_page, MMIO64_PAGE_BYTES);
    g_ahci_publish_plan_page_checksum_match =
        (g_ahci_publish_plan_page_checksum == g_ahci_patch_plan_checksum_after) ? 1u : 0u;
    g_ahci_publish_plan_clb_aligned =
        ((command_list_physical & 0x3FFull) == 0ull) ? 1u : 0u;
    g_ahci_publish_plan_fis_aligned =
        ((receive_fis_physical & (MMIO64_AHCI_RECEIVE_FIS_ALIGNMENT - 1u)) == 0ull) ? 1u : 0u;
    g_ahci_publish_plan_range_ready =
        (mmio64_range_fits(
                g_ahci_publish_plan_receive_fis_offset,
                g_ahci_publish_plan_receive_fis_bytes,
                MMIO64_PAGE_BYTES)
            && mmio64_register_fits_span(g_ahci_publish_plan_clb_offset)
            && mmio64_register_fits_span(g_ahci_publish_plan_clbu_offset)
            && mmio64_register_fits_span(g_ahci_publish_plan_fb_offset)
            && mmio64_register_fits_span(g_ahci_publish_plan_fbu_offset)
            && mmio64_register_fits_span(g_ahci_publish_plan_cmd_offset)
            && mmio64_register_fits_span(g_ahci_publish_plan_ci_offset)) ? 1u : 0u;
    g_ahci_publish_plan_below_4g =
        ((g_ahci_publish_plan_command_list_high == 0u)
            && (g_ahci_publish_plan_receive_fis_high == 0u)) ? 1u : 0u;
    g_ahci_publish_plan_memory_written = 0u;
    g_ahci_publish_plan_dma_mapped = 0u;
    g_ahci_publish_plan_mmio_written = 0u;
    g_ahci_publish_plan_port_programmed = 0u;
    g_ahci_publish_plan_published = 0u;
    g_ahci_publish_plan_command_issued = 0u;
    g_ahci_publish_plan_armed = 0u;

    flags = MMIO64_AHCI_PUBLISH_PLAN_FLAG_REQUESTED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_PATCH_PLAN_READY
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_BIND_PLAN_READY
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_PORT_BOUND
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_REGISTER_OFFSETS_DESCRIBED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_COMMAND_LIST_ADDR_READY
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_RECEIVE_FIS_ADDR_READY
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_CLB_VALUE_READY
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_FB_VALUE_READY
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_PAGE_CHECKSUM_MATCHED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_MEMORY_WRITES
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_DMA_MAPPING
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NOT_PUBLISHED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NOT_ARMED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_USES_PATCH_PLAN_TOKEN
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_KERNEL_PRIVATE
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_PUBLISH_BLOCKED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_COMMAND_ISSUE_BLOCKED;

    if ((g_ahci_publish_plan_clb_aligned != 0u) && (g_ahci_publish_plan_fis_aligned != 0u))
    {
        flags |= MMIO64_AHCI_PUBLISH_PLAN_FLAG_ADDRESS_ALIGN_READY;
    }

    if (g_ahci_publish_plan_range_ready != 0u)
    {
        flags |= MMIO64_AHCI_PUBLISH_PLAN_FLAG_ADDRESS_RANGE_READY;
    }

    if (g_ahci_publish_plan_below_4g != 0u)
    {
        flags |= MMIO64_AHCI_PUBLISH_PLAN_FLAG_BELOW_4G;
    }

    required_flags = MMIO64_AHCI_PUBLISH_PLAN_FLAG_PATCH_PLAN_READY
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_BIND_PLAN_READY
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_PORT_BOUND
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_REGISTER_OFFSETS_DESCRIBED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_COMMAND_LIST_ADDR_READY
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_RECEIVE_FIS_ADDR_READY
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_CLB_VALUE_READY
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_FB_VALUE_READY
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_ADDRESS_ALIGN_READY
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_ADDRESS_RANGE_READY
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_BELOW_4G
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_PAGE_CHECKSUM_MATCHED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_MEMORY_WRITES
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_DMA_MAPPING
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NOT_PUBLISHED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_NOT_ARMED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_USES_PATCH_PLAN_TOKEN
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_KERNEL_PRIVATE
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_PUBLISH_BLOCKED
        | MMIO64_AHCI_PUBLISH_PLAN_FLAG_COMMAND_ISSUE_BLOCKED;

    g_ahci_publish_plan_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_publish_plan_unavailable_count;
        g_ahci_publish_plan_state = MMIO64_AHCI_PUBLISH_PLAN_STATE_UNAVAILABLE;
        g_ahci_publish_plan_flags |= MMIO64_AHCI_PUBLISH_PLAN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_publish_plan_state = MMIO64_AHCI_PUBLISH_PLAN_STATE_STAGED_NO_MMIO;
    g_ahci_publish_plan_token = mmio64_make_publish_plan_token();
    ++g_ahci_publish_plan_stage_count;
    return g_ahci_publish_plan_token;
}

