u32 mmio64_gate_ahci_controller_publication(u32 hardware_capability_handle, u32 owner_id)
{
    u32 flags;
    u32 required_flags;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_publish_gate_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_publish_gate();
    g_ahci_publish_gate_live_hardware_handles =
        capability64_live_for_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE);
    g_ahci_publish_gate_exclusive_hardware_handle =
        (g_ahci_publish_gate_live_hardware_handles == 1u) ? 1u : 0u;
    g_ahci_publish_gate_revocation_required = 1u;
    g_ahci_publish_gate_revocation_satisfied = 0u;
    g_ahci_publish_gate_write_window_enabled = 0u;
    g_ahci_publish_gate_commit_allowed = 0u;
    g_ahci_publish_gate_mmio_written = 0u;
    g_ahci_publish_gate_port_programmed = 0u;
    g_ahci_publish_gate_published = 0u;
    g_ahci_publish_gate_command_issued = 0u;
    g_ahci_publish_gate_armed = 0u;

    flags = MMIO64_AHCI_PUBLISH_GATE_FLAG_REQUESTED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_REVOCATION_NOT_SATISFIED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_WRITE_WINDOW_NOT_ENABLED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_COMMIT_BLOCKED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_NOT_PUBLISHED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_NOT_ARMED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_KERNEL_PRIVATE
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_COMMAND_ISSUE_BLOCKED;

    if (mmio64_publish_plan_ready())
    {
        g_ahci_publish_gate_publish_token = g_ahci_publish_plan_token;
        flags |= MMIO64_AHCI_PUBLISH_GATE_FLAG_PUBLISH_PLAN_READY
            | MMIO64_AHCI_PUBLISH_GATE_FLAG_PUBLISH_TOKEN_BOUND;
    }

    if (g_ahci_publish_gate_exclusive_hardware_handle != 0u)
    {
        flags |= MMIO64_AHCI_PUBLISH_GATE_FLAG_EXCLUSIVE_HARDWARE_HANDLE;
    }

    required_flags = MMIO64_AHCI_PUBLISH_GATE_FLAG_PUBLISH_PLAN_READY
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_PUBLISH_TOKEN_BOUND
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_EXCLUSIVE_HARDWARE_HANDLE
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_REVOCATION_NOT_SATISFIED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_WRITE_WINDOW_NOT_ENABLED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_COMMIT_BLOCKED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_NOT_PUBLISHED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_NOT_ARMED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_KERNEL_PRIVATE
        | MMIO64_AHCI_PUBLISH_GATE_FLAG_COMMAND_ISSUE_BLOCKED;

    g_ahci_publish_gate_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_publish_gate_unavailable_count;
        g_ahci_publish_gate_state = MMIO64_AHCI_PUBLISH_GATE_STATE_UNAVAILABLE;
        g_ahci_publish_gate_flags |= MMIO64_AHCI_PUBLISH_GATE_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_publish_gate_state = MMIO64_AHCI_PUBLISH_GATE_STATE_BLOCKED_NEEDS_REVOCATION;
    g_ahci_publish_gate_token = mmio64_make_publish_gate_token();
    ++g_ahci_publish_gate_stage_count;
    return g_ahci_publish_gate_token;
}

