u32 mmio64_stage_ahci_publish_write_window_policy(u32 hardware_capability_handle, u32 owner_id)
{
    u32 flags;
    u32 required_flags;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_publish_window_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_publish_window();
    g_ahci_publish_window_live_hardware_handles =
        capability64_live_for_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE);
    g_ahci_publish_window_exclusive_hardware_handle =
        (g_ahci_publish_window_live_hardware_handles == 1u) ? 1u : 0u;
    g_ahci_publish_window_revocation_required = 1u;
    g_ahci_publish_window_revocation_satisfied = 0u;
    g_ahci_publish_window_revocation_executed = 0u;
    g_ahci_publish_window_write_window_enabled = 0u;
    g_ahci_publish_window_commit_allowed = 0u;
    g_ahci_publish_window_mmio_written = 0u;
    g_ahci_publish_window_port_programmed = 0u;
    g_ahci_publish_window_published = 0u;
    g_ahci_publish_window_command_issued = 0u;
    g_ahci_publish_window_armed = 0u;

    flags = MMIO64_AHCI_PUBLISH_WINDOW_FLAG_REQUESTED
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_REVOCATION_NOT_EXECUTED
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_WRITE_WINDOW_DISABLED
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_COMMIT_BLOCKED
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_NO_COMMANDS
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_KERNEL_PRIVATE
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_WRITE_WINDOW_BLOCKED;

    if (g_ahci_publish_window_live_hardware_handles != 0u)
    {
        flags |= MMIO64_AHCI_PUBLISH_WINDOW_FLAG_LIVE_HANDLES_PRESENT;
    }

    if (g_ahci_publish_window_exclusive_hardware_handle != 0u)
    {
        flags |= MMIO64_AHCI_PUBLISH_WINDOW_FLAG_EXCLUSIVE_HARDWARE_HANDLE;
    }

    if (mmio64_publish_gate_ready())
    {
        g_ahci_publish_window_gate_token = g_ahci_publish_gate_token;
        g_ahci_publish_window_publish_token = g_ahci_publish_gate_publish_token;
        flags |= MMIO64_AHCI_PUBLISH_WINDOW_FLAG_GATE_READY
            | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_GATE_TOKEN_BOUND
            | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_PUBLISH_TOKEN_BOUND;
    }

    required_flags = MMIO64_AHCI_PUBLISH_WINDOW_FLAG_GATE_READY
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_GATE_TOKEN_BOUND
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_PUBLISH_TOKEN_BOUND
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_EXCLUSIVE_HARDWARE_HANDLE
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_LIVE_HANDLES_PRESENT
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_REVOCATION_NOT_EXECUTED
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_WRITE_WINDOW_DISABLED
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_COMMIT_BLOCKED
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_NO_COMMANDS
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_KERNEL_PRIVATE
        | MMIO64_AHCI_PUBLISH_WINDOW_FLAG_WRITE_WINDOW_BLOCKED;

    g_ahci_publish_window_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_publish_window_unavailable_count;
        g_ahci_publish_window_state = MMIO64_AHCI_PUBLISH_WINDOW_STATE_UNAVAILABLE;
        g_ahci_publish_window_flags |= MMIO64_AHCI_PUBLISH_WINDOW_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_publish_window_state = MMIO64_AHCI_PUBLISH_WINDOW_STATE_BLOCKED_REVOKE_FIRST;
    g_ahci_publish_window_token = mmio64_make_publish_window_token();
    ++g_ahci_publish_window_stage_count;
    return g_ahci_publish_window_token;
}

