u32 mmio64_stage_ahci_publish_revocation_plan(u32 hardware_capability_handle, u32 owner_id)
{
    u32 flags;
    u32 required_flags;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_publish_revoke_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_publish_revoke_plan();
    g_ahci_publish_revoke_live_before =
        capability64_live_for_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE);
    g_ahci_publish_revoke_live_after = g_ahci_publish_revoke_live_before;
    g_ahci_publish_revoke_exclusive_hardware_handle =
        (g_ahci_publish_revoke_live_before == 1u) ? 1u : 0u;
    g_ahci_publish_revoke_revocation_required = 1u;
    g_ahci_publish_revoke_revocation_planned =
        (g_ahci_publish_revoke_live_before != 0u) ? 1u : 0u;
    g_ahci_publish_revoke_revocation_executed = 0u;
    g_ahci_publish_revoke_would_revoke = g_ahci_publish_revoke_live_before;
    g_ahci_publish_revoke_write_window_enabled = 0u;
    g_ahci_publish_revoke_commit_allowed = 0u;
    g_ahci_publish_revoke_mmio_written = 0u;
    g_ahci_publish_revoke_port_programmed = 0u;
    g_ahci_publish_revoke_published = 0u;
    g_ahci_publish_revoke_command_issued = 0u;
    g_ahci_publish_revoke_armed = 0u;

    flags = MMIO64_AHCI_PUBLISH_REVOKE_FLAG_REQUESTED
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_REVOCATION_NOT_EXECUTED
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_POST_LIVE_UNCHANGED
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_WRITE_WINDOW_DISABLED
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_COMMIT_BLOCKED
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_NO_COMMANDS;

    if (g_ahci_publish_revoke_live_before != 0u)
    {
        flags |= MMIO64_AHCI_PUBLISH_REVOKE_FLAG_LIVE_HANDLES_OBSERVED
            | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_REVOCATION_PLANNED
            | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_WOULD_REVOKE_HANDLE;
    }

    if (g_ahci_publish_revoke_exclusive_hardware_handle != 0u)
    {
        flags |= MMIO64_AHCI_PUBLISH_REVOKE_FLAG_EXCLUSIVE_HARDWARE_HANDLE;
    }

    if (mmio64_publish_window_ready())
    {
        g_ahci_publish_revoke_window_token = g_ahci_publish_window_token;
        g_ahci_publish_revoke_gate_token = g_ahci_publish_window_gate_token;
        flags |= MMIO64_AHCI_PUBLISH_REVOKE_FLAG_WINDOW_READY
            | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_WINDOW_TOKEN_BOUND
            | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_GATE_TOKEN_BOUND;
    }

    required_flags = MMIO64_AHCI_PUBLISH_REVOKE_FLAG_WINDOW_READY
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_WINDOW_TOKEN_BOUND
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_GATE_TOKEN_BOUND
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_LIVE_HANDLES_OBSERVED
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_EXCLUSIVE_HARDWARE_HANDLE
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_REVOCATION_PLANNED
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_REVOCATION_NOT_EXECUTED
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_WOULD_REVOKE_HANDLE
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_POST_LIVE_UNCHANGED
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_WRITE_WINDOW_DISABLED
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_COMMIT_BLOCKED
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PUBLISH_REVOKE_FLAG_NO_COMMANDS;

    g_ahci_publish_revoke_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_publish_revoke_unavailable_count;
        g_ahci_publish_revoke_state = MMIO64_AHCI_PUBLISH_REVOKE_STATE_UNAVAILABLE;
        g_ahci_publish_revoke_flags |= MMIO64_AHCI_PUBLISH_REVOKE_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_publish_revoke_state = MMIO64_AHCI_PUBLISH_REVOKE_STATE_STAGED_NO_REVOKE;
    g_ahci_publish_revoke_token = mmio64_make_publish_revoke_token();
    ++g_ahci_publish_revoke_stage_count;
    return g_ahci_publish_revoke_token;
}

