u32 mmio64_request_ahci_publish_exclusive_session(u32 hardware_capability_handle, u32 owner_id)
{
    u32 flags;
    u32 required_flags;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_publish_session_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_publish_session();
    g_ahci_publish_session_live_hardware_handles =
        capability64_live_for_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE);
    g_ahci_publish_session_revocation_required = 1u;
    g_ahci_publish_session_revocation_planned =
        (g_ahci_publish_session_live_hardware_handles != 0u) ? 1u : 0u;
    g_ahci_publish_session_revocation_executed = 0u;
    g_ahci_publish_session_allowed = 0u;
    g_ahci_publish_session_driver_owned = 0u;
    g_ahci_publish_session_write_window_enabled = 0u;
    g_ahci_publish_session_commit_allowed = 0u;
    g_ahci_publish_session_mmio_written = 0u;
    g_ahci_publish_session_port_programmed = 0u;
    g_ahci_publish_session_published = 0u;
    g_ahci_publish_session_command_issued = 0u;
    g_ahci_publish_session_armed = 0u;

    flags = MMIO64_AHCI_PUBLISH_SESSION_FLAG_REQUESTED
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_REVOCATION_NOT_EXECUTED
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_SESSION_BLOCKED
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_DRIVER_NOT_OWNER
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_WRITE_WINDOW_DISABLED
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_COMMIT_BLOCKED
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_NO_COMMANDS
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_CAPABILITY_GATED;

    if (g_ahci_publish_session_live_hardware_handles != 0u)
    {
        flags |= MMIO64_AHCI_PUBLISH_SESSION_FLAG_LIVE_HANDLES_PRESENT
            | MMIO64_AHCI_PUBLISH_SESSION_FLAG_REVOCATION_PLANNED;
    }

    if (mmio64_publish_open_attempt_ready())
    {
        g_ahci_publish_session_open_token = g_ahci_publish_open_token;
        g_ahci_publish_session_revoke_token = g_ahci_publish_open_revoke_token;
        g_ahci_publish_session_window_token = g_ahci_publish_open_window_token;
        flags |= MMIO64_AHCI_PUBLISH_SESSION_FLAG_OPEN_ATTEMPT_READY
            | MMIO64_AHCI_PUBLISH_SESSION_FLAG_OPEN_TOKEN_BOUND
            | MMIO64_AHCI_PUBLISH_SESSION_FLAG_REVOKE_TOKEN_BOUND;
    }

    required_flags = MMIO64_AHCI_PUBLISH_SESSION_FLAG_REQUESTED
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_OPEN_ATTEMPT_READY
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_OPEN_TOKEN_BOUND
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_REVOKE_TOKEN_BOUND
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_REVOCATION_PLANNED
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_REVOCATION_NOT_EXECUTED
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_LIVE_HANDLES_PRESENT
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_SESSION_BLOCKED
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_DRIVER_NOT_OWNER
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_WRITE_WINDOW_DISABLED
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_COMMIT_BLOCKED
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_NO_COMMANDS
        | MMIO64_AHCI_PUBLISH_SESSION_FLAG_CAPABILITY_GATED;

    g_ahci_publish_session_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_publish_session_unavailable_count;
        g_ahci_publish_session_state = MMIO64_AHCI_PUBLISH_SESSION_STATE_UNAVAILABLE;
        g_ahci_publish_session_flags |= MMIO64_AHCI_PUBLISH_SESSION_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_publish_session_state = MMIO64_AHCI_PUBLISH_SESSION_STATE_BLOCKED_REVOKE_NOT_EXECUTED;
    g_ahci_publish_session_token = mmio64_make_publish_session_token();
    ++g_ahci_publish_session_stage_count;
    return g_ahci_publish_session_token;
}

