u32 mmio64_execute_ahci_publish_capability_drain(u32 hardware_capability_handle, u32 owner_id)
{
    u32 flags;
    u32 preflight_flags;
    u32 required_flags;
    u32 revoked_handles;

    if (!mmio64_authorize(hardware_capability_handle, owner_id, 0))
    {
        ++g_ahci_publish_drain_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_publish_drain();
    g_ahci_publish_drain_live_before =
        capability64_live_for_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE);
    g_ahci_publish_drain_live_after = g_ahci_publish_drain_live_before;
    g_ahci_publish_drain_revocation_required = 1u;
    g_ahci_publish_drain_revocation_planned =
        (g_ahci_publish_drain_live_before != 0u) ? 1u : 0u;
    g_ahci_publish_drain_write_window_enabled = 0u;
    g_ahci_publish_drain_commit_allowed = 0u;
    g_ahci_publish_drain_mmio_written = 0u;
    g_ahci_publish_drain_port_programmed = 0u;
    g_ahci_publish_drain_published = 0u;
    g_ahci_publish_drain_command_issued = 0u;
    g_ahci_publish_drain_armed = 0u;

    flags = MMIO64_AHCI_PUBLISH_DRAIN_FLAG_REQUESTED
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_WRITE_WINDOW_DISABLED
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_COMMIT_BLOCKED
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_CAPABILITY_GATED;

    if (g_ahci_publish_drain_live_before != 0u)
    {
        flags |= MMIO64_AHCI_PUBLISH_DRAIN_FLAG_LIVE_HANDLES_BEFORE
            | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_REVOCATION_PLANNED;
    }

    if (mmio64_publish_session_ready())
    {
        g_ahci_publish_drain_session_token = g_ahci_publish_session_token;
        g_ahci_publish_drain_open_token = g_ahci_publish_session_open_token;
        g_ahci_publish_drain_revoke_token = g_ahci_publish_session_revoke_token;
        g_ahci_publish_drain_window_token = g_ahci_publish_session_window_token;
        flags |= MMIO64_AHCI_PUBLISH_DRAIN_FLAG_SESSION_READY
            | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_SESSION_TOKEN_BOUND
            | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_OPEN_TOKEN_BOUND;
    }

    preflight_flags = MMIO64_AHCI_PUBLISH_DRAIN_FLAG_REQUESTED
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_SESSION_READY
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_SESSION_TOKEN_BOUND
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_OPEN_TOKEN_BOUND
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_LIVE_HANDLES_BEFORE
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_REVOCATION_PLANNED
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_WRITE_WINDOW_DISABLED
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_COMMIT_BLOCKED
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_CAPABILITY_GATED;

    if ((flags & preflight_flags) != preflight_flags)
    {
        ++g_ahci_publish_drain_unavailable_count;
        g_ahci_publish_drain_state = MMIO64_AHCI_PUBLISH_DRAIN_STATE_UNAVAILABLE;
        g_ahci_publish_drain_flags = flags | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    revoked_handles = capability64_revoke_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE);
    g_ahci_publish_drain_revoked_handles = revoked_handles;
    g_ahci_publish_drain_live_after =
        capability64_live_for_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE);
    if ((revoked_handles != 0u) && (g_ahci_publish_drain_live_after == 0u))
    {
        g_ahci_publish_drain_revocation_executed = 1u;
        flags |= MMIO64_AHCI_PUBLISH_DRAIN_FLAG_REVOCATION_EXECUTED
            | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_HANDLES_REVOKED
            | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_LIVE_HANDLES_DRAINED;
    }

    required_flags = preflight_flags
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_REVOCATION_EXECUTED
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_HANDLES_REVOKED
        | MMIO64_AHCI_PUBLISH_DRAIN_FLAG_LIVE_HANDLES_DRAINED;

    g_ahci_publish_drain_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_publish_drain_unavailable_count;
        g_ahci_publish_drain_state = MMIO64_AHCI_PUBLISH_DRAIN_STATE_UNAVAILABLE;
        g_ahci_publish_drain_flags |= MMIO64_AHCI_PUBLISH_DRAIN_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_publish_drain_state = MMIO64_AHCI_PUBLISH_DRAIN_STATE_EXECUTED;
    g_ahci_publish_drain_token = mmio64_make_publish_drain_token();
    ++g_ahci_publish_drain_stage_count;
    return g_ahci_publish_drain_token;
}

