u32 mmio64_stage_ahci_publish_driver_handoff(
    u32 stale_hardware_capability_handle,
    u32 drain_token,
    u32 requester_owner_id,
    u32 driver_owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 granted_handle;

    if (requester_owner_id != PRINCIPAL64_ID_INIT_SUPERVISOR)
    {
        ++g_ahci_publish_handoff_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_publish_handoff();
    g_ahci_publish_handoff_drain_token = drain_token;
    g_ahci_publish_handoff_old_handle = stale_hardware_capability_handle;
    g_ahci_publish_handoff_driver_owner = driver_owner_id;
    g_ahci_publish_handoff_live_before =
        capability64_live_for_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE);
    g_ahci_publish_handoff_live_after = g_ahci_publish_handoff_live_before;
    g_ahci_publish_handoff_driver_principal_valid = principal64_is_active(driver_owner_id);
    g_ahci_publish_handoff_driver_role = principal64_role(driver_owner_id);
    g_ahci_publish_handoff_write_window_enabled = 0u;
    g_ahci_publish_handoff_commit_allowed = 0u;
    g_ahci_publish_handoff_mmio_written = 0u;
    g_ahci_publish_handoff_port_programmed = 0u;
    g_ahci_publish_handoff_published = 0u;
    g_ahci_publish_handoff_command_issued = 0u;
    g_ahci_publish_handoff_armed = 0u;

    flags = MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_REQUESTED
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_WRITE_WINDOW_DISABLED
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_COMMIT_BLOCKED
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_NO_COMMANDS
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_CAPABILITY_GATED;

    if (mmio64_publish_drain_ready(drain_token))
    {
        flags |= MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_DRAIN_READY
            | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_DRAIN_TOKEN_BOUND;
    }

    if (g_ahci_publish_handoff_live_before == 0u)
    {
        flags |= MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_LIVE_HANDLES_DRAINED;
    }

    if (capability64_route(
        stale_hardware_capability_handle,
        CAPABILITY64_RIGHT_QUERY,
        PRINCIPAL64_ID_DRIVER_HOST) == CAPABILITY64_INVALID_HANDLE)
    {
        g_ahci_publish_handoff_stale_old_denied = 1u;
        flags |= MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_STALE_HANDLE_DENIED;
    }

    if (g_ahci_publish_handoff_driver_principal_valid != 0u)
    {
        flags |= MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_DRIVER_PRINCIPAL_VALID;
    }

    if ((g_ahci_publish_handoff_driver_role & PRINCIPAL64_ROLE_DRIVER) != 0u)
    {
        flags |= MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_DRIVER_ROLE_PRESENT;
    }

    required_flags = MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_REQUESTED
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_DRAIN_READY
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_DRAIN_TOKEN_BOUND
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_LIVE_HANDLES_DRAINED
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_STALE_HANDLE_DENIED
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_DRIVER_PRINCIPAL_VALID
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_DRIVER_ROLE_PRESENT
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_WRITE_WINDOW_DISABLED
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_COMMIT_BLOCKED
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_NO_COMMANDS
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_CAPABILITY_GATED;

    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_publish_handoff_unavailable_count;
        g_ahci_publish_handoff_state = MMIO64_AHCI_PUBLISH_HANDOFF_STATE_UNAVAILABLE;
        g_ahci_publish_handoff_flags = flags | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    granted_handle = capability64_grant_service(
        SERVICE_ENDPOINT_CLASS_HARDWARE,
        CAPABILITY64_RIGHT_QUERY,
        driver_owner_id);
    g_ahci_publish_handoff_driver_capability = granted_handle;
    if (granted_handle != CAPABILITY64_INVALID_HANDLE)
    {
        flags |= MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_DRIVER_HANDLE_GRANTED;
    }

    if (capability64_owner(granted_handle, driver_owner_id) == driver_owner_id)
    {
        g_ahci_publish_handoff_driver_owner_bound = 1u;
        flags |= MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_DRIVER_OWNER_BOUND;
    }

    if (capability64_rights(granted_handle, driver_owner_id) == CAPABILITY64_RIGHT_QUERY)
    {
        g_ahci_publish_handoff_driver_query_only = 1u;
        flags |= MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_DRIVER_QUERY_ONLY;
    }

    g_ahci_publish_handoff_live_after =
        capability64_live_for_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE);
    if (g_ahci_publish_handoff_live_after == 1u)
    {
        flags |= MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_LIVE_AFTER_REGRANT;
    }

    required_flags |= MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_DRIVER_HANDLE_GRANTED
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_LIVE_AFTER_REGRANT;

    g_ahci_publish_handoff_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_publish_handoff_unavailable_count;
        g_ahci_publish_handoff_state = MMIO64_AHCI_PUBLISH_HANDOFF_STATE_UNAVAILABLE;
        g_ahci_publish_handoff_flags |= MMIO64_AHCI_PUBLISH_HANDOFF_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_publish_handoff_state = MMIO64_AHCI_PUBLISH_HANDOFF_STATE_DRIVER_BOUND;
    g_ahci_publish_handoff_token = mmio64_make_publish_handoff_token();
    ++g_ahci_publish_handoff_stage_count;
    return g_ahci_publish_handoff_token;
}

