u32 mmio64_stage_ahci_driver_read_probe(
    u32 driver_capability_handle,
    u32 handoff_token,
    u32 owner_id)
{
    volatile const u32 *registers;
    u32 flags;
    u32 required_flags;
    u32 endpoint;
    u32 port;
    u32 selected = MMIO64_INVALID_RESULT;

    if ((owner_id != g_ahci_publish_handoff_driver_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_probe_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_probe();
    g_ahci_driver_probe_handoff_token = handoff_token;
    g_ahci_driver_probe_driver_capability = driver_capability_handle;
    g_ahci_driver_probe_driver_owner = owner_id;
    g_ahci_driver_probe_mmio_written = 0u;
    g_ahci_driver_probe_port_programmed = 0u;
    g_ahci_driver_probe_published = 0u;
    g_ahci_driver_probe_command_issued = 0u;
    g_ahci_driver_probe_dma_mapped = 0u;
    g_ahci_driver_probe_armed = 0u;

    flags = MMIO64_AHCI_DRIVER_PROBE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_CAPABILITY_GATED;

    if (mmio64_publish_handoff_ready(handoff_token))
    {
        flags |= MMIO64_AHCI_DRIVER_PROBE_FLAG_HANDOFF_READY
            | MMIO64_AHCI_DRIVER_PROBE_FLAG_HANDOFF_TOKEN_BOUND;
    }

    if ((driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle == g_ahci_publish_handoff_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_PROBE_FLAG_DRIVER_CAP_BOUND;
    }

    if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
        && (owner_id == g_ahci_publish_handoff_driver_owner))
    {
        g_ahci_driver_probe_owner_bound = 1u;
        flags |= MMIO64_AHCI_DRIVER_PROBE_FLAG_DRIVER_OWNER_BOUND;
    }

    if (capability64_rights(driver_capability_handle, owner_id) == CAPABILITY64_RIGHT_QUERY)
    {
        g_ahci_driver_probe_query_only = 1u;
        flags |= MMIO64_AHCI_DRIVER_PROBE_FLAG_DRIVER_QUERY_ONLY;
    }

    endpoint = capability64_route(driver_capability_handle, CAPABILITY64_RIGHT_QUERY, owner_id);
    if ((endpoint == services64_resolve_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE))
        && mmio64_driver_probe_map_ready())
    {
        flags |= MMIO64_AHCI_DRIVER_PROBE_FLAG_MAP_READY;
    }

    required_flags = MMIO64_AHCI_DRIVER_PROBE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_HANDOFF_READY
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_HANDOFF_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_MAP_READY
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_CAPABILITY_GATED;

    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_probe_unavailable_count;
        g_ahci_driver_probe_state = MMIO64_AHCI_DRIVER_PROBE_STATE_UNAVAILABLE;
        g_ahci_driver_probe_flags = flags | MMIO64_AHCI_DRIVER_PROBE_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    registers = (volatile const u32 *)(u64)g_ahci_map_virtual_base;
    g_ahci_driver_probe_controller_cap = registers[MMIO64_AHCI_CAP_REGISTER];
    g_ahci_driver_probe_controller_ghc = registers[MMIO64_AHCI_GHC_REGISTER];
    g_ahci_driver_probe_controller_pi = registers[MMIO64_AHCI_PI_REGISTER];
    g_ahci_driver_probe_controller_version = registers[MMIO64_AHCI_VERSION_REGISTER];
    flags |= MMIO64_AHCI_DRIVER_PROBE_FLAG_CONTROLLER_READ;

    for (port = 0u; port < MMIO64_AHCI_MAX_PORTS; ++port)
    {
        u32 ssts;

        if ((g_ahci_driver_probe_controller_pi & (1u << port)) == 0u)
        {
            continue;
        }

        if (!mmio64_register_fits_span(
                mmio64_ahci_port_offset(port, MMIO64_AHCI_PORT_LAST_READ_OFFSET)))
        {
            continue;
        }

        ssts = registers[mmio64_ahci_port_offset(port, MMIO64_AHCI_PORT_SSTS_OFFSET) / sizeof(u32)];
        if ((ssts & 0xFu) == MMIO64_AHCI_PORT_DET_PRESENT)
        {
            selected = port;
            break;
        }

        if (selected == MMIO64_INVALID_RESULT)
        {
            selected = port;
        }
    }

    if (selected == MMIO64_INVALID_RESULT)
    {
        ++g_ahci_driver_probe_unavailable_count;
        g_ahci_driver_probe_state = MMIO64_AHCI_DRIVER_PROBE_STATE_UNAVAILABLE;
        g_ahci_driver_probe_flags = flags | MMIO64_AHCI_DRIVER_PROBE_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_probe_port_selected = selected;
    g_ahci_driver_probe_port_ssts =
        registers[mmio64_ahci_port_offset(selected, MMIO64_AHCI_PORT_SSTS_OFFSET) / sizeof(u32)];
    g_ahci_driver_probe_port_signature =
        registers[mmio64_ahci_port_offset(selected, MMIO64_AHCI_PORT_SIG_OFFSET) / sizeof(u32)];
    g_ahci_driver_probe_port_command =
        registers[mmio64_ahci_port_offset(selected, MMIO64_AHCI_PORT_CMD_OFFSET) / sizeof(u32)];
    g_ahci_driver_probe_port_task_file =
        registers[mmio64_ahci_port_offset(selected, MMIO64_AHCI_PORT_TFD_OFFSET) / sizeof(u32)];
    g_ahci_driver_probe_port_ci =
        registers[mmio64_ahci_port_offset(selected, MMIO64_AHCI_PORT_CI_OFFSET) / sizeof(u32)];
    g_ahci_driver_probe_port_serr =
        registers[mmio64_ahci_port_offset(selected, MMIO64_AHCI_PORT_SERR_OFFSET) / sizeof(u32)];
    flags |= MMIO64_AHCI_DRIVER_PROBE_FLAG_PORT_READ;

    if (g_ahci_driver_probe_port_signature == MMIO64_AHCI_PORT_SIG_SATA)
    {
        g_ahci_driver_probe_policy_kind = MMIO64_PORT_DEVICE_SATA;
        g_ahci_driver_probe_read_operation = MMIO64_AHCI_READ_OPERATION_ATA_READ_DMA_EXT;
        g_ahci_driver_probe_read_bytes = MMIO64_AHCI_SATA_LOGICAL_BLOCK_BYTES;
    }
    else if (g_ahci_driver_probe_port_signature == MMIO64_AHCI_PORT_SIG_ATAPI)
    {
        g_ahci_driver_probe_policy_kind = MMIO64_PORT_DEVICE_ATAPI;
        g_ahci_driver_probe_read_operation = MMIO64_AHCI_READ_OPERATION_ATAPI_READ_10;
        g_ahci_driver_probe_read_bytes = MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES;
    }
    else
    {
        g_ahci_driver_probe_policy_kind = MMIO64_PORT_DEVICE_UNKNOWN;
        g_ahci_driver_probe_read_operation = MMIO64_AHCI_READ_OPERATION_NONE;
        g_ahci_driver_probe_read_bytes = 0u;
    }

    g_ahci_driver_probe_policy_busy =
        ((g_ahci_driver_probe_port_task_file & MMIO64_AHCI_TFD_STS_BSY) != 0u) ? 1u : 0u;
    g_ahci_driver_probe_policy_drq =
        ((g_ahci_driver_probe_port_task_file & MMIO64_AHCI_TFD_STS_DRQ) != 0u) ? 1u : 0u;
    g_ahci_driver_probe_policy_ci_idle = (g_ahci_driver_probe_port_ci == 0u) ? 1u : 0u;
    g_ahci_driver_probe_policy_serr_clear = (g_ahci_driver_probe_port_serr == 0u) ? 1u : 0u;
    g_ahci_driver_probe_read_lba = 0u;
    g_ahci_driver_probe_read_blocks = 1u;
    g_ahci_driver_probe_policy_ready =
        (((g_ahci_driver_probe_port_ssts & 0xFu) == MMIO64_AHCI_PORT_DET_PRESENT)
            && (((g_ahci_driver_probe_port_ssts >> 8) & 0xFu) == MMIO64_AHCI_PORT_IPM_ACTIVE)
            && (g_ahci_driver_probe_policy_busy == 0u)
            && (g_ahci_driver_probe_policy_drq == 0u)
            && (g_ahci_driver_probe_policy_ci_idle != 0u)
            && (g_ahci_driver_probe_policy_serr_clear != 0u)
            && ((g_ahci_driver_probe_policy_kind == MMIO64_PORT_DEVICE_SATA)
                || (g_ahci_driver_probe_policy_kind == MMIO64_PORT_DEVICE_ATAPI)))
            ? 1u : 0u;
    if (g_ahci_driver_probe_policy_ready != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_PROBE_FLAG_POLICY_READY;
    }

    required_flags |= MMIO64_AHCI_DRIVER_PROBE_FLAG_CONTROLLER_READ
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_PORT_READ
        | MMIO64_AHCI_DRIVER_PROBE_FLAG_POLICY_READY;
    g_ahci_driver_probe_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_probe_unavailable_count;
        g_ahci_driver_probe_state = MMIO64_AHCI_DRIVER_PROBE_STATE_UNAVAILABLE;
        g_ahci_driver_probe_flags |= MMIO64_AHCI_DRIVER_PROBE_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_probe_state = MMIO64_AHCI_DRIVER_PROBE_STATE_READ_ONLY_READY;
    g_ahci_driver_probe_token = mmio64_make_driver_probe_token();
    ++g_ahci_driver_probe_stage_count;
    return g_ahci_driver_probe_token;
}

