u32 mmio64_stage_ahci_driver_read_intent(
    u32 driver_capability_handle,
    u32 driver_probe_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 endpoint = 0u;

    if ((owner_id != g_ahci_driver_probe_driver_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_intent_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_intent();
    g_ahci_driver_intent_probe_token = driver_probe_token;
    g_ahci_driver_intent_driver_capability = driver_capability_handle;
    g_ahci_driver_intent_driver_owner = owner_id;
    g_ahci_driver_intent_mmio_written = 0u;
    g_ahci_driver_intent_port_programmed = 0u;
    g_ahci_driver_intent_published = 0u;
    g_ahci_driver_intent_command_issued = 0u;
    g_ahci_driver_intent_dma_mapped = 0u;
    g_ahci_driver_intent_armed = 0u;
    g_ahci_driver_intent_media_read = 0u;

    flags = MMIO64_AHCI_DRIVER_INTENT_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_CAPABILITY_GATED;

    if (mmio64_driver_probe_ready(driver_probe_token))
    {
        flags |= MMIO64_AHCI_DRIVER_INTENT_FLAG_PROBE_READY
            | MMIO64_AHCI_DRIVER_INTENT_FLAG_PROBE_TOKEN_BOUND;
        g_ahci_driver_intent_port = g_ahci_driver_probe_port_selected;
        g_ahci_driver_intent_kind = g_ahci_driver_probe_policy_kind;
        g_ahci_driver_intent_read_operation = g_ahci_driver_probe_read_operation;
        g_ahci_driver_intent_read_lba = g_ahci_driver_probe_read_lba;
        g_ahci_driver_intent_read_blocks = g_ahci_driver_probe_read_blocks;
        g_ahci_driver_intent_read_bytes = g_ahci_driver_probe_read_bytes;
        g_ahci_driver_intent_read_ready = 1u;
        flags |= MMIO64_AHCI_DRIVER_INTENT_FLAG_PORT_BOUND
            | MMIO64_AHCI_DRIVER_INTENT_FLAG_DEVICE_KIND_BOUND
            | MMIO64_AHCI_DRIVER_INTENT_FLAG_READ_OPERATION_BOUND
            | MMIO64_AHCI_DRIVER_INTENT_FLAG_READ_SHAPE_BOUND;
    }

    if ((driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle == g_ahci_driver_probe_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_INTENT_FLAG_DRIVER_CAP_BOUND;
    }

    if (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_probe_driver_owner))
        {
            g_ahci_driver_intent_owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_INTENT_FLAG_DRIVER_OWNER_BOUND;
        }

        endpoint = capability64_route(
            driver_capability_handle,
            CAPABILITY64_RIGHT_QUERY,
            owner_id);
        if ((endpoint == services64_resolve_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE))
            && (capability64_rights(driver_capability_handle, owner_id) == CAPABILITY64_RIGHT_QUERY))
        {
            g_ahci_driver_intent_query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_INTENT_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    required_flags = MMIO64_AHCI_DRIVER_INTENT_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_PROBE_READY
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_PROBE_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_DEVICE_KIND_BOUND
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_READ_OPERATION_BOUND
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_INTENT_FLAG_CAPABILITY_GATED;

    g_ahci_driver_intent_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_intent_unavailable_count;
        g_ahci_driver_intent_state = MMIO64_AHCI_DRIVER_INTENT_STATE_UNAVAILABLE;
        g_ahci_driver_intent_flags |= MMIO64_AHCI_DRIVER_INTENT_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_intent_state = MMIO64_AHCI_DRIVER_INTENT_STATE_STAGED;
    g_ahci_driver_intent_token = mmio64_make_driver_intent_token();
    ++g_ahci_driver_intent_stage_count;
    return g_ahci_driver_intent_token;
}

