static u32 mmio64_driver_buffer_ready(u32 driver_buffer_token)
{
    u32 required_flags = MMIO64_AHCI_DRIVER_BUFFER_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_INTENT_READY
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_INTENT_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_BUFFER_FLAG_CAPABILITY_GATED;

    if ((g_ahci_driver_buffer_state != MMIO64_AHCI_DRIVER_BUFFER_STATE_STAGED)
        || (g_ahci_driver_buffer_token == 0u)
        || (driver_buffer_token != g_ahci_driver_buffer_token)
        || (g_ahci_driver_buffer_driver_capability == CAPABILITY64_INVALID_HANDLE)
        || (g_ahci_driver_buffer_owner_bound == 0u)
        || (g_ahci_driver_buffer_query_only == 0u)
        || (g_ahci_driver_buffer_port == MMIO64_INVALID_RESULT)
        || (g_ahci_driver_buffer_kind == MMIO64_PORT_DEVICE_NONE)
        || (g_ahci_driver_buffer_read_operation == MMIO64_AHCI_READ_OPERATION_NONE)
        || (g_ahci_driver_buffer_read_blocks == 0u)
        || (g_ahci_driver_buffer_read_bytes == 0u)
        || (g_ahci_driver_buffer_page_bytes < g_ahci_driver_buffer_read_bytes)
        || (g_ahci_driver_buffer_zeroed == 0u)
        || (g_ahci_driver_buffer_read_ready == 0u)
        || (g_ahci_driver_buffer_mmio_written != 0u)
        || (g_ahci_driver_buffer_port_programmed != 0u)
        || (g_ahci_driver_buffer_published != 0u)
        || (g_ahci_driver_buffer_command_issued != 0u)
        || (g_ahci_driver_buffer_dma_mapped != 0u)
        || (g_ahci_driver_buffer_armed != 0u)
        || (g_ahci_driver_buffer_media_read != 0u)
        || (g_ahci_driver_buffer_stage_count == 0u))
    {
        return 0u;
    }

    if ((g_ahci_driver_buffer_flags & required_flags) != required_flags)
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_gate(
    u32 driver_capability_handle,
    u32 driver_buffer_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 endpoint = 0u;

    if ((owner_id != g_ahci_driver_buffer_driver_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_gate_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_gate();
    g_ahci_driver_gate_buffer_token = driver_buffer_token;
    g_ahci_driver_gate_driver_capability = driver_capability_handle;
    g_ahci_driver_gate_driver_owner = owner_id;
    g_ahci_driver_gate_execution_required = 1u;
    g_ahci_driver_gate_execution_granted = 0u;
    g_ahci_driver_gate_issue_allowed = 0u;
    g_ahci_driver_gate_mmio_written = 0u;
    g_ahci_driver_gate_port_programmed = 0u;
    g_ahci_driver_gate_published = 0u;
    g_ahci_driver_gate_command_issued = 0u;
    g_ahci_driver_gate_dma_mapped = 0u;
    g_ahci_driver_gate_armed = 0u;
    g_ahci_driver_gate_media_read = 0u;

    flags = MMIO64_AHCI_DRIVER_GATE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_GATE_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_GATE_FLAG_EXECUTION_REQUIRED
        | MMIO64_AHCI_DRIVER_GATE_FLAG_EXECUTION_DENIED
        | MMIO64_AHCI_DRIVER_GATE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_GATE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_GATE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_GATE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_GATE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_GATE_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_GATE_FLAG_CAPABILITY_GATED;

    if (mmio64_driver_buffer_ready(driver_buffer_token))
    {
        flags |= MMIO64_AHCI_DRIVER_GATE_FLAG_BUFFER_READY
            | MMIO64_AHCI_DRIVER_GATE_FLAG_BUFFER_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_GATE_FLAG_PORT_BOUND
            | MMIO64_AHCI_DRIVER_GATE_FLAG_READ_SHAPE_BOUND
            | MMIO64_AHCI_DRIVER_GATE_FLAG_BUFFER_SHAPE_BOUND;
        g_ahci_driver_gate_port = g_ahci_driver_buffer_port;
        g_ahci_driver_gate_kind = g_ahci_driver_buffer_kind;
        g_ahci_driver_gate_read_operation = g_ahci_driver_buffer_read_operation;
        g_ahci_driver_gate_read_lba = g_ahci_driver_buffer_read_lba;
        g_ahci_driver_gate_read_blocks = g_ahci_driver_buffer_read_blocks;
        g_ahci_driver_gate_read_bytes = g_ahci_driver_buffer_read_bytes;
        g_ahci_driver_gate_page_bytes = g_ahci_driver_buffer_page_bytes;
        g_ahci_driver_gate_buffer_checksum = g_ahci_driver_buffer_checksum;
        g_ahci_driver_gate_buffer_zeroed = g_ahci_driver_buffer_zeroed;
        g_ahci_driver_gate_read_ready = g_ahci_driver_buffer_read_ready;
        if (g_ahci_driver_gate_buffer_zeroed != 0u)
        {
            flags |= MMIO64_AHCI_DRIVER_GATE_FLAG_BUFFER_ZEROED;
        }
    }

    if ((driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle == g_ahci_driver_buffer_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_GATE_FLAG_DRIVER_CAP_BOUND;
    }

    if (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_buffer_driver_owner))
        {
            g_ahci_driver_gate_owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_GATE_FLAG_DRIVER_OWNER_BOUND;
        }

        endpoint = capability64_route(
            driver_capability_handle,
            CAPABILITY64_RIGHT_QUERY,
            owner_id);
        if ((endpoint == services64_resolve_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE))
            && (capability64_rights(driver_capability_handle, owner_id) == CAPABILITY64_RIGHT_QUERY))
        {
            g_ahci_driver_gate_query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_GATE_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    required_flags = MMIO64_AHCI_DRIVER_GATE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_GATE_FLAG_BUFFER_READY
        | MMIO64_AHCI_DRIVER_GATE_FLAG_BUFFER_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_GATE_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_GATE_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_GATE_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_GATE_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_GATE_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_GATE_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_GATE_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_GATE_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_GATE_FLAG_EXECUTION_REQUIRED
        | MMIO64_AHCI_DRIVER_GATE_FLAG_EXECUTION_DENIED
        | MMIO64_AHCI_DRIVER_GATE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_GATE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_GATE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_GATE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_GATE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_GATE_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_GATE_FLAG_CAPABILITY_GATED;

    g_ahci_driver_gate_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_gate_unavailable_count;
        g_ahci_driver_gate_state = MMIO64_AHCI_DRIVER_GATE_STATE_UNAVAILABLE;
        g_ahci_driver_gate_flags |= MMIO64_AHCI_DRIVER_GATE_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_gate_state = MMIO64_AHCI_DRIVER_GATE_STATE_LOCKED;
    g_ahci_driver_gate_token = mmio64_make_driver_gate_token();
    ++g_ahci_driver_gate_stage_count;
    return g_ahci_driver_gate_token;
}

