static u32 mmio64_driver_exec_denied_ready(u32 driver_exec_token)
{
    u32 required_flags = MMIO64_AHCI_DRIVER_EXEC_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_GATE_READY
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_GATE_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_EXECUTION_ATTEMPTED
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_EXECUTION_REQUIRED
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_EXECUTION_DENIED
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_ISSUE_DENIED
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_GATE_LOCKED
        | MMIO64_AHCI_DRIVER_EXEC_FLAG_CAPABILITY_GATED;

    if ((g_ahci_driver_exec_state != MMIO64_AHCI_DRIVER_EXEC_STATE_DENIED)
        || (g_ahci_driver_exec_token == 0u)
        || (driver_exec_token != g_ahci_driver_exec_token)
        || (g_ahci_driver_exec_driver_capability == CAPABILITY64_INVALID_HANDLE)
        || (g_ahci_driver_exec_owner_bound == 0u)
        || (g_ahci_driver_exec_query_only == 0u)
        || (g_ahci_driver_exec_port == MMIO64_INVALID_RESULT)
        || (g_ahci_driver_exec_kind == MMIO64_PORT_DEVICE_NONE)
        || (g_ahci_driver_exec_read_operation == MMIO64_AHCI_READ_OPERATION_NONE)
        || (g_ahci_driver_exec_read_blocks == 0u)
        || (g_ahci_driver_exec_read_bytes == 0u)
        || (g_ahci_driver_exec_page_bytes < g_ahci_driver_exec_read_bytes)
        || (g_ahci_driver_exec_buffer_zeroed == 0u)
        || (g_ahci_driver_exec_read_ready == 0u)
        || (g_ahci_driver_exec_execution_attempted == 0u)
        || (g_ahci_driver_exec_execution_required == 0u)
        || (g_ahci_driver_exec_execution_granted != 0u)
        || (g_ahci_driver_exec_issue_allowed != 0u)
        || (g_ahci_driver_exec_issue_denied == 0u)
        || (g_ahci_driver_exec_mmio_written != 0u)
        || (g_ahci_driver_exec_port_programmed != 0u)
        || (g_ahci_driver_exec_published != 0u)
        || (g_ahci_driver_exec_command_issued != 0u)
        || (g_ahci_driver_exec_dma_mapped != 0u)
        || (g_ahci_driver_exec_armed != 0u)
        || (g_ahci_driver_exec_media_read != 0u)
        || (g_ahci_driver_exec_stage_count == 0u))
    {
        return 0u;
    }

    if ((g_ahci_driver_exec_flags & required_flags) != required_flags)
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_result(
    u32 driver_capability_handle,
    u32 driver_exec_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 endpoint = 0u;
    u32 expected_owner = g_ahci_driver_exec_driver_owner;

    if (expected_owner == 0u)
    {
        expected_owner = g_ahci_driver_gate_driver_owner;
    }
    if (expected_owner == 0u)
    {
        expected_owner = g_ahci_driver_buffer_driver_owner;
    }

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_result_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_result();
    g_ahci_driver_result_exec_token = driver_exec_token;
    g_ahci_driver_result_driver_capability = driver_capability_handle;
    g_ahci_driver_result_driver_owner = owner_id;
    g_ahci_driver_result_execution_denied = 1u;
    g_ahci_driver_result_result_requested = 1u;
    g_ahci_driver_result_result_granted = 0u;
    g_ahci_driver_result_result_denied = 1u;
    g_ahci_driver_result_bytes_available = 0u;
    g_ahci_driver_result_block_cap_minted = 0u;
    g_ahci_driver_result_fs_minted = 0u;
    g_ahci_driver_result_mmio_written = 0u;
    g_ahci_driver_result_port_programmed = 0u;
    g_ahci_driver_result_published = 0u;
    g_ahci_driver_result_command_issued = 0u;
    g_ahci_driver_result_dma_mapped = 0u;
    g_ahci_driver_result_armed = 0u;
    g_ahci_driver_result_media_read = 0u;

    flags = MMIO64_AHCI_DRIVER_RESULT_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_EXECUTION_DENIED
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_RESULT_REQUESTED
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_RESULT_DENIED
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_CAPABILITY_GATED;

    if (mmio64_driver_exec_denied_ready(driver_exec_token))
    {
        flags |= MMIO64_AHCI_DRIVER_RESULT_FLAG_EXEC_READY
            | MMIO64_AHCI_DRIVER_RESULT_FLAG_EXEC_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_RESULT_FLAG_PORT_BOUND
            | MMIO64_AHCI_DRIVER_RESULT_FLAG_READ_SHAPE_BOUND
            | MMIO64_AHCI_DRIVER_RESULT_FLAG_BUFFER_SHAPE_BOUND;
        g_ahci_driver_result_port = g_ahci_driver_exec_port;
        g_ahci_driver_result_kind = g_ahci_driver_exec_kind;
        g_ahci_driver_result_read_operation = g_ahci_driver_exec_read_operation;
        g_ahci_driver_result_read_lba = g_ahci_driver_exec_read_lba;
        g_ahci_driver_result_read_blocks = g_ahci_driver_exec_read_blocks;
        g_ahci_driver_result_read_bytes = g_ahci_driver_exec_read_bytes;
        g_ahci_driver_result_page_bytes = g_ahci_driver_exec_page_bytes;
        g_ahci_driver_result_buffer_checksum = g_ahci_driver_exec_buffer_checksum;
        g_ahci_driver_result_buffer_zeroed = g_ahci_driver_exec_buffer_zeroed;
        g_ahci_driver_result_read_ready = g_ahci_driver_exec_read_ready;
        if (g_ahci_driver_result_buffer_zeroed != 0u)
        {
            flags |= MMIO64_AHCI_DRIVER_RESULT_FLAG_BUFFER_ZEROED;
        }
    }

    if ((driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle == g_ahci_driver_exec_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_RESULT_FLAG_DRIVER_CAP_BOUND;
    }

    if (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_exec_driver_owner))
        {
            g_ahci_driver_result_owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_RESULT_FLAG_DRIVER_OWNER_BOUND;
        }

        endpoint = capability64_route(
            driver_capability_handle,
            CAPABILITY64_RIGHT_QUERY,
            owner_id);
        if ((endpoint == services64_resolve_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE))
            && (capability64_rights(driver_capability_handle, owner_id) == CAPABILITY64_RIGHT_QUERY))
        {
            g_ahci_driver_result_query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_RESULT_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    required_flags = MMIO64_AHCI_DRIVER_RESULT_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_EXEC_READY
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_EXEC_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_EXECUTION_DENIED
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_RESULT_REQUESTED
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_RESULT_DENIED
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_RESULT_FLAG_CAPABILITY_GATED;

    g_ahci_driver_result_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_result_unavailable_count;
        g_ahci_driver_result_state = MMIO64_AHCI_DRIVER_RESULT_STATE_UNAVAILABLE;
        g_ahci_driver_result_flags |= MMIO64_AHCI_DRIVER_RESULT_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_result_state = MMIO64_AHCI_DRIVER_RESULT_STATE_DENIED;
    g_ahci_driver_result_token = mmio64_make_driver_result_token();
    ++g_ahci_driver_result_stage_count;
    return g_ahci_driver_result_token;
}

