static u32 mmio64_driver_read_grant_denied_ready(u32 driver_read_grant_token)
{
    u32 required_flags = MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_PUBLISH_READY
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_PUBLISH_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_RESULT_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_EXECUTION_DENIED
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_RESULT_DENIED
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_PUBLISH_DENIED
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_READ_GRANT_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_READ_GRANT_DENIED
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_NO_MEDIA_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_GRANT_FLAG_CAPABILITY_GATED;

    if ((g_ahci_driver_read_grant_state != MMIO64_AHCI_DRIVER_READ_GRANT_STATE_DENIED)
        || (driver_read_grant_token == 0u)
        || (driver_read_grant_token != g_ahci_driver_read_grant_token)
        || (g_ahci_driver_read_grant_driver_capability == CAPABILITY64_INVALID_HANDLE)
        || (g_ahci_driver_read_grant_owner_bound == 0u)
        || (g_ahci_driver_read_grant_query_only == 0u)
        || (g_ahci_driver_read_grant_port == MMIO64_INVALID_RESULT)
        || (g_ahci_driver_read_grant_kind == MMIO64_PORT_DEVICE_NONE)
        || (g_ahci_driver_read_grant_read_operation == MMIO64_AHCI_READ_OPERATION_NONE)
        || (g_ahci_driver_read_grant_read_blocks == 0u)
        || (g_ahci_driver_read_grant_read_bytes == 0u)
        || (g_ahci_driver_read_grant_page_bytes < g_ahci_driver_read_grant_read_bytes)
        || (g_ahci_driver_read_grant_buffer_zeroed == 0u)
        || (g_ahci_driver_read_grant_read_ready == 0u)
        || (g_ahci_driver_read_grant_execution_denied == 0u)
        || (g_ahci_driver_read_grant_result_denied == 0u)
        || (g_ahci_driver_read_grant_publish_denied == 0u)
        || (g_ahci_driver_read_grant_bytes_available != 0u)
        || (g_ahci_driver_read_grant_read_grant_requested == 0u)
        || (g_ahci_driver_read_grant_read_grant_granted != 0u)
        || (g_ahci_driver_read_grant_read_grant_denied == 0u)
        || (g_ahci_driver_read_grant_media_read_authority != 0u)
        || (g_ahci_driver_read_grant_block_endpoint_published != 0u)
        || (g_ahci_driver_read_grant_block_cap_minted != 0u)
        || (g_ahci_driver_read_grant_fs_minted != 0u)
        || (g_ahci_driver_read_grant_mmio_written != 0u)
        || (g_ahci_driver_read_grant_port_programmed != 0u)
        || (g_ahci_driver_read_grant_published != 0u)
        || (g_ahci_driver_read_grant_command_issued != 0u)
        || (g_ahci_driver_read_grant_dma_mapped != 0u)
        || (g_ahci_driver_read_grant_armed != 0u)
        || (g_ahci_driver_read_grant_media_read != 0u)
        || (g_ahci_driver_read_grant_media_written != 0u)
        || (g_ahci_driver_read_grant_stage_count == 0u))
    {
        return 0u;
    }

    if ((g_ahci_driver_read_grant_flags & required_flags) != required_flags)
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_media_read(
    u32 driver_capability_handle,
    u32 driver_read_grant_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 endpoint = 0u;
    u32 expected_owner = g_ahci_driver_read_grant_driver_owner;

    if (expected_owner == 0u)
    {
        expected_owner = g_ahci_driver_publish_driver_owner;
    }
    if (expected_owner == 0u)
    {
        expected_owner = g_ahci_driver_result_driver_owner;
    }

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_media_read_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_media_read();
    g_ahci_driver_media_read_read_grant_token = driver_read_grant_token;
    g_ahci_driver_media_read_driver_capability = driver_capability_handle;
    g_ahci_driver_media_read_driver_owner = owner_id;
    g_ahci_driver_media_read_read_grant_denied = 1u;
    g_ahci_driver_media_read_media_read_authority = 0u;
    g_ahci_driver_media_read_read_attempted = 1u;
    g_ahci_driver_media_read_read_denied = 1u;
    g_ahci_driver_media_read_bytes_available = 0u;
    g_ahci_driver_media_read_block_endpoint_published = 0u;
    g_ahci_driver_media_read_block_cap_minted = 0u;
    g_ahci_driver_media_read_fs_minted = 0u;
    g_ahci_driver_media_read_mmio_written = 0u;
    g_ahci_driver_media_read_port_programmed = 0u;
    g_ahci_driver_media_read_published = 0u;
    g_ahci_driver_media_read_command_issued = 0u;
    g_ahci_driver_media_read_dma_mapped = 0u;
    g_ahci_driver_media_read_armed = 0u;
    g_ahci_driver_media_read_media_read = 0u;
    g_ahci_driver_media_read_media_written = 0u;
    g_ahci_driver_media_read_buffer_unchanged = 1u;

    flags = MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_GRANT_DENIED
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_AUTHORITY_ABSENT
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_ATTEMPTED
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_DENIED
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_CAPABILITY_GATED;

    if (mmio64_driver_read_grant_denied_ready(driver_read_grant_token))
    {
        flags |= MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_GRANT_READY
            | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_GRANT_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_PORT_BOUND
            | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_SHAPE_BOUND
            | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_BUFFER_SHAPE_BOUND;
        g_ahci_driver_media_read_port = g_ahci_driver_read_grant_port;
        g_ahci_driver_media_read_kind = g_ahci_driver_read_grant_kind;
        g_ahci_driver_media_read_read_operation = g_ahci_driver_read_grant_read_operation;
        g_ahci_driver_media_read_read_lba = g_ahci_driver_read_grant_read_lba;
        g_ahci_driver_media_read_read_blocks = g_ahci_driver_read_grant_read_blocks;
        g_ahci_driver_media_read_read_bytes = g_ahci_driver_read_grant_read_bytes;
        g_ahci_driver_media_read_page_bytes = g_ahci_driver_read_grant_page_bytes;
        g_ahci_driver_media_read_buffer_checksum = g_ahci_driver_read_grant_buffer_checksum;
        g_ahci_driver_media_read_buffer_zeroed = g_ahci_driver_read_grant_buffer_zeroed;
        g_ahci_driver_media_read_read_ready = g_ahci_driver_read_grant_read_ready;
        if (g_ahci_driver_media_read_buffer_zeroed != 0u)
        {
            flags |= MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_BUFFER_ZEROED;
        }
    }

    if ((driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle == g_ahci_driver_read_grant_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_DRIVER_CAP_BOUND;
    }

    if (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_grant_driver_owner))
        {
            g_ahci_driver_media_read_owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_DRIVER_OWNER_BOUND;
        }

        endpoint = capability64_route(
            driver_capability_handle,
            CAPABILITY64_RIGHT_QUERY,
            owner_id);
        if ((endpoint == services64_resolve_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE))
            && (capability64_rights(driver_capability_handle, owner_id) == CAPABILITY64_RIGHT_QUERY))
        {
            g_ahci_driver_media_read_query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    required_flags = MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_GRANT_READY
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_GRANT_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_GRANT_DENIED
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_AUTHORITY_ABSENT
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_ATTEMPTED
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_READ_DENIED
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_CAPABILITY_GATED;

    g_ahci_driver_media_read_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_media_read_unavailable_count;
        g_ahci_driver_media_read_state = MMIO64_AHCI_DRIVER_MEDIA_READ_STATE_UNAVAILABLE;
        g_ahci_driver_media_read_flags |= MMIO64_AHCI_DRIVER_MEDIA_READ_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_media_read_state = MMIO64_AHCI_DRIVER_MEDIA_READ_STATE_DENIED;
    g_ahci_driver_media_read_token = mmio64_make_driver_media_read_token();
    ++g_ahci_driver_media_read_stage_count;
    return g_ahci_driver_media_read_token;
}

