static u32 mmio64_driver_read_response_denied_ready(u32 driver_read_response_token)
{
    u32 required_flags = MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_READ_EXPORT_READY
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_READ_EXPORT_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_READ_EXPORT_DENIED
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_RESPONSE_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_RESPONSE_DENIED
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_NO_RESPONSE_BYTES
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_NO_RESPONSE_STATUS
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_DRIVER_READ_RESPONSE_FLAG_NO_STORAGE_AUTHORITY;

    if ((g_ahci_driver_read_response_state != MMIO64_AHCI_DRIVER_READ_RESPONSE_STATE_DENIED)
        || (driver_read_response_token == 0u)
        || (driver_read_response_token != g_ahci_driver_read_response_token)
        || (g_ahci_driver_read_response_driver_capability == CAPABILITY64_INVALID_HANDLE)
        || (g_ahci_driver_read_response_owner_bound == 0u)
        || (g_ahci_driver_read_response_query_only == 0u)
        || (g_ahci_driver_read_response_port == MMIO64_INVALID_RESULT)
        || (g_ahci_driver_read_response_kind == MMIO64_PORT_DEVICE_NONE)
        || (g_ahci_driver_read_response_read_operation == MMIO64_AHCI_READ_OPERATION_NONE)
        || (g_ahci_driver_read_response_read_blocks == 0u)
        || (g_ahci_driver_read_response_read_bytes == 0u)
        || (g_ahci_driver_read_response_page_bytes < g_ahci_driver_read_response_read_bytes)
        || (g_ahci_driver_read_response_buffer_zeroed == 0u)
        || (g_ahci_driver_read_response_read_ready == 0u)
        || (g_ahci_driver_read_response_read_export_denied == 0u)
        || (g_ahci_driver_read_response_requested == 0u)
        || (g_ahci_driver_read_response_granted != 0u)
        || (g_ahci_driver_read_response_denied == 0u)
        || (g_ahci_driver_read_response_bytes_available != 0u)
        || (g_ahci_driver_read_response_response_bytes != 0u)
        || (g_ahci_driver_read_response_response_status != 0u)
        || (g_ahci_driver_read_response_response_checksum != 0u)
        || (g_ahci_driver_read_response_block_endpoint_published != 0u)
        || (g_ahci_driver_read_response_block_cap_minted != 0u)
        || (g_ahci_driver_read_response_fs_minted != 0u)
        || (g_ahci_driver_read_response_mmio_written != 0u)
        || (g_ahci_driver_read_response_port_programmed != 0u)
        || (g_ahci_driver_read_response_published != 0u)
        || (g_ahci_driver_read_response_command_issued != 0u)
        || (g_ahci_driver_read_response_dma_mapped != 0u)
        || (g_ahci_driver_read_response_armed != 0u)
        || (g_ahci_driver_read_response_media_read != 0u)
        || (g_ahci_driver_read_response_media_written != 0u)
        || (g_ahci_driver_read_response_buffer_unchanged == 0u)
        || (g_ahci_driver_read_response_stage_count == 0u))
    {
        return 0u;
    }

    if ((g_ahci_driver_read_response_flags & required_flags) != required_flags)
    {
        return 0u;
    }

    return 1u;
}

