static u32 mmio64_driver_read_delivery_denied_ready(u32 driver_read_delivery_token)
{
    u32 required_flags = MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_READ_RESPONSE_READY
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_READ_RESPONSE_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_READ_RESPONSE_DENIED
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_DELIVERY_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_DELIVERY_DENIED
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_NO_DELIVERED_BYTES
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_NO_DELIVERY_STATUS
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_DRIVER_READ_DELIVERY_FLAG_NO_STORAGE_AUTHORITY;

    if ((g_ahci_driver_read_delivery_state != MMIO64_AHCI_DRIVER_READ_DELIVERY_STATE_DENIED)
        || (driver_read_delivery_token == 0u)
        || (driver_read_delivery_token != g_ahci_driver_read_delivery_token)
        || (g_ahci_driver_read_delivery_driver_capability == CAPABILITY64_INVALID_HANDLE)
        || (g_ahci_driver_read_delivery_owner_bound == 0u)
        || (g_ahci_driver_read_delivery_query_only == 0u)
        || (g_ahci_driver_read_delivery_port == MMIO64_INVALID_RESULT)
        || (g_ahci_driver_read_delivery_kind == MMIO64_PORT_DEVICE_NONE)
        || (g_ahci_driver_read_delivery_read_operation == MMIO64_AHCI_READ_OPERATION_NONE)
        || (g_ahci_driver_read_delivery_read_blocks == 0u)
        || (g_ahci_driver_read_delivery_read_bytes == 0u)
        || (g_ahci_driver_read_delivery_page_bytes < g_ahci_driver_read_delivery_read_bytes)
        || (g_ahci_driver_read_delivery_buffer_zeroed == 0u)
        || (g_ahci_driver_read_delivery_read_ready == 0u)
        || (g_ahci_driver_read_delivery_read_response_denied == 0u)
        || (g_ahci_driver_read_delivery_requested == 0u)
        || (g_ahci_driver_read_delivery_granted != 0u)
        || (g_ahci_driver_read_delivery_denied == 0u)
        || (g_ahci_driver_read_delivery_bytes_available != 0u)
        || (g_ahci_driver_read_delivery_delivered_bytes != 0u)
        || (g_ahci_driver_read_delivery_delivery_status != 0u)
        || (g_ahci_driver_read_delivery_delivery_checksum != 0u)
        || (g_ahci_driver_read_delivery_block_endpoint_published != 0u)
        || (g_ahci_driver_read_delivery_block_cap_minted != 0u)
        || (g_ahci_driver_read_delivery_fs_minted != 0u)
        || (g_ahci_driver_read_delivery_mmio_written != 0u)
        || (g_ahci_driver_read_delivery_port_programmed != 0u)
        || (g_ahci_driver_read_delivery_published != 0u)
        || (g_ahci_driver_read_delivery_command_issued != 0u)
        || (g_ahci_driver_read_delivery_dma_mapped != 0u)
        || (g_ahci_driver_read_delivery_armed != 0u)
        || (g_ahci_driver_read_delivery_media_read != 0u)
        || (g_ahci_driver_read_delivery_media_written != 0u)
        || (g_ahci_driver_read_delivery_buffer_unchanged == 0u)
        || (g_ahci_driver_read_delivery_stage_count == 0u))
    {
        return 0u;
    }

    if ((g_ahci_driver_read_delivery_flags & required_flags) != required_flags)
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_visible(
    u32 driver_capability_handle,
    u32 driver_read_delivery_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 endpoint = 0u;
    u32 expected_owner = g_ahci_driver_read_delivery_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_visible_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_visible();
    g_ahci_driver_read_visible_read_delivery_token = driver_read_delivery_token;
    g_ahci_driver_read_visible_driver_capability = driver_capability_handle;
    g_ahci_driver_read_visible_driver_owner = owner_id;
    g_ahci_driver_read_visible_read_delivery_denied = 1u;
    g_ahci_driver_read_visible_requested = 1u;
    g_ahci_driver_read_visible_granted = 0u;
    g_ahci_driver_read_visible_denied = 1u;
    g_ahci_driver_read_visible_bytes_available = 0u;
    g_ahci_driver_read_visible_visible_bytes = 0u;
    g_ahci_driver_read_visible_visibility_status = 0u;
    g_ahci_driver_read_visible_visibility_checksum = 0u;
    g_ahci_driver_read_visible_block_endpoint_published = 0u;
    g_ahci_driver_read_visible_block_cap_minted = 0u;
    g_ahci_driver_read_visible_fs_minted = 0u;
    g_ahci_driver_read_visible_mmio_written = 0u;
    g_ahci_driver_read_visible_port_programmed = 0u;
    g_ahci_driver_read_visible_published = 0u;
    g_ahci_driver_read_visible_command_issued = 0u;
    g_ahci_driver_read_visible_dma_mapped = 0u;
    g_ahci_driver_read_visible_armed = 0u;
    g_ahci_driver_read_visible_media_read = 0u;
    g_ahci_driver_read_visible_media_written = 0u;
    g_ahci_driver_read_visible_buffer_unchanged = 1u;

    flags = MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_READ_DELIVERY_DENIED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_VISIBILITY_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_VISIBILITY_DENIED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_VISIBLE_BYTES
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_VISIBILITY_STATUS
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_STORAGE_AUTHORITY;

    if (mmio64_driver_read_delivery_denied_ready(driver_read_delivery_token))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_READ_DELIVERY_READY
            | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_READ_DELIVERY_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_PORT_BOUND
            | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_READ_SHAPE_BOUND
            | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_BUFFER_SHAPE_BOUND;
        g_ahci_driver_read_visible_port = g_ahci_driver_read_delivery_port;
        g_ahci_driver_read_visible_kind = g_ahci_driver_read_delivery_kind;
        g_ahci_driver_read_visible_read_operation = g_ahci_driver_read_delivery_read_operation;
        g_ahci_driver_read_visible_read_lba = g_ahci_driver_read_delivery_read_lba;
        g_ahci_driver_read_visible_read_blocks = g_ahci_driver_read_delivery_read_blocks;
        g_ahci_driver_read_visible_read_bytes = g_ahci_driver_read_delivery_read_bytes;
        g_ahci_driver_read_visible_page_bytes = g_ahci_driver_read_delivery_page_bytes;
        g_ahci_driver_read_visible_buffer_checksum = g_ahci_driver_read_delivery_buffer_checksum;
        g_ahci_driver_read_visible_buffer_zeroed = g_ahci_driver_read_delivery_buffer_zeroed;
        g_ahci_driver_read_visible_read_ready = g_ahci_driver_read_delivery_read_ready;
        if (g_ahci_driver_read_visible_buffer_zeroed != 0u)
        {
            flags |= MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_BUFFER_ZEROED;
        }
    }

    if ((driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle == g_ahci_driver_read_delivery_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_DRIVER_CAP_BOUND;
    }

    if (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_delivery_driver_owner))
        {
            g_ahci_driver_read_visible_owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_DRIVER_OWNER_BOUND;
        }

        endpoint = capability64_route(
            driver_capability_handle,
            CAPABILITY64_RIGHT_QUERY,
            owner_id);
        if ((endpoint == services64_resolve_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE))
            && (capability64_rights(driver_capability_handle, owner_id) == CAPABILITY64_RIGHT_QUERY))
        {
            g_ahci_driver_read_visible_query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    required_flags = MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_READ_DELIVERY_READY
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_READ_DELIVERY_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_READ_DELIVERY_DENIED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_VISIBILITY_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_VISIBILITY_DENIED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_VISIBLE_BYTES
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_VISIBILITY_STATUS
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_NO_STORAGE_AUTHORITY;

    g_ahci_driver_read_visible_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_visible_unavailable_count;
        g_ahci_driver_read_visible_state = MMIO64_AHCI_DRIVER_READ_VISIBLE_STATE_UNAVAILABLE;
        g_ahci_driver_read_visible_flags |= MMIO64_AHCI_DRIVER_READ_VISIBLE_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_visible_state = MMIO64_AHCI_DRIVER_READ_VISIBLE_STATE_DENIED;
    g_ahci_driver_read_visible_token = mmio64_make_driver_read_visible_token();
    ++g_ahci_driver_read_visible_stage_count;
    return g_ahci_driver_read_visible_token;
}

