static u32 mmio64_driver_read_commit_denied_ready(u32 driver_read_commit_token)
{
    u32 required_flags = MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_READ_VISIBLE_READY
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_READ_VISIBLE_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_READ_VISIBLE_DENIED
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_COMMIT_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_COMMIT_DENIED
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_NO_COMMITTED_BYTES
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_NO_COMMIT_STATUS
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_DRIVER_READ_COMMIT_FLAG_NO_STORAGE_AUTHORITY;

    if ((g_ahci_driver_read_commit_state != MMIO64_AHCI_DRIVER_READ_COMMIT_STATE_DENIED)
        || (driver_read_commit_token == 0u)
        || (driver_read_commit_token != g_ahci_driver_read_commit_token)
        || (g_ahci_driver_read_commit_driver_capability == CAPABILITY64_INVALID_HANDLE)
        || (g_ahci_driver_read_commit_owner_bound == 0u)
        || (g_ahci_driver_read_commit_query_only == 0u)
        || (g_ahci_driver_read_commit_port == MMIO64_INVALID_RESULT)
        || (g_ahci_driver_read_commit_kind == MMIO64_PORT_DEVICE_NONE)
        || (g_ahci_driver_read_commit_read_operation == MMIO64_AHCI_READ_OPERATION_NONE)
        || (g_ahci_driver_read_commit_read_blocks == 0u)
        || (g_ahci_driver_read_commit_read_bytes == 0u)
        || (g_ahci_driver_read_commit_page_bytes < g_ahci_driver_read_commit_read_bytes)
        || (g_ahci_driver_read_commit_buffer_zeroed == 0u)
        || (g_ahci_driver_read_commit_read_ready == 0u)
        || (g_ahci_driver_read_commit_read_visible_denied == 0u)
        || (g_ahci_driver_read_commit_requested == 0u)
        || (g_ahci_driver_read_commit_granted != 0u)
        || (g_ahci_driver_read_commit_denied == 0u)
        || (g_ahci_driver_read_commit_bytes_available != 0u)
        || (g_ahci_driver_read_commit_committed_bytes != 0u)
        || (g_ahci_driver_read_commit_commit_status != 0u)
        || (g_ahci_driver_read_commit_commit_checksum != 0u)
        || (g_ahci_driver_read_commit_block_endpoint_published != 0u)
        || (g_ahci_driver_read_commit_block_cap_minted != 0u)
        || (g_ahci_driver_read_commit_fs_minted != 0u)
        || (g_ahci_driver_read_commit_mmio_written != 0u)
        || (g_ahci_driver_read_commit_port_programmed != 0u)
        || (g_ahci_driver_read_commit_published != 0u)
        || (g_ahci_driver_read_commit_command_issued != 0u)
        || (g_ahci_driver_read_commit_dma_mapped != 0u)
        || (g_ahci_driver_read_commit_armed != 0u)
        || (g_ahci_driver_read_commit_media_read != 0u)
        || (g_ahci_driver_read_commit_media_written != 0u)
        || (g_ahci_driver_read_commit_buffer_unchanged == 0u)
        || (g_ahci_driver_read_commit_stage_count == 0u))
    {
        return 0u;
    }

    if ((g_ahci_driver_read_commit_flags & required_flags) != required_flags)
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_audit(
    u32 driver_capability_handle,
    u32 driver_read_commit_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 endpoint = 0u;
    u32 expected_owner = g_ahci_driver_read_commit_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_audit_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_audit();
    g_ahci_driver_read_audit_read_commit_token = driver_read_commit_token;
    g_ahci_driver_read_audit_driver_capability = driver_capability_handle;
    g_ahci_driver_read_audit_driver_owner = owner_id;
    g_ahci_driver_read_audit_read_commit_denied = 1u;
    g_ahci_driver_read_audit_requested = 1u;
    g_ahci_driver_read_audit_granted = 0u;
    g_ahci_driver_read_audit_denied = 1u;
    g_ahci_driver_read_audit_bytes_available = 0u;
    g_ahci_driver_read_audit_audited_bytes = 0u;
    g_ahci_driver_read_audit_audit_status = 0u;
    g_ahci_driver_read_audit_audit_checksum = 0u;
    g_ahci_driver_read_audit_block_endpoint_published = 0u;
    g_ahci_driver_read_audit_block_cap_minted = 0u;
    g_ahci_driver_read_audit_fs_minted = 0u;
    g_ahci_driver_read_audit_mmio_written = 0u;
    g_ahci_driver_read_audit_port_programmed = 0u;
    g_ahci_driver_read_audit_published = 0u;
    g_ahci_driver_read_audit_command_issued = 0u;
    g_ahci_driver_read_audit_dma_mapped = 0u;
    g_ahci_driver_read_audit_armed = 0u;
    g_ahci_driver_read_audit_media_read = 0u;
    g_ahci_driver_read_audit_media_written = 0u;
    g_ahci_driver_read_audit_buffer_unchanged = 1u;

    flags = MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_READ_COMMIT_DENIED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_AUDIT_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_AUDIT_DENIED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_AUDITED_BYTES
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_AUDIT_STATUS
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_STORAGE_AUTHORITY;

    if (mmio64_driver_read_commit_denied_ready(driver_read_commit_token))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_READ_COMMIT_READY
            | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_READ_COMMIT_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_PORT_BOUND
            | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_READ_SHAPE_BOUND
            | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_BUFFER_SHAPE_BOUND;
        g_ahci_driver_read_audit_port = g_ahci_driver_read_commit_port;
        g_ahci_driver_read_audit_kind = g_ahci_driver_read_commit_kind;
        g_ahci_driver_read_audit_read_operation = g_ahci_driver_read_commit_read_operation;
        g_ahci_driver_read_audit_read_lba = g_ahci_driver_read_commit_read_lba;
        g_ahci_driver_read_audit_read_blocks = g_ahci_driver_read_commit_read_blocks;
        g_ahci_driver_read_audit_read_bytes = g_ahci_driver_read_commit_read_bytes;
        g_ahci_driver_read_audit_page_bytes = g_ahci_driver_read_commit_page_bytes;
        g_ahci_driver_read_audit_buffer_checksum = g_ahci_driver_read_commit_buffer_checksum;
        g_ahci_driver_read_audit_buffer_zeroed = g_ahci_driver_read_commit_buffer_zeroed;
        g_ahci_driver_read_audit_read_ready = g_ahci_driver_read_commit_read_ready;
        if (g_ahci_driver_read_audit_buffer_zeroed != 0u)
        {
            flags |= MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_BUFFER_ZEROED;
        }
    }

    if ((driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle == g_ahci_driver_read_commit_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_DRIVER_CAP_BOUND;
    }

    if (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_commit_driver_owner))
        {
            g_ahci_driver_read_audit_owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_DRIVER_OWNER_BOUND;
        }

        endpoint = capability64_route(
            driver_capability_handle,
            CAPABILITY64_RIGHT_QUERY,
            owner_id);
        if ((endpoint == services64_resolve_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE))
            && (capability64_rights(driver_capability_handle, owner_id) == CAPABILITY64_RIGHT_QUERY))
        {
            g_ahci_driver_read_audit_query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    required_flags = MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_READ_COMMIT_READY
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_READ_COMMIT_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_READ_COMMIT_DENIED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_AUDIT_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_AUDIT_DENIED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_AUDITED_BYTES
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_AUDIT_STATUS
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_NO_STORAGE_AUTHORITY;

    g_ahci_driver_read_audit_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_audit_unavailable_count;
        g_ahci_driver_read_audit_state = MMIO64_AHCI_DRIVER_READ_AUDIT_STATE_UNAVAILABLE;
        g_ahci_driver_read_audit_flags |= MMIO64_AHCI_DRIVER_READ_AUDIT_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_audit_state = MMIO64_AHCI_DRIVER_READ_AUDIT_STATE_DENIED;
    g_ahci_driver_read_audit_token = mmio64_make_driver_read_audit_token();
    ++g_ahci_driver_read_audit_stage_count;
    return g_ahci_driver_read_audit_token;
}

