static u32 mmio64_driver_read_upgrade_denied_ready(u32 driver_read_upgrade_token)
{
    u32 required_flags = MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_READ_AUDIT_READY
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_READ_AUDIT_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_READ_AUDIT_DENIED
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_UPGRADE_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_UPGRADE_DENIED
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_NO_UPGRADED_CAPABILITY
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_NO_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_CAPABILITY_GATED
        | MMIO64_AHCI_DRIVER_READ_UPGRADE_FLAG_NO_STORAGE_AUTHORITY;

    if (g_ahci_driver_read_upgrade_state != MMIO64_AHCI_DRIVER_READ_UPGRADE_STATE_DENIED)
    {
        return 0u;
    }

    if ((g_ahci_driver_read_upgrade_flags & required_flags) != required_flags)
    {
        return 0u;
    }

    if ((driver_read_upgrade_token == 0u)
        || (driver_read_upgrade_token != g_ahci_driver_read_upgrade_token))
    {
        return 0u;
    }

    if ((g_ahci_driver_read_upgrade_denied == 0u)
        || (g_ahci_driver_read_upgrade_granted != 0u)
        || (g_ahci_driver_read_upgrade_bytes_available != 0u)
        || (g_ahci_driver_read_upgrade_upgraded_capability != CAPABILITY64_INVALID_HANDLE)
        || (g_ahci_driver_read_upgrade_media_authority != 0u)
        || (g_ahci_driver_read_upgrade_execute_authority != 0u)
        || (g_ahci_driver_read_upgrade_block_endpoint_published != 0u)
        || (g_ahci_driver_read_upgrade_block_cap_minted != 0u)
        || (g_ahci_driver_read_upgrade_fs_minted != 0u)
        || (g_ahci_driver_read_upgrade_mmio_written != 0u)
        || (g_ahci_driver_read_upgrade_port_programmed != 0u)
        || (g_ahci_driver_read_upgrade_published != 0u)
        || (g_ahci_driver_read_upgrade_command_issued != 0u)
        || (g_ahci_driver_read_upgrade_dma_mapped != 0u)
        || (g_ahci_driver_read_upgrade_armed != 0u)
        || (g_ahci_driver_read_upgrade_media_read != 0u)
        || (g_ahci_driver_read_upgrade_media_written != 0u)
        || (g_ahci_driver_read_upgrade_buffer_unchanged == 0u))
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_activate(
    u32 driver_capability_handle,
    u32 driver_read_upgrade_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 endpoint = 0u;
    u32 expected_owner = g_ahci_driver_read_upgrade_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_activate_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_activate();
    g_ahci_driver_read_activate_read_upgrade_token = driver_read_upgrade_token;
    g_ahci_driver_read_activate_driver_capability = driver_capability_handle;
    g_ahci_driver_read_activate_driver_owner = owner_id;
    g_ahci_driver_read_activate_read_upgrade_denied = 1u;
    g_ahci_driver_read_activate_requested = 1u;
    g_ahci_driver_read_activate_granted = 0u;
    g_ahci_driver_read_activate_denied = 1u;
    g_ahci_driver_read_activate_bytes_available = 0u;
    g_ahci_driver_read_activate_activated_capability = CAPABILITY64_INVALID_HANDLE;
    g_ahci_driver_read_activate_read_authority = 0u;
    g_ahci_driver_read_activate_execute_authority = 0u;
    g_ahci_driver_read_activate_block_endpoint_published = 0u;
    g_ahci_driver_read_activate_block_cap_minted = 0u;
    g_ahci_driver_read_activate_fs_minted = 0u;
    g_ahci_driver_read_activate_mmio_written = 0u;
    g_ahci_driver_read_activate_port_programmed = 0u;
    g_ahci_driver_read_activate_published = 0u;
    g_ahci_driver_read_activate_command_issued = 0u;
    g_ahci_driver_read_activate_dma_mapped = 0u;
    g_ahci_driver_read_activate_armed = 0u;
    g_ahci_driver_read_activate_media_read = 0u;
    g_ahci_driver_read_activate_media_written = 0u;
    g_ahci_driver_read_activate_buffer_unchanged = 1u;

    flags = MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_READ_UPGRADE_DENIED
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_ACTIVATION_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_ACTIVATION_DENIED
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_ACTIVATED_CAPABILITY
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_EXECUTE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_STORAGE_AUTHORITY;

    if (mmio64_driver_read_upgrade_denied_ready(driver_read_upgrade_token))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_READ_UPGRADE_READY
            | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_READ_UPGRADE_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_PORT_BOUND
            | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_READ_SHAPE_BOUND
            | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_BUFFER_SHAPE_BOUND;
        g_ahci_driver_read_activate_port = g_ahci_driver_read_upgrade_port;
        g_ahci_driver_read_activate_kind = g_ahci_driver_read_upgrade_kind;
        g_ahci_driver_read_activate_read_operation = g_ahci_driver_read_upgrade_read_operation;
        g_ahci_driver_read_activate_read_lba = g_ahci_driver_read_upgrade_read_lba;
        g_ahci_driver_read_activate_read_blocks = g_ahci_driver_read_upgrade_read_blocks;
        g_ahci_driver_read_activate_read_bytes = g_ahci_driver_read_upgrade_read_bytes;
        g_ahci_driver_read_activate_page_bytes = g_ahci_driver_read_upgrade_page_bytes;
        g_ahci_driver_read_activate_buffer_checksum = g_ahci_driver_read_upgrade_buffer_checksum;
        g_ahci_driver_read_activate_buffer_zeroed = g_ahci_driver_read_upgrade_buffer_zeroed;
        g_ahci_driver_read_activate_read_ready = g_ahci_driver_read_upgrade_read_ready;
        if (g_ahci_driver_read_activate_buffer_zeroed != 0u)
        {
            flags |= MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_BUFFER_ZEROED;
        }
    }

    if ((driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle == g_ahci_driver_read_upgrade_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_DRIVER_CAP_BOUND;
    }

    if (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_upgrade_driver_owner))
        {
            g_ahci_driver_read_activate_owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_DRIVER_OWNER_BOUND;
        }

        endpoint = capability64_route(
            driver_capability_handle,
            CAPABILITY64_RIGHT_QUERY,
            owner_id);
        if ((endpoint == services64_resolve_endpoint_class(SERVICE_ENDPOINT_CLASS_HARDWARE))
            && (capability64_rights(driver_capability_handle, owner_id) == CAPABILITY64_RIGHT_QUERY))
        {
            g_ahci_driver_read_activate_query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    required_flags = MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_READ_UPGRADE_READY
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_READ_UPGRADE_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_READ_UPGRADE_DENIED
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_ACTIVATION_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_ACTIVATION_DENIED
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_ACTIVATED_CAPABILITY
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_EXECUTE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_NO_STORAGE_AUTHORITY;

    g_ahci_driver_read_activate_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_activate_unavailable_count;
        g_ahci_driver_read_activate_state = MMIO64_AHCI_DRIVER_READ_ACTIVATE_STATE_UNAVAILABLE;
        g_ahci_driver_read_activate_flags |= MMIO64_AHCI_DRIVER_READ_ACTIVATE_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_activate_state = MMIO64_AHCI_DRIVER_READ_ACTIVATE_STATE_DENIED;
    g_ahci_driver_read_activate_token = mmio64_make_driver_read_activate_token();
    ++g_ahci_driver_read_activate_stage_count;
    return g_ahci_driver_read_activate_token;
}

