        g_ahci_driver_read_arm_port = g_ahci_driver_read_activate_port;
        g_ahci_driver_read_arm_kind = g_ahci_driver_read_activate_kind;
        g_ahci_driver_read_arm_read_operation = g_ahci_driver_read_activate_read_operation;
        g_ahci_driver_read_arm_read_lba = g_ahci_driver_read_activate_read_lba;
