static u32 mmio64_driver_read_submit_denied_ready(u32 driver_read_submit_token)
{
    u32 required_flags = MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_READ_ARM_READY
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_READ_ARM_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_READ_ARM_DENIED
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_SUBMIT_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_SUBMIT_DENIED
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NO_SUBMITTED_CAPABILITY
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NO_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NO_EXECUTE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_SUBMIT_FLAG_NO_STORAGE_AUTHORITY;

    if ((driver_read_submit_token == 0u)
        || (driver_read_submit_token == MMIO64_INVALID_RESULT)
        || (driver_read_submit_token != g_ahci_driver_read_submit_token))
    {
        return 0u;
    }
    if (g_ahci_driver_read_submit_state != MMIO64_AHCI_DRIVER_READ_SUBMIT_STATE_DENIED)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_submit_flags & required_flags) != required_flags)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_submit_denied == 0u)
        || (g_ahci_driver_read_submit_granted != 0u)
        || (g_ahci_driver_read_submit_bytes_available != 0u)
        || (g_ahci_driver_read_submit_submitted_capability != CAPABILITY64_INVALID_HANDLE)
        || (g_ahci_driver_read_submit_read_authority != 0u)
        || (g_ahci_driver_read_submit_execute_authority != 0u)
        || (g_ahci_driver_read_submit_block_endpoint_published != 0u)
        || (g_ahci_driver_read_submit_block_cap_minted != 0u)
        || (g_ahci_driver_read_submit_fs_minted != 0u)
        || (g_ahci_driver_read_submit_mmio_written != 0u)
        || (g_ahci_driver_read_submit_port_programmed != 0u)
        || (g_ahci_driver_read_submit_published != 0u)
        || (g_ahci_driver_read_submit_command_issued != 0u)
        || (g_ahci_driver_read_submit_dma_mapped != 0u)
        || (g_ahci_driver_read_submit_armed != 0u)
        || (g_ahci_driver_read_submit_media_read != 0u)
        || (g_ahci_driver_read_submit_media_written != 0u)
        || (g_ahci_driver_read_submit_buffer_unchanged == 0u))
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_observe(
    u32 driver_capability_handle,
    u32 driver_read_submit_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 expected_owner = g_ahci_driver_read_submit_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_observe_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_observe();
    g_ahci_driver_read_observe_read_submit_token = driver_read_submit_token;
    g_ahci_driver_read_observe_driver_capability = driver_capability_handle;
    g_ahci_driver_read_observe_driver_owner = owner_id;
    g_ahci_driver_read_observe_read_submit_denied = 1u;
    g_ahci_driver_read_observe_requested = 1u;
    g_ahci_driver_read_observe_granted = 0u;
    g_ahci_driver_read_observe_denied = 1u;
    g_ahci_driver_read_observe_bytes_available = 0u;
    g_ahci_driver_read_observe_observed_status = 0u;
    g_ahci_driver_read_observe_observed_bytes = 0u;
    g_ahci_driver_read_observe_observed_checksum = 0u;
    g_ahci_driver_read_observe_read_authority = 0u;
    g_ahci_driver_read_observe_execute_authority = 0u;
    g_ahci_driver_read_observe_block_endpoint_published = 0u;
    g_ahci_driver_read_observe_block_cap_minted = 0u;
    g_ahci_driver_read_observe_fs_minted = 0u;
    g_ahci_driver_read_observe_mmio_written = 0u;
    g_ahci_driver_read_observe_port_programmed = 0u;
    g_ahci_driver_read_observe_published = 0u;
    g_ahci_driver_read_observe_command_issued = 0u;
    g_ahci_driver_read_observe_dma_mapped = 0u;
    g_ahci_driver_read_observe_armed = 0u;
    g_ahci_driver_read_observe_media_read = 0u;
    g_ahci_driver_read_observe_media_written = 0u;
    g_ahci_driver_read_observe_buffer_unchanged = 1u;

    flags = MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_READ_SUBMIT_DENIED
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_OBSERVE_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_OBSERVE_DENIED
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_OBSERVED_RESULT
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_EXECUTE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_STORAGE_AUTHORITY;

    if (mmio64_driver_read_submit_denied_ready(driver_read_submit_token))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_READ_SUBMIT_READY
            | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_READ_SUBMIT_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_PORT_BOUND
            | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_READ_SHAPE_BOUND
            | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_BUFFER_SHAPE_BOUND;
        g_ahci_driver_read_observe_port = g_ahci_driver_read_submit_port;
        g_ahci_driver_read_observe_kind = g_ahci_driver_read_submit_kind;
        g_ahci_driver_read_observe_read_operation = g_ahci_driver_read_submit_read_operation;
        g_ahci_driver_read_observe_read_lba = g_ahci_driver_read_submit_read_lba;
        g_ahci_driver_read_observe_read_blocks = g_ahci_driver_read_submit_read_blocks;
        g_ahci_driver_read_observe_read_bytes = g_ahci_driver_read_submit_read_bytes;
        g_ahci_driver_read_observe_page_bytes = g_ahci_driver_read_submit_page_bytes;
        g_ahci_driver_read_observe_buffer_checksum = g_ahci_driver_read_submit_buffer_checksum;
        g_ahci_driver_read_observe_buffer_zeroed = g_ahci_driver_read_submit_buffer_zeroed;
        g_ahci_driver_read_observe_read_ready = g_ahci_driver_read_submit_read_ready;
        if (g_ahci_driver_read_observe_buffer_zeroed != 0u)
        {
            flags |= MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_BUFFER_ZEROED;
        }
    }

    if ((driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle == g_ahci_driver_read_submit_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_DRIVER_CAP_BOUND;
    }

    if (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_submit_driver_owner))
        {
            g_ahci_driver_read_observe_owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_DRIVER_OWNER_BOUND;
        }

        if ((g_ahci_driver_read_observe_owner_bound != 0u)
            && (capability64_rights(driver_capability_handle, owner_id) == CAPABILITY64_RIGHT_QUERY))
        {
            g_ahci_driver_read_observe_query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    required_flags = MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_READ_SUBMIT_READY
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_READ_SUBMIT_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_READ_SUBMIT_DENIED
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_OBSERVE_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_OBSERVE_DENIED
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_OBSERVED_RESULT
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_EXECUTE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_NO_STORAGE_AUTHORITY;

    g_ahci_driver_read_observe_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_observe_unavailable_count;
        g_ahci_driver_read_observe_state = MMIO64_AHCI_DRIVER_READ_OBSERVE_STATE_UNAVAILABLE;
        g_ahci_driver_read_observe_flags |= MMIO64_AHCI_DRIVER_READ_OBSERVE_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_observe_state = MMIO64_AHCI_DRIVER_READ_OBSERVE_STATE_DENIED;
    g_ahci_driver_read_observe_token = mmio64_make_driver_read_observe_token();
    ++g_ahci_driver_read_observe_stage_count;
    return g_ahci_driver_read_observe_token;
}

