    required_flags = MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_READ_OBSERVE_READY
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_READ_OBSERVE_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_READ_OBSERVE_DENIED
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_RETIRE_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_RETIRE_DENIED
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NO_RETIRED_RESULT
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NO_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NO_EXECUTE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_RETIRE_FLAG_NO_STORAGE_AUTHORITY;

