static u32 mmio64_driver_read_permit_denied_ready(u32 driver_read_permit_token)
{
    u32 required_flags = MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_READ_RETIRE_READY
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_READ_RETIRE_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_READ_RETIRE_DENIED
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_PERMIT_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_PERMIT_DENIED
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NO_PERMIT_CAPABILITY
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NO_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NO_EXECUTE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_PERMIT_FLAG_NO_STORAGE_AUTHORITY;

    if ((driver_read_permit_token == 0u)
        || (driver_read_permit_token == MMIO64_INVALID_RESULT)
        || (driver_read_permit_token != g_ahci_driver_read_permit_token))
    {
        return 0u;
    }
    if (g_ahci_driver_read_permit_state != MMIO64_AHCI_DRIVER_READ_PERMIT_STATE_DENIED)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_permit_flags & required_flags) != required_flags)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_permit_denied == 0u)
        || (g_ahci_driver_read_permit_granted != 0u)
        || (g_ahci_driver_read_permit_bytes_available != 0u)
        || (g_ahci_driver_read_permit_permit_capability != CAPABILITY64_INVALID_HANDLE)
        || (g_ahci_driver_read_permit_read_authority != 0u)
        || (g_ahci_driver_read_permit_execute_authority != 0u)
        || (g_ahci_driver_read_permit_block_endpoint_published != 0u)
        || (g_ahci_driver_read_permit_block_cap_minted != 0u)
        || (g_ahci_driver_read_permit_fs_minted != 0u)
        || (g_ahci_driver_read_permit_mmio_written != 0u)
        || (g_ahci_driver_read_permit_port_programmed != 0u)
        || (g_ahci_driver_read_permit_published != 0u)
        || (g_ahci_driver_read_permit_command_issued != 0u)
        || (g_ahci_driver_read_permit_dma_mapped != 0u)
        || (g_ahci_driver_read_permit_armed != 0u)
        || (g_ahci_driver_read_permit_media_read != 0u)
        || (g_ahci_driver_read_permit_media_written != 0u)
        || (g_ahci_driver_read_permit_buffer_unchanged == 0u))
    {
        return 0u;
    }

    return 1u;
}

