static u32 mmio64_driver_read_use_denied_ready(u32 driver_read_use_token)
{
    u32 required_flags = MMIO64_AHCI_DRIVER_READ_USE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_READ_LEASE_READY
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_READ_LEASE_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_READ_LEASE_DENIED
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_USE_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_USE_DENIED
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NO_USE_CAPABILITY
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NO_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NO_EXECUTE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_USE_FLAG_NO_STORAGE_AUTHORITY;

    if ((driver_read_use_token == 0u)
        || (driver_read_use_token == MMIO64_INVALID_RESULT)
        || (driver_read_use_token != g_ahci_driver_read_use_token))
    {
        return 0u;
    }
    if (g_ahci_driver_read_use_state != MMIO64_AHCI_DRIVER_READ_USE_STATE_DENIED)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_use_flags & required_flags) != required_flags)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_use_read_lease_denied == 0u)
        || (g_ahci_driver_read_use_requested == 0u)
        || (g_ahci_driver_read_use_denied == 0u)
        || (g_ahci_driver_read_use_granted != 0u)
        || (g_ahci_driver_read_use_bytes_available != 0u)
        || (g_ahci_driver_read_use_use_capability != CAPABILITY64_INVALID_HANDLE)
        || (g_ahci_driver_read_use_active != 0u)
        || (g_ahci_driver_read_use_read_authority != 0u)
        || (g_ahci_driver_read_use_execute_authority != 0u)
        || (g_ahci_driver_read_use_block_endpoint_published != 0u)
        || (g_ahci_driver_read_use_block_cap_minted != 0u)
        || (g_ahci_driver_read_use_fs_minted != 0u)
        || (g_ahci_driver_read_use_mmio_written != 0u)
        || (g_ahci_driver_read_use_port_programmed != 0u)
        || (g_ahci_driver_read_use_published != 0u)
        || (g_ahci_driver_read_use_command_issued != 0u)
        || (g_ahci_driver_read_use_dma_mapped != 0u)
        || (g_ahci_driver_read_use_armed != 0u)
        || (g_ahci_driver_read_use_media_read != 0u)
        || (g_ahci_driver_read_use_media_written != 0u)
        || (g_ahci_driver_read_use_buffer_unchanged == 0u))
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_report(
    u32 driver_capability_handle,
    u32 driver_read_use_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 expected_owner = g_ahci_driver_read_use_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_report_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_report();
    g_ahci_driver_read_report_read_use_token = driver_read_use_token;
    g_ahci_driver_read_report_driver_capability = driver_capability_handle;
    g_ahci_driver_read_report_driver_owner = owner_id;
    g_ahci_driver_read_report_read_use_denied = 1u;
    g_ahci_driver_read_report_requested = 1u;
    g_ahci_driver_read_report_granted = 0u;
    g_ahci_driver_read_report_denied = 1u;
    g_ahci_driver_read_report_bytes_available = 0u;
    g_ahci_driver_read_report_status = 0u;
    g_ahci_driver_read_report_reported_bytes = 0u;
    g_ahci_driver_read_report_report_checksum = 0u;
    g_ahci_driver_read_report_report_capability = CAPABILITY64_INVALID_HANDLE;
    g_ahci_driver_read_report_read_authority = 0u;
    g_ahci_driver_read_report_execute_authority = 0u;
    g_ahci_driver_read_report_block_endpoint_published = 0u;
    g_ahci_driver_read_report_block_cap_minted = 0u;
    g_ahci_driver_read_report_fs_minted = 0u;
    g_ahci_driver_read_report_mmio_written = 0u;
    g_ahci_driver_read_report_port_programmed = 0u;
    g_ahci_driver_read_report_published = 0u;
    g_ahci_driver_read_report_command_issued = 0u;
    g_ahci_driver_read_report_dma_mapped = 0u;
    g_ahci_driver_read_report_armed = 0u;
    g_ahci_driver_read_report_media_read = 0u;
    g_ahci_driver_read_report_media_written = 0u;
    g_ahci_driver_read_report_buffer_unchanged = 1u;

    flags = MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_READ_USE_DENIED
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_REPORT_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_REPORT_DENIED
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_DENIED_STATUS
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_REPORTED_BYTES
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_REPORT_CHECKSUM_ZERO
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_EXECUTE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_BUFFER_UNCHANGED;

    if (mmio64_driver_read_use_denied_ready(driver_read_use_token))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_READ_USE_READY
            | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_READ_USE_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_PORT_BOUND
            | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_READ_SHAPE_BOUND
            | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_BUFFER_SHAPE_BOUND;
        g_ahci_driver_read_report_port = g_ahci_driver_read_use_port;
        g_ahci_driver_read_report_kind = g_ahci_driver_read_use_kind;
        g_ahci_driver_read_report_read_operation = g_ahci_driver_read_use_read_operation;
        g_ahci_driver_read_report_read_lba = g_ahci_driver_read_use_read_lba;
        g_ahci_driver_read_report_read_blocks = g_ahci_driver_read_use_read_blocks;
        g_ahci_driver_read_report_read_bytes = g_ahci_driver_read_use_read_bytes;
        g_ahci_driver_read_report_page_bytes = g_ahci_driver_read_use_page_bytes;
        g_ahci_driver_read_report_buffer_checksum = g_ahci_driver_read_use_buffer_checksum;
        g_ahci_driver_read_report_buffer_zeroed = g_ahci_driver_read_use_buffer_zeroed;
        g_ahci_driver_read_report_read_ready = g_ahci_driver_read_use_read_ready;
        if (g_ahci_driver_read_report_buffer_zeroed != 0u)
        {
            flags |= MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_BUFFER_ZEROED;
        }
    }

    if ((driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle == g_ahci_driver_read_use_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_DRIVER_CAP_BOUND;
    }

    if (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_use_driver_owner))
        {
            g_ahci_driver_read_report_owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_DRIVER_OWNER_BOUND;
        }

        if ((g_ahci_driver_read_report_owner_bound != 0u)
            && (capability64_rights(driver_capability_handle, owner_id) == CAPABILITY64_RIGHT_QUERY))
        {
            g_ahci_driver_read_report_query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    required_flags = MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_READ_USE_READY
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_READ_USE_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_READ_USE_DENIED
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_REPORT_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_REPORT_DENIED
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_DENIED_STATUS
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_REPORTED_BYTES
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_REPORT_CHECKSUM_ZERO
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_EXECUTE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_BUFFER_UNCHANGED;

    g_ahci_driver_read_report_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_report_unavailable_count;
        g_ahci_driver_read_report_state = MMIO64_AHCI_DRIVER_READ_REPORT_STATE_UNAVAILABLE;
        g_ahci_driver_read_report_flags |= MMIO64_AHCI_DRIVER_READ_REPORT_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_report_state = MMIO64_AHCI_DRIVER_READ_REPORT_STATE_DENIED;
    g_ahci_driver_read_report_token = mmio64_make_driver_read_report_token();
    ++g_ahci_driver_read_report_stage_count;
    return g_ahci_driver_read_report_token;
}

