static u32 mmio64_driver_read_discard_denied_ready(u32 driver_read_discard_token)
{
    u32 required_flags = MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_READ_UNSEAL_READY
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_READ_UNSEAL_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_READ_UNSEAL_DENIED
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_DISCARD_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_DISCARD_DENIED
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_DENIED_STATUS
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_NO_DISCARDED_BYTES
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_DISCARD_CHECKSUM_ZERO
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_NO_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_NO_EXECUTE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_DISCARD_FLAG_BUFFER_UNCHANGED;

    if ((driver_read_discard_token == 0u)
        || (driver_read_discard_token == MMIO64_INVALID_RESULT)
        || (g_ahci_driver_read_discard_token != driver_read_discard_token)
        || (g_ahci_driver_read_discard_state != MMIO64_AHCI_DRIVER_READ_DISCARD_STATE_DENIED)
        || ((g_ahci_driver_read_discard_flags & required_flags) != required_flags)
        || (g_ahci_driver_read_discard_status != 0u)
        || (g_ahci_driver_read_discard_discarded_bytes != 0u)
        || (g_ahci_driver_read_discard_discard_checksum != 0u)
        || (g_ahci_driver_read_discard_discard_capability != CAPABILITY64_INVALID_HANDLE)
        || (g_ahci_driver_read_discard_read_authority != 0u)
        || (g_ahci_driver_read_discard_execute_authority != 0u)
        || (g_ahci_driver_read_discard_block_endpoint_published != 0u)
        || (g_ahci_driver_read_discard_block_cap_minted != 0u)
        || (g_ahci_driver_read_discard_fs_minted != 0u)
        || (g_ahci_driver_read_discard_mmio_written != 0u)
        || (g_ahci_driver_read_discard_port_programmed != 0u)
        || (g_ahci_driver_read_discard_published != 0u)
        || (g_ahci_driver_read_discard_command_issued != 0u)
        || (g_ahci_driver_read_discard_dma_mapped != 0u)
        || (g_ahci_driver_read_discard_armed != 0u)
        || (g_ahci_driver_read_discard_media_read != 0u)
        || (g_ahci_driver_read_discard_media_written != 0u)
        || (g_ahci_driver_read_discard_buffer_unchanged == 0u))
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_finalize(
    u32 driver_capability_handle,
    u32 driver_read_discard_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 expected_owner = g_ahci_driver_read_discard_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_finalize_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_finalize();
    g_ahci_driver_read_finalize_read_discard_token = driver_read_discard_token;
    g_ahci_driver_read_finalize_driver_capability = driver_capability_handle;
    g_ahci_driver_read_finalize_driver_owner = owner_id;
    g_ahci_driver_read_finalize_read_discard_denied = 1u;
    g_ahci_driver_read_finalize_requested = 1u;
    g_ahci_driver_read_finalize_granted = 0u;
    g_ahci_driver_read_finalize_denied = 1u;
    g_ahci_driver_read_finalize_bytes_available = 0u;
    g_ahci_driver_read_finalize_status = 0u;
    g_ahci_driver_read_finalize_finalized_bytes = 0u;
    g_ahci_driver_read_finalize_finalize_checksum = 0u;
    g_ahci_driver_read_finalize_finalize_capability = CAPABILITY64_INVALID_HANDLE;
    g_ahci_driver_read_finalize_read_authority = 0u;
    g_ahci_driver_read_finalize_execute_authority = 0u;
    g_ahci_driver_read_finalize_block_endpoint_published = 0u;
    g_ahci_driver_read_finalize_block_cap_minted = 0u;
    g_ahci_driver_read_finalize_fs_minted = 0u;
    g_ahci_driver_read_finalize_mmio_written = 0u;
    g_ahci_driver_read_finalize_port_programmed = 0u;
    g_ahci_driver_read_finalize_published = 0u;
    g_ahci_driver_read_finalize_command_issued = 0u;
    g_ahci_driver_read_finalize_dma_mapped = 0u;
    g_ahci_driver_read_finalize_armed = 0u;
    g_ahci_driver_read_finalize_media_read = 0u;
    g_ahci_driver_read_finalize_media_written = 0u;
    g_ahci_driver_read_finalize_buffer_unchanged = 1u;

    flags = MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_READ_DISCARD_DENIED
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_FINALIZE_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_FINALIZE_DENIED
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_DENIED_STATUS
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_FINALIZED_BYTES
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_FINALIZE_CHECKSUM_ZERO
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_EXECUTE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_BUFFER_UNCHANGED;

    if (mmio64_driver_read_discard_denied_ready(driver_read_discard_token))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_READ_DISCARD_READY
            | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_READ_DISCARD_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_PORT_BOUND
            | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_READ_SHAPE_BOUND
            | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_BUFFER_SHAPE_BOUND;
        g_ahci_driver_read_finalize_port = g_ahci_driver_read_discard_port;
        g_ahci_driver_read_finalize_kind = g_ahci_driver_read_discard_kind;
        g_ahci_driver_read_finalize_read_operation = g_ahci_driver_read_discard_read_operation;
        g_ahci_driver_read_finalize_read_lba = g_ahci_driver_read_discard_read_lba;
        g_ahci_driver_read_finalize_read_blocks = g_ahci_driver_read_discard_read_blocks;
        g_ahci_driver_read_finalize_read_bytes = g_ahci_driver_read_discard_read_bytes;
        g_ahci_driver_read_finalize_page_bytes = g_ahci_driver_read_discard_page_bytes;
        g_ahci_driver_read_finalize_buffer_checksum = g_ahci_driver_read_discard_buffer_checksum;
        g_ahci_driver_read_finalize_buffer_zeroed = g_ahci_driver_read_discard_buffer_zeroed;
        g_ahci_driver_read_finalize_read_ready = g_ahci_driver_read_discard_read_ready;
        if (g_ahci_driver_read_finalize_buffer_zeroed != 0u)
        {
            flags |= MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_BUFFER_ZEROED;
        }
    }

    if ((driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle == g_ahci_driver_read_discard_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_DRIVER_CAP_BOUND;
    }

    if (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_discard_driver_owner))
        {
            g_ahci_driver_read_finalize_owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_DRIVER_OWNER_BOUND;
        }

        if ((g_ahci_driver_read_finalize_owner_bound != 0u)
            && (capability64_rights(driver_capability_handle, owner_id) == CAPABILITY64_RIGHT_QUERY))
        {
            g_ahci_driver_read_finalize_query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    required_flags = MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_READ_DISCARD_READY
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_READ_DISCARD_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_READ_DISCARD_DENIED
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_FINALIZE_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_FINALIZE_DENIED
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_DENIED_STATUS
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_FINALIZED_BYTES
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_FINALIZE_CHECKSUM_ZERO
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_EXECUTE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_MEDIA_READ
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_NO_MEDIA_WRITE
        | MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_BUFFER_UNCHANGED;

    g_ahci_driver_read_finalize_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_finalize_unavailable_count;
        g_ahci_driver_read_finalize_state = MMIO64_AHCI_DRIVER_READ_FINALIZE_STATE_UNAVAILABLE;
        g_ahci_driver_read_finalize_flags |= MMIO64_AHCI_DRIVER_READ_FINALIZE_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_finalize_state = MMIO64_AHCI_DRIVER_READ_FINALIZE_STATE_DENIED;
    g_ahci_driver_read_finalize_token = mmio64_make_driver_read_finalize_token();
    ++g_ahci_driver_read_finalize_stage_count;
    return g_ahci_driver_read_finalize_token;
}

