        flags |= MMIO64_AHCI_DRIVER_READ_DISPATCH_FLAG_READ_AUTHORIZE_READY
            | MMIO64_AHCI_DRIVER_READ_DISPATCH_FLAG_READ_AUTHORIZE_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_DISPATCH_FLAG_PORT_BOUND
            | MMIO64_AHCI_DRIVER_READ_DISPATCH_FLAG_READ_SHAPE_BOUND
            | MMIO64_AHCI_DRIVER_READ_DISPATCH_FLAG_BUFFER_SHAPE_BOUND;
