    mmio64_reset_driver_read_schedule();
    g_ahci_driver_read_schedule_read_worker_token = driver_read_worker_token;
    g_ahci_driver_read_schedule_driver_capability = driver_capability_handle;
    g_ahci_driver_read_schedule_driver_owner = owner_id;
