static u32 mmio64_driver_read_run_denied_ready(u32 token)
{
    u32 required_flags = MMIO64_AHCI_DRIVER_READ_RUN_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_READ_SCHEDULE_READY
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_READ_SCHEDULE_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_READ_SCHEDULE_DENIED
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_RUN_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_RUN_DENIED
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NO_POLICY_GRANT
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NO_WORKER_RUN
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_QUEUE_EMPTY
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NO_ISSUE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NO_DMA_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NO_MEDIA_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_RUN_FLAG_BUFFER_UNCHANGED;

    if ((token == 0u)
        || (token != g_ahci_driver_read_run_token)
        || (g_ahci_driver_read_run_state != MMIO64_AHCI_DRIVER_READ_RUN_STATE_DENIED)
        || (g_ahci_driver_read_run_read_schedule_token == 0u)
        || (g_ahci_driver_read_run_driver_capability == CAPABILITY64_INVALID_HANDLE)
        || (g_ahci_driver_read_run_driver_owner == 0u)
        || (g_ahci_driver_read_run_owner_bound == 0u)
        || (g_ahci_driver_read_run_query_only == 0u)
        || (g_ahci_driver_read_run_port == MMIO64_INVALID_RESULT)
        || (g_ahci_driver_read_run_kind == MMIO64_PORT_DEVICE_NONE)
        || (g_ahci_driver_read_run_read_operation == MMIO64_AHCI_READ_OPERATION_NONE)
        || (g_ahci_driver_read_run_read_blocks == 0u)
        || (g_ahci_driver_read_run_read_bytes == 0u)
        || (g_ahci_driver_read_run_page_bytes == 0u)
        || (g_ahci_driver_read_run_buffer_checksum == 0u)
        || (g_ahci_driver_read_run_buffer_zeroed == 0u)
        || (g_ahci_driver_read_run_read_ready == 0u)
        || (g_ahci_driver_read_run_read_schedule_denied == 0u)
        || (g_ahci_driver_read_run_requested == 0u)
        || (g_ahci_driver_read_run_granted != 0u)
        || (g_ahci_driver_read_run_denied == 0u)
        || (g_ahci_driver_read_run_policy_grant != 0u)
        || (g_ahci_driver_read_run_queue_inserted != 0u)
        || (g_ahci_driver_read_run_queue_depth != 0u)
        || (g_ahci_driver_read_run_worker_wake != 0u)
        || (g_ahci_driver_read_run_worker_dequeued != 0u)
        || (g_ahci_driver_read_run_worker_runnable != 0u)
        || (g_ahci_driver_read_run_worker_scheduled != 0u)
        || (g_ahci_driver_read_run_worker_run != 0u)
        || (g_ahci_driver_read_run_worker_executed != 0u)
        || (g_ahci_driver_read_run_issue_authority != 0u)
        || (g_ahci_driver_read_run_dma_authority != 0u)
        || (g_ahci_driver_read_run_media_read_authority != 0u)
        || (g_ahci_driver_read_run_write_authority != 0u)
        || (g_ahci_driver_read_run_commit_authority != 0u)
        || (g_ahci_driver_read_run_block_endpoint_published != 0u)
        || (g_ahci_driver_read_run_block_cap_minted != 0u)
        || (g_ahci_driver_read_run_fs_minted != 0u)
        || (g_ahci_driver_read_run_mmio_written != 0u)
        || (g_ahci_driver_read_run_port_programmed != 0u)
        || (g_ahci_driver_read_run_published != 0u)
        || (g_ahci_driver_read_run_command_issued != 0u)
        || (g_ahci_driver_read_run_dma_mapped != 0u)
        || (g_ahci_driver_read_run_armed != 0u)
        || (g_ahci_driver_read_run_media_read != 0u)
        || (g_ahci_driver_read_run_media_written != 0u)
        || (g_ahci_driver_read_run_buffer_unchanged == 0u)
        || (g_ahci_driver_read_run_stage_count == 0u))
    {
        return 0u;
    }

    if ((g_ahci_driver_read_run_flags & required_flags) != required_flags)
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_body(
    u32 driver_capability_handle,
    u32 driver_read_run_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 read_run_ready;
    u32 expected_owner = g_ahci_driver_read_run_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_body_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_body();
    g_ahci_driver_read_body_read_run_token = driver_read_run_token;
    g_ahci_driver_read_body_driver_capability = driver_capability_handle;
    g_ahci_driver_read_body_driver_owner = owner_id;
    g_ahci_driver_read_body_read_run_denied = 1u;
    g_ahci_driver_read_body_requested = 1u;
    g_ahci_driver_read_body_granted = 0u;
    g_ahci_driver_read_body_denied = 1u;
    g_ahci_driver_read_body_policy_grant = 0u;
    g_ahci_driver_read_body_queue_inserted = 0u;
    g_ahci_driver_read_body_queue_depth = 0u;
    g_ahci_driver_read_body_worker_wake = 0u;
    g_ahci_driver_read_body_worker_dequeued = 0u;
    g_ahci_driver_read_body_worker_runnable = 0u;
    g_ahci_driver_read_body_worker_scheduled = 0u;
    g_ahci_driver_read_body_worker_run = 0u;
    g_ahci_driver_read_body_worker_executed = 0u;
    g_ahci_driver_read_body_body_entered = 0u;
    g_ahci_driver_read_body_body_completed = 0u;
    g_ahci_driver_read_body_issue_authority = 0u;
    g_ahci_driver_read_body_dma_authority = 0u;
    g_ahci_driver_read_body_media_read_authority = 0u;
    g_ahci_driver_read_body_write_authority = 0u;
    g_ahci_driver_read_body_commit_authority = 0u;
    g_ahci_driver_read_body_block_endpoint_published = 0u;
    g_ahci_driver_read_body_block_cap_minted = 0u;
    g_ahci_driver_read_body_fs_minted = 0u;
    g_ahci_driver_read_body_mmio_written = 0u;
    g_ahci_driver_read_body_port_programmed = 0u;
    g_ahci_driver_read_body_published = 0u;
    g_ahci_driver_read_body_command_issued = 0u;
    g_ahci_driver_read_body_dma_mapped = 0u;
    g_ahci_driver_read_body_armed = 0u;
    g_ahci_driver_read_body_media_read = 0u;
    g_ahci_driver_read_body_media_written = 0u;
    g_ahci_driver_read_body_buffer_unchanged = 1u;

    flags = MMIO64_AHCI_DRIVER_READ_BODY_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_READ_RUN_DENIED
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_BODY_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_BODY_DENIED
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_POLICY_GRANT
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_WORKER_BODY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_QUEUE_EMPTY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_ISSUE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_DMA_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_MEDIA_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_BUFFER_UNCHANGED;

    read_run_ready = mmio64_driver_read_run_denied_ready(driver_read_run_token);
    if (read_run_ready != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_BODY_FLAG_READ_RUN_READY
            | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_READ_RUN_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_PORT_BOUND
            | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_READ_SHAPE_BOUND
            | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_BUFFER_SHAPE_BOUND;
        g_ahci_driver_read_body_port = g_ahci_driver_read_run_port;
        g_ahci_driver_read_body_kind = g_ahci_driver_read_run_kind;
        g_ahci_driver_read_body_read_operation = g_ahci_driver_read_run_read_operation;
        g_ahci_driver_read_body_read_lba = g_ahci_driver_read_run_read_lba;
        g_ahci_driver_read_body_read_blocks = g_ahci_driver_read_run_read_blocks;
        g_ahci_driver_read_body_read_bytes = g_ahci_driver_read_run_read_bytes;
        g_ahci_driver_read_body_page_bytes = g_ahci_driver_read_run_page_bytes;
        g_ahci_driver_read_body_buffer_checksum = g_ahci_driver_read_run_buffer_checksum;
        g_ahci_driver_read_body_buffer_zeroed = g_ahci_driver_read_run_buffer_zeroed;
        g_ahci_driver_read_body_read_ready = g_ahci_driver_read_run_read_ready;
        if (g_ahci_driver_read_body_buffer_zeroed != 0u)
        {
            flags |= MMIO64_AHCI_DRIVER_READ_BODY_FLAG_BUFFER_ZEROED;
        }
    }

    if ((read_run_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle == g_ahci_driver_read_run_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_BODY_FLAG_DRIVER_CAP_BOUND;
    }

    if ((read_run_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE))
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_run_driver_owner))
        {
            g_ahci_driver_read_body_owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_BODY_FLAG_DRIVER_OWNER_BOUND;
        }

        if ((g_ahci_driver_read_body_owner_bound != 0u)
            && (capability64_rights(driver_capability_handle, owner_id) == CAPABILITY64_RIGHT_QUERY))
        {
            g_ahci_driver_read_body_query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_BODY_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    required_flags = MMIO64_AHCI_DRIVER_READ_BODY_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_READ_RUN_READY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_READ_RUN_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_READ_RUN_DENIED
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_BODY_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_BODY_DENIED
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_POLICY_GRANT
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_WORKER_BODY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_QUEUE_EMPTY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_ISSUE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_DMA_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_MEDIA_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_BODY_FLAG_BUFFER_UNCHANGED;

    g_ahci_driver_read_body_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_body_unavailable_count;
        g_ahci_driver_read_body_state = MMIO64_AHCI_DRIVER_READ_BODY_STATE_UNAVAILABLE;
        g_ahci_driver_read_body_flags |= MMIO64_AHCI_DRIVER_READ_BODY_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_body_state = MMIO64_AHCI_DRIVER_READ_BODY_STATE_DENIED;
    g_ahci_driver_read_body_token = mmio64_make_driver_read_body_token();
    ++g_ahci_driver_read_body_stage_count;
    return g_ahci_driver_read_body_token;
}

