static u32 mmio64_driver_read_dma_denied_ready(u32 token)
{
    u32 required_flags = MMIO64_AHCI_DRIVER_READ_DMA_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_READ_ISSUE_READY
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_READ_ISSUE_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_READ_ISSUE_DENIED
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_DMA_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_DMA_DENIED
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_POLICY_GRANT
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_DMA_WINDOW
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_ISSUE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_DMA_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_MEDIA_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_DMA_FLAG_BUFFER_UNCHANGED;

    if ((token == 0u)
        || (token != g_ahci_driver_read_dma_token)
        || (g_ahci_driver_read_dma_state != MMIO64_AHCI_DRIVER_READ_DMA_STATE_DENIED)
        || (g_ahci_driver_read_dma_read_issue_token == 0u)
        || (g_ahci_driver_read_dma_driver_capability == CAPABILITY64_INVALID_HANDLE)
        || (g_ahci_driver_read_dma_driver_owner == 0u)
        || (g_ahci_driver_read_dma_owner_bound == 0u)
        || (g_ahci_driver_read_dma_query_only == 0u)
        || (g_ahci_driver_read_dma_port == MMIO64_INVALID_RESULT)
        || (g_ahci_driver_read_dma_kind == MMIO64_PORT_DEVICE_NONE)
        || (g_ahci_driver_read_dma_read_operation == MMIO64_AHCI_READ_OPERATION_NONE)
        || (g_ahci_driver_read_dma_read_blocks == 0u)
        || (g_ahci_driver_read_dma_read_bytes == 0u)
        || (g_ahci_driver_read_dma_page_bytes == 0u)
        || (g_ahci_driver_read_dma_buffer_checksum == 0u)
        || (g_ahci_driver_read_dma_buffer_zeroed == 0u)
        || (g_ahci_driver_read_dma_read_ready == 0u)
        || (g_ahci_driver_read_dma_read_issue_denied == 0u)
        || (g_ahci_driver_read_dma_requested == 0u)
        || (g_ahci_driver_read_dma_granted != 0u)
        || (g_ahci_driver_read_dma_denied == 0u)
        || (g_ahci_driver_read_dma_policy_grant != 0u)
        || (g_ahci_driver_read_dma_bytes_available != 0u)
        || (g_ahci_driver_read_dma_window_capability != CAPABILITY64_INVALID_HANDLE)
        || (g_ahci_driver_read_dma_window_open != 0u)
        || (g_ahci_driver_read_dma_entered != 0u)
        || (g_ahci_driver_read_dma_completed != 0u)
        || (g_ahci_driver_read_dma_issue_authority != 0u)
        || (g_ahci_driver_read_dma_dma_authority != 0u)
        || (g_ahci_driver_read_dma_media_read_authority != 0u)
        || (g_ahci_driver_read_dma_write_authority != 0u)
        || (g_ahci_driver_read_dma_commit_authority != 0u)
        || (g_ahci_driver_read_dma_block_endpoint_published != 0u)
        || (g_ahci_driver_read_dma_block_cap_minted != 0u)
        || (g_ahci_driver_read_dma_fs_minted != 0u)
        || (g_ahci_driver_read_dma_mmio_written != 0u)
        || (g_ahci_driver_read_dma_port_programmed != 0u)
        || (g_ahci_driver_read_dma_published != 0u)
        || (g_ahci_driver_read_dma_command_issued != 0u)
        || (g_ahci_driver_read_dma_dma_mapped != 0u)
        || (g_ahci_driver_read_dma_armed != 0u)
        || (g_ahci_driver_read_dma_media_read != 0u)
        || (g_ahci_driver_read_dma_media_written != 0u)
        || (g_ahci_driver_read_dma_buffer_unchanged == 0u)
        || (g_ahci_driver_read_dma_stage_count == 0u))
    {
        return 0u;
    }

    if ((g_ahci_driver_read_dma_flags & required_flags) != required_flags)
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_irq(
    u32 driver_capability_handle,
    u32 driver_read_dma_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 read_dma_ready;
    u32 expected_owner = g_ahci_driver_read_dma_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_irq_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_irq();
    g_ahci_driver_read_irq_read_dma_token = driver_read_dma_token;
    g_ahci_driver_read_irq_driver_capability = driver_capability_handle;
    g_ahci_driver_read_irq_driver_owner = owner_id;
    g_ahci_driver_read_irq_read_dma_denied = 1u;
    g_ahci_driver_read_irq_requested = 1u;
    g_ahci_driver_read_irq_granted = 0u;
    g_ahci_driver_read_irq_denied = 1u;
    g_ahci_driver_read_irq_policy_grant = 0u;
    g_ahci_driver_read_irq_bytes_available = 0u;
    g_ahci_driver_read_irq_irq_wait = 0u;
    g_ahci_driver_read_irq_irq_fired = 0u;
    g_ahci_driver_read_irq_completion_status = 0u;
    g_ahci_driver_read_irq_completion_bytes = 0u;
    g_ahci_driver_read_irq_completion_checksum = 0u;
    g_ahci_driver_read_irq_issue_authority = 0u;
    g_ahci_driver_read_irq_dma_authority = 0u;
    g_ahci_driver_read_irq_media_read_authority = 0u;
    g_ahci_driver_read_irq_write_authority = 0u;
    g_ahci_driver_read_irq_commit_authority = 0u;
    g_ahci_driver_read_irq_block_endpoint_published = 0u;
    g_ahci_driver_read_irq_block_cap_minted = 0u;
    g_ahci_driver_read_irq_fs_minted = 0u;
    g_ahci_driver_read_irq_mmio_written = 0u;
    g_ahci_driver_read_irq_port_programmed = 0u;
    g_ahci_driver_read_irq_published = 0u;
    g_ahci_driver_read_irq_command_issued = 0u;
    g_ahci_driver_read_irq_dma_mapped = 0u;
    g_ahci_driver_read_irq_armed = 0u;
    g_ahci_driver_read_irq_media_read = 0u;
    g_ahci_driver_read_irq_media_written = 0u;
    g_ahci_driver_read_irq_buffer_unchanged = 1u;

    flags = MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_READ_DMA_DENIED
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_IRQ_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_IRQ_DENIED
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_POLICY_GRANT
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_IRQ_COMPLETION
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_ISSUE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_DMA_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_MEDIA_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_BUFFER_UNCHANGED;

    read_dma_ready = mmio64_driver_read_dma_denied_ready(driver_read_dma_token);
    if (read_dma_ready != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_READ_DMA_READY
            | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_READ_DMA_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_PORT_BOUND
            | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_READ_SHAPE_BOUND
            | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_BUFFER_SHAPE_BOUND;
        g_ahci_driver_read_irq_port = g_ahci_driver_read_dma_port;
        g_ahci_driver_read_irq_kind = g_ahci_driver_read_dma_kind;
        g_ahci_driver_read_irq_read_operation = g_ahci_driver_read_dma_read_operation;
        g_ahci_driver_read_irq_read_lba = g_ahci_driver_read_dma_read_lba;
        g_ahci_driver_read_irq_read_blocks = g_ahci_driver_read_dma_read_blocks;
        g_ahci_driver_read_irq_read_bytes = g_ahci_driver_read_dma_read_bytes;
        g_ahci_driver_read_irq_page_bytes = g_ahci_driver_read_dma_page_bytes;
        g_ahci_driver_read_irq_buffer_checksum = g_ahci_driver_read_dma_buffer_checksum;
        g_ahci_driver_read_irq_buffer_zeroed = g_ahci_driver_read_dma_buffer_zeroed;
        g_ahci_driver_read_irq_read_ready = g_ahci_driver_read_dma_read_ready;
        if (g_ahci_driver_read_irq_buffer_zeroed != 0u)
        {
            flags |= MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_BUFFER_ZEROED;
        }
    }

    if ((read_dma_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle == g_ahci_driver_read_dma_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_DRIVER_CAP_BOUND;
    }

    if ((read_dma_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE))
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_dma_driver_owner))
        {
            g_ahci_driver_read_irq_owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_DRIVER_OWNER_BOUND;
        }

        if ((g_ahci_driver_read_irq_owner_bound != 0u)
            && (capability64_rights(driver_capability_handle, owner_id) == CAPABILITY64_RIGHT_QUERY))
        {
            g_ahci_driver_read_irq_query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    required_flags = MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_READ_DMA_READY
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_READ_DMA_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_PORT_BOUND
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_READ_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_BUFFER_SHAPE_BOUND
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_BUFFER_ZEROED
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_READ_DMA_DENIED
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_IRQ_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_IRQ_DENIED
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_POLICY_GRANT
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_IRQ_COMPLETION
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_ISSUE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_DMA_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_MEDIA_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_DMA
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NO_COMMANDS
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_NOT_ARMED
        | MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_BUFFER_UNCHANGED;

    g_ahci_driver_read_irq_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_irq_unavailable_count;
        g_ahci_driver_read_irq_state = MMIO64_AHCI_DRIVER_READ_IRQ_STATE_UNAVAILABLE;
        g_ahci_driver_read_irq_flags |= MMIO64_AHCI_DRIVER_READ_IRQ_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_irq_state = MMIO64_AHCI_DRIVER_READ_IRQ_STATE_DENIED;
    g_ahci_driver_read_irq_token = mmio64_make_driver_read_irq_token();
    ++g_ahci_driver_read_irq_stage_count;
    return g_ahci_driver_read_irq_token;
}

