static u32 mmio64_driver_read_status_descriptor_ready(
    u32 driver_read_status_descriptor_token)
{
    u32 required_flags = 0x3FFFFFFFu;

    if ((driver_read_status_descriptor_token == 0u)
        || (driver_read_status_descriptor_token == MMIO64_INVALID_RESULT)
        || (driver_read_status_descriptor_token
            != g_ahci_driver_read_status_descriptor_token))
    {
        return 0u;
    }
    if (g_ahci_driver_read_status_descriptor_state
        != MMIO64_AHCI_DRIVER_READ_STATUS_DESCRIPTOR_STATE_READY)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_status_descriptor_flags & required_flags)
        != required_flags)
    {
        return 0u;
    }
    if (g_ahci_driver_read_status_descriptor_stage_count == 0u)
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_status_command_table(
    u32 driver_capability_handle,
    u32 driver_read_status_descriptor_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags = 0x3FFFFFFFu;
    u32 descriptor_ready;
    u32 owner_bound = 0u;
    u32 query_only = 0u;
    u32 table_ready = 0u;
    u32 expected_owner = g_ahci_driver_read_status_export_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_status_command_table_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_status_command_table();
    flags = MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_TABLE_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_ISSUE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_DMA_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_MEDIA_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_QUEUE_DEQUEUE
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_WORKER_ADMIT
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_WORKER_WAKE
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_WORKER_RUNNABLE
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_WORKER_SCHEDULE
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_WORKER_RUN
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_WORKER_EXECUTE
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_NO_MEDIA_READ;

    descriptor_ready = mmio64_driver_read_status_descriptor_ready(
        driver_read_status_descriptor_token);
    if (descriptor_ready != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_DESCRIPTOR_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_DESCRIPTOR_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_READ_SHAPE_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_DESCRIPTOR_BOUND;
    }

    if ((descriptor_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle
            == g_ahci_driver_read_status_export_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_DRIVER_CAP_BOUND;
    }

    if ((descriptor_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE))
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_status_export_driver_owner))
        {
            owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_DRIVER_OWNER_BOUND;
        }

        if ((owner_bound != 0u)
            && (capability64_rights(driver_capability_handle, owner_id)
                == CAPABILITY64_RIGHT_QUERY))
        {
            query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    if ((g_ahci_table_plan_state == MMIO64_AHCI_TABLE_PLAN_STATE_PREPARED_NO_ISSUE)
        && (g_ahci_table_plan_stage_count != 0u)
        && (g_ahci_table_plan_table_written != 0u)
        && (g_ahci_table_plan_checksum_before
            == g_ahci_driver_read_status_export_buffer_checksum)
        && (g_ahci_table_plan_checksum_after != 0u)
        && (g_ahci_table_plan_checksum_changed != 0u)
        && (g_ahci_table_plan_header_flags == 0x00010025u)
        && (g_ahci_table_plan_header_prdt_length == 1u)
        && (g_ahci_table_plan_header_prdbc == 0u)
        && (g_ahci_table_plan_header_ctba_low == 0u)
        && (g_ahci_table_plan_header_ctba_high == 0u)
        && (g_ahci_table_plan_cfis_command == 0x000000A0u)
        && (g_ahci_table_plan_packet_opcode == 0x00000028u)
        && (g_ahci_table_plan_packet_blocks == 1u)
        && (g_ahci_table_plan_prdt_dba_low == 0u)
        && (g_ahci_table_plan_prdt_dba_high == 0u)
        && (g_ahci_table_plan_prdt_byte_count == 2047u)
        && (g_ahci_table_plan_dma_mapped == 0u)
        && (g_ahci_table_plan_port_programmed == 0u)
        && (g_ahci_table_plan_armed == 0u)
        && (g_ahci_table_plan_issued == 0u))
    {
        table_ready = 1u;
    }

    if ((descriptor_ready != 0u)
        && ((flags & MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_DRIVER_CAP_BOUND) != 0u)
        && (owner_bound != 0u)
        && (query_only != 0u)
        && (table_ready != 0u))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_TABLE_MATERIALIZED
            | MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_TABLE_READY;
    }

    g_ahci_driver_read_status_command_table_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_status_command_table_unavailable_count;
        g_ahci_driver_read_status_command_table_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_command_table_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_command_table_state =
        MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_TABLE_STATE_READY;
    g_ahci_driver_read_status_command_table_token =
        mmio64_make_driver_read_status_command_table_token();
    ++g_ahci_driver_read_status_command_table_stage_count;
    return g_ahci_driver_read_status_command_table_token;
}

