static u32 mmio64_driver_read_status_command_issue_denied_ready(
    u32 driver_read_status_command_issue_token)
{
    u32 required_flags = 0x3FFFFFFFu;

    if ((driver_read_status_command_issue_token == 0u)
        || (driver_read_status_command_issue_token == MMIO64_INVALID_RESULT)
        || (driver_read_status_command_issue_token
            != g_ahci_driver_read_status_command_issue_token))
    {
        return 0u;
    }
    if (g_ahci_driver_read_status_command_issue_state
        != MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_ISSUE_STATE_DENIED)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_status_command_issue_flags & required_flags)
        != required_flags)
    {
        return 0u;
    }
    if (g_ahci_driver_read_status_command_issue_stage_count == 0u)
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_status_issue_grant(
    u32 driver_capability_handle,
    u32 driver_read_status_command_issue_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags = 0x3FFFFFFFu;
    u32 command_issue_ready;
    u32 owner_bound = 0u;
    u32 query_only = 0u;
    u32 grant_ready = 0u;
    u32 expected_owner = g_ahci_driver_read_status_export_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_status_issue_grant_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_status_issue_grant();
    flags = MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_ISSUE_GRANT_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_ISSUE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_DMA_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_MEDIA_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_QUEUE_DEQUEUE
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_WORKER_ADMIT
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_WORKER_WAKE
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_WORKER_RUNNABLE
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_WORKER_SCHEDULE
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_WORKER_RUN
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_WORKER_EXECUTE
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_NO_MEDIA_READ;

    command_issue_ready = mmio64_driver_read_status_command_issue_denied_ready(
        driver_read_status_command_issue_token);
    if (command_issue_ready != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_COMMAND_ISSUE_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_COMMAND_ISSUE_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_READ_SHAPE_BOUND;
    }

    if ((command_issue_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle
            == g_ahci_driver_read_status_export_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_DRIVER_CAP_BOUND;
    }

    if ((command_issue_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE))
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_status_export_driver_owner))
        {
            owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_DRIVER_OWNER_BOUND;
        }

        if ((owner_bound != 0u)
            && (capability64_rights(driver_capability_handle, owner_id)
                == CAPABILITY64_RIGHT_QUERY))
        {
            query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    if ((g_ahci_driver_read_status_command_issue_state
            == MMIO64_AHCI_DRIVER_READ_STATUS_COMMAND_ISSUE_STATE_DENIED)
        && (g_ahci_issue_plan_state == MMIO64_AHCI_ISSUE_PLAN_STATE_READY_NO_ISSUE)
        && (g_ahci_issue_plan_stage_count != 0u)
        && (g_ahci_issue_plan_table_token == g_ahci_table_plan_token)
        && (g_ahci_issue_plan_policy_ready != 0u)
        && (g_ahci_issue_plan_slot_mask == 1u)
        && (g_ahci_issue_plan_ci_snapshot == 0u)
        && (g_ahci_issue_plan_slot_idle != 0u)
        && (g_ahci_issue_plan_tfd_ready != 0u)
        && (g_ahci_issue_plan_serr_clear != 0u)
        && (g_ahci_issue_plan_table_checksum == g_ahci_table_plan_checksum_after)
        && (g_ahci_issue_plan_expected_table_checksum
            == g_ahci_table_plan_checksum_after)
        && (g_ahci_issue_plan_checksum_match != 0u)
        && (g_ahci_issue_plan_dma_mapped == 0u)
        && (g_ahci_issue_plan_port_programmed == 0u)
        && (g_ahci_issue_plan_command_issued == 0u)
        && (g_ahci_issue_plan_armed == 0u)
        && (g_ahci_table_plan_dma_mapped == 0u)
        && (g_ahci_table_plan_port_programmed == 0u)
        && (g_ahci_table_plan_issued == 0u)
        && (g_ahci_table_plan_armed == 0u))
    {
        grant_ready = 1u;
    }

    if ((command_issue_ready != 0u)
        && ((flags & MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_DRIVER_CAP_BOUND) != 0u)
        && (owner_bound != 0u)
        && (query_only != 0u)
        && (grant_ready != 0u))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_GRANT_POLICY_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_ISSUE_GRANT_DENIED
            | MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_POLICY_DENIED;
    }

    g_ahci_driver_read_status_issue_grant_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_status_issue_grant_unavailable_count;
        g_ahci_driver_read_status_issue_grant_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_issue_grant_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_issue_grant_state =
        MMIO64_AHCI_DRIVER_READ_STATUS_ISSUE_GRANT_STATE_DENIED;
    g_ahci_driver_read_status_issue_grant_token =
        mmio64_make_driver_read_status_issue_grant_token();
    ++g_ahci_driver_read_status_issue_grant_stage_count;
    return g_ahci_driver_read_status_issue_grant_token;
}

