            return (g_ahci_driver_read_status_arm_flags & MMIO64_AHCI_DRIVER_READ_STATUS_ARM_FLAG_DRIVER_QUERY_ONLY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_BUFFER_CHECKSUM:
            return arm_denied ? g_ahci_driver_read_status_export_buffer_checksum : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_ISSUE_GRANT_BOUND:
            return (g_ahci_driver_read_status_arm_flags & MMIO64_AHCI_DRIVER_READ_STATUS_ARM_FLAG_ISSUE_GRANT_TOKEN_BOUND) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_ARM_READY:
            return (g_ahci_driver_read_status_arm_flags & MMIO64_AHCI_DRIVER_READ_STATUS_ARM_FLAG_ARM_PREFLIGHT_READY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_ARM_REQUESTED:
            return (g_ahci_driver_read_status_arm_flags & MMIO64_AHCI_DRIVER_READ_STATUS_ARM_FLAG_ARM_REQUESTED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_ARM_GRANTED:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_ARM_DENIED:
            return arm_denied;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_PORT:
            return arm_denied ? g_ahci_driver_read_status_export_port : MMIO64_INVALID_RESULT;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_KIND:
            return arm_denied ? g_ahci_driver_read_status_export_kind : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_READ_OPERATION:
            return arm_denied ? g_ahci_driver_read_status_export_read_operation : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_READ_LBA:
