        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_READ_BYTES:
            return arm_denied ? g_ahci_driver_read_status_export_read_bytes : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_PAGE_BYTES:
            return arm_denied ? MMIO64_PAGE_BYTES : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_CI:
            return arm_denied ? g_ahci_issue_plan_ci_snapshot : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_SLOT_MASK:
            return arm_denied ? g_ahci_issue_plan_slot_mask : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_SLOT_IDLE:
            return arm_denied ? g_ahci_issue_plan_slot_idle : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_TFD_READY:
            return arm_denied ? g_ahci_issue_plan_tfd_ready : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_SERR_CLEAR:
            return arm_denied ? g_ahci_issue_plan_serr_clear : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_TABLE_CHECKSUM:
            return arm_denied ? g_ahci_issue_plan_table_checksum : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_EXPECTED_CHECKSUM:
            return arm_denied ? g_ahci_issue_plan_expected_table_checksum : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_CHECKSUM_MATCH:
            return arm_denied ? g_ahci_issue_plan_checksum_match : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_ISSUE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_DMA_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_MEDIA_READ_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_WRITE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_COMMIT_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_BLOCK_ENDPOINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_BLOCK_CAP_MINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_FS_MINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_SAFETY_MASK:
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_MMIO_WRITE:
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_PORT_PROGRAM:
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_COMMAND_ISSUE:
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_DMA:
        case MMIO64_AHCI_DRIVER_READ_STATUS_ARM_TELEMETRY_MEDIA_READ:
