static u32 mmio64_driver_read_status_arm_denied_ready(
    u32 driver_read_status_arm_token)
{
    u32 required_flags = 0x3FFFFFFFu;

    if ((driver_read_status_arm_token == 0u)
        || (driver_read_status_arm_token == MMIO64_INVALID_RESULT)
        || (driver_read_status_arm_token
            != g_ahci_driver_read_status_arm_token))
    {
        return 0u;
    }
    if (g_ahci_driver_read_status_arm_state
        != MMIO64_AHCI_DRIVER_READ_STATUS_ARM_STATE_DENIED)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_status_arm_flags & required_flags)
        != required_flags)
    {
        return 0u;
    }
    if (g_ahci_driver_read_status_arm_stage_count == 0u)
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_status_exec(
    u32 driver_capability_handle,
    u32 driver_read_status_arm_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags = 0x3FFFFFFFu;
    u32 arm_ready;
    u32 owner_bound = 0u;
    u32 query_only = 0u;
    u32 exec_ready = 0u;
    u32 expected_owner = g_ahci_driver_read_status_export_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_status_exec_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_status_exec();
    flags = MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_EXEC_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_ISSUE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_DMA_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_MEDIA_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_QUEUE_DEQUEUE
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_WORKER_ADMIT
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_WORKER_WAKE
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_WORKER_RUNNABLE
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_WORKER_SCHEDULE
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_WORKER_RUN
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_WORKER_EXECUTE
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_NO_MEDIA_READ;

    arm_ready = mmio64_driver_read_status_arm_denied_ready(
        driver_read_status_arm_token);
    if (arm_ready != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_ARM_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_ARM_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_READ_SHAPE_BOUND;
    }

    if ((arm_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle
            == g_ahci_driver_read_status_export_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_DRIVER_CAP_BOUND;
    }

    if ((arm_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE))
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_status_export_driver_owner))
        {
            owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_DRIVER_OWNER_BOUND;
        }

        if ((owner_bound != 0u)
            && (capability64_rights(driver_capability_handle, owner_id)
                == CAPABILITY64_RIGHT_QUERY))
        {
            query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    if ((g_ahci_driver_read_status_arm_state
            == MMIO64_AHCI_DRIVER_READ_STATUS_ARM_STATE_DENIED)
        && ((g_ahci_driver_read_status_arm_flags
            & MMIO64_AHCI_DRIVER_READ_STATUS_ARM_FLAG_ARM_DENIED) != 0u)
        && (g_ahci_issue_plan_state == MMIO64_AHCI_ISSUE_PLAN_STATE_READY_NO_ISSUE)
        && (g_ahci_issue_plan_stage_count != 0u)
        && (g_ahci_issue_plan_table_token == g_ahci_table_plan_token)
        && (g_ahci_issue_plan_policy_ready != 0u)
        && (g_ahci_issue_plan_slot_mask == 1u)
        && (g_ahci_issue_plan_ci_snapshot == 0u)
        && (g_ahci_issue_plan_slot_idle != 0u)
        && (g_ahci_issue_plan_tfd_ready != 0u)
        && (g_ahci_issue_plan_serr_clear != 0u)
        && (g_ahci_issue_plan_table_checksum == g_ahci_table_plan_checksum_after)
        && (g_ahci_issue_plan_expected_table_checksum
            == g_ahci_table_plan_checksum_after)
        && (g_ahci_issue_plan_checksum_match != 0u)
        && (g_ahci_issue_plan_dma_mapped == 0u)
        && (g_ahci_issue_plan_port_programmed == 0u)
        && (g_ahci_issue_plan_command_issued == 0u)
        && (g_ahci_issue_plan_armed == 0u)
        && (g_ahci_table_plan_dma_mapped == 0u)
        && (g_ahci_table_plan_port_programmed == 0u)
        && (g_ahci_table_plan_issued == 0u)
        && (g_ahci_table_plan_armed == 0u))
    {
        exec_ready = 1u;
    }

    if ((arm_ready != 0u)
        && ((flags & MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_DRIVER_CAP_BOUND) != 0u)
        && (owner_bound != 0u)
        && (query_only != 0u)
        && (exec_ready != 0u))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_EXEC_PREFLIGHT_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_EXEC_DENIED
            | MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_POLICY_DENIED;
    }

    g_ahci_driver_read_status_exec_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_status_exec_unavailable_count;
        g_ahci_driver_read_status_exec_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_exec_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_exec_state =
        MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_STATE_DENIED;
    g_ahci_driver_read_status_exec_token =
        mmio64_make_driver_read_status_exec_token();
    ++g_ahci_driver_read_status_exec_stage_count;
    return g_ahci_driver_read_status_exec_token;
}

u32 mmio64_ahci_driver_read_status_exec_telemetry(u32 selector)
{
    u32 exec_denied =
        (g_ahci_driver_read_status_exec_flags
            & MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_EXEC_DENIED)
        ? 1u : 0u;

    switch (selector)
    {
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_STATE:
            return g_ahci_driver_read_status_exec_state;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_FLAGS:
            return g_ahci_driver_read_status_exec_flags;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_DRIVER_OWNER:
            return g_ahci_driver_read_status_export_driver_owner;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_QUERY_ONLY:
            return (g_ahci_driver_read_status_exec_flags & MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_DRIVER_QUERY_ONLY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_BUFFER_CHECKSUM:
            return exec_denied ? g_ahci_driver_read_status_export_buffer_checksum : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_ARM_BOUND:
            return (g_ahci_driver_read_status_exec_flags & MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_ARM_TOKEN_BOUND) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_EXEC_READY:
            return (g_ahci_driver_read_status_exec_flags & MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_EXEC_PREFLIGHT_READY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_EXEC_REQUESTED:
            return (g_ahci_driver_read_status_exec_flags & MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_EXEC_REQUESTED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_EXEC_GRANTED:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_EXEC_DENIED:
            return exec_denied;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_PORT:
            return exec_denied ? g_ahci_driver_read_status_export_port : MMIO64_INVALID_RESULT;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_KIND:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_READ_OPERATION:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_READ_LBA:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_READ_BLOCKS:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_READ_BYTES:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_PAGE_BYTES:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_CI:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_SLOT_MASK:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_SLOT_IDLE:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_TFD_READY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_SERR_CLEAR:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_TABLE_CHECKSUM:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_EXPECTED_CHECKSUM:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_CHECKSUM_MATCH:
            return exec_denied
                ? mmio64_ahci_driver_read_status_arm_telemetry(selector)
                : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_ISSUE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_DMA_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_MEDIA_READ_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_WRITE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_COMMIT_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_BLOCK_ENDPOINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_BLOCK_CAP_MINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_FS_MINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_SAFETY_MASK:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_MMIO_WRITE:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_PORT_PROGRAM:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_COMMAND_ISSUE:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_DMA:
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_MEDIA_READ:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_BUFFER_UNCHANGED:
            return (g_ahci_driver_read_status_exec_flags & MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_BUFFER_UNCHANGED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_STAGE_COUNT:
            return g_ahci_driver_read_status_exec_stage_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_DENIAL_COUNT:
            return g_ahci_driver_read_status_exec_denial_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_TELEMETRY_UNAVAILABLE_COUNT:
            return g_ahci_driver_read_status_exec_unavailable_count;
        default:
            return 0u;
    }
}

static u32 mmio64_driver_read_status_exec_denied_ready(
    u32 driver_read_status_exec_token)
{
    u32 required_flags = 0x3FFFFFFFu;

    if ((driver_read_status_exec_token == 0u)
        || (driver_read_status_exec_token == MMIO64_INVALID_RESULT)
        || (driver_read_status_exec_token
            != g_ahci_driver_read_status_exec_token))
    {
        return 0u;
    }
    if (g_ahci_driver_read_status_exec_state
        != MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_STATE_DENIED)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_status_exec_flags & required_flags)
        != required_flags)
    {
        return 0u;
    }
    if (g_ahci_driver_read_status_exec_stage_count == 0u)
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_status_dma(
    u32 driver_capability_handle,
    u32 driver_read_status_exec_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags = 0x3FFFFFFFu;
    u32 exec_ready;
    u32 owner_bound = 0u;
    u32 query_only = 0u;
    u32 dma_ready = 0u;
    u32 expected_owner = g_ahci_driver_read_status_export_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_status_dma_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_status_dma();
    flags = MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_DMA_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_ISSUE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_DMA_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_MEDIA_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_QUEUE_DEQUEUE
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_WORKER_ADMIT
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_WORKER_WAKE
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_WORKER_RUNNABLE
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_WORKER_SCHEDULE
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_WORKER_RUN
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_WORKER_EXECUTE
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_MMIO_WRITES
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_PORT_WRITES
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_NO_MEDIA_READ;

    exec_ready = mmio64_driver_read_status_exec_denied_ready(
        driver_read_status_exec_token);
    if (exec_ready != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_EXEC_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_EXEC_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_READ_SHAPE_BOUND;
    }

    if ((exec_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle
            == g_ahci_driver_read_status_export_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_DRIVER_CAP_BOUND;
    }

    if ((exec_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE))
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_status_export_driver_owner))
        {
            owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_DRIVER_OWNER_BOUND;
        }

        if ((owner_bound != 0u)
            && (capability64_rights(driver_capability_handle, owner_id)
                == CAPABILITY64_RIGHT_QUERY))
        {
            query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    if ((g_ahci_driver_read_status_exec_state
            == MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_STATE_DENIED)
        && ((g_ahci_driver_read_status_exec_flags
            & MMIO64_AHCI_DRIVER_READ_STATUS_EXEC_FLAG_EXEC_DENIED) != 0u)
        && (g_ahci_issue_plan_state == MMIO64_AHCI_ISSUE_PLAN_STATE_READY_NO_ISSUE)
        && (g_ahci_issue_plan_stage_count != 0u)
        && (g_ahci_issue_plan_table_token == g_ahci_table_plan_token)
        && (g_ahci_issue_plan_policy_ready != 0u)
        && (g_ahci_issue_plan_slot_mask == 1u)
        && (g_ahci_issue_plan_ci_snapshot == 0u)
        && (g_ahci_issue_plan_slot_idle != 0u)
        && (g_ahci_issue_plan_tfd_ready != 0u)
        && (g_ahci_issue_plan_serr_clear != 0u)
        && (g_ahci_issue_plan_table_checksum == g_ahci_table_plan_checksum_after)
        && (g_ahci_issue_plan_expected_table_checksum
            == g_ahci_table_plan_checksum_after)
        && (g_ahci_issue_plan_checksum_match != 0u)
        && (g_ahci_issue_plan_dma_mapped == 0u)
        && (g_ahci_issue_plan_port_programmed == 0u)
        && (g_ahci_issue_plan_command_issued == 0u)
        && (g_ahci_issue_plan_armed == 0u)
        && (g_ahci_table_plan_dma_mapped == 0u)
        && (g_ahci_table_plan_port_programmed == 0u)
        && (g_ahci_table_plan_issued == 0u)
        && (g_ahci_table_plan_armed == 0u))
    {
        dma_ready = 1u;
    }

    if ((exec_ready != 0u)
        && ((flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_DRIVER_CAP_BOUND) != 0u)
        && (owner_bound != 0u)
        && (query_only != 0u)
        && (dma_ready != 0u))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_DMA_PREFLIGHT_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_DMA_DENIED
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_POLICY_DENIED;
    }

    g_ahci_driver_read_status_dma_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_status_dma_unavailable_count;
        g_ahci_driver_read_status_dma_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_DMA_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_dma_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_dma_state =
        MMIO64_AHCI_DRIVER_READ_STATUS_DMA_STATE_DENIED;
    g_ahci_driver_read_status_dma_token =
        mmio64_make_driver_read_status_dma_token();
    ++g_ahci_driver_read_status_dma_stage_count;
    return g_ahci_driver_read_status_dma_token;
}

u32 mmio64_ahci_driver_read_status_dma_telemetry(u32 selector)
{
    u32 dma_denied =
        (g_ahci_driver_read_status_dma_flags
            & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_DMA_DENIED)
        ? 1u : 0u;

    switch (selector)
    {
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_STATE:
            return g_ahci_driver_read_status_dma_state;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_FLAGS:
            return g_ahci_driver_read_status_dma_flags;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_DRIVER_OWNER:
            return g_ahci_driver_read_status_export_driver_owner;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_QUERY_ONLY:
            return (g_ahci_driver_read_status_dma_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_DRIVER_QUERY_ONLY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_BUFFER_CHECKSUM:
            return dma_denied ? g_ahci_driver_read_status_export_buffer_checksum : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_EXEC_BOUND:
            return (g_ahci_driver_read_status_dma_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_EXEC_TOKEN_BOUND) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_DMA_READY:
            return (g_ahci_driver_read_status_dma_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_DMA_PREFLIGHT_READY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_DMA_REQUESTED:
            return (g_ahci_driver_read_status_dma_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_DMA_REQUESTED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_DMA_GRANTED:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_DMA_DENIED:
            return dma_denied;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_PORT:
            return dma_denied ? g_ahci_driver_read_status_export_port : MMIO64_INVALID_RESULT;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_KIND:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_READ_OPERATION:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_READ_LBA:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_READ_BLOCKS:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_READ_BYTES:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_PAGE_BYTES:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_CI:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_SLOT_MASK:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_SLOT_IDLE:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_TFD_READY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_SERR_CLEAR:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_TABLE_CHECKSUM:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_EXPECTED_CHECKSUM:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_CHECKSUM_MATCH:
            return dma_denied
                ? mmio64_ahci_driver_read_status_exec_telemetry(selector)
                : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_ISSUE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_DMA_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_MEDIA_READ_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_WRITE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_COMMIT_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_BLOCK_ENDPOINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_BLOCK_CAP_MINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_FS_MINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_SAFETY_MASK:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_MMIO_WRITE:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_PORT_PROGRAM:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_COMMAND_ISSUE:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_DMA:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_MEDIA_READ:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_BUFFER_UNCHANGED:
            return (g_ahci_driver_read_status_dma_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_BUFFER_UNCHANGED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_STAGE_COUNT:
            return g_ahci_driver_read_status_dma_stage_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_DENIAL_COUNT:
            return g_ahci_driver_read_status_dma_denial_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_TELEMETRY_UNAVAILABLE_COUNT:
            return g_ahci_driver_read_status_dma_unavailable_count;
        default:
            return 0u;
    }
}

static u32 mmio64_driver_read_status_dma_denied_ready(
    u32 driver_read_status_dma_token)
{
    u32 required_flags = 0x3FFFFFFFu;

    if ((driver_read_status_dma_token == 0u)
        || (driver_read_status_dma_token == MMIO64_INVALID_RESULT)
        || (driver_read_status_dma_token
            != g_ahci_driver_read_status_dma_token))
    {
        return 0u;
    }
    if (g_ahci_driver_read_status_dma_state
        != MMIO64_AHCI_DRIVER_READ_STATUS_DMA_STATE_DENIED)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_status_dma_flags & required_flags)
        != required_flags)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_status_dma_flags
            & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_FLAG_DMA_DENIED) == 0u)
    {
        return 0u;
    }
    if (g_ahci_driver_read_status_dma_stage_count == 0u)
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_status_mmio(
    u32 driver_capability_handle,
    u32 driver_read_status_dma_token,
    u32 owner_id)
{
    volatile u32 *registers;
    u32 flags;
    u32 required_flags = 0x3FF7FFFFu;
    u32 dma_ready;
    u32 owner_bound = 0u;
    u32 query_only = 0u;
    u32 write_ready = 0u;
    u32 expected_owner = g_ahci_driver_read_status_export_driver_owner;
    u32 port_base = 0u;
    u32 pxis_offset = 0u;
    u32 pxis_page = 0u;
    u32 write_window_open = 0u;
    u32 write_window_closed = 0u;
    u32 current_dma_token = g_ahci_driver_read_status_dma_token;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_status_mmio_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if ((current_dma_token != 0u)
        && (current_dma_token != MMIO64_INVALID_RESULT)
        && (driver_read_status_dma_token != current_dma_token))
    {
        ++g_ahci_driver_read_status_mmio_denial_count;
        ++g_ahci_driver_read_status_mmio_stale_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_status_mmio();
    flags = MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_WRITE_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_NO_ISSUE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_NO_DMA_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_NO_MEDIA_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_NO_BLOCK_CAP_MINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_NO_COMMANDS;

    if (g_ahci_driver_read_status_mmio_stale_denial_count != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_STALE_DENIED;
    }

    dma_ready = mmio64_driver_read_status_dma_denied_ready(
        driver_read_status_dma_token);
    if (dma_ready != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_DMA_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_DMA_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_READ_SHAPE_BOUND;
    }

    if ((dma_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle
            == g_ahci_driver_read_status_export_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_DRIVER_CAP_BOUND;
    }

    if ((dma_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE))
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_status_export_driver_owner))
        {
            owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_DRIVER_OWNER_BOUND;
        }

        if ((owner_bound != 0u)
            && (capability64_rights(driver_capability_handle, owner_id)
                == CAPABILITY64_RIGHT_QUERY))
        {
            query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    if ((dma_ready != 0u)
        && ((flags & MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_DRIVER_CAP_BOUND) != 0u)
        && (owner_bound != 0u)
        && (query_only != 0u)
        && (g_ahci_issue_plan_state == MMIO64_AHCI_ISSUE_PLAN_STATE_READY_NO_ISSUE)
        && (g_ahci_issue_plan_stage_count != 0u)
        && (g_ahci_issue_plan_table_token == g_ahci_table_plan_token)
        && (g_ahci_issue_plan_policy_ready != 0u)
        && (g_ahci_issue_plan_slot_mask == 1u)
        && (g_ahci_issue_plan_ci_snapshot == 0u)
        && (g_ahci_issue_plan_slot_idle != 0u)
        && (g_ahci_issue_plan_tfd_ready != 0u)
        && (g_ahci_issue_plan_serr_clear != 0u)
        && (g_ahci_issue_plan_table_checksum == g_ahci_table_plan_checksum_after)
        && (g_ahci_issue_plan_expected_table_checksum
            == g_ahci_table_plan_checksum_after)
        && (g_ahci_issue_plan_checksum_match != 0u)
        && (g_ahci_issue_plan_dma_mapped == 0u)
        && (g_ahci_issue_plan_port_programmed == 0u)
        && (g_ahci_issue_plan_command_issued == 0u)
        && (g_ahci_issue_plan_armed == 0u)
        && (g_ahci_table_plan_dma_mapped == 0u)
        && (g_ahci_table_plan_port_programmed == 0u)
        && (g_ahci_table_plan_issued == 0u)
        && (g_ahci_table_plan_armed == 0u)
        && (g_ahci_map_virtual_base != 0ull))
    {
        port_base = mmio64_ahci_port_offset(
            g_ahci_driver_read_status_export_port,
            0u);
        pxis_offset = port_base + MMIO64_AHCI_PORT_IS_OFFSET;
        if (mmio64_register_fits_span(pxis_offset))
        {
            pxis_page = pxis_offset / MMIO64_PAGE_BYTES;
            write_ready = 1u;
        }
    }

    if ((write_ready != 0u) && (mmio64_activate_ahci_mapping() == 0u))
    {
        write_ready = 0u;
    }

    if (write_ready != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_MMIO_PREFLIGHT_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_POLICY_GRANTED
            | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_EXACT_REGISTER
            | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_EXACT_VALUE;
        g_ahci_driver_read_status_mmio_register_offset = pxis_offset;
        g_ahci_driver_read_status_mmio_write_value = 0u;
        registers = (volatile u32 *)(u64)g_ahci_map_virtual_base;
        write_window_open = paging64_kernel_mmio_write_window_open(pxis_page);
        if (write_window_open != 0u)
        {
            g_ahci_driver_read_status_mmio_pxis_before =
                registers[pxis_offset / sizeof(u32)];
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_PXIS_READ_BEFORE;
            registers[pxis_offset / sizeof(u32)] = 0u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_WRITE_GRANTED
                | MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_PXIS_WRITE;
            write_window_closed =
                paging64_kernel_mmio_write_window_close(pxis_page);
            if (write_window_closed != 0u)
            {
                g_ahci_driver_read_status_mmio_pxis_after =
                    registers[pxis_offset / sizeof(u32)];
                flags |= MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_PXIS_READ_AFTER;
                if (g_ahci_driver_read_status_mmio_pxis_before
                    == g_ahci_driver_read_status_mmio_pxis_after)
                {
                    flags |=
                        MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_PXIS_UNCHANGED;
                }
                flags |=
                    MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_TEARDOWN_COMPLETE;
            }
        }
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_ROLLBACK_NOT_REQUIRED;
    }

    g_ahci_driver_read_status_mmio_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_status_mmio_unavailable_count;
        g_ahci_driver_read_status_mmio_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_mmio_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_mmio_state =
        MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_STATE_WRITTEN;
    g_ahci_driver_read_status_mmio_token =
        mmio64_make_driver_read_status_mmio_token();
    ++g_ahci_driver_read_status_mmio_stage_count;
    return g_ahci_driver_read_status_mmio_token;
}

u32 mmio64_ahci_driver_read_status_mmio_telemetry(u32 selector)
{
    u32 mmio_written =
        ((g_ahci_driver_read_status_mmio_state
            == MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_STATE_WRITTEN)
        && ((g_ahci_driver_read_status_mmio_flags
            & MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_PXIS_WRITE) != 0u))
        ? 1u : 0u;

    switch (selector)
    {
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_STATE:
            return g_ahci_driver_read_status_mmio_state;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_FLAGS:
            return g_ahci_driver_read_status_mmio_flags;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_DRIVER_OWNER:
            return g_ahci_driver_read_status_export_driver_owner;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_QUERY_ONLY:
            return (g_ahci_driver_read_status_mmio_flags & MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_DRIVER_QUERY_ONLY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_BUFFER_CHECKSUM:
            return mmio_written ? g_ahci_driver_read_status_export_buffer_checksum : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_DMA_BOUND:
            return (g_ahci_driver_read_status_mmio_flags & MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_DMA_TOKEN_BOUND) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_MMIO_READY:
            return (g_ahci_driver_read_status_mmio_flags & MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_MMIO_PREFLIGHT_READY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_WRITE_REQUESTED:
            return (g_ahci_driver_read_status_mmio_flags & MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_WRITE_REQUESTED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_WRITE_GRANTED:
            return (g_ahci_driver_read_status_mmio_flags & MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_WRITE_GRANTED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_WRITE_DENIED:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_PORT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_KIND:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_READ_OPERATION:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_READ_LBA:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_READ_BLOCKS:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_READ_BYTES:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_PAGE_BYTES:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_CI:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_SLOT_MASK:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_SLOT_IDLE:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_TFD_READY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_SERR_CLEAR:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_TABLE_CHECKSUM:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_EXPECTED_CHECKSUM:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_CHECKSUM_MATCH:
            return mmio_written
                ? mmio64_ahci_driver_read_status_dma_telemetry(selector)
                : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_REGISTER_OFFSET:
            return mmio_written
                ? g_ahci_driver_read_status_mmio_register_offset
                : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_WRITE_VALUE:
            return mmio_written
                ? g_ahci_driver_read_status_mmio_write_value
                : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_PXIS_BEFORE:
            return mmio_written
                ? g_ahci_driver_read_status_mmio_pxis_before
                : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_PXIS_AFTER:
            return mmio_written
                ? g_ahci_driver_read_status_mmio_pxis_after
                : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_PXIS_UNCHANGED:
            return (g_ahci_driver_read_status_mmio_flags & MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_PXIS_UNCHANGED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_ROLLBACK_REQUIRED:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_ROLLBACK_DONE:
            return (g_ahci_driver_read_status_mmio_flags & MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_ROLLBACK_NOT_REQUIRED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_TEARDOWN:
            return (g_ahci_driver_read_status_mmio_flags & MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_TEARDOWN_COMPLETE) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_STALE_DENIED:
            return (g_ahci_driver_read_status_mmio_stale_denial_count != 0u) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_ISSUE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_DMA_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_MEDIA_READ_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_WRITE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_COMMIT_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_BLOCK_ENDPOINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_BLOCK_CAP_MINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_FS_MINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_SAFETY_MASK:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_PORT_PROGRAM:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_COMMAND_ISSUE:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_DMA:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_MEDIA_READ:
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_MEDIA_WRITE:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_MMIO_WRITE:
            return mmio_written;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_BUFFER_UNCHANGED:
            return (g_ahci_driver_read_status_mmio_flags & MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_BUFFER_UNCHANGED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_STAGE_COUNT:
            return g_ahci_driver_read_status_mmio_stage_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_DENIAL_COUNT:
            return g_ahci_driver_read_status_mmio_denial_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_TELEMETRY_UNAVAILABLE_COUNT:
            return g_ahci_driver_read_status_mmio_unavailable_count;
        default:
            return 0u;
    }
}

static u32 mmio64_driver_read_status_mmio_written_ready(
    u32 driver_read_status_mmio_token)
{
    u32 required_flags = 0x3FF7FFFFu;

    if ((driver_read_status_mmio_token == 0u)
        || (driver_read_status_mmio_token == MMIO64_INVALID_RESULT)
        || (driver_read_status_mmio_token
            != g_ahci_driver_read_status_mmio_token))
    {
        return 0u;
    }
    if (g_ahci_driver_read_status_mmio_state
        != MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_STATE_WRITTEN)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_status_mmio_flags & required_flags)
        != required_flags)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_status_mmio_flags
            & MMIO64_AHCI_DRIVER_READ_STATUS_MMIO_FLAG_PXIS_WRITE) == 0u)
    {
        return 0u;
    }
    if (g_ahci_driver_read_status_mmio_stage_count == 0u)
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_status_dma_window(
    u32 driver_capability_handle,
    u32 driver_read_status_mmio_token,
    u32 owner_id)
{
    u64 page_physical;
    u64 page_end;
    u64 bounce_physical;
    u64 bounce_end;
    u32 flags;
    u32 required_flags = 0x3FFFFFFFu;
    u32 mmio_ready;
    u32 owner_bound = 0u;
    u32 query_only = 0u;
    u32 window_ready = 0u;
    u32 expected_owner = g_ahci_driver_read_status_export_driver_owner;
    u32 current_mmio_token = g_ahci_driver_read_status_mmio_token;
    u32 range_end = 0u;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_status_dma_window_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if ((current_mmio_token != 0u)
        && (current_mmio_token != MMIO64_INVALID_RESULT)
        && (driver_read_status_mmio_token != current_mmio_token))
    {
        ++g_ahci_driver_read_status_dma_window_denial_count;
        ++g_ahci_driver_read_status_dma_window_stale_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_status_dma_window();
    flags = MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_REVOCATION_REQUIRED
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_NO_ISSUE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_NO_DMA_EXECUTION
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_NO_MEDIA_BYTES
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_NO_BLOCK_STORAGE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_BUFFER_UNCHANGED
        | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_NO_COMMANDS;

    if (g_ahci_driver_read_status_dma_window_stale_denial_count != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_STALE_DENIED;
    }

    mmio_ready = mmio64_driver_read_status_mmio_written_ready(
        driver_read_status_mmio_token);
    if (mmio_ready != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_MMIO_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_MMIO_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_READ_SHAPE_BOUND;
    }

    if ((mmio_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle
            == g_ahci_driver_read_status_export_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_DRIVER_CAP_BOUND;
    }

    if ((mmio_ready != 0u)
        && (driver_capability_handle != CAPABILITY64_INVALID_HANDLE))
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_status_export_driver_owner))
        {
            owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_DRIVER_OWNER_BOUND;
        }

        if ((owner_bound != 0u)
            && (capability64_rights(driver_capability_handle, owner_id)
                == CAPABILITY64_RIGHT_QUERY))
        {
            query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    page_physical = g_ahci_memory_plan_page_physical;
    range_end =
        g_ahci_memory_plan_bounce_offset + g_ahci_memory_plan_bounce_bytes;
    page_end = page_physical + (u64)MMIO64_PAGE_BYTES;
    bounce_physical =
        page_physical + (u64)g_ahci_memory_plan_bounce_offset;
    bounce_end =
        bounce_physical + (u64)g_ahci_memory_plan_bounce_bytes;

    if ((mmio_ready != 0u)
        && ((flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_DRIVER_CAP_BOUND) != 0u)
        && (owner_bound != 0u)
        && (query_only != 0u)
        && (g_ahci_memory_plan_state == MMIO64_AHCI_MEM_PLAN_STATE_STAGED_NO_DMA)
        && (g_ahci_memory_plan_page_count == 1u)
        && (g_ahci_memory_plan_page_bytes == MMIO64_PAGE_BYTES)
        && (g_ahci_memory_plan_page_materialized != 0u)
        && (g_ahci_memory_plan_bounce_offset == MMIO64_AHCI_BOUNCE_BUFFER_OFFSET)
        && (g_ahci_memory_plan_bounce_bytes
            == g_ahci_driver_read_status_export_read_bytes)
        && (g_ahci_memory_plan_bounce_bytes
            == MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES)
        && (range_end <= MMIO64_PAGE_BYTES)
        && (bounce_physical >= page_physical)
        && (bounce_end <= page_end)
        && (page_end <= 0x100000000ull)
        && (g_ahci_memory_plan_command_list_bytes
            <= g_ahci_memory_plan_bounce_offset)
        && ((g_ahci_memory_plan_command_table_offset
                + g_ahci_memory_plan_command_table_bytes)
            <= g_ahci_memory_plan_bounce_offset)
        && ((g_ahci_memory_plan_prdt_offset + g_ahci_memory_plan_prdt_bytes)
            <= g_ahci_memory_plan_bounce_offset)
        && (g_ahci_issue_plan_state == MMIO64_AHCI_ISSUE_PLAN_STATE_READY_NO_ISSUE)
        && (g_ahci_issue_plan_stage_count != 0u)
        && (g_ahci_issue_plan_table_token == g_ahci_table_plan_token)
        && (g_ahci_issue_plan_policy_ready != 0u)
        && (g_ahci_issue_plan_slot_mask == 1u)
        && (g_ahci_issue_plan_ci_snapshot == 0u)
        && (g_ahci_issue_plan_slot_idle != 0u)
        && (g_ahci_issue_plan_tfd_ready != 0u)
        && (g_ahci_issue_plan_serr_clear != 0u)
        && (g_ahci_issue_plan_dma_mapped == 0u)
        && (g_ahci_issue_plan_port_programmed == 0u)
        && (g_ahci_issue_plan_command_issued == 0u)
        && (g_ahci_issue_plan_armed == 0u)
        && (g_ahci_table_plan_dma_mapped == 0u)
        && (g_ahci_table_plan_port_programmed == 0u)
        && (g_ahci_table_plan_issued == 0u)
        && (g_ahci_table_plan_armed == 0u))
    {
        window_ready = 1u;
    }

    if (window_ready != 0u)
    {
        g_ahci_driver_read_status_dma_window_page_low = (u32)page_physical;
        g_ahci_driver_read_status_dma_window_page_high =
            (u32)(page_physical >> 32);
        g_ahci_driver_read_status_dma_window_bounce_low =
            (u32)bounce_physical;
        g_ahci_driver_read_status_dma_window_bounce_high =
            (u32)(bounce_physical >> 32);
        g_ahci_driver_read_status_dma_window_bounce_bytes =
            g_ahci_memory_plan_bounce_bytes;
        g_ahci_driver_read_status_dma_window_bounce_offset =
            g_ahci_memory_plan_bounce_offset;
        g_ahci_driver_read_status_dma_window_range_end = range_end;
        g_ahci_driver_read_status_dma_window_active = 1u;
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_SINGLE_PAGE
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_BROKER_OWNED
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_BOUNCE_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_BOUNDS_ENFORCED
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_PHYSICAL_CONFINED
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_BELOW_4G
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_IDENTITY_DMA_ASSUMED
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_IOMMU_NOT_CONFIGURED
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_NON_USER_MAPPED
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_NO_UNCONTROLLED_ALIAS
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_LIFETIME_STARTED;
        g_ahci_driver_read_status_dma_window_active = 0u;
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_LIFETIME_CLOSED
            | MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_REVOCATION_DONE;
    }

    g_ahci_driver_read_status_dma_window_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_status_dma_window_unavailable_count;
        g_ahci_driver_read_status_dma_window_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_dma_window_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_dma_window_state =
        MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_STATE_OPENED_CLOSED;
    g_ahci_driver_read_status_dma_window_token =
        mmio64_make_driver_read_status_dma_window_token();
    ++g_ahci_driver_read_status_dma_window_stage_count;
    return g_ahci_driver_read_status_dma_window_token;
}

u32 mmio64_ahci_driver_read_status_dma_window_telemetry(u32 selector)
{
    u32 window_ready =
        ((g_ahci_driver_read_status_dma_window_state
            == MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_STATE_OPENED_CLOSED)
        && ((g_ahci_driver_read_status_dma_window_flags
            & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_LIFETIME_CLOSED) != 0u))
        ? 1u : 0u;

    switch (selector)
    {
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_STATE:
            return g_ahci_driver_read_status_dma_window_state;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_FLAGS:
            return g_ahci_driver_read_status_dma_window_flags;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_DRIVER_OWNER:
            return g_ahci_driver_read_status_export_driver_owner;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_QUERY_ONLY:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_DRIVER_QUERY_ONLY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_BUFFER_CHECKSUM:
            return window_ready ? g_ahci_driver_read_status_export_buffer_checksum : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_MMIO_BOUND:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_MMIO_TOKEN_BOUND) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_WINDOW_READY:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_BOUNCE_BOUND) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_WINDOW_REQUESTED:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_REQUESTED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_WINDOW_GRANTED:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_LIFETIME_STARTED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_WINDOW_DENIED:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_PORT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_KIND:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_READ_OPERATION:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_READ_LBA:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_READ_BLOCKS:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_READ_BYTES:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_PAGE_BYTES:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_CI:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_SLOT_MASK:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_SLOT_IDLE:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_TFD_READY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_SERR_CLEAR:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_TABLE_CHECKSUM:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_EXPECTED_CHECKSUM:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_CHECKSUM_MATCH:
            return window_ready
                ? mmio64_ahci_driver_read_status_mmio_telemetry(selector)
                : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_PAGE_LOW:
            return window_ready ? g_ahci_driver_read_status_dma_window_page_low : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_PAGE_HIGH:
            return window_ready ? g_ahci_driver_read_status_dma_window_page_high : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_BOUNCE_LOW:
            return window_ready ? g_ahci_driver_read_status_dma_window_bounce_low : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_BOUNCE_HIGH:
            return window_ready ? g_ahci_driver_read_status_dma_window_bounce_high : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_BOUNCE_BYTES:
            return window_ready ? g_ahci_driver_read_status_dma_window_bounce_bytes : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_BOUNCE_OFFSET:
            return window_ready ? g_ahci_driver_read_status_dma_window_bounce_offset : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_RANGE_END:
            return window_ready ? g_ahci_driver_read_status_dma_window_range_end : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_SINGLE_PAGE:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_SINGLE_PAGE) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_BROKER_OWNED:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_BROKER_OWNED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_BOUNDS_ENFORCED:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_BOUNDS_ENFORCED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_PHYSICAL_CONFINED:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_PHYSICAL_CONFINED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_BELOW_4G:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_BELOW_4G) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_IOMMU_CONFIGURED:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_IDENTITY_DMA_ASSUMED:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_IDENTITY_DMA_ASSUMED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_NON_USER_MAPPED:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_NON_USER_MAPPED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_ALIAS_SAFE:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_NO_UNCONTROLLED_ALIAS) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_LIFETIME_OPENED:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_LIFETIME_STARTED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_LIFETIME_CLOSED:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_LIFETIME_CLOSED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_ACTIVE:
            return g_ahci_driver_read_status_dma_window_active;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_REVOKE_REQUIRED:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_REVOCATION_REQUIRED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_REVOKE_DONE:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_REVOCATION_DONE) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_STALE_DENIED:
            return (g_ahci_driver_read_status_dma_window_stale_denial_count != 0u) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_ISSUE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_DMA_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_MEDIA_READ_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_WRITE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_COMMIT_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_BLOCK_ENDPOINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_BLOCK_CAP_MINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_FS_MINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_SAFETY_MASK:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_MMIO_WRITE:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_PORT_PROGRAM:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_COMMAND_ISSUE:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_DMA:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_MEDIA_READ:
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_MEDIA_WRITE:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_BUFFER_UNCHANGED:
            return (g_ahci_driver_read_status_dma_window_flags & MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_FLAG_BUFFER_UNCHANGED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_STAGE_COUNT:
            return g_ahci_driver_read_status_dma_window_stage_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_DENIAL_COUNT:
            return g_ahci_driver_read_status_dma_window_denial_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_TELEMETRY_UNAVAILABLE_COUNT:
            return g_ahci_driver_read_status_dma_window_unavailable_count;
        default:
            return 0u;
    }
}

static u32 mmio64_driver_read_status_dma_window_ready(
    u32 driver_read_status_dma_window_token)
{
    u32 required_flags = 0x3FFFFFFFu;

    if ((driver_read_status_dma_window_token == 0u)
        || (driver_read_status_dma_window_token == MMIO64_INVALID_RESULT)
        || (driver_read_status_dma_window_token
            != g_ahci_driver_read_status_dma_window_token))
    {
        return 0u;
    }
    if (g_ahci_driver_read_status_dma_window_state
        != MMIO64_AHCI_DRIVER_READ_STATUS_DMA_WINDOW_STATE_OPENED_CLOSED)
    {
        return 0u;
    }
    if ((g_ahci_driver_read_status_dma_window_flags & required_flags)
        != required_flags)
    {
        return 0u;
    }
    if (g_ahci_driver_read_status_dma_window_stage_count == 0u)
    {
        return 0u;
    }

    return 1u;
}

u32 mmio64_stage_ahci_driver_read_status_read(
    u32 driver_capability_handle,
    u32 driver_read_status_dma_window_token,
    u32 owner_id)
{
    volatile u32 *registers;
    u32 flags;
    u32 required_flags;
    u32 owner_bound = 0u;
    u32 query_only = 0u;
    u32 ready = 0u;
    u32 completed = 0u;
    u32 port_base;
    u32 port_page;
    u32 clb_index;
    u32 clbu_index;
    u32 fb_index;
    u32 fbu_index;
    u32 cmd_index;
    u32 is_index;
    u32 serr_index;
    u32 ci_index;
    u32 tfd_index;
    u32 command_table_physical_low;
    u32 command_table_physical_high;
    u32 receive_fis_low;
    u32 receive_fis_high;
    u32 header_patch_offset;
    u32 prdt_patch_offset;
    u32 table_offset;
    u32 bounce_offset;
    u32 bounce_bytes;
    u32 command;
    u32 poll;
    u32 ci;
    u32 tfd;
    u32 write_window_open = 0u;
    u32 write_window_closed = 0u;
    u32 expected_owner = g_ahci_driver_read_status_export_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_status_read_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if ((driver_read_status_dma_window_token == 0u)
        || (driver_read_status_dma_window_token == MMIO64_INVALID_RESULT))
    {
        mmio64_reset_driver_read_status_read();
        g_ahci_driver_read_status_read_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_READ_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_read_error = 1u;
        g_ahci_driver_read_status_read_flags =
            MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_REQUESTED
            | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_NO_WRITE_AUTHORITY
            | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_NO_COMMIT_AUTHORITY
            | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_NO_BLOCK_ENDPOINT
            | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_NO_FS_MINT
            | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_BUFFER_SEALED
            | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_UNAVAILABLE;
        ++g_ahci_driver_read_status_read_unavailable_count;
        return MMIO64_INVALID_RESULT;
    }

    if (driver_read_status_dma_window_token
        != g_ahci_driver_read_status_dma_window_token)
    {
        ++g_ahci_driver_read_status_read_denial_count;
        ++g_ahci_driver_read_status_read_stale_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_status_read();
    flags = MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_BUFFER_SEALED;

    if (mmio64_driver_read_status_dma_window_ready(
            driver_read_status_dma_window_token) != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DWIN_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DWIN_TOKEN_BOUND;
    }

    if ((driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle
            == g_ahci_driver_read_status_export_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DRIVER_CAP_BOUND;
    }

    if (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == g_ahci_driver_read_status_export_driver_owner))
        {
            owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DRIVER_OWNER_BOUND;
        }
        if ((owner_bound != 0u)
            && (capability64_rights(driver_capability_handle, owner_id)
                == CAPABILITY64_RIGHT_QUERY))
        {
            query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    bounce_offset = g_ahci_memory_plan_bounce_offset;
    bounce_bytes = g_ahci_memory_plan_bounce_bytes;
    if (((flags & (MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DWIN_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DRIVER_CAP_BOUND))
            == (MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DWIN_READY
                | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DRIVER_CAP_BOUND))
        && (owner_bound != 0u)
        && (query_only != 0u)
        && (g_ahci_driver_read_status_dma_window_bounce_bytes
            == MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES)
        && (bounce_bytes == MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES)
        && (bounce_offset == MMIO64_AHCI_BOUNCE_BUFFER_OFFSET)
        && (g_ahci_issue_plan_slot_mask == 1u)
        && (g_ahci_issue_plan_ci_snapshot == 0u)
        && (g_ahci_issue_plan_slot_idle != 0u)
        && (g_ahci_issue_plan_tfd_ready != 0u)
        && (g_ahci_issue_plan_serr_clear != 0u)
        && (g_ahci_driver_read_status_export_kind == MMIO64_PORT_DEVICE_ATAPI)
        && (g_ahci_driver_read_status_export_read_operation
            == MMIO64_AHCI_READ_OPERATION_ATAPI_READ_10)
        && (g_ahci_map_virtual_base != 0ull)
        && (g_ahci_map_installed != 0u))
    {
        ready = 1u;
    }

    g_ahci_driver_read_status_read_page_low =
        g_ahci_driver_read_status_dma_window_page_low;
    g_ahci_driver_read_status_read_page_high =
        g_ahci_driver_read_status_dma_window_page_high;
    g_ahci_driver_read_status_read_bounce_low =
        g_ahci_driver_read_status_dma_window_bounce_low;
    g_ahci_driver_read_status_read_bounce_high =
        g_ahci_driver_read_status_dma_window_bounce_high;

    if (ready == 0u)
    {
        ++g_ahci_driver_read_status_read_unavailable_count;
        g_ahci_driver_read_status_read_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_READ_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_read_error = 1u;
        g_ahci_driver_read_status_read_flags =
            flags | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    flags |= MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_ISSUE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DMA_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_MEDIA_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_BYTES_BOUNDED;

    header_patch_offset = g_ahci_memory_plan_command_header_offset + 8u;
    prdt_patch_offset = g_ahci_memory_plan_prdt_offset;
    table_offset = g_ahci_memory_plan_command_table_offset;
    command_table_physical_low =
        g_ahci_driver_read_status_read_page_low + table_offset;
    command_table_physical_high = g_ahci_driver_read_status_read_page_high;
    receive_fis_low =
        g_ahci_driver_read_status_read_page_low + MMIO64_AHCI_RECEIVE_FIS_OFFSET;
    receive_fis_high = g_ahci_driver_read_status_read_page_high;

    g_ahci_driver_read_status_read_table_before =
        mmio64_checksum_bytes((const u8 *)g_ahci_command_page, MMIO64_PAGE_BYTES);
    mmio64_zero_bytes(g_ahci_command_page + bounce_offset, bounce_bytes);
    mmio64_write_u32(
        g_ahci_command_page,
        g_ahci_memory_plan_command_header_offset,
        g_ahci_table_plan_header_flags | MMIO64_AHCI_COMMAND_HEADER_PREFETCHABLE);
    mmio64_write_u32(g_ahci_command_page, header_patch_offset, command_table_physical_low);
    mmio64_write_u32(g_ahci_command_page, header_patch_offset + 4u, command_table_physical_high);
    mmio64_write_u32(g_ahci_command_page, prdt_patch_offset, g_ahci_driver_read_status_read_bounce_low);
    mmio64_write_u32(g_ahci_command_page, prdt_patch_offset + 4u, g_ahci_driver_read_status_read_bounce_high);
    g_ahci_command_page[table_offset + 3u] = 1u;
    g_ahci_command_page[table_offset + 5u] =
        (u8)(MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES & 0xFFu);
    g_ahci_command_page[table_offset + 6u] =
        (u8)((MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES >> 8) & 0xFFu);
    g_ahci_driver_read_status_read_table_after =
        mmio64_checksum_bytes((const u8 *)g_ahci_command_page, MMIO64_PAGE_BYTES);
    flags |= MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_PRDT_PATCHED
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_CHECKSUM_RECORDED;

    registers = (volatile u32 *)(u64)g_ahci_map_virtual_base;
    port_base = mmio64_ahci_port_offset(g_ahci_issue_plan_port, 0u);
    port_page = port_base / MMIO64_PAGE_BYTES;
    clb_index = (port_base + MMIO64_AHCI_PORT_CLB_OFFSET) / sizeof(u32);
    clbu_index = (port_base + MMIO64_AHCI_PORT_CLBU_OFFSET) / sizeof(u32);
    fb_index = (port_base + MMIO64_AHCI_PORT_FB_OFFSET) / sizeof(u32);
    fbu_index = (port_base + MMIO64_AHCI_PORT_FBU_OFFSET) / sizeof(u32);
    cmd_index = (port_base + MMIO64_AHCI_PORT_CMD_OFFSET) / sizeof(u32);
    is_index = (port_base + MMIO64_AHCI_PORT_IS_OFFSET) / sizeof(u32);
    serr_index = (port_base + MMIO64_AHCI_PORT_SERR_OFFSET) / sizeof(u32);
    ci_index = (port_base + MMIO64_AHCI_PORT_CI_OFFSET) / sizeof(u32);
    tfd_index = (port_base + MMIO64_AHCI_PORT_TFD_OFFSET) / sizeof(u32);

    if (mmio64_activate_ahci_mapping() == 0u)
    {
        ++g_ahci_driver_read_status_read_unavailable_count;
        g_ahci_driver_read_status_read_error = 5u;
        g_ahci_driver_read_status_read_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_READ_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_read_flags =
            flags | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_read_ci_before = registers[ci_index];
    g_ahci_driver_read_status_read_tfd_before = registers[tfd_index];
    if (((g_ahci_driver_read_status_read_ci_before & g_ahci_issue_plan_slot_mask) != 0u)
        || ((g_ahci_driver_read_status_read_tfd_before & MMIO64_AHCI_TFD_STS_BSY) != 0u))
    {
        ++g_ahci_driver_read_status_read_unavailable_count;
        g_ahci_driver_read_status_read_error = 4u;
        g_ahci_driver_read_status_read_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_READ_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_read_flags =
            flags | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    write_window_open = paging64_kernel_mmio_write_window_open(port_page);
    if (write_window_open == 0u)
    {
        ++g_ahci_driver_read_status_read_unavailable_count;
        g_ahci_driver_read_status_read_error = 5u;
        g_ahci_driver_read_status_read_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_READ_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_read_flags =
            flags | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    registers[clb_index] = g_ahci_driver_read_status_read_page_low;
    registers[clbu_index] = g_ahci_driver_read_status_read_page_high;
    registers[fb_index] = receive_fis_low;
    registers[fbu_index] = receive_fis_high;
    command = registers[cmd_index] | MMIO64_AHCI_PORT_CMD_FRE;
    registers[cmd_index] = command;
    registers[cmd_index] = command | MMIO64_AHCI_PORT_CMD_ST;
    registers[is_index] = 0xFFFFFFFFu;
    registers[serr_index] = 0xFFFFFFFFu;
    flags |= MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_MMIO_PROGRAMMED
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_PORT_PROGRAMMED;

    g_ahci_driver_read_status_read_active = 1u;
    registers[ci_index] = g_ahci_issue_plan_slot_mask;
    flags |= MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_COMMAND_ISSUED;

    for (poll = 0u; poll < MMIO64_AHCI_READ_POLL_BUDGET; ++poll)
    {
        ci = registers[ci_index];
        tfd = registers[tfd_index];
        if (((ci & g_ahci_issue_plan_slot_mask) == 0u)
            && ((tfd & MMIO64_AHCI_TFD_STS_BSY) == 0u))
        {
            completed = 1u;
            break;
        }
    }

    g_ahci_driver_read_status_read_poll_count =
        (poll < MMIO64_AHCI_READ_POLL_BUDGET) ? (poll + 1u) : poll;
    g_ahci_driver_read_status_read_ci_after = registers[ci_index];
    g_ahci_driver_read_status_read_tfd_after = registers[tfd_index];
    g_ahci_driver_read_status_read_prdbc = mmio64_read_u32(
        g_ahci_command_page,
        g_ahci_memory_plan_command_header_offset + 4u);
    registers[cmd_index] = registers[cmd_index] & ~MMIO64_AHCI_PORT_CMD_ST;
    write_window_closed = paging64_kernel_mmio_write_window_close(port_page);
    g_ahci_driver_read_status_read_active = 0u;
    if (write_window_closed != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_TEARDOWN_DONE;
    }
    else
    {
        g_ahci_driver_read_status_read_error = 6u;
    }

    if (g_ahci_driver_read_status_read_error != 0u)
    {
    }
    else if (completed == 0u)
    {
        g_ahci_driver_read_status_read_error = 2u;
    }
    else if ((g_ahci_driver_read_status_read_tfd_after
            & MMIO64_AHCI_TFD_STS_ERR) != 0u)
    {
        g_ahci_driver_read_status_read_error = 3u;
    }
    else
    {
        g_ahci_driver_read_status_read_result_bytes = bounce_bytes;
        g_ahci_driver_read_status_read_checksum = mmio64_checksum_bytes(
            (const u8 *)(g_ahci_command_page + bounce_offset),
            bounce_bytes);
        g_ahci_driver_read_status_read_error = 0u;
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_COMPLETED
            | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_ERROR_CLEAR;
    }

    flags |= MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DMA_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_MEDIA_READ_AUTHORITY;
    g_ahci_driver_read_status_read_flags = flags;
    if ((g_ahci_driver_read_status_read_error != 0u)
        || ((flags & MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_COMPLETED) == 0u))
    {
        ++g_ahci_driver_read_status_read_unavailable_count;
        g_ahci_driver_read_status_read_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_READ_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_read_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    required_flags = MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DWIN_READY
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DWIN_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_ISSUE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DMA_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_MEDIA_READ_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_PRDT_PATCHED
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_CHECKSUM_RECORDED
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_MMIO_PROGRAMMED
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_PORT_PROGRAMMED
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_COMMAND_ISSUED
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_COMPLETED
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_BYTES_BOUNDED
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_BUFFER_SEALED
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_NO_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_NO_FS_MINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_TEARDOWN_DONE
        | MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_ERROR_CLEAR;

    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_status_read_unavailable_count;
        g_ahci_driver_read_status_read_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_READ_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_read_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_read_state =
        MMIO64_AHCI_DRIVER_READ_STATUS_READ_STATE_COMPLETED;
    g_ahci_driver_read_status_read_token =
        mmio64_make_driver_read_status_read_token();
    ++g_ahci_driver_read_status_read_stage_count;
    return g_ahci_driver_read_status_read_token;
}

u32 mmio64_ahci_driver_read_status_read_telemetry(u32 selector)
{
    switch (selector)
    {
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_STATE:
            return g_ahci_driver_read_status_read_state;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_FLAGS:
            return g_ahci_driver_read_status_read_flags;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_DRIVER_OWNER:
            return g_ahci_driver_read_status_export_driver_owner;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_QUERY_ONLY:
            return (g_ahci_driver_read_status_read_flags & MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DRIVER_QUERY_ONLY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_DWIN_BOUND:
            return (g_ahci_driver_read_status_read_flags & MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DWIN_TOKEN_BOUND) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_READY:
            return (g_ahci_driver_read_status_read_flags & MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DWIN_READY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_REQUESTED:
            return (g_ahci_driver_read_status_read_flags & MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_REQUESTED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_ISSUED:
            return (g_ahci_driver_read_status_read_flags & MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_COMMAND_ISSUED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_COMPLETED:
            return (g_ahci_driver_read_status_read_flags & MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_COMPLETED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_BYTES:
            return g_ahci_driver_read_status_read_result_bytes;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_CHECKSUM:
            return g_ahci_driver_read_status_read_checksum;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_ERROR:
            return g_ahci_driver_read_status_read_error;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_PORT:
            return g_ahci_driver_read_status_export_port;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_KIND:
            return g_ahci_driver_read_status_export_kind;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_OPERATION:
            return g_ahci_driver_read_status_export_read_operation;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_LBA:
            return g_ahci_driver_read_status_export_read_lba;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_BLOCKS:
            return g_ahci_driver_read_status_export_read_blocks;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_PAGE_LOW:
            return g_ahci_driver_read_status_read_page_low;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_BOUNCE_LOW:
            return g_ahci_driver_read_status_read_bounce_low;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_TABLE_BEFORE:
            return g_ahci_driver_read_status_read_table_before;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_TABLE_AFTER:
            return g_ahci_driver_read_status_read_table_after;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_PRDBC:
            return g_ahci_driver_read_status_read_prdbc;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_CI_BEFORE:
            return g_ahci_driver_read_status_read_ci_before;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_CI_AFTER:
            return g_ahci_driver_read_status_read_ci_after;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_TFD_BEFORE:
            return g_ahci_driver_read_status_read_tfd_before;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_TFD_AFTER:
            return g_ahci_driver_read_status_read_tfd_after;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_POLL_COUNT:
            return g_ahci_driver_read_status_read_poll_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_MMIO_WRITE:
            return (g_ahci_driver_read_status_read_flags & MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_MMIO_PROGRAMMED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_PORT_PROGRAM:
            return (g_ahci_driver_read_status_read_flags & MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_PORT_PROGRAMMED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_DMA:
            return (g_ahci_driver_read_status_read_flags & MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_DMA_AUTHORITY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_MEDIA_READ:
            return (g_ahci_driver_read_status_read_flags & MMIO64_AHCI_DRIVER_READ_STATUS_READ_FLAG_MEDIA_READ_AUTHORITY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_WRITE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_COMMIT_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_BLOCK_ENDPOINT:
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_FS_MINT:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_ACTIVE:
            return g_ahci_driver_read_status_read_active;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_STAGE_COUNT:
            return g_ahci_driver_read_status_read_stage_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_DENIAL_COUNT:
            return g_ahci_driver_read_status_read_denial_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_READ_TELEMETRY_UNAVAILABLE_COUNT:
            return g_ahci_driver_read_status_read_unavailable_count;
        default:
            return 0u;
    }
}

u32 mmio64_stage_ahci_driver_read_status_block(
    u32 driver_capability_handle,
    u32 driver_read_status_read_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 owner_bound = 0u;
    u32 query_only = 0u;
    u32 ready = 0u;
    u32 endpoint;
    u32 route_endpoint;
    u32 stale_route;
    u32 index;
    u32 bounce_offset;
    u32 expected_owner = g_ahci_driver_read_status_export_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_status_block_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if ((driver_read_status_read_token == 0u)
        || (driver_read_status_read_token == MMIO64_INVALID_RESULT))
    {
        mmio64_reset_driver_read_status_block();
        g_ahci_driver_read_status_block_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_block_flags =
            MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_REQUESTED
            | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_NO_WRITE_AUTHORITY
            | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_NO_COMMIT_AUTHORITY
            | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_NO_FS_MINT
            | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_UNAVAILABLE;
        ++g_ahci_driver_read_status_block_unavailable_count;
        return MMIO64_INVALID_RESULT;
    }

    if (driver_read_status_read_token != g_ahci_driver_read_status_read_token)
    {
        ++g_ahci_driver_read_status_block_denial_count;
        ++g_ahci_driver_read_status_block_stale_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_status_block();
    g_ahci_driver_read_status_block_read_token = driver_read_status_read_token;
    g_ahci_driver_read_status_block_read_checksum =
        g_ahci_driver_read_status_read_checksum;
    flags = MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_NO_FS_MINT;

    if ((g_ahci_driver_read_status_read_state
            == MMIO64_AHCI_DRIVER_READ_STATUS_READ_STATE_COMPLETED)
        && (g_ahci_driver_read_status_read_error == 0u)
        && (g_ahci_driver_read_status_read_result_bytes
            == MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES)
        && (g_ahci_driver_read_status_read_checksum != 0u))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_TOKEN_BOUND;
    }

    if ((driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (driver_capability_handle
            == g_ahci_driver_read_status_export_driver_capability))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DRIVER_CAP_BOUND;
    }

    if (driver_capability_handle != CAPABILITY64_INVALID_HANDLE)
    {
        if ((capability64_owner(driver_capability_handle, owner_id) == owner_id)
            && (owner_id == expected_owner))
        {
            owner_bound = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DRIVER_OWNER_BOUND;
        }
        if ((owner_bound != 0u)
            && (capability64_rights(driver_capability_handle, owner_id)
                == CAPABILITY64_RIGHT_QUERY))
        {
            query_only = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DRIVER_QUERY_ONLY;
        }
    }

    endpoint = services64_resolve_endpoint_class(SERVICE_ENDPOINT_CLASS_BLOCK);
    if (endpoint != 0xFFFFFFFFu)
    {
        g_ahci_driver_read_status_block_endpoint = 1u;
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_SERVICE_NAMESPACE;
    }

    if (((flags & (MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DRIVER_CAP_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DRIVER_OWNER_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DRIVER_QUERY_ONLY
            | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_SERVICE_NAMESPACE))
            == (MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_READY
                | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_TOKEN_BOUND
                | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DRIVER_CAP_BOUND
                | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DRIVER_OWNER_BOUND
                | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DRIVER_QUERY_ONLY
                | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_SERVICE_NAMESPACE))
        && (query_only != 0u))
    {
        ready = 1u;
    }

    if (ready == 0u)
    {
        ++g_ahci_driver_read_status_block_unavailable_count;
        g_ahci_driver_read_status_block_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_block_flags =
            flags | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_block_capability =
        capability64_grant_service(
            SERVICE_ENDPOINT_CLASS_BLOCK,
            CAPABILITY64_RIGHT_SEND | CAPABILITY64_RIGHT_DELEGATE,
            owner_id);
    if (g_ahci_driver_read_status_block_capability
        != CAPABILITY64_INVALID_HANDLE)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_BLOCK_ENDPOINT
            | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_BLOCK_CAP_MINTED
            | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_ONLY;
    }

    g_ahci_driver_read_status_block_consumer_capability =
        capability64_delegate(
            g_ahci_driver_read_status_block_capability,
            CAPABILITY64_RIGHT_SEND,
            CAPABILITY64_CONTEXT(owner_id, PRINCIPAL64_ID_POLICY_CLIENT));
    if (g_ahci_driver_read_status_block_consumer_capability
        != CAPABILITY64_INVALID_HANDLE)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DELEGATED_CAP_MINTED;
    }

    if (capability64_route(
            g_ahci_driver_read_status_block_consumer_capability,
            CAPABILITY64_RIGHT_SEND,
            PRINCIPAL64_ID_CONSOLE_CLIENT) == 0xFFFFFFFFu)
    {
        g_ahci_driver_read_status_block_wrong_owner_denied = 1u;
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_WRONG_OWNER_DENIED;
    }

    g_ahci_driver_read_status_block_stale_capability =
        capability64_delegate(
            g_ahci_driver_read_status_block_capability,
            CAPABILITY64_RIGHT_SEND,
            CAPABILITY64_CONTEXT(owner_id, PRINCIPAL64_ID_POLICY_CLIENT));
    if (g_ahci_driver_read_status_block_stale_capability
        != CAPABILITY64_INVALID_HANDLE)
    {
        (void)capability64_revoke(
            g_ahci_driver_read_status_block_stale_capability,
            PRINCIPAL64_ID_POLICY_CLIENT);
        stale_route = capability64_route(
            g_ahci_driver_read_status_block_stale_capability,
            CAPABILITY64_RIGHT_SEND,
            PRINCIPAL64_ID_POLICY_CLIENT);
        if (stale_route == 0xFFFFFFFFu)
        {
            g_ahci_driver_read_status_block_stale_denied = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_STALE_HANDLE_DENIED;
        }
    }

    route_endpoint = capability64_route(
        g_ahci_driver_read_status_block_consumer_capability,
        CAPABILITY64_RIGHT_SEND,
        PRINCIPAL64_ID_POLICY_CLIENT);
    if (route_endpoint == endpoint)
    {
        bounce_offset = g_ahci_memory_plan_bounce_offset;
        for (index = 0u; index < MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES; ++index)
        {
            g_ahci_driver_read_status_block_buffer[index] =
                g_ahci_command_page[bounce_offset + index];
        }
        g_ahci_driver_read_status_block_result_bytes =
            MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES;
        g_ahci_driver_read_status_block_checksum = mmio64_checksum_bytes(
            g_ahci_driver_read_status_block_buffer,
            MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES);
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_ROUTED
            | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_BUFFER_DELEGATED
            | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_BYTES_BOUNDED;
        if (g_ahci_driver_read_status_block_checksum
            == g_ahci_driver_read_status_block_read_checksum)
        {
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_CHECKSUM_MATCH;
        }
    }

    g_ahci_driver_read_status_block_flags = flags;
    required_flags = MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_READY
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DRIVER_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DRIVER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DRIVER_QUERY_ONLY
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_SERVICE_NAMESPACE
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_BLOCK_ENDPOINT
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_BLOCK_CAP_MINTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DELEGATED_CAP_MINTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_ROUTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_BUFFER_DELEGATED
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_BYTES_BOUNDED
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_CHECKSUM_MATCH
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_WRONG_OWNER_DENIED
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_STALE_HANDLE_DENIED
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_NO_FS_MINT;

    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_status_block_unavailable_count;
        g_ahci_driver_read_status_block_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_block_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_block_state =
        MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_STATE_PUBLISHED;
    g_ahci_driver_read_status_block_token =
        mmio64_make_driver_read_status_block_token();
    ++g_ahci_driver_read_status_block_stage_count;
    return g_ahci_driver_read_status_block_token;
}

u32 mmio64_ahci_driver_read_status_block_telemetry(u32 selector)
{
    switch (selector)
    {
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_STATE:
            return g_ahci_driver_read_status_block_state;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_FLAGS:
            return g_ahci_driver_read_status_block_flags;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_OWNER:
            return g_ahci_driver_read_status_export_driver_owner;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_READ_BOUND:
            return (g_ahci_driver_read_status_block_flags & MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_TOKEN_BOUND) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_ENDPOINT:
            return (g_ahci_driver_read_status_block_flags & MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_BLOCK_ENDPOINT) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_CAP_MINTED:
            return (g_ahci_driver_read_status_block_flags & MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_BLOCK_CAP_MINTED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_CAPABILITY:
            return g_ahci_driver_read_status_block_capability;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_READ_ONLY:
            return (g_ahci_driver_read_status_block_flags & MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_ONLY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_DELEGATED_CAP:
            return (g_ahci_driver_read_status_block_flags & MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_DELEGATED_CAP_MINTED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_READ_ROUTED:
            return (g_ahci_driver_read_status_block_flags & MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_READ_ROUTED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_BYTES:
            return g_ahci_driver_read_status_block_result_bytes;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_CHECKSUM:
            return g_ahci_driver_read_status_block_checksum;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_READ_CHECKSUM:
            return g_ahci_driver_read_status_block_read_checksum;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_CHECKSUM_MATCH:
            return (g_ahci_driver_read_status_block_flags & MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_CHECKSUM_MATCH) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_WRONG_OWNER_DENIED:
            return g_ahci_driver_read_status_block_wrong_owner_denied;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_STALE_DENIED:
            return g_ahci_driver_read_status_block_stale_denied;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_WRITE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_COMMIT_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_FS_MINT:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_LBA:
            return g_ahci_driver_read_status_export_read_lba;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_BLOCKS:
            return g_ahci_driver_read_status_export_read_blocks;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_BUFFER_DELEGATED:
            return (g_ahci_driver_read_status_block_flags & MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_FLAG_BUFFER_DELEGATED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_STAGE_COUNT:
            return g_ahci_driver_read_status_block_stage_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_DENIAL_COUNT:
            return g_ahci_driver_read_status_block_denial_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_TELEMETRY_UNAVAILABLE_COUNT:
            return g_ahci_driver_read_status_block_unavailable_count;
        default:
            return 0u;
    }
}

u32 mmio64_stage_ahci_driver_read_status_fs(
    u32 block_capability_handle,
    u32 driver_read_status_block_token,
    u32 owner_id)
{
    const u8 *sector;
    u32 flags;
    u32 required_flags;
    u32 ready = 0u;
    u32 endpoint;
    u32 route_endpoint;
    u32 pvd_checksum = 0u;
    u32 root_checksum = 0u;
    u32 readme_checksum = 0u;
    u32 root_record_offset = MMIO64_ISO9660_ROOT_DIRECTORY_RECORD_OFFSET;
    u32 root_record_length;
    u32 root_lba = 0u;
    u32 root_bytes = 0u;
    u32 file_lba = 0u;
    u32 file_bytes = 0u;
    u32 expected_owner = g_ahci_driver_read_status_export_driver_owner;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_status_fs_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if ((driver_read_status_block_token == 0u)
        || (driver_read_status_block_token == MMIO64_INVALID_RESULT))
    {
        mmio64_reset_driver_read_status_fs();
        g_ahci_driver_read_status_fs_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_fs_flags =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_REQUESTED
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_NO_WRITE_AUTHORITY
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_NO_COMMIT_AUTHORITY
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_NO_FS_MINT
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_UNAVAILABLE;
        ++g_ahci_driver_read_status_fs_unavailable_count;
        return MMIO64_INVALID_RESULT;
    }

    if (driver_read_status_block_token != g_ahci_driver_read_status_block_token)
    {
        ++g_ahci_driver_read_status_fs_denial_count;
        ++g_ahci_driver_read_status_fs_stale_denial_count;
        ++g_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_status_fs();
    g_ahci_driver_read_status_fs_block_token = driver_read_status_block_token;
    flags = MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_NO_FS_MINT;

    if ((g_ahci_driver_read_status_block_state
            == MMIO64_AHCI_DRIVER_READ_STATUS_BLOCK_STATE_PUBLISHED)
        && (g_ahci_driver_read_status_block_result_bytes
            == MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES)
        && (g_ahci_driver_read_status_block_checksum != 0u))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_TOKEN_BOUND;
    }

    if ((block_capability_handle != CAPABILITY64_INVALID_HANDLE)
        && (block_capability_handle
            == g_ahci_driver_read_status_block_capability)
        && (capability64_owner(block_capability_handle, owner_id) == owner_id)
        && ((capability64_rights(block_capability_handle, owner_id)
                & CAPABILITY64_RIGHT_SEND) != 0u))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_CAP_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_READ_ONLY;
    }

    endpoint = services64_resolve_endpoint_class(SERVICE_ENDPOINT_CLASS_BLOCK);
    route_endpoint = capability64_route(
        block_capability_handle,
        CAPABILITY64_RIGHT_SEND,
        owner_id);
    if ((endpoint != 0xFFFFFFFFu) && (route_endpoint == endpoint))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_ROUTE_BOUND;
    }

    if ((flags & (MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_CAP_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_READ_ONLY
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_ROUTE_BOUND))
        == (MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_READY
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_CAP_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_READ_ONLY
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_ROUTE_BOUND))
    {
        ready = 1u;
    }

    if (ready == 0u)
    {
        ++g_ahci_driver_read_status_fs_unavailable_count;
        g_ahci_driver_read_status_fs_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_fs_flags =
            flags | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    if (mmio64_ahci_driver_read_status_route_sector(
            MMIO64_ISO9660_PRIMARY_VOLUME_DESCRIPTOR_LBA,
            &pvd_checksum) != 0u)
    {
        ++g_ahci_driver_read_status_fs_unavailable_count;
        g_ahci_driver_read_status_fs_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_fs_flags =
            flags | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_fs_pvd_checksum = pvd_checksum;
    flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_PVD_READ;
    sector = (const u8 *)(g_ahci_command_page + g_ahci_memory_plan_bounce_offset);
    if ((sector[0] == 1u)
        && (sector[1] == (u8)'C')
        && (sector[2] == (u8)'D')
        && (sector[3] == (u8)'0')
        && (sector[4] == (u8)'0')
        && (sector[5] == (u8)'1')
        && (sector[6] == 1u))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_PVD_SIGNATURE;
    }

    root_record_length = sector[root_record_offset];
    if (((flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_PVD_SIGNATURE) != 0u)
        && (root_record_length >= 34u)
        && ((root_record_offset + root_record_length)
            <= MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES))
    {
        root_lba = mmio64_read_u32(sector, root_record_offset + 2u);
        root_bytes = mmio64_read_u32(sector, root_record_offset + 10u);
        if ((root_lba != 0u)
            && (root_bytes != 0u)
            && (root_bytes <= MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES))
        {
            g_ahci_driver_read_status_fs_root_lba = root_lba;
            g_ahci_driver_read_status_fs_root_bytes = root_bytes;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_ROOT_BOUND;
        }
    }

    if ((flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_ROOT_BOUND) == 0u)
    {
        ++g_ahci_driver_read_status_fs_unavailable_count;
        g_ahci_driver_read_status_fs_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_fs_flags =
            flags | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    if (mmio64_ahci_driver_read_status_route_sector(root_lba, &root_checksum) != 0u)
    {
        ++g_ahci_driver_read_status_fs_unavailable_count;
        g_ahci_driver_read_status_fs_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_fs_flags =
            flags | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    (void)root_checksum;
    flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_ROOT_READ;
    sector = (const u8 *)(g_ahci_command_page + g_ahci_memory_plan_bounce_offset);
    if (mmio64_iso9660_find_readme(
            sector,
            root_bytes,
            &file_lba,
            &file_bytes) != 0u)
    {
        g_ahci_driver_read_status_fs_file_lba = file_lba;
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_README_LOCATED;
    }

    if (((flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_README_LOCATED) == 0u)
        || (file_lba == 0u)
        || (file_bytes == 0u)
        || (file_bytes > MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES))
    {
        ++g_ahci_driver_read_status_fs_unavailable_count;
        g_ahci_driver_read_status_fs_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_fs_flags =
            flags | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    if (mmio64_ahci_driver_read_status_route_sector(file_lba, &readme_checksum) != 0u)
    {
        ++g_ahci_driver_read_status_fs_unavailable_count;
        g_ahci_driver_read_status_fs_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_fs_flags =
            flags | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    sector = (const u8 *)(g_ahci_command_page + g_ahci_memory_plan_bounce_offset);
    g_ahci_driver_read_status_fs_read_bytes = file_bytes;
    g_ahci_driver_read_status_fs_checksum =
        mmio64_checksum_bytes(sector, file_bytes);
    flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_README_READ
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BYTES_BOUNDED;
    if ((file_bytes == MMIO64_ISO9660_BOOT_README_BYTES)
        && (g_ahci_driver_read_status_fs_checksum
            == MMIO64_ISO9660_BOOT_README_CHECKSUM)
        && (readme_checksum != 0u))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_CONTENT_MATCH;
    }

    required_flags = MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_READY
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_CAP_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_READ_ONLY
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_ROUTE_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_PVD_READ
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_PVD_SIGNATURE
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_ROOT_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_ROOT_READ
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_README_LOCATED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_README_READ
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BYTES_BOUNDED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_CONTENT_MATCH
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_NO_FS_MINT;

    g_ahci_driver_read_status_fs_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_status_fs_unavailable_count;
        g_ahci_driver_read_status_fs_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_fs_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_fs_state =
        MMIO64_AHCI_DRIVER_READ_STATUS_FS_STATE_VERIFIED;
    g_ahci_driver_read_status_fs_token =
        mmio64_make_driver_read_status_fs_token();
    ++g_ahci_driver_read_status_fs_stage_count;
    return g_ahci_driver_read_status_fs_token;
}

u32 mmio64_ahci_driver_read_status_fs_telemetry(u32 selector)
{
    switch (selector)
    {
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_STATE:
            return g_ahci_driver_read_status_fs_state;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_FLAGS:
            return g_ahci_driver_read_status_fs_flags;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_OWNER:
            return g_ahci_driver_read_status_export_driver_owner;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_BLOCK_BOUND:
            return (g_ahci_driver_read_status_fs_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_TOKEN_BOUND) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_BLOCK_CAPABILITY:
            return g_ahci_driver_read_status_block_capability;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_BLOCK_READ_ONLY:
            return (g_ahci_driver_read_status_fs_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_READ_ONLY) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_BLOCK_ROUTE:
            return (g_ahci_driver_read_status_fs_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_BLOCK_ROUTE_BOUND) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_PVD:
            return (g_ahci_driver_read_status_fs_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_PVD_SIGNATURE) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_PVD_CHECKSUM:
            return g_ahci_driver_read_status_fs_pvd_checksum;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_ROOT_LBA:
            return g_ahci_driver_read_status_fs_root_lba;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_ROOT_BYTES:
            return g_ahci_driver_read_status_fs_root_bytes;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_ROOT_READ:
            return (g_ahci_driver_read_status_fs_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_ROOT_READ) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_LOCATED:
            return (g_ahci_driver_read_status_fs_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_README_LOCATED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_FILE_LBA:
            return g_ahci_driver_read_status_fs_file_lba;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_READ_BYTES:
            return g_ahci_driver_read_status_fs_read_bytes;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_CHECKSUM:
            return g_ahci_driver_read_status_fs_checksum;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_EXPECTED_CHECKSUM:
            return MMIO64_ISO9660_BOOT_README_CHECKSUM;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_CONTENT_MATCH:
            return (g_ahci_driver_read_status_fs_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_FLAG_CONTENT_MATCH) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_WRITE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_COMMIT_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_FS_MINT:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_STAGE_COUNT:
            return g_ahci_driver_read_status_fs_stage_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_DENIAL_COUNT:
            return g_ahci_driver_read_status_fs_denial_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_TELEMETRY_UNAVAILABLE_COUNT:
            return g_ahci_driver_read_status_fs_unavailable_count;
        default:
            return 0u;
    }
}

static u32 mmio64_fs_user_read_allowed(u32 capability_handle, u32 owner_id)
{
    if ((capability_handle == g_ahci_driver_read_status_fs_user_capability)
        && (g_ahci_driver_read_status_fs_user_cap_active != 0u)
        && (owner_id == g_ahci_driver_read_status_fs_user_user_owner))
    {
        return 1u;
    }

    if ((capability_handle == MMIO64_FS_USER_STALE_CAPABILITY)
        && (g_ahci_driver_read_status_fs_user_stale_active != 0u)
        && (owner_id == g_ahci_driver_read_status_fs_user_user_owner))
    {
        return 1u;
    }

    return 0u;
}

u32 mmio64_stage_ahci_driver_read_status_fs_user(
    u32 driver_read_status_fs_token,
    u64 path_address,
    u32 owner_id)
{
    u8 path[MMIO64_FS_USER_PATH_BYTES];
    u32 flags;
    u32 required_flags;
    u32 expected_owner = g_ahci_driver_read_status_export_driver_owner;
    u32 user_owner = PRINCIPAL64_ID_CONSOLE_CLIENT;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_status_fs_user_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if ((driver_read_status_fs_token == 0u)
        || (driver_read_status_fs_token == MMIO64_INVALID_RESULT))
    {
        mmio64_reset_driver_read_status_fs_user();
        g_ahci_driver_read_status_fs_user_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_fs_user_flags =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_REQUESTED
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_NO_WRITE_AUTHORITY
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_NO_COMMIT_AUTHORITY
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_NO_ADDITIONAL_FS_CAPS
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_UNAVAILABLE;
        ++g_ahci_driver_read_status_fs_user_unavailable_count;
        return MMIO64_INVALID_RESULT;
    }

    if (driver_read_status_fs_token != g_ahci_driver_read_status_fs_token)
    {
        ++g_ahci_driver_read_status_fs_user_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_status_fs_user();
    g_ahci_driver_read_status_fs_user_fs_token = driver_read_status_fs_token;
    g_ahci_driver_read_status_fs_user_user_owner = user_owner;
    flags = MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_NO_ADDITIONAL_FS_CAPS;

    if ((g_ahci_driver_read_status_fs_state
            == MMIO64_AHCI_DRIVER_READ_STATUS_FS_STATE_VERIFIED)
        && (g_ahci_driver_read_status_fs_checksum
            == MMIO64_ISO9660_BOOT_README_CHECKSUM)
        && (g_ahci_driver_read_status_fs_root_lba != 0u)
        && (g_ahci_driver_read_status_fs_root_bytes != 0u))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_FS_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_FS_VERIFIED
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_ROOT_BOUND;
    }

    if ((principal64_is_active(user_owner) != 0u)
        && (mmio64_copy_null_path_from_address(
                path_address,
                path,
                MMIO64_FS_USER_PATH_BYTES) != 0u))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_PATH_ACCEPTED;
    }

    if ((flags & (MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_FS_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_FS_VERIFIED
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_ROOT_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_PATH_ACCEPTED))
        != (MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_FS_TOKEN_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_FS_VERIFIED
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_ROOT_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_PATH_ACCEPTED))
    {
        ++g_ahci_driver_read_status_fs_user_unavailable_count;
        g_ahci_driver_read_status_fs_user_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_fs_user_flags =
            flags | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_fs_user_capability = MMIO64_FS_USER_CAPABILITY;
    g_ahci_driver_read_status_fs_user_cap_active = 1u;
    flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_CAP_MINTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_DELEGATED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_USER_OWNER_BOUND;

    if (mmio64_fs_user_read_allowed(
            g_ahci_driver_read_status_fs_user_capability,
            PRINCIPAL64_ID_POLICY_CLIENT) == 0u)
    {
        g_ahci_driver_read_status_fs_user_wrong_owner = 1u;
        ++g_ahci_driver_read_status_fs_user_denial_count;
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_WRONG_OWNER_DENIED;
    }

    g_ahci_driver_read_status_fs_user_stale_active = 1u;
    g_ahci_driver_read_status_fs_user_stale_active = 0u;
    if (mmio64_fs_user_read_allowed(
            MMIO64_FS_USER_STALE_CAPABILITY,
            user_owner) == 0u)
    {
        g_ahci_driver_read_status_fs_user_stale = 1u;
        ++g_ahci_driver_read_status_fs_user_denial_count;
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_STALE_DENIED;
    }

    if ((mmio64_fs_user_read_allowed(
                g_ahci_driver_read_status_fs_user_capability,
                user_owner) != 0u)
        && (mmio64_iso9660_read_path(
                path,
                g_ahci_driver_read_status_fs_user_buffer,
                MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES,
                &g_ahci_driver_read_status_fs_user_file_lba,
                &g_ahci_driver_read_status_fs_user_bytes,
                &g_ahci_driver_read_status_fs_user_checksum,
                &g_ahci_driver_read_status_fs_user_apps_lba,
                &g_ahci_driver_read_status_fs_user_apps_bytes,
                &flags) != 0u))
    {
        if (mmio64_copy_to_address(
                MMIO64_FS_USER_BUFFER_ADDRESS,
                g_ahci_driver_read_status_fs_user_buffer,
                g_ahci_driver_read_status_fs_user_bytes) != 0)
        {
            g_ahci_driver_read_status_fs_user_buffer_written = 1u;
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_USER_BUFFER_WRITTEN;
        }

        if ((g_ahci_driver_read_status_fs_user_bytes
                == MMIO64_ISO9660_LS_APP_BYTES)
            && (g_ahci_driver_read_status_fs_user_checksum
                == MMIO64_ISO9660_LS_APP_CHECKSUM))
        {
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_CHECKSUM_MATCH;
        }
    }

    g_ahci_driver_read_status_fs_user_flags = flags;
    required_flags = MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_FS_TOKEN_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_FS_VERIFIED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_PATH_ACCEPTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_ROOT_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_ROOT_READ
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_APPS_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_APPS_READ
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_FILE_LOCATED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_CAP_MINTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_DELEGATED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_USER_OWNER_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_READ_ROUTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_USER_BUFFER_WRITTEN
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_BYTES_BOUNDED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_CHECKSUM_MATCH
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_WRONG_OWNER_DENIED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_STALE_DENIED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_NO_ADDITIONAL_FS_CAPS;

    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_status_fs_user_unavailable_count;
        g_ahci_driver_read_status_fs_user_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_fs_user_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_fs_user_state =
        MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_STATE_DELEGATED;
    g_ahci_driver_read_status_fs_user_token =
        mmio64_make_driver_read_status_fs_user_token();
    ++g_ahci_driver_read_status_fs_user_stage_count;
    return g_ahci_driver_read_status_fs_user_token;
}

u32 mmio64_ahci_driver_read_status_fs_user_telemetry(u32 selector)
{
    switch (selector)
    {
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_STATE:
            return g_ahci_driver_read_status_fs_user_state;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_FLAGS:
            return g_ahci_driver_read_status_fs_user_flags;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_OWNER:
            return g_ahci_driver_read_status_export_driver_owner;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_USER_OWNER:
            return g_ahci_driver_read_status_fs_user_user_owner;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_FS_BOUND:
            return (g_ahci_driver_read_status_fs_user_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_FS_TOKEN_BOUND) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_CAP_MINTED:
            return (g_ahci_driver_read_status_fs_user_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_CAP_MINTED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_DELEGATED:
            return (g_ahci_driver_read_status_fs_user_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_DELEGATED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_READ_ROUTED:
            return (g_ahci_driver_read_status_fs_user_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_READ_ROUTED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_ROOT_READ:
            return (g_ahci_driver_read_status_fs_user_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_ROOT_READ) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_APPS_LBA:
            return g_ahci_driver_read_status_fs_user_apps_lba;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_APPS_BYTES:
            return g_ahci_driver_read_status_fs_user_apps_bytes;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_FILE_LBA:
            return g_ahci_driver_read_status_fs_user_file_lba;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_BYTES:
            return g_ahci_driver_read_status_fs_user_bytes;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_CHECKSUM:
            return g_ahci_driver_read_status_fs_user_checksum;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_EXPECTED_CHECKSUM:
            return MMIO64_ISO9660_LS_APP_CHECKSUM;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_CONTENT_MATCH:
            return (g_ahci_driver_read_status_fs_user_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_FLAG_CHECKSUM_MATCH) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_WRONG_OWNER:
            return g_ahci_driver_read_status_fs_user_wrong_owner;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_STALE:
            return g_ahci_driver_read_status_fs_user_stale;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_WRITE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_COMMIT_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_ADDITIONAL_FS_CAPS:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_USER_BUFFER:
            return g_ahci_driver_read_status_fs_user_buffer_written;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_STAGE_COUNT:
            return g_ahci_driver_read_status_fs_user_stage_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_DENIAL_COUNT:
            return g_ahci_driver_read_status_fs_user_denial_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_TELEMETRY_UNAVAILABLE_COUNT:
            return g_ahci_driver_read_status_fs_user_unavailable_count;
        default:
            return 0u;
    }
}

static u32 mmio64_fs_shell_descriptor_read_number(
    const u8 *bytes,
    u32 byte_count,
    u32 *index,
    u32 *value)
{
    u32 cursor;
    u32 parsed = 0u;
    u32 seen_digit = 0u;

    if ((bytes == (const u8 *)0)
        || (index == (u32 *)0)
        || (value == (u32 *)0)
        || (*index >= byte_count))
    {
        return 0u;
    }

    cursor = *index;
    while (cursor < byte_count)
    {
        u8 ch = bytes[cursor];
        if (ch == (u8)'\n')
        {
            if (seen_digit == 0u)
            {
                return 0u;
            }
            *index = cursor + 1u;
            *value = parsed;
            return 1u;
        }
        if ((ch < (u8)'0') || (ch > (u8)'9'))
        {
            return 0u;
        }
        seen_digit = 1u;
        parsed = (parsed * 10u) + (u32)(ch - (u8)'0');
        ++cursor;
    }

    return 0u;
}

static u32 mmio64_fs_shell_descriptor_header_ok(
    const u8 *bytes,
    u32 byte_count,
    u8 command_id)
{
    u32 index = 0u;
    u32 parsed_command = 0u;
    u32 authority = 0u;
    u32 policy = 0u;
    u32 bindings = 0u;

    if ((bytes == (const u8 *)0)
        || (byte_count < 8u)
        || (mmio64_fs_shell_descriptor_read_number(
                bytes,
                byte_count,
                &index,
                &parsed_command) == 0u)
        || (mmio64_fs_shell_descriptor_read_number(
                bytes,
                byte_count,
                &index,
                &authority) == 0u)
        || (mmio64_fs_shell_descriptor_read_number(
                bytes,
                byte_count,
                &index,
                &policy) == 0u)
        || (mmio64_fs_shell_descriptor_read_number(
                bytes,
                byte_count,
                &index,
                &bindings) == 0u))
    {
        return 0u;
    }

    return (((command_id == 0u) || (parsed_command == (u32)command_id))
        && (parsed_command != 0u)
        && (authority != 0u)
        && (policy != 0u)
        && (bindings != 0u)) ? 1u : 0u;
}

static u32 mmio64_iso9660_visible_name_length(const u8 *name, u32 name_length)
{
    u32 index;

    if (name == (const u8 *)0)
    {
        return 0u;
    }

    for (index = 0u; index < name_length; ++index)
    {
        if (name[index] == (u8)';')
        {
            return index;
        }
    }

    return name_length;
}

static u32 mmio64_iso9660_name_is_app(const u8 *name, u32 name_length)
{
    u32 length = mmio64_iso9660_visible_name_length(name, name_length);

    return (length > 4u)
        && (name[length - 4u] == (u8)'.')
        && (mmio64_ascii_upper(name[length - 3u]) == (u8)'A')
        && (mmio64_ascii_upper(name[length - 2u]) == (u8)'P')
        && (mmio64_ascii_upper(name[length - 1u]) == (u8)'P');
}

static u32 mmio64_copy_iso9660_app_path(
    const u8 *name,
    u32 name_length,
    u8 *destination,
    u32 destination_bytes)
{
    static const u8 prefix[] = {'A', 'P', 'P', 'S', '/'};
    u32 visible_length = mmio64_iso9660_visible_name_length(name, name_length);
    u32 index;

    if ((name == (const u8 *)0)
        || (destination == (u8 *)0)
        || (visible_length == 0u)
        || ((u32)sizeof(prefix) + visible_length >= destination_bytes))
    {
        return 0u;
    }

    for (index = 0u; index < (u32)sizeof(prefix); ++index)
    {
        destination[index] = prefix[index];
    }
    for (index = 0u; index < visible_length; ++index)
    {
        destination[(u32)sizeof(prefix) + index] = mmio64_ascii_upper(name[index]);
    }
    destination[(u32)sizeof(prefix) + visible_length] = 0u;
    return 1u;
}

static u32 mmio64_fs_shell_cached_path_equals(
    const u8 *cached_path,
    const char *literal)
{
    u32 index = 0u;

    if ((cached_path == (const u8 *)0) || (literal == (const char *)0))
    {
        return 0u;
    }

    while ((cached_path[index] != 0u) && (literal[index] != 0))
    {
        if (cached_path[index] != (u8)literal[index])
        {
            return 0u;
        }
        ++index;
    }

    return ((cached_path[index] == 0u) && (literal[index] == 0)) ? 1u : 0u;
}

static u32 mmio64_stage_fs_shell_dynamic_descriptors(u32 *flags)
{
    static const u8 apps_name[] = {'A', 'P', 'P', 'S'};
    const u8 *sector;
    const u8 *directory;
    u32 root_checksum = 0u;
    u32 apps_checksum = 0u;
    u32 media_checksum = 0u;
    u32 apps_lba = 0u;
    u32 apps_bytes = 0u;
    u32 offset = 0u;
    u32 record_length;
    u32 name_length;
    u32 file_flags;
    u32 file_lba;
    u32 file_bytes;
    u32 descriptor_index;

    if ((flags == (u32 *)0)
        || (g_ahci_driver_read_status_fs_root_lba == 0u)
        || (g_ahci_driver_read_status_fs_root_bytes == 0u)
        || (g_ahci_driver_read_status_fs_root_bytes
            > MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES))
    {
        return 0u;
    }

    if (mmio64_ahci_driver_read_status_route_sector(
            g_ahci_driver_read_status_fs_root_lba,
            &root_checksum) != 0u)
    {
        return 0u;
    }
    (void)root_checksum;
    sector = (const u8 *)(g_ahci_command_page + g_ahci_memory_plan_bounce_offset);
    if (mmio64_iso9660_find_entry(
            sector,
            g_ahci_driver_read_status_fs_root_bytes,
            apps_name,
            (u32)sizeof(apps_name),
            1u,
            &apps_lba,
            &apps_bytes) == 0u)
    {
        return 0u;
    }
    if ((apps_lba == 0u)
        || (apps_bytes == 0u)
        || (apps_bytes > MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES))
    {
        return 0u;
    }
    if (mmio64_ahci_driver_read_status_route_sector(apps_lba, &apps_checksum) != 0u)
    {
        return 0u;
    }
    (void)apps_checksum;
    sector = (const u8 *)(g_ahci_command_page + g_ahci_memory_plan_bounce_offset);
    mmio64_copy_bytes(
        g_ahci_driver_read_status_fs_shell_buffer,
        sector,
        apps_bytes);
    directory = g_ahci_driver_read_status_fs_shell_buffer;
    *flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_SCAN_DYNAMIC;

    while ((offset < apps_bytes)
        && (offset < MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES))
    {
        record_length = directory[offset];
        if (record_length == 0u)
        {
            break;
        }
        if ((record_length < 34u)
            || ((offset + record_length) > MMIO64_AHCI_ATAPI_LOGICAL_BLOCK_BYTES))
        {
            return 0u;
        }

        file_flags = directory[offset + 25u];
        name_length = directory[offset + 32u];
        if ((name_length != 0u)
            && ((33u + name_length) <= record_length)
            && ((file_flags & 0x02u) == 0u)
            && (mmio64_iso9660_name_is_app(
                    directory + offset + 33u,
                    name_length) != 0u))
        {
            descriptor_index = g_ahci_driver_read_status_fs_shell_descriptors_read;
            if (descriptor_index >= MMIO64_FS_SHELL_MAX_DESCRIPTORS)
            {
                return 0u;
            }

            file_lba = mmio64_read_u32(directory, offset + 2u);
            file_bytes = mmio64_read_u32(directory, offset + 10u);
            if ((file_lba == 0u)
                || (file_bytes == 0u)
                || (file_bytes > MMIO64_FS_SHELL_DESCRIPTOR_BYTES)
                || (mmio64_copy_iso9660_app_path(
                        directory + offset + 33u,
                        name_length,
                        g_ahci_driver_read_status_fs_shell_paths[descriptor_index],
                        MMIO64_FS_SHELL_DESCRIPTOR_PATH_BYTES) == 0u)
                || (mmio64_ahci_driver_read_status_route_sector(
                        file_lba,
                        &media_checksum) != 0u))
            {
                return 0u;
            }

            sector = (const u8 *)(g_ahci_command_page + g_ahci_memory_plan_bounce_offset);
            if ((media_checksum == 0u)
                || (mmio64_fs_shell_descriptor_header_ok(
                        sector,
                        file_bytes,
                        0u) == 0u))
            {
                return 0u;
            }

            mmio64_copy_bytes(
                g_ahci_driver_read_status_fs_shell_descriptors[descriptor_index],
                sector,
                file_bytes);
            g_ahci_driver_read_status_fs_shell_descriptor_bytes[descriptor_index] =
                file_bytes;

            if (mmio64_fs_shell_cached_path_equals(
                    g_ahci_driver_read_status_fs_shell_paths[descriptor_index],
                    "APPS/LS.APP") != 0u)
            {
                *flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_LS_DESCRIPTOR_READ;
            }
            if (mmio64_fs_shell_cached_path_equals(
                    g_ahci_driver_read_status_fs_shell_paths[descriptor_index],
                    "APPS/CAT.APP") != 0u)
            {
                *flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_CAT_DESCRIPTOR_READ;
            }
            if (mmio64_fs_shell_cached_path_equals(
                    g_ahci_driver_read_status_fs_shell_paths[descriptor_index],
                    "APPS/STAT.APP") != 0u)
            {
                *flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_STAT_DESCRIPTOR_READ;
            }
            ++g_ahci_driver_read_status_fs_shell_descriptors_read;
        }

        offset += record_length;
    }

    return (g_ahci_driver_read_status_fs_shell_descriptors_read != 0u) ? 1u : 0u;
}

u32 mmio64_stage_ahci_driver_read_status_fs_shell(
    u32 driver_read_status_fs_user_token,
    u32 owner_id)
{
    u32 flags;
    u32 required_flags;
    u32 expected_owner = g_ahci_driver_read_status_export_driver_owner;
    u32 user_owner = PRINCIPAL64_ID_CONSOLE_CLIENT;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_status_fs_shell_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if ((driver_read_status_fs_user_token == 0u)
        || (driver_read_status_fs_user_token == MMIO64_INVALID_RESULT))
    {
        mmio64_reset_driver_read_status_fs_shell();
        g_ahci_driver_read_status_fs_shell_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_fs_shell_flags =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_REQUESTED
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_NO_WRITE_AUTHORITY
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_NO_COMMIT_AUTHORITY
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_NO_ADDITIONAL_FS_CAPS
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_UNAVAILABLE;
        ++g_ahci_driver_read_status_fs_shell_unavailable_count;
        return MMIO64_INVALID_RESULT;
    }

    if (driver_read_status_fs_user_token != g_ahci_driver_read_status_fs_user_token)
    {
        ++g_ahci_driver_read_status_fs_shell_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_status_fs_shell();
    g_ahci_driver_read_status_fs_shell_fs_user_token =
        driver_read_status_fs_user_token;
    g_ahci_driver_read_status_fs_shell_user_owner = user_owner;
    flags = MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_NO_ADDITIONAL_FS_CAPS;

    if ((g_ahci_driver_read_status_fs_user_state
            == MMIO64_AHCI_DRIVER_READ_STATUS_FS_USER_STATE_DELEGATED)
        && (g_ahci_driver_read_status_fs_user_capability != 0u)
        && (mmio64_fs_user_read_allowed(
                g_ahci_driver_read_status_fs_user_capability,
                user_owner) != 0u))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_FS_USER_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_PERSISTENT_DELEGATED;
    }

    if ((flags & (MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_FS_USER_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_PERSISTENT_DELEGATED))
        != (MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_FS_USER_BOUND
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_PERSISTENT_DELEGATED))
    {
        ++g_ahci_driver_read_status_fs_shell_unavailable_count;
        g_ahci_driver_read_status_fs_shell_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_fs_shell_flags =
            flags | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    if (mmio64_stage_fs_shell_dynamic_descriptors(&flags) != 0u)
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_DESCRIPTORS_PARSED
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_COMMANDS_REGISTERED
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_LS_DISPATCHED
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_CAT_DISPATCHED
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_STAT_DISPATCHED
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_RAMFS_ROUTE
            | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_ISO_ROUTE;
    }

    g_ahci_driver_read_status_fs_shell_flags = flags;
    required_flags = MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_FS_USER_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_PERSISTENT_DELEGATED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_SCAN_DYNAMIC
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_LS_DESCRIPTOR_READ
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_CAT_DESCRIPTOR_READ
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_STAT_DESCRIPTOR_READ
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_DESCRIPTORS_PARSED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_COMMANDS_REGISTERED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_LS_DISPATCHED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_CAT_DISPATCHED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_STAT_DISPATCHED
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_RAMFS_ROUTE
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_ISO_ROUTE
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_NO_ADDITIONAL_FS_CAPS;

    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_status_fs_shell_unavailable_count;
        g_ahci_driver_read_status_fs_shell_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_fs_shell_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_fs_shell_state =
        MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_STATE_READY;
    g_ahci_driver_read_status_fs_shell_token =
        mmio64_make_driver_read_status_fs_shell_token();
    ++g_ahci_driver_read_status_fs_shell_stage_count;
    return g_ahci_driver_read_status_fs_shell_token;
}

u32 mmio64_ahci_driver_read_status_fs_shell_telemetry(u32 selector)
{
    switch (selector)
    {
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_STATE:
            return g_ahci_driver_read_status_fs_shell_state;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_FLAGS:
            return g_ahci_driver_read_status_fs_shell_flags;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_OWNER:
            return g_ahci_driver_read_status_export_driver_owner;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_USER_OWNER:
            return g_ahci_driver_read_status_fs_shell_user_owner;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_FS_USER_BOUND:
            return (g_ahci_driver_read_status_fs_shell_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_FS_USER_BOUND) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_DELEGATED:
            return (g_ahci_driver_read_status_fs_shell_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_PERSISTENT_DELEGATED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_DESCRIPTORS_READ:
            return g_ahci_driver_read_status_fs_shell_descriptors_read;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_DESCRIPTORS_PARSED:
            return (g_ahci_driver_read_status_fs_shell_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_DESCRIPTORS_PARSED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_SCAN_DYNAMIC:
            return (g_ahci_driver_read_status_fs_shell_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_SCAN_DYNAMIC) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_LS_DISPATCHED:
            return (g_ahci_driver_read_status_fs_shell_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_LS_DISPATCHED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_CAT_DISPATCHED:
            return (g_ahci_driver_read_status_fs_shell_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_CAT_DISPATCHED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_STAT_DISPATCHED:
            return (g_ahci_driver_read_status_fs_shell_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_STAT_DISPATCHED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_RAMFS_ROUTE:
            return (g_ahci_driver_read_status_fs_shell_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_RAMFS_ROUTE) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_ISO_ROUTE:
            return (g_ahci_driver_read_status_fs_shell_flags & MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_FLAG_ISO_ROUTE) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_WRITE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_COMMIT_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_ADDITIONAL_FS_CAPS:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_STAGE_COUNT:
            return g_ahci_driver_read_status_fs_shell_stage_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_DENIAL_COUNT:
            return g_ahci_driver_read_status_fs_shell_denial_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_UNAVAILABLE_COUNT:
            return g_ahci_driver_read_status_fs_shell_unavailable_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_TELEMETRY_TOKEN:
            return g_ahci_driver_read_status_fs_shell_token;
        default:
            return 0u;
    }
}

u32 mmio64_stage_ahci_driver_read_status_load(
    u32 driver_read_status_fs_shell_token,
    u32 owner_id)
{
    static const u8 ls_bin_path[] = {
        'A', 'P', 'P', 'S', '/', 'L', 'S', '.', 'B', 'I', 'N', 0u
    };
    u32 flags;
    u32 path_flags = 0u;
    u32 required_flags;
    u32 expected_owner = g_ahci_driver_read_status_export_driver_owner;
    u32 user_owner = PRINCIPAL64_ID_CONSOLE_CLIENT;
    u32 file_lba = 0u;
    u32 apps_lba = 0u;
    u32 apps_bytes = 0u;

    if ((owner_id != expected_owner)
        || (principal64_is_active(owner_id) == 0u))
    {
        ++g_ahci_driver_read_status_load_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    if ((driver_read_status_fs_shell_token == 0u)
        || (driver_read_status_fs_shell_token == MMIO64_INVALID_RESULT))
    {
        mmio64_reset_driver_read_status_load();
        g_ahci_driver_read_status_load_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_load_expected_checksum =
            launch64_payload_checksum_by_slot(LAUNCH64_DISK_LS_PAYLOAD_SLOT);
        g_ahci_driver_read_status_load_flags =
            MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_REQUESTED
            | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_NO_WRITE_AUTHORITY
            | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_NO_COMMIT_AUTHORITY
            | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_NO_ADDITIONAL_FS_CAPS
            | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_UNAVAILABLE;
        ++g_ahci_driver_read_status_load_unavailable_count;
        return MMIO64_INVALID_RESULT;
    }

    if (driver_read_status_fs_shell_token != g_ahci_driver_read_status_fs_shell_token)
    {
        ++g_ahci_driver_read_status_load_denial_count;
        return MMIO64_INVALID_RESULT;
    }

    mmio64_reset_driver_read_status_load();
    g_ahci_driver_read_status_load_fs_shell_token =
        driver_read_status_fs_shell_token;
    g_ahci_driver_read_status_load_user_owner = user_owner;
    g_ahci_driver_read_status_load_expected_checksum =
        launch64_payload_checksum_by_slot(LAUNCH64_DISK_LS_PAYLOAD_SLOT);
    flags = MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_NO_ADDITIONAL_FS_CAPS;

    if ((g_ahci_driver_read_status_fs_shell_state
            == MMIO64_AHCI_DRIVER_READ_STATUS_FS_SHELL_STATE_READY)
        && (g_ahci_driver_read_status_fs_user_capability != 0u)
        && (mmio64_fs_user_read_allowed(
                g_ahci_driver_read_status_fs_user_capability,
                user_owner) != 0u))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_FS_SHELL_BOUND;
    }

    if ((flags & MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_FS_SHELL_BOUND) == 0u)
    {
        ++g_ahci_driver_read_status_load_unavailable_count;
        g_ahci_driver_read_status_load_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_load_flags =
            flags | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    if (mmio64_iso9660_read_path(
            ls_bin_path,
            g_ahci_driver_read_status_load_buffer,
            MMIO64_DRS_LOAD_BUFFER_BYTES,
            &file_lba,
            &g_ahci_driver_read_status_load_bytes,
            &g_ahci_driver_read_status_load_checksum,
            &apps_lba,
            &apps_bytes,
            &path_flags) != 0u)
    {
        (void)file_lba;
        (void)apps_lba;
        (void)apps_bytes;
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_BINARY_READ
            | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_SOURCE_DISK;
        g_ahci_driver_read_status_load_source = MMIO64_DRS_LOAD_SOURCE_DISK;
    }

    if ((g_ahci_driver_read_status_load_bytes
            == launch64_payload_size_by_slot(LAUNCH64_DISK_LS_PAYLOAD_SLOT))
        && (g_ahci_driver_read_status_load_checksum
            == g_ahci_driver_read_status_load_expected_checksum)
        && (g_ahci_driver_read_status_load_checksum != 0u))
    {
        flags |= MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_CHECKSUM_VERIFIED;
    }

    if ((flags & (MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_BINARY_READ
            | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_CHECKSUM_VERIFIED))
        == (MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_BINARY_READ
            | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_CHECKSUM_VERIFIED))
    {
        g_ahci_driver_read_status_load_map_token =
            launch64_stage_disk_flat_binary(
                LAUNCH64_DISK_LS_PAYLOAD_SLOT,
                g_ahci_driver_read_status_load_buffer,
                g_ahci_driver_read_status_load_bytes,
                MMIO64_DRS_LOAD_BUFFER_BYTES,
                MMIO64_DRS_LOAD_ENTRY_RESULT,
                &g_ahci_driver_read_status_load_entry_rip,
                &g_ahci_driver_read_status_load_entry_rsp,
                &g_ahci_driver_read_status_load_entry_selectors,
                &g_ahci_driver_read_status_load_entry_rflags,
                &g_ahci_driver_read_status_load_map_token);
        if (g_ahci_driver_read_status_load_map_token != 0u)
        {
            flags |= MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_MAPPED;
            g_ahci_driver_read_status_load_mapped_bytes =
                MMIO64_DRS_LOAD_BUFFER_BYTES;
        }
    }

    required_flags = MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_REQUESTED
        | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_FS_SHELL_BOUND
        | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_BINARY_READ
        | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_CHECKSUM_VERIFIED
        | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_MAPPED
        | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_SOURCE_DISK
        | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_NO_WRITE_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_NO_COMMIT_AUTHORITY
        | MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_NO_ADDITIONAL_FS_CAPS;
    g_ahci_driver_read_status_load_flags = flags;
    if ((flags & required_flags) != required_flags)
    {
        ++g_ahci_driver_read_status_load_unavailable_count;
        g_ahci_driver_read_status_load_state =
            MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_STATE_UNAVAILABLE;
        g_ahci_driver_read_status_load_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_UNAVAILABLE;
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_load_state =
        MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_STATE_READY;
    g_ahci_driver_read_status_load_token =
        mmio64_make_driver_read_status_load_token();
    ++g_ahci_driver_read_status_load_stage_count;
    return g_ahci_driver_read_status_load_token;
}

u32 mmio64_ahci_driver_read_status_load_record_launch(u32 result, u32 list_bytes)
{
    if ((g_ahci_driver_read_status_load_state
            != MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_STATE_READY)
        || ((g_ahci_driver_read_status_load_flags
                & MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_MAPPED) == 0u))
    {
        return MMIO64_INVALID_RESULT;
    }

    g_ahci_driver_read_status_load_exit_result = result;
    g_ahci_driver_read_status_load_ls_bytes = list_bytes;
    if (result != 0u)
    {
        g_ahci_driver_read_status_load_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_LAUNCHED;
    }
    if ((result == MMIO64_DRS_LOAD_LS_RESULT) && (list_bytes != 0u))
    {
        g_ahci_driver_read_status_load_flags |=
            MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_LS_COMPLETED;
    }

    g_ahci_driver_read_status_load_token =
        mmio64_make_driver_read_status_load_token();
    return g_ahci_driver_read_status_load_token;
}

u32 mmio64_ahci_driver_read_status_load_telemetry(u32 selector)
{
    switch (selector)
    {
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_STATE:
            return g_ahci_driver_read_status_load_state;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_FLAGS:
            return g_ahci_driver_read_status_load_flags;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_OWNER:
            return g_ahci_driver_read_status_export_driver_owner;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_USER_OWNER:
            return g_ahci_driver_read_status_load_user_owner;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_FS_SHELL_BOUND:
            return (g_ahci_driver_read_status_load_flags & MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_FS_SHELL_BOUND) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_BINARY_READ:
            return (g_ahci_driver_read_status_load_flags & MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_BINARY_READ) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_CHECKSUM_VERIFIED:
            return (g_ahci_driver_read_status_load_flags & MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_CHECKSUM_VERIFIED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_MAPPED:
            return (g_ahci_driver_read_status_load_flags & MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_MAPPED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_LAUNCHED:
            return (g_ahci_driver_read_status_load_flags & MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_LAUNCHED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_LS_COMPLETED:
            return (g_ahci_driver_read_status_load_flags & MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_FLAG_LS_COMPLETED) ? 1u : 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_SOURCE:
            return g_ahci_driver_read_status_load_source;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_BYTES:
            return g_ahci_driver_read_status_load_bytes;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_CHECKSUM:
            return g_ahci_driver_read_status_load_checksum;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_EXPECTED_CHECKSUM:
            return g_ahci_driver_read_status_load_expected_checksum;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_MAPPED_BYTES:
            return g_ahci_driver_read_status_load_mapped_bytes;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_ENTRY_RIP:
            return g_ahci_driver_read_status_load_entry_rip;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_ENTRY_RSP:
            return g_ahci_driver_read_status_load_entry_rsp;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_ENTRY_SELECTORS:
            return g_ahci_driver_read_status_load_entry_selectors;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_ENTRY_RFLAGS:
            return g_ahci_driver_read_status_load_entry_rflags;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_EXIT_RESULT:
            return g_ahci_driver_read_status_load_exit_result;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_LS_BYTES:
            return g_ahci_driver_read_status_load_ls_bytes;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_WRITE_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_COMMIT_AUTHORITY:
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_ADDITIONAL_FS_CAPS:
            return 0u;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_STAGE_COUNT:
            return g_ahci_driver_read_status_load_stage_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_DENIAL_COUNT:
            return g_ahci_driver_read_status_load_denial_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_UNAVAILABLE_COUNT:
            return g_ahci_driver_read_status_load_unavailable_count;
        case MMIO64_AHCI_DRIVER_READ_STATUS_LOAD_TELEMETRY_TOKEN:
            return g_ahci_driver_read_status_load_token;
        default:
            return 0u;
    }
}

